#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum Paint {
    Font,
    Interior,
    Edge(BorderSelection),
}

/// What `Worksheet.Protect` was asked for.
///
/// Measured against Excel, the flags divide the sheet three ways. `Contents`
/// covers the cells: with it, a LOCKED cell refuses a write, every cell
/// refuses a format, the columns refuse a width, the rows a height, the sheet
/// an insert, a delete, a sort and a merge -- each of the `Allow` flags
/// letting one of those through again -- and `Contents:=False` lets all of
/// them through. `UserInterfaceOnly` lifts all of that for macros and leaves
/// it for the person. `DrawingObjects` covers the notes: a protected sheet
/// refuses `AddComment` even with `UserInterfaceOnly`, even on an unlocked
/// cell, and even with `Contents:=False`, and only `DrawingObjects:=False`
/// lets one be added.
#[derive(Debug, Clone)]
struct Protection {
    password: String,
    contents: bool,
    drawing_objects: bool,
    user_interface_only: bool,
    allow_formatting_cells: bool,
    allow_formatting_columns: bool,
    allow_formatting_rows: bool,
    allow_inserting_columns: bool,
    allow_inserting_rows: bool,
    allow_deleting_columns: bool,
    allow_deleting_rows: bool,
    allow_sorting: bool,
}

impl Protection {
    /// Read off `Protect`'s arguments in their declared order: Password,
    /// DrawingObjects, Contents, Scenarios, UserInterfaceOnly, then the
    /// Allow flags -- FormattingCells, FormattingColumns, FormattingRows,
    /// InsertingColumns, InsertingRows, InsertingHyperlinks, DeletingColumns,
    /// DeletingRows, Sorting, Filtering, UsingPivotTables.
    fn asked(args: &[Value]) -> Result<Self, String> {
        let flag = |index: usize, default: bool| -> Result<bool, String> {
            match args.get(index) {
                None | Some(Value::Missing) => Ok(default),
                Some(value) => Ok(style_face_boolean(value, "Worksheet.Protect")?.unwrap_or(default)),
            }
        };
        Ok(Self {
            password: match args.first() {
                None | Some(Value::Missing) => String::new(),
                Some(value) => shown_text(value, None),
            },
            drawing_objects: flag(1, true)?,
            contents: flag(2, true)?,
            user_interface_only: flag(4, false)?,
            allow_formatting_cells: flag(5, false)?,
            allow_formatting_columns: flag(6, false)?,
            allow_formatting_rows: flag(7, false)?,
            allow_inserting_columns: flag(8, false)?,
            allow_inserting_rows: flag(9, false)?,
            allow_deleting_columns: flag(11, false)?,
            allow_deleting_rows: flag(12, false)?,
            allow_sorting: flag(13, false)?,
        })
    }
}

/// How `Range.TextToColumns` last split a column.
///
/// Excel keeps these from one call to the next: measured, a call naming no
/// delimiter at all splits on whatever the call before it named -- after
/// `Comma:=True, Tab:=False`, a bare `TextToColumns` splits `k,l` and leaves
/// a tab alone. A fresh Excel starts on Tab.
#[derive(Debug, Clone)]
struct SplitSettings {
    delimited: bool,
    consecutive: bool,
    /// The character that fences a field, or None for `xlTextQualifierNone`.
    qualifier: Option<char>,
    tab: bool,
    semicolon: bool,
    comma: bool,
    space: bool,
    other: Option<char>,
    trailing_minus: bool,
}

impl Default for SplitSettings {
    fn default() -> Self {
        Self {
            delimited: true,
            consecutive: false,
            qualifier: Some('"'),
            tab: true,
            semicolon: false,
            comma: false,
            space: false,
            other: None,
            trailing_minus: false,
        }
    }
}

/// What `FieldInfo` says about one field: where it starts (fixed width) or
/// which it is (delimited), and how to read it.
#[derive(Debug, Clone, Copy)]
struct FieldRule {
    at: usize,
    /// 1 General, 2 Text, 3-8 a date order, 9 skip the field.
    kind: i64,
}


/// One of the cell styles a new workbook carries.
///
/// What a style includes is what applying it sets; what it leaves out it
/// leaves alone. Measured on a Japanese Office: `Percent` includes only the
/// number, so a bold cell given it stays bold; `Normal` includes everything
/// and puts a cell back to bare; the themed styles include font and fill.
struct BuiltInStyle {
    /// The name `Range.Style = "..."` answers to. Six styles keep English
    /// names on a Japanese Office and the rest answer only to Japanese ones:
    /// `Range("A1").Style = "Good"` there is error 450.
    name: &'static str,
    local: &'static str,
    number: Option<&'static str>,
    font: Option<StyleFont>,
    /// Some(None) includes the fill and clears it; Some(Some(colour)) fills.
    fill: Option<Option<i64>>,
    /// Left, top, bottom, right, each a kind and a colour.
    borders: Option<[Option<(&'static str, i64)>; 4]>,
    alignment: bool,
    protection: bool,
    /// Where the font's colour is the theme's: its number.
    font_theme: Option<usize>,
    /// Where the fill is the theme's: its number and the tint.
    fill_theme: Option<(usize, f64)>,
}

struct StyleFont {
    bold: bool,
    italic: bool,
    underline: bool,
    size: f32,
    name: Option<&'static str>,
    /// A packed BGR colour; None is the automatic black.
    color: Option<i64>,
}

const NO_FONT_CHANGE: Option<StyleFont> = None;

const fn themed_font(color: Option<i64>) -> Option<StyleFont> {
    Some(StyleFont {
        bold: false,
        italic: false,
        underline: false,
        size: 11.0,
        name: None,
        color,
    })
}

const fn bold_font(color: Option<i64>, size: f32) -> Option<StyleFont> {
    Some(StyleFont {
        bold: true,
        italic: false,
        underline: false,
        size,
        name: None,
        color,
    })
}

const fn tint(
    name: &'static str,
    local: &'static str,
    fill: i64,
    accent: usize,
    shade: f64,
) -> BuiltInStyle {
    BuiltInStyle {
        name,
        local,
        number: None,
        font: themed_font(None),
        fill: Some(Some(fill)),
        borders: None,
        alignment: false,
        protection: false,
        font_theme: None,
        fill_theme: Some((accent, shade)),
    }
}

const fn accent(name: &'static str, local: &'static str, fill: i64, accent: usize) -> BuiltInStyle {
    BuiltInStyle {
        name,
        local,
        number: None,
        font: themed_font(Some(16_777_215)),
        fill: Some(Some(fill)),
        borders: None,
        alignment: false,
        protection: false,
        font_theme: Some(1),
        fill_theme: Some((accent, 0.0)),
    }
}

const fn numbered(name: &'static str, local: &'static str, format: &'static str) -> BuiltInStyle {
    BuiltInStyle {
        name,
        local,
        number: Some(format),
        font: NO_FONT_CHANGE,
        fill: None,
        borders: None,
        alignment: false,
        protection: false,
        font_theme: None,
        fill_theme: None,
    }
}

/// A style whose colours are all given as numbers.
const fn plain(
    name: &'static str,
    local: &'static str,
    font: Option<StyleFont>,
    fill: Option<Option<i64>>,
    borders: Option<[Option<(&'static str, i64)>; 4]>,
) -> BuiltInStyle {
    BuiltInStyle {
        name,
        local,
        number: None,
        font,
        fill,
        borders,
        alignment: false,
        protection: false,
        font_theme: None,
        fill_theme: None,
    }
}

