/// Where `Normal` sits in the table.
const NORMAL_STYLE: usize = 35;

/// Where `Hyperlink` sits: it is listed only once a hyperlink has been added
/// -- measured, `Styles.Count` is 47 before the first `Hyperlinks.Add` and
/// 48 after -- and the table keeps it last.
const HYPERLINK_STYLE: usize = 47;

/// Where `Hyperlink` falls among the listed styles once it is listed:
/// measured, `Styles(28)` is `Percent` and `Styles(29)` is `Hyperlink`,
/// ハイパーリンク sorting after パーセント and before メモ.
const HYPERLINK_LISTED_AT: usize = 28;

/// The style a name stands for. Measured: `percent`, `PERCENT`, `Percent `
/// and the Japanese `パーセント` all reach the style, so the case and the
/// edges do not count and either name will do; `Good` and `Heading 1` -- the
/// English names of styles this Office names in Japanese -- and a number are
/// error 450.
fn built_in_style(name: &str) -> Option<usize> {
    let wanted = name.trim().to_lowercase();
    BUILT_IN_STYLES.iter().position(|style| {
        style.name.to_lowercase() == wanted || style.local.to_lowercase() == wanted
    })
}

/// Whose hyperlinks a `Hyperlinks` collection speaks for.
#[derive(Debug, Clone, Copy)]
enum HyperlinkScope {
    Sheet(usize),
    Range(CellRange),
}

/// A hyperlink a macro added, held beside the workbook the way a note is:
/// the file's own hyperlinks are not read in, and what a macro adds is for
/// the macro's own reading and is not saved -- a known limit.
#[derive(Debug, Clone)]
struct Link {
    id: u64,
    /// The cells it hangs from. Excel lets a hyperlink span a block.
    anchor: CellRange,
    address: String,
    sub_address: String,
    screen_tip: String,
}

/// An address the way Excel keeps it: a web address whose host is followed
/// by nothing, or by a query, gets its `/` -- measured, `http://x.example`
/// is kept as `http://x.example/` and `https://x.example?q=1` as
/// `https://x.example/?q=1`, while `http://x.example/a/b`, `mailto:a@b.c`,
/// `www.x.example` and `C:\temp\a.txt` are kept as written.
fn kept_address(address: &str) -> String {
    let lower = address.to_ascii_lowercase();
    let after_scheme = if lower.starts_with("http://") {
        7
    } else if lower.starts_with("https://") {
        8
    } else {
        return address.to_string();
    };
    let rest = &address[after_scheme..];
    if rest.is_empty() {
        return address.to_string();
    }
    let host_end = rest
        .find(['/', '?', '#'])
        .unwrap_or(rest.len());
    if rest[host_end..].starts_with('/') {
        return address.to_string();
    }
    format!("{}{}/{}", &address[..after_scheme], &rest[..host_end], &rest[host_end..])
}


/// One character's dress, for taking a cell's runs apart and putting them
/// back together.
#[derive(Debug, Clone, PartialEq)]
struct Dress {
    bold: bool,
    italic: bool,
    underline: bool,
    size: Option<f32>,
    font: Option<String>,
    color: Option<String>,
    vert_align: Option<String>,
}

impl Dress {
    fn of_style(style: &CellStyle) -> Self {
        Self {
            bold: style.bold,
            italic: style.italic,
            underline: style.underline,
            size: style.font_size,
            font: style.font_name.clone(),
            color: style.font_color.clone(),
            vert_align: None,
        }
    }

    /// A run's dress. A run with no `<rPr>` of its own wears the cell's; one
    /// with an `<rPr>` wears what it says, borrowing only a size or a face
    /// it does not state.
    fn of_run(run: &TextRun, style: &CellStyle) -> Self {
        if !run.dressed {
            return Self::of_style(style);
        }
        Self {
            bold: run.bold,
            italic: run.italic,
            underline: run.underline,
            size: run.size.or(style.font_size),
            font: run.font.clone().or_else(|| style.font_name.clone()),
            color: run.color.clone(),
            vert_align: run.vert_align.clone(),
        }
    }
}

/// The dress of each character of a cell's text.
fn dresses_of(cell: &Cell) -> Vec<Dress> {
    let text = cell_text_of(cell);
    if cell.runs.is_empty() {
        return vec![Dress::of_style(&cell.style); text.chars().count()];
    }
    let mut dresses = Vec::with_capacity(text.chars().count());
    for run in &cell.runs {
        let dress = Dress::of_run(run, &cell.style);
        for _ in run.text.chars() {
            dresses.push(dress.clone());
        }
    }
    // The runs are meant to cover the text; where a file's do not, the rest
    // wears the cell's dress.
    dresses.resize(text.chars().count(), Dress::of_style(&cell.style));
    dresses
}

/// The text a cell's characters are counted over: its string, or what a
/// number shows as.
fn cell_text_of(cell: &Cell) -> String {
    match &cell.value {
        CellValue::String(text) => text.clone(),
        CellValue::Empty => String::new(),
        other => shown_text(&from_cell_value(other), cell.style.number_format.as_deref()),
    }
}

/// Put a cell's text and per-character dresses back as runs: neighbours
/// dressed alike become one run, and a text dressed all as the cell is has
/// no runs at all -- measured, a character made bold and then not leaves
/// `Font.Bold` a plain False again.
fn redress(cell: &mut Cell, text: &str, dresses: &[Dress]) {
    let plain = Dress::of_style(&cell.style);
    cell.value = CellValue::String(text.to_string());
    if dresses.iter().all(|dress| *dress == plain) {
        cell.runs.clear();
        return;
    }
    let mut runs: Vec<TextRun> = Vec::new();
    let mut last: Option<Dress> = None;
    for (character, dress) in text.chars().zip(dresses) {
        if last.as_ref() == Some(dress) {
            runs.last_mut().expect("a run was started").text.push(character);
            continue;
        }
        runs.push(TextRun {
            text: character.to_string(),
            size: dress.size,
            font: dress.font.clone(),
            bold: dress.bold,
            italic: dress.italic,
            underline: dress.underline,
            color: dress.color.clone(),
            dressed: true,
            vert_align: dress.vert_align.clone(),
        });
        last = Some(dress.clone());
    }
    cell.runs = runs;
}

/// Which characters `Characters(Start, Length)` names, as a range of
/// character positions counted from 0, clipped to the text -- measured,
/// `Characters(3, 100)` of a nine-letter text is its last seven letters and
/// `Characters(100, 2)` is nothing, neither an error.
fn character_span(start: u32, length: Option<u32>, text_length: usize) -> (usize, usize) {
    let from = (start.max(1) as usize - 1).min(text_length);
    let to = match length {
        Some(length) => (from + length as usize).min(text_length),
        None => text_length,
    };
    (from, to)
}


/// The data validation on a cell, as `Range.Validation` sets and reads it.
///
/// Held per cell beside the workbook: the file's own validations are not read
/// in and these are not saved -- a known limit, the same one notes and
/// hyperlinks have. Two cells validated alike answer as one range.
#[derive(Debug, Clone, PartialEq)]
struct Validation {
    /// xlValidateInputOnly 0, WholeNumber 1, Decimal 2, List 3, Date 4,
    /// Time 5, TextLength 6, Custom 7.
    kind: i64,
    /// xlValidAlertStop 1, Warning 2, Information 3.
    alert: i64,
    /// xlBetween 1, NotBetween 2, Equal 3, NotEqual 4, Greater 5, Less 6,
    /// GreaterEqual 7, LessEqual 8.
    operator: i64,
    formula1: String,
    formula2: String,
    in_cell_dropdown: bool,
    ignore_blank: bool,
    show_input: bool,
    show_error: bool,
    input_title: String,
    input_message: String,
    error_title: String,
    error_message: String,
}

/// A validation's formula as Excel keeps it: a time is written back as its
/// long form -- measured, `12:00` is kept as `12:00:00 PM` -- and the rest
/// as given.
fn kept_validation_formula(kind: i64, formula: &str) -> String {
    if kind == 5 && !formula.starts_with('=') {
        if let Some((fraction, _)) = written_time(formula) {
            return vba_date_text(fraction);
        }
    }
    formula.to_string()
}

/// The number a validation's formula text stands for: a plain number, or a
/// date or time as typed.
fn formula_number(formula: &str) -> Option<f64> {
    if let Some(number) = plain_number(formula.trim()) {
        return Some(number);
    }
    match written_moment(formula, this_year_now()) {
        Some((CellValue::Number(number), _)) => Some(number),
        _ => None,
    }
}


/// One conditional format, as `FormatConditions.Add` makes it and a macro
/// reads it back. Held beside the workbook: the file's own are not read in
/// and these are not drawn or saved -- a known limit -- but `DisplayFormat`
/// works them out for a macro that asks.
#[derive(Debug, Clone)]
struct Condition {
    id: u64,
    sheet: usize,
    /// The blocks it applies to. Deleting the conditions of one cell of a
    /// block leaves the rest, so a condition can come to apply to several.
    applies: Vec<CellRange>,
    /// xlCellValue 1, xlExpression 2, xlColorScale 3, xlDataBar 4, xlTop10 5,
    /// xlIconSets 6, xlUniqueValues 8, xlTextString 9, xlBlanksCondition 10,
    /// xlAboveAverageCondition 12, xlNoBlanksCondition 13,
    /// xlErrorsCondition 16, xlNoErrorsCondition 17.
    kind: i64,
    operator: Option<i64>,
    formula1: Option<String>,
    formula2: Option<String>,
    text: Option<String>,
    /// xlContains 0, xlDoesNotContain 1, xlBeginsWith 2, xlEndsWith 3.
    text_operator: Option<i64>,
    rank: i64,
    dupe_unique: i64,
    stop_if_true: bool,
    /// Its priority among the sheet's conditions. Excel gives each a
    /// number and keeps the numbers rather than the order: a new condition
    /// takes one past the highest, moving one to `p` pushes every condition
    /// at `p` or below one further, and a deleted one leaves a gap.
    priority: i64,
    bold: Option<bool>,
    italic: Option<bool>,
    underline: Option<bool>,
    strikethrough: Option<bool>,
    font_color: Option<String>,
    fill: Option<String>,
}

/// A condition's formula as Excel keeps it: everything gets its `=`, and a
/// text that is not a formula is quoted -- measured, `2` is kept as `=2`,
/// `abc` as `="abc"` and `A1>0` (no `=`) as `="A1>0"`.
fn kept_condition_formula(formula: &str) -> String {
    if formula.starts_with('=') {
        return formula.to_string();
    }
    if plain_number(formula.trim()).is_some() {
        return format!("={}", formula.trim());
    }
    format!("=\"{}\"", formula.replace('"', "\"\""))
}

/// Which of number, text and Boolean a cell's value is, in the order Excel
/// compares them: every number is below every text, and every text below
/// every Boolean -- measured, `abc` passes a `> 2` condition.
fn comparison_key(value: &Value) -> (u8, f64, String) {
    match value {
        Value::Boolean(held) => (2, f64::from(*held), String::new()),
        Value::String(text) => (1, 0.0, text.to_lowercase()),
        Value::Empty => (0, 0.0, String::new()),
        other => (0, any_number(other).unwrap_or(0.0), String::new()),
    }
}

fn compare_as_excel(left: &Value, right: &Value) -> Ordering {
    let (left, right) = (comparison_key(left), comparison_key(right));
    left.0
        .cmp(&right.0)
        .then_with(|| left.1.partial_cmp(&right.1).unwrap_or(Ordering::Equal))
        .then_with(|| left.2.cmp(&right.2))
}


/// What a `ListObject` keeps beside the IR's table: whether its totals row
/// is shown, and what each column totals.
#[derive(Debug, Clone, Default)]
struct TableExtra {
    totals: bool,
    /// xlTotalsCalculationNone 0, Sum 1, Average 2, Count 3, CountNums 4,
    /// Min 5, Max 6, StdDev 7, Var 8, per column.
    calculations: Vec<i64>,
    /// Which columns were headed by the table itself (列1, 列2, ...) rather
    /// than by anyone typing: measured, a `Resize` that drops such a column
    /// clears its header cell, and keeps one that was named.
    auto_named: Vec<bool>,
}

/// The SUBTOTAL function number a totals calculation stands for.
fn subtotal_function(calculation: i64) -> Option<i64> {
    Some(match calculation {
        1 => 109,
        2 => 101,
        3 => 103,
        4 => 102,
        5 => 105,
        6 => 104,
        7 => 107,
        8 => 110,
        _ => return None,
    })
}

/// The highest number among the tables named テーブルN, which is where the
/// workbook's counter starts.
fn last_table_number(workbook: &Workbook) -> u32 {
    workbook
        .sheets
        .iter()
        .flat_map(|sheet| sheet.tables.iter())
        .filter_map(|table| table.name.strip_prefix("テーブル")?.parse::<u32>().ok())
        .max()
        .unwrap_or(0)
}

/// The name a new column takes: 列 and the first number not taken.
fn next_column_name(columns: &[String]) -> String {
    (1..)
        .map(|number| format!("列{number}"))
        .find(|name| !columns.iter().any(|held| held == name))
        .expect("the numbers do not run out")
}

/// A table's colours from its style, the way the parser settles them: the
/// Medium, Light and Dark styles from 2 on walk the six accents.
fn table_colours(style: &str) -> (Option<String>, Option<String>, Option<String>) {
    let number: Option<u32> = style
        .strip_prefix("TableStyleMedium")
        .or_else(|| style.strip_prefix("TableStyleLight"))
        .or_else(|| style.strip_prefix("TableStyleDark"))
        .and_then(|rest| rest.parse().ok());
    let Some(number) = number.filter(|number| *number >= 2) else {
        return (None, None, None);
    };
    let accent = THEME_COLOURS[4 + ((number - 2) % 6) as usize];
    let band = tinted(accent, 0.8);
    let rule = if style.starts_with("TableStyleMedium") {
        Some(colour_from_packed(tinted(accent, 0.4)))
    } else {
        None
    };
    (
        Some(colour_from_packed(accent)),
        Some(colour_from_packed(band)),
        rule,
    )
}

/// Whether a table style name is one Excel has: measured, `NoSuchStyle` is
/// 450 where `TableStyleLight1` is taken.
fn known_table_style(name: &str) -> bool {
    let number: Option<u32> = name
        .strip_prefix("TableStyleMedium")
        .or_else(|| name.strip_prefix("TableStyleLight"))
        .or_else(|| name.strip_prefix("TableStyleDark"))
        .and_then(|rest| rest.parse().ok());
    match number {
        Some(number) if name.starts_with("TableStyleDark") => (1..=11).contains(&number),
        Some(number) => (1..=28).contains(&number),
        None => false,
    }
}


/// A sheet's page setup, as `Worksheet.PageSetup` reads and writes it.
///
/// Nothing here prints, but macros set these on their way to doing other
/// things and read them back. Held beside the workbook; the file's own
/// settings are not read in and these are not saved -- a known limit. The
/// defaults are what a new sheet answered on a Japanese Office: A4, portrait,
/// margins of 50.4, 54 and 21.6 points.
#[derive(Debug, Clone)]
struct PageSetup {
    orientation: i64,
    paper_size: i64,
    /// A percentage, or None for `Zoom = False`, when the pages-wide and
    /// pages-tall counts take over.
    zoom: Option<i64>,
    fit_to_pages_wide: Option<i64>,
    fit_to_pages_tall: Option<i64>,
    left_margin: f64,
    right_margin: f64,
    top_margin: f64,
    bottom_margin: f64,
    header_margin: f64,
    footer_margin: f64,
    /// The blocks to print, as Excel writes them: `$A$1:$B$2,$D$1:$D$9`.
    print_area: Vec<CellRange>,
    print_title_rows: Option<(u32, u32)>,
    print_title_columns: Option<(u32, u32)>,
    center_horizontally: bool,
    center_vertically: bool,
    headers: [String; 6],
    print_gridlines: bool,
    print_headings: bool,
    first_page_number: i64,
    order: i64,
    black_and_white: bool,
    draft: bool,
    print_errors: i64,
    print_comments: i64,
    scale_with_doc: bool,
    align_margins: bool,
    different_first_page: bool,
    odd_and_even: bool,
}

impl Default for PageSetup {
    fn default() -> Self {
        Self {
            orientation: 1,
            paper_size: 9,
            zoom: Some(100),
            fit_to_pages_wide: Some(1),
            fit_to_pages_tall: Some(1),
            left_margin: 50.4,
            right_margin: 50.4,
            top_margin: 54.0,
            bottom_margin: 54.0,
            header_margin: 21.6,
            footer_margin: 21.6,
            print_area: Vec::new(),
            print_title_rows: None,
            print_title_columns: None,
            center_horizontally: false,
            center_vertically: false,
            headers: Default::default(),
            print_gridlines: false,
            print_headings: false,
            first_page_number: -4105,
            order: 1,
            black_and_white: false,
            draft: false,
            print_errors: 0,
            print_comments: -4142,
            scale_with_doc: true,
            align_margins: true,
            different_first_page: false,
            odd_and_even: false,
        }
    }
}

/// `Application.International(n)`, for the indexes macros ask about, as
/// the machine this host is measured against answers them: a Japanese Office
/// under a Windows whose formats are month-day-year, dot, comma and dollar.
fn international(index: i64) -> Result<Value, String> {
    Ok(match index {
        // xlCountryCode, xlCountrySetting
        1 => Value::Integer(81),
        2 => Value::Integer(1),
        // xlDecimalSeparator, xlThousandsSeparator, xlListSeparator
        3 => Value::String(".".to_string()),
        4 => Value::String(",".to_string()),
        5 => Value::String(",".to_string()),
        // xlUpperCaseRowLetter, xlUpperCaseColumnLetter, xlLowerCaseRowLetter,
        // xlLowerCaseColumnLetter
        6 => Value::String("R".to_string()),
        7 => Value::String("C".to_string()),
        8 => Value::String("r".to_string()),
        9 => Value::String("c".to_string()),
        // xlLeftBracket, xlRightBracket, xlLeftBrace, xlRightBrace
        10 => Value::String("[".to_string()),
        11 => Value::String("]".to_string()),
        12 => Value::String("{".to_string()),
        13 => Value::String("}".to_string()),
        // xlColumnSeparator, xlRowSeparator, xlAlternateArraySeparator
        14 => Value::String(",".to_string()),
        15 => Value::String(";".to_string()),
        16 => Value::String(String::new()),
        // xlDateSeparator, xlTimeSeparator
        17 => Value::String("/".to_string()),
        18 => Value::String(":".to_string()),
        // xlYearCode, xlMonthCode, xlDayCode, xlHourCode, xlMinuteCode,
        // xlSecondCode
        19 => Value::String("y".to_string()),
        20 => Value::String("m".to_string()),
        21 => Value::String("d".to_string()),
        22 => Value::String("h".to_string()),
        23 => Value::String("m".to_string()),
        24 => Value::String("s".to_string()),
        // xlCurrencyCode, xlGeneralFormatName
        25 => Value::String("$".to_string()),
        26 => Value::String("General".to_string()),
        // xlCurrencyDigits, xlCurrencyNegative, xlNoncurrencyDigits
        27 => Value::Integer(2),
        28 => Value::Integer(0),
        29 => Value::Integer(2),
        // xlMonthNameChars, xlWeekdayNameChars
        30 => Value::Integer(3),
        31 => Value::Integer(3),
        // xlDateOrder: 0 month-day-year
        32 => Value::Integer(0),
        // xl24HourClock
        33 => Value::Boolean(false),
        // xlNonEnglishFunctions, xlMetric, xlCurrencySpaceBefore,
        // xlCurrencyBefore, xlCurrencyMinusSign, xlCurrencyTrailingZeros,
        // xlCurrencyLeadingZeros
        34 => Value::Boolean(false),
        35 => Value::Boolean(false),
        36 => Value::Boolean(false),
        37 => Value::Boolean(true),
        38 => Value::Boolean(false),
        39 => Value::Boolean(true),
        40 => Value::Boolean(true),
        // xlMonthLeadingZero, xlDayLeadingZero, xl4DigitYears, xlMDY,
        // xlTimeLeadingZero
        41 => Value::Boolean(false),
        42 => Value::Boolean(false),
        43 => Value::Boolean(true),
        44 => Value::Boolean(true),
        45 => Value::Boolean(false),
        other => return Err(format!("Application.International has no index {other}")),
    })
}

/// A note a macro can read and write.
///
/// Kept beside the workbook rather than in it: the IR holds only the notes a
/// sheet keeps pinned open, placed for drawing, and a note a macro adds has
/// no place on the sheet until someone gives it one. So what a macro adds is
/// held for the macro's own reading and is not drawn or saved -- a known
/// limit, the same one the sheet's own protection has.
#[derive(Debug, Clone)]
struct Note {
    at: CellAddress,
    text: String,
    visible: bool,
}

/// What the window shows of one sheet. Excel keeps each sheet's zoom,
/// gridlines and scroll position with the sheet, and a window opened on
/// another sheet shows that sheet's: measured, with Zoom 80 and the gridlines
/// off on Sheet1, a sheet added answers 100 and True, and Sheet1 answers 80
/// and False again when it is back in front.
#[derive(Debug, Clone, Copy)]
struct View {
    zoom: f64,
    gridlines: bool,
    headings: bool,
    formulas: bool,
    zeros: bool,
    scroll_row: u32,
    scroll_column: u32,
}

impl Default for View {
    fn default() -> Self {
        Self {
            zoom: 100.0,
            gridlines: true,
            headings: true,
            formulas: false,
            zeros: true,
            scroll_row: 1,
            scroll_column: 1,
        }
    }
}

/// The outline of one sheet: the level of every grouped row and column --
/// one being ungrouped, eight the most -- and where its summaries sit.
#[derive(Debug, Clone)]
struct Outline {
    rows: std::collections::HashMap<u32, u8>,
    columns: std::collections::HashMap<u32, u8>,
    /// xlSummaryBelow 1, xlSummaryAbove 0.
    summary_row: i64,
    /// xlSummaryOnRight -4152, xlSummaryOnLeft -4131.
    summary_column: i64,
    automatic_styles: bool,
}

impl Default for Outline {
    fn default() -> Self {
        Self {
            rows: std::collections::HashMap::new(),
            columns: std::collections::HashMap::new(),
            summary_row: 1,
            summary_column: -4152,
            automatic_styles: false,
        }
    }
}

/// The recorder's `Worksheet.Sort` object, built up before `.Apply`. A
/// field is the key's lane -- its column, or its row when the sort runs
/// sideways -- and whether it descends. Measured: `SortFields.Add Key:=
/// Range("A2:A3"), Order:=xlAscending` then `.SetRange`, `.Header`, `.Apply`
/// sorts the range by column A.
#[derive(Debug, Clone, Default)]
struct SortState {
    range: Option<CellRange>,
    header: i64,
    match_case: bool,
    sideways: bool,
    fields: Vec<(u32, bool)>,
}

/// The colour of a sheet's tab: a plain colour, or one from the theme with
/// a tint on it. Measured: a fresh tab answers `Color` False (a Boolean),
/// `ColorIndex` xlNone and `ThemeColor` 0; `Color = 65280` reads back with
/// ColorIndex 4; `ThemeColor = 5` reads Color 8544277.
#[derive(Debug, Clone, Copy, PartialEq)]
struct TabColour {
    colour: i64,
    theme: Option<usize>,
    tint: f64,
}

/// A hatching drawn over a cell's fill, and the colour it is drawn in.
///
/// `kind` is the pattern as the FILE numbers it -- solid 1, mediumGray 2,
/// darkGray 3, lightGray 4, darkHorizontal 5, darkVertical 6, darkDown 7,
/// darkUp 8, darkGrid 9, darkTrellis 10, the light ones 11 to 16, gray125
/// 17, gray0625 18 -- plus 4000 and 4001 for the two gradients. Excel takes
/// the file's numbers as well as its own names for them, and answers with
/// the name where it has one: measured, `Pattern = 7` reads back as
/// `xlDown`, -4121.
#[derive(Debug, Clone, Copy, PartialEq)]
struct Hatching {
    kind: i64,
    /// The pattern's colour, packed the way VBA counts it; None is automatic.
    colour: Option<i64>,
}

/// The marks this host keeps on a cell beside the workbook: its turn, the
/// rule under its writing, its hatching, and whether its indent grows with
/// its rotation. Lifted and put down together when the cell moves.
#[derive(Debug, Clone, Copy, Default)]
struct CellMarks {
    rotation: Option<i32>,
    underline: Option<i64>,
    hatching: Option<Hatching>,
    indented: bool,
}

/// The functions `Range.Subtotal` totals with: the xlConsolidationFunction
/// constant, the SUBTOTAL number it becomes, the word after a group's key,
/// and the grand total's label -- in Excel's own order, which is the order
/// the rows of one group take when several functions are laid together.
/// Measured on a Japanese Office (misc3.vba, 2026-09-05).
const SUBTOTAL_FUNCTIONS: [(i64, i64, &str, &str); 11] = [
    (-4157, 9, "集計", "総計"),
    (-4112, 3, "個数", "総合計"),
    (-4106, 1, "平均", "全体の平均"),
    (-4136, 4, "最大", "全体の最大値"),
    (-4139, 5, "最小", "全体の最小値"),
    (-4149, 6, "積", "全体の積"),
    (-4113, 2, "数値の個数", "総合計"),
    (-4155, 7, "標本標準偏差", "全体の標本標準偏差"),
    (-4156, 8, "標準偏差", "全体の標準偏差"),
    (-4164, 10, "標本分散", "全体の標本分散"),
    (-4165, 11, "分散", "全体の分散"),
];

/// Where a format that reaches every cell of a sheet, a column or a row
/// is kept: `Cells.Font.Name = "Meiryo"`, `Columns("C").NumberFormat =
/// "0.00"`, `Rows(1).Font.Bold = True`. Excel keeps such a format on the
/// column or the row itself and hands it to a cell the moment one is made
/// there; here the cells that exist are dressed at once and the rest take
/// the dress from these templates when they come to be, or when they are
/// asked. A row's template stands over a column's, and both over the sheet's.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum FormatScope {
    Sheet(usize),
    Column(usize, u32),
    Row(usize, u32),
}

/// The shape of a range, as far as formats and clears care.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Band {
    /// Every cell of the sheet.
    Whole,
    /// Whole rows.
    Rows,
    /// Whole columns.
    Columns,
    /// A block of cells.
    Cells,
}

/// Which edge of a range `FillDown` and its three siblings copy from.
#[derive(Debug, Clone, Copy)]
enum FillEdge {
    Top,
    Bottom,
    Left,
    Right,
}

/// What `Range.Copy` set aside, as it stood when it was copied. Excel keeps a
/// live link to the cells instead, so changing them before pasting changes what
/// arrives; this build pastes what was there at the time.
struct Clipboard {
    /// Row-major, one entry per cell of the copied block.
    cells: Vec<Option<Cell>>,
    /// The note on each of those cells, in the same order.
    notes: Vec<Option<Note>>,
    /// Whether each of those cells was unlocked, in the same order.
    unlocked: Vec<bool>,
    rows: u32,
    columns: u32,
    /// Where it came from, so a formula can be moved by the right offset.
    origin: CellAddress,
}

struct AutoFilter {
    range: CellRange,
    fields: Vec<FieldTest>,
}

struct FieldTest {
    /// One-based column within the filtered range.
    field: u32,
    /// What the cell is tested against. Usually one, or two joined by
    /// `either`; a filter given a LIST of values (`xlFilterValues`) holds one
    /// equality test per value, all joined by `either`, which is the same
    /// thing said longer.
    criteria: Vec<Criteria>,
    /// True when the criteria are joined by xlOr rather than xlAnd.
    either: bool,
}

#[derive(Clone)]
struct FindState {
    range: CellRange,
    args: Vec<Value>,
    last_found: Option<CellAddress>,
}

struct WorkbookHost<'a> {
    workbook: &'a mut Workbook,
    active_sheet: usize,
    clipboard: Option<Clipboard>,
    /// The block a `Cut` set aside without saying where it goes. Excel holds
    /// the cells themselves rather than a copy of them, so a Paste MOVES them
    /// and a second Paste has nothing left to move.
    pending_cut: Option<CellRange>,
    /// The range a sheet is filtering, and the tests each field is under.
    /// Filtering a second field narrows what the first left showing, so the
    /// tests accumulate and every row is judged against all of them.
    auto_filter: Option<AutoFilter>,
    selection: CellRange,
    /// The one cell in front of the selection. Selecting a block puts it on
    /// the block's top-left, but `Activate` moves it about INSIDE the block
    /// without disturbing what is selected — measured in Excel: after
    /// `Range("B2:C3").Select` and then `Range("C3").Activate` the selection
    /// is still B2:C3 and the active cell is C3.
    active_cell: CellAddress,
    screen_updating: bool,
    enable_events: bool,
    display_alerts: bool,
    calculation: i64,
    /// Which sheets are protected, and how. Runtime state rather than part
    /// of the workbook: the file format's own protection is not read in, so
    /// this is what a MACRO has done, which is what a macro then runs into.
    protected: Vec<Option<Protection>>,
    /// The cells a macro has UNLOCKED. Every cell starts locked -- asked of
    /// Excel, `Range("A1").Locked` is True on a fresh sheet -- so it is the
    /// exceptions that are kept.
    unlocked: std::collections::HashSet<CellAddress>,
    /// The notes on every sheet, in the order they were added.
    notes: Vec<Note>,
    /// The hyperlinks on every sheet, in the order they were added.
    links: Vec<Link>,
    /// The data validation on each cell that has one.
    validations: std::collections::HashMap<CellAddress, Validation>,
    /// The conditional formats, in order of priority within each sheet.
    conditions: Vec<Condition>,
    next_condition: u64,
    /// The tables a macro can reach, by number: which sheet each is on and
    /// what it is called there, since renaming moves nothing else.
    table_handles: Vec<(u64, usize, String)>,
    table_extra: std::collections::HashMap<u64, TableExtra>,
    next_table: u64,
    /// Each sheet's page setup, once a macro has touched it.
    page_setups: std::collections::HashMap<usize, PageSetup>,
    /// The selection and active cell of every sheet that is not in front.
    selections: std::collections::HashMap<usize, (CellRange, CellAddress)>,
    /// How many sheets have been made since the workbook was opened, which
    /// is where the next new sheet's number comes from. Measured: the count
    /// starts over when a file is opened -- a saved workbook whose one sheet
    /// is Sheet3, or Base, gets Sheet1 next -- so a workbook the browser
    /// has just read starts from nothing.
    sheet_counter: usize,
    /// What the window shows of each sheet, once a macro has changed it.
    views: std::collections::HashMap<usize, View>,
    /// Each sheet's outline, once a macro has grouped anything.
    outlines: std::collections::HashMap<usize, Outline>,
    /// The colour of each sheet's tab, where one has been given.
    tabs: std::collections::HashMap<usize, TabColour>,
    /// Each sheet's pending `Sort` object.
    sorts: std::collections::HashMap<usize, SortState>,
    /// Every shape and chart, the file's and the macro's, in the order
    /// they were made.
    shapes: Vec<shapes::ShapeRecord>,
    /// How many shapes each sheet has ever had, which numbers the next.
    shape_counters: std::collections::HashMap<usize, u32>,
    next_shape_id: u64,
    /// The shape a `Copy` set aside for `Worksheet.Paste`.
    shape_clipboard: Option<u64>,
    /// The turn of every cell written at an angle, in degrees from -90 to
    /// 90. The IR keeps only the stacked kind, which is 771 of the 774
    /// rotations in the conformance corpus; the angles are kept here for
    /// the macro's own reading, and are not drawn or saved -- the same limit
    /// the notes a macro adds have.
    rotations: std::collections::HashMap<CellAddress, i32>,
    /// The rule under a cell's writing where it is not the single one the
    /// IR can say: double -4119, single accounting 4, double accounting 5.
    underlines: std::collections::HashMap<CellAddress, i64>,
    /// The hatching over each cell that has one.
    hatchings: std::collections::HashMap<CellAddress, Hatching>,
    /// The cells whose indent grows with their rotation (`AddIndent`).
    indented: std::collections::HashSet<CellAddress>,
    /// The formats given to whole sheets, columns and rows, for the cells
    /// not yet made there.
    templates: std::collections::HashMap<FormatScope, CellStyle>,
    /// The number the next new table is named with. Measured: a workbook
    /// counter, not the lowest free number -- with テーブル1 renamed to T,
    /// the next table is still テーブル2.
    table_counter: u32,
    /// The number the next hyperlink gets.
    next_link: u64,
    /// Whether a hyperlink has ever been added: the `Hyperlink` style joins
    /// the workbook's styles the first time one is.
    linked_once: bool,
    /// How `TextToColumns` last split, which is how it splits next.
    split: SplitSettings,
    /// The style each cell was last given, by its place in the table; a cell
    /// not listed wears `Normal`.
    styled: std::collections::HashMap<CellAddress, usize>,
    /// Where a cell's colour came from the theme: the theme colour's number
    /// and the tint on it, for each part of the cell so painted. A colour
    /// given as a number is not here, and the theme questions answer
    /// accordingly.
    theme_paint: std::collections::HashMap<(CellAddress, Paint), (usize, f64)>,
    /// What a macro has written across the bottom of the window, while it is
    /// the macro's to write. Nothing here means the bar is Excel's own again,
    /// which is what it answers `False` to say.
    status_bar: Option<String>,
    /// The pointer the macro has asked for while it works — the hourglass a
    /// long loop puts up, and the arrow it puts back.
    cursor: i64,
    /// Whether the sheet is taking anything from whoever is at the keyboard.
    /// A macro turns this off to work undisturbed, and turns it back on.
    interactive: bool,
    last_find: Option<FindState>,
    objects: Vec<HostObject>,
    /// Whether anything was written to a cell. Excel works the formulas out
    /// after a change; this build does it once, when the macro is done, so
    /// that a loop writing a hundred cells does not pay for a hundred passes.
    wrote: bool,
    /// What moment the page says it is, as a serial. `TODAY()` and `NOW()`
    /// are answered from it when a macro asks for a recalculation; a browser
    /// has no clock of its own to ask.
    now: Option<f64>,
    /// The blocks of every many-block range handed out.
    blocks: Vec<Vec<CellRange>>,
    /// The text of every name a `Name` object was handed out for.
    name_handles: Vec<String>,
    /// Whether the workbook counts as saved: `ThisWorkbook.Saved`, False
    /// until a macro says otherwise, and False again after any write.
    saved: bool,
    /// What the file this workbook came from is called, when the page says.
    /// Excel calls a workbook that was never saved `Book1`, and a browser
    /// never saves one anywhere it can name, so what the page hands over is
    /// the file's own name and nothing else — no folder in front of it.
    file_name: Option<String>,
    debug_output: Vec<String>,
    messages: Vec<BrowserMessage>,
}

impl<'a> WorkbookHost<'a> {
    fn new(workbook: &'a mut Workbook, active_sheet: usize) -> Result<Self, String> {
        let mut host = Self::stand_up(workbook, active_sheet)?;
        host.adopt_drawings();
        Ok(host)
    }

    fn stand_up(workbook: &'a mut Workbook, active_sheet: usize) -> Result<Self, String> {
        if active_sheet >= workbook.sheets.len() {
            return Err(format!(
                "active sheet index is out of range: {active_sheet}"
            ));
        }
        let notes = notes_pinned_open(workbook);
        let table_counter = last_table_number(workbook);
        Ok(Self {
            workbook,
            active_sheet,
            clipboard: None,
            pending_cut: None,
            auto_filter: None,
            selection: CellRange::single(CellAddress {
                sheet: active_sheet,
                row: 1,
                column: 0,
            }),
            active_cell: CellAddress {
                sheet: active_sheet,
                row: 1,
                column: 0,
            },
            screen_updating: true,
            protected: Vec::new(),
            unlocked: std::collections::HashSet::new(),
            notes,
            links: Vec::new(),
            validations: std::collections::HashMap::new(),
            conditions: Vec::new(),
            next_condition: 1,
            table_handles: Vec::new(),
            table_extra: std::collections::HashMap::new(),
            next_table: 1,
            page_setups: std::collections::HashMap::new(),
            selections: std::collections::HashMap::new(),
            sheet_counter: 0,
            saved: false,
            views: std::collections::HashMap::new(),
            outlines: std::collections::HashMap::new(),
            tabs: std::collections::HashMap::new(),
            sorts: std::collections::HashMap::new(),
            shapes: Vec::new(),
            shape_counters: std::collections::HashMap::new(),
            next_shape_id: 1,
            shape_clipboard: None,
            rotations: std::collections::HashMap::new(),
            underlines: std::collections::HashMap::new(),
            hatchings: std::collections::HashMap::new(),
            indented: std::collections::HashSet::new(),
            templates: std::collections::HashMap::new(),
            table_counter,
            next_link: 1,
            linked_once: false,
            split: SplitSettings::default(),
            styled: std::collections::HashMap::new(),
            theme_paint: std::collections::HashMap::new(),
            enable_events: true,
            display_alerts: true,
            calculation: -4105,
            status_bar: None,
            cursor: CURSOR_DEFAULT,
            interactive: true,
            last_find: None,
            objects: Vec::new(),
            wrote: false,
            now: None,
            blocks: Vec::new(),
            name_handles: Vec::new(),
            file_name: None,
            debug_output: Vec::new(),
            messages: Vec::new(),
        })
    }

    fn object(&mut self, object: HostObject) -> Value {
        let handle = self.objects.len() as u64;
        self.objects.push(object);
        Value::Object(ObjectRef {
            handle,
            kind: match object {
                HostObject::Range(_) => "Range",
                HostObject::RangeFont(_) => "Font",
                HostObject::RangeInterior(_) => "Interior",
                HostObject::RangeBorders(_, _) => "Borders",
                HostObject::RangeCollection(_, RangeAxis::Rows) => "Rows",
                HostObject::RangeCollection(_, RangeAxis::Columns) => "Columns",
                HostObject::Worksheet(_) => "Worksheet",
                HostObject::Worksheets => "Worksheets",
                HostObject::Blocks(_) => "Range",
                HostObject::Areas(_) => "Areas",
                HostObject::BlocksStyle(_, StyleFace::Font) => "Font",
                HostObject::BlocksStyle(_, StyleFace::Interior) => "Interior",
                HostObject::BlocksStyle(_, StyleFace::Borders(_)) => "Borders",
                HostObject::Names => "Names",
                HostObject::DefinedName(_) => "Name",
                HostObject::Workbook => "Workbook",
                HostObject::Application => "Application",
                HostObject::Window => "Window",
                HostObject::Style(_) => "Style",
                HostObject::Styles => "Styles",
                HostObject::Hyperlink(_) => "Hyperlink",
                HostObject::Hyperlinks(_) => "Hyperlinks",
                HostObject::PageSetup(_) => "PageSetup",
                HostObject::ListObjects(_) => "ListObjects",
                HostObject::ListObject(_) => "ListObject",
                HostObject::ListRows(_) => "ListRows",
                HostObject::ListRow(..) => "ListRow",
                HostObject::ListColumns(_) => "ListColumns",
                HostObject::ListColumn(..) => "ListColumn",
                HostObject::Validation(_) => "Validation",
                HostObject::FormatConditions(_) => "FormatConditions",
                HostObject::FormatCondition(id) => match self
                    .conditions
                    .iter()
                    .find(|condition| condition.id == id)
                    .map(|condition| condition.kind)
                {
                    Some(3) => "ColorScale",
                    Some(4) => "Databar",
                    Some(5) => "Top10",
                    Some(6) => "IconSetCondition",
                    Some(8) => "UniqueValues",
                    Some(12) => "AboveAverage",
                    _ => "FormatCondition",
                },
                HostObject::ConditionFont(_) => "Font",
                HostObject::ConditionInterior(_) => "Interior",
                HostObject::DisplayFormat(_) => "DisplayFormat",
                HostObject::DisplayFont(_) => "Font",
                HostObject::DisplayInterior(_) => "Interior",
                HostObject::Characters(..) => "Characters",
                HostObject::CharactersFont(..) => "Font",
                HostObject::Comment(_) => "Comment",
                HostObject::Comments(_) => "Comments",
                HostObject::WorksheetFunction => "WorksheetFunction",
                HostObject::DebugConsole => "Debug",
                HostObject::Outline(_) => "Outline",
                HostObject::Tab(_) => "Tab",
                HostObject::Workbooks => "Workbooks",
                HostObject::Sort(_) => "Sort",
                HostObject::SortFields(_) => "SortFields",
                HostObject::Drawing(part) => part.kind_name(),
                HostObject::Gone => "Nothing",
            }
            .to_string(),
        })
    }

    /// The cells behind a range object, whether or not it remembers being
    /// asked for by row or by column.
    ///
    /// A range that came through `.Rows`, `.Columns`, `.EntireRow` or
    /// `.EntireColumn` is still a range and answers like one — asked of Excel,
    /// `TypeName(Rows(1))` is "Range", `Rows(2).Row` is 2 and
    /// `Rows(2).Cells(2).Value` reads B2. Only `Count` and `Item` follow the
    /// sense, and those are handled before anything gets here.
    fn range(&self, object: &ObjectRef) -> Option<CellRange> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::Range(range)) => Some(*range),
            Some(HostObject::RangeCollection(range, _)) => Some(*range),
            _ => None,
        }
    }

    /// The row-or-column sense a range object carries, if it has one.
    fn range_sense(&self, object: &ObjectRef) -> Option<RangeAxis> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::RangeCollection(_, axis)) => Some(*axis),
            _ => None,
        }
    }

    /// Give a range the sense the one it came from had.
    ///
    /// Asked of Excel, the sense survives `Offset` and `Resize`:
    /// `Rows(1).Offset(1, 0)` is `$2:$2` and still counts 1, and
    /// `Columns(1).Resize(, 2)` counts 2 while `Rows(1).Resize(, 2)` counts 1.
    /// `Cells`, `Areas` and `Union` drop it — `Rows("1:3").Areas(1).Count` is
    /// 49152, back to counting cells.
    fn carry_sense(&mut self, source: &ObjectRef, produced: Value) -> Value {
        let Some(axis) = self.range_sense(source) else {
            return produced;
        };
        let Value::Object(object) = &produced else {
            return produced;
        };
        match self.objects.get(object.handle as usize) {
            Some(HostObject::Range(range)) => {
                let range = *range;
                self.object(HostObject::RangeCollection(range, axis))
            }
            _ => produced,
        }
    }

    fn range_font(&self, object: &ObjectRef) -> Option<CellRange> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::RangeFont(range)) => Some(*range),
            _ => None,
        }
    }

    fn range_interior(&self, object: &ObjectRef) -> Option<CellRange> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::RangeInterior(range)) => Some(*range),
            _ => None,
        }
    }

    fn range_borders(&self, object: &ObjectRef) -> Option<(CellRange, BorderSelection)> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::RangeBorders(range, selection)) => Some((*range, *selection)),
            _ => None,
        }
    }

    fn borders_object(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        let selection = match args {
            [] => BorderSelection::All,
            [value] => border_selection(value)?,
            _ => return Err("Range.Borders expects zero or one border index".to_string()),
        };
        Ok(self.object(HostObject::RangeBorders(range, selection)))
    }

    fn range_collection(&self, object: &ObjectRef) -> Option<(CellRange, RangeAxis)> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::RangeCollection(range, axis)) => Some((*range, *axis)),
            _ => None,
        }
    }

    fn worksheet(&self, object: &ObjectRef) -> Option<usize> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::Worksheet(sheet)) => Some(*sheet),
            _ => None,
        }
    }

    fn is_workbook(&self, object: &ObjectRef) -> bool {
        matches!(
            self.objects.get(object.handle as usize),
            Some(HostObject::Workbook)
        )
    }

    fn is_worksheets(&self, object: &ObjectRef) -> bool {
        matches!(
            self.objects.get(object.handle as usize),
            Some(HostObject::Worksheets)
        )
    }

    /// Work out every formula in the workbook again.
    ///
    /// A macro has to ASK for this. Excel does it by itself after every
    /// change, but the engine here rebuilds the whole dependency graph each
    /// time, so the cost goes with how many cells the workbook has rather than
    /// how many formulas: measured over the conformance corpus, a small book
    /// takes under 3ms, one of 300,000 cells takes 270ms, and the largest —
    /// 936,000 cells — takes 15 seconds. Doing that after every assignment
    /// would make a loop that writes a hundred cells unusable, so this build
    /// waits to be told.
    /// What year it is, for a written date that leaves the year out. It
    /// comes from the same moment `Now` and `TODAY()` read, so a host given a
    /// fixed time reads `1/5` against that time and not against the wall.
    fn this_year(&self) -> i64 {
        match self.now {
            Some(now) => year_of_serial(now),
            None => this_year_now(),
        }
    }

    fn recalculate(&mut self) {
        match self.now {
            Some(now) => oxicells_core::formula::evaluate_workbook_formulas_at(self.workbook, now),
            None => oxicells_core::formula::evaluate_workbook_formulas(self.workbook),
        }
        self.wrote = false;
    }

    /// Work the book out, if an answer is about to be given from a formula
    /// that has not been worked out since the last write.
    ///
    /// Excel settles a formula the moment anything it reads changes, so a
    /// macro that writes `=A1*2` and then asks that cell for its value gets
    /// the answer. This build works the whole book out in one pass, which is
    /// far too much to do after every write — so it does it here instead, and
    /// only when the cells being read actually hold a formula. A macro that
    /// only writes pays nothing; one that writes and then reads pays a single
    /// pass for the round, however many cells it wrote.
    ///
    /// A macro that turned calculation off is taken at its word, the same way
    /// the pass at the end of the run takes it.
    fn settle(&mut self, range: CellRange) {
        if !self.wrote || self.calculation != -4105 || !self.holds_formula(range) {
            return;
        }
        self.recalculate();
    }

    /// The same, for whatever cells a set of arguments names — what
    /// `WorksheetFunction.Sum(Range("A1:A4"))` is about to add up.
    fn settle_arguments(&mut self, args: &[Value]) {
        for value in args {
            let Value::Object(object) = value else {
                continue;
            };
            if let Some(range) = self.range(object) {
                self.settle(range);
            } else if let Some(blocks) = self.blocks(object) {
                for block in blocks.to_vec() {
                    self.settle(block);
                }
            }
        }
    }

    /// Whether any cell of `range` holds a formula. Only the rows and cells
    /// that exist are looked at, so an empty sheet costs nothing.
    fn holds_formula(&self, range: CellRange) -> bool {
        let Some(sheet) = self.workbook.sheets.get(range.sheet) else {
            return false;
        };
        sheet
            .rows
            .iter()
            .filter(|row| row.index >= range.start_row && row.index <= range.end_row)
            .any(|row| {
                row.cells.iter().any(|cell| {
                    cell.formula.is_some()
                        && cell.col >= range.start_column
                        && cell.col <= range.end_column
                })
            })
    }

    /// The blocks a many-block range is made of.
    fn blocks(&self, object: &ObjectRef) -> Option<&[CellRange]> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::Blocks(handle)) | Some(HostObject::Areas(handle)) => {
                self.blocks.get(*handle).map(Vec::as_slice)
            }
            _ => None,
        }
    }

    /// Name several blocks as one range.
    ///
    /// Blocks that JOIN are one block: asked of Excel, `Union` of A1:A3 and
    /// A2:A4 answers `A1:A4` with one area, and so does `Union` of A1:A2 and
    /// A3:A4, which only touch. What is left is a range with as many areas as
    /// there are blocks — or, where they all came to one, an ordinary range.
    fn blocks_object(&mut self, given: Vec<CellRange>) -> Result<Value, String> {
        let mut areas: Vec<CellRange> = Vec::with_capacity(given.len());
        for block in given {
            Self::range_cell_count(block)?;
            let mut block = block;
            // Joining one may let it join another, so go round until nothing
            // more comes together.
            loop {
                match areas.iter().position(|held| joined(*held, block).is_some()) {
                    Some(at) => {
                        block = joined(areas.remove(at), block).expect("just found");
                    }
                    None => break,
                }
            }
            areas.push(block);
        }
        if areas.len() == 1 {
            return Ok(self.object(HostObject::Range(areas[0])));
        }
        let handle = self.blocks.len();
        self.blocks.push(areas);
        Ok(self.object(HostObject::Blocks(handle)))
    }

    /// Name several blocks as one range, keeping each as it was written.
    ///
    /// A comma-written address does not join anything, where `Union` does:
    /// asked of Excel, `Range("A1:A3,A2:A4")` has two areas against
    /// `Union(A1:A3, A2:A4)`'s one, `Range("A1:A2,A3:A4")` — blocks that only
    /// touch — has two against Union's one, and even `Range("A1,A1")` has two.
    fn written_blocks_object(&mut self, given: Vec<CellRange>) -> Result<Value, String> {
        for block in &given {
            Self::range_cell_count(*block)?;
        }
        if given.len() == 1 {
            return Ok(self.object(HostObject::Range(given[0])));
        }
        let handle = self.blocks.len();
        self.blocks.push(given);
        Ok(self.object(HostObject::Blocks(handle)))
    }

    /// `Address(RowAbsolute, ColumnAbsolute, ReferenceStyle, External, RelativeTo)`.
    ///
    /// The last three were measured in Excel 16.0. In R1C1 an absolute part is
    /// `R2C2` and a relative one counts from `RelativeTo`, which is A1 unless
    /// something else is handed over: B2 is `R[1]C[1]` from A1 and `R[-1]C[-1]`
    /// from C3, and an offset of nothing loses its brackets altogether — A1 from
    /// A1 is `RC`, C4 from C3 is `R[1]C`. A band keeps one axis: rows 2 to 4 are
    /// `R2:R4` and columns B to D are `C2:C4`. `External` puts the file and the
    /// sheet in front — `[Book1]Sheet1!$B$2`, and `'[Book1]A Sheet'!$B$2` when
    /// the name needs quoting.
    fn range_address_from_args(&self, range: CellRange, args: &[Value]) -> Result<String, String> {
        let read = |at: usize, default: bool, label: &str| -> Result<bool, String> {
            match args.get(at) {
                None => Ok(default),
                Some(value) => optional_boolean_argument(value, default, label),
            }
        };
        if args.len() > 5 {
            return Err("Range.Address supports up to five arguments".to_string());
        }
        let row_absolute = read(0, true, "row absolute")?;
        let column_absolute = read(1, true, "column absolute")?;
        let r1c1 = match args.get(2) {
            None | Some(Value::Missing) => false,
            Some(value) if any_whole_number(value) == Some(1) => false,
            Some(value) if any_whole_number(value) == Some(-4150) => true,
            Some(other) => {
                return Err(format!(
                    "unsupported Range.Address ReferenceStyle constant: {other:?}"
                ))
            }
        };
        let external = read(3, false, "external")?;
        let relative_to = match args.get(4) {
            None | Some(Value::Missing) => (1, 0),
            Some(Value::Object(object)) => match self.range(object) {
                Some(from) => (from.start_row, from.start_column),
                None => return Err("Range.Address RelativeTo must be a Range".to_string()),
            },
            Some(_) => return Err("Range.Address RelativeTo must be a Range".to_string()),
        };
        let written = if r1c1 {
            format_range_address_r1c1(range, row_absolute, column_absolute, relative_to)
        } else {
            format_range_address(range, row_absolute, column_absolute)
        };
        if !external {
            return Ok(written);
        }
        let sheet = self
            .workbook
            .sheets
            .get(range.sheet)
            .map(|sheet| sheet.name.as_str())
            .unwrap_or_default();
        let book = self.file_name.as_deref().unwrap_or("Book1");
        // The quoting is decided by the two names, not by the brackets around
        // one of them: `[Book1]Sheet1!$B$2` stands bare where
        // `'[Book1]A Sheet'!$B$2` is quoted whole, brackets and all.
        let front = format!("[{book}]{sheet}");
        if oxicells_calc::reference::needs_quoting(sheet)
            || oxicells_calc::reference::needs_quoting(book)
        {
            Ok(format!("'{}'!{written}", front.replace('\'', "''")))
        } else {
            Ok(format!("{front}!{written}"))
        }
    }

    /// The `Areas` of a range that is one block: a collection of one, which
    /// is what Excel hands back for any ordinary range.
    fn areas_of(&mut self, range: CellRange) -> Value {
        let handle = self.blocks.len();
        self.blocks.push(vec![range]);
        self.object(HostObject::Areas(handle))
    }

    /// The cells of a block that answer to a description.
    ///
    /// Asked of Excel about a column holding 10, "text", a blank, `=A1*2`, 30,
    /// `=1/0`, a blank and TRUE: the constants are `A1:A2,A5,A8`, the formulas
    /// `A4,A6`, the blanks `A3,A7`. The second argument is a MASK over what a
    /// value may be — 1 a number, 2 text, 4 a Boolean, 16 an error — so
    /// constants asked for 3 answer `A1:A2,A5`. A block of one cell is taken
    /// to mean the whole of the sheet that has been written on, the same way
    /// `Find` takes it. Where nothing answers, Excel raises rather than
    /// handing back an empty range.
    fn special_cells(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        let (kind, mask) = match args {
            [kind] | [kind, Value::Missing] => (sort_number(kind, "SpecialCells")?, 23),
            [kind, mask] => (
                sort_number(kind, "SpecialCells")?,
                sort_number(mask, "SpecialCells")?,
            ),
            _ => return Err("Range.SpecialCells takes a kind and what it may hold".to_string()),
        };
        // The last cell is the corner of everything written on the sheet, and
        // it does not depend on the block it was asked of.
        if kind == 11 {
            let used = self.used_range(range.sheet)?;
            return Ok(self.object(HostObject::Range(CellRange::single(CellAddress {
                sheet: used.sheet,
                row: used.end_row,
                column: used.end_column,
            }))));
        }
        let hunted = if range.is_single() {
            self.used_range(range.sheet)?
        } else {
            range
        };
        Self::range_cell_count(hunted)?;

        let mut found = Vec::new();
        for address in hunted.addresses() {
            let cell = self
                .workbook
                .sheets
                .get(address.sheet)
                .and_then(|sheet| sheet.rows.iter().find(|row| row.index == address.row))
                .and_then(|row| row.cells.iter().find(|cell| cell.col == address.column));
            let wanted = match kind {
                4 => cell.is_none_or(|cell| {
                    cell.formula.is_none() && matches!(cell.value, CellValue::Empty)
                }),
                12 => !self.is_cell_hidden(address),
                2 | -4123 => cell.is_some_and(|cell| {
                    let by_formula = cell.formula.is_some();
                    let holds_something = by_formula || !matches!(cell.value, CellValue::Empty);
                    holds_something
                        && by_formula == (kind == -4123)
                        && value_answers(&cell.value, mask)
                }),
                other => return Err(format!("Range.SpecialCells cannot look for {other}")),
            };
            if wanted {
                found.push(CellRange::single(address));
            }
        }
        if found.is_empty() {
            return Err("Range.SpecialCells found no cells like that".to_string());
        }
        self.blocks_object(found)
    }

    /// Work a function out the way the sheet would.
    ///
    /// Everything above is written out here because Excel answers it
    /// differently from the sheet. What is left is the same function the sheet
    /// has, so it is asked of the same engine the sheet is worked out with
    /// rather than written a second time.
    ///
    /// Two things are not the sheet's behaviour and are done here:
    /// `WorksheetFunction` RAISES where the sheet would show an error value —
    /// `Search("z", "abc")` raises in Excel where `=SEARCH("z","abc")` shows
    /// `#VALUE!` — and a name Excel does not carry is refused before the
    /// engine ever sees it.
    fn worksheet_function_from_engine(
        &mut self,
        name: &str,
        args: &[Value],
    ) -> Result<Value, String> {
        if vba_has_its_own(name) {
            return Err(format!(
                "WorksheetFunction has no {name}; VBA has one of its own"
            ));
        }
        // A trailing argument nobody passed is not an empty one: it is not
        // there at all, which is what the engine's own arity checks read.
        let mut given = args;
        while matches!(given.last(), Some(Value::Missing)) {
            given = &given[..given.len() - 1];
        }
        let mut asked = Vec::with_capacity(given.len());
        for value in given {
            asked.push(self.engine_argument(value)?);
        }
        // The engine's own dispatch is written in capitals, as the parser
        // hands names to it; a macro writes `Substitute` and would find
        // nothing at all.
        let asked_for = name.to_ascii_uppercase();
        match oxicells_calc::functions::call(&asked_for, &asked) {
            oxicells_calc::Value::Error(oxicells_calc::ExcelError::Name) => Err(format!(
                "WorksheetFunction.{name} is not supported in the browser"
            )),
            // Every other error is one the sheet would SHOW, so it is handed
            // back as a value and raised further up if the caller asked
            // through `WorksheetFunction`.
            oxicells_calc::Value::Error(other) => Ok(Value::Error(
                spreadsheet_error_number(other.as_str()),
            )),
            oxicells_calc::Value::Number(number) => Ok(numeric_result(number)),
            oxicells_calc::Value::Text(text) => Ok(Value::String(text)),
            oxicells_calc::Value::Logical(state) => Ok(Value::Boolean(state)),
            oxicells_calc::Value::Blank => Ok(Value::Empty),
        }
    }

    /// One argument, put the way the engine takes it. A range goes over as the
    /// block it is, so that a function reading down a column sees a column.
    fn engine_argument(&mut self, value: &Value) -> Result<oxicells_calc::functions::Arg, String> {
        use oxicells_calc::functions::{Arg, RangeData};
        if let Value::Object(object) = value {
            if let Some(range) = self.range(object) {
                Self::range_cell_count(range)?;
                let width = (range.end_column - range.start_column + 1) as usize;
                let height = (range.end_row - range.start_row + 1) as usize;
                let mut cells = Vec::with_capacity(width * height);
                for address in range.addresses() {
                    cells.push(engine_value(&self.cell_value(address)));
                }
                return Ok(Arg::Range(RangeData {
                    width,
                    height,
                    cells,
                }));
            }
            return Err("WorksheetFunction was handed something that is not a Range".to_string());
        }
        if let Value::Array(array) = value {
            let (width, height) = match array.dimensions.as_slice() {
                [rows] => (1, rows.length),
                [rows, columns] => (columns.length, rows.length),
                _ => return Err("WorksheetFunction takes an array of one or two axes".to_string()),
            };
            let cells = array.values.iter().map(engine_value).collect();
            return Ok(Arg::Range(RangeData {
                width,
                height,
                cells,
            }));
        }
        Ok(Arg::Value(engine_value(value)))
    }

    /// Whether a cell is out of sight, by its row or by its column.
    fn is_cell_hidden(&self, address: CellAddress) -> bool {
        let Some(sheet) = self.workbook.sheets.get(address.sheet) else {
            return false;
        };
        if sheet.hidden_cols.contains(&address.column) {
            return true;
        }
        sheet
            .rows
            .iter()
            .find(|row| row.index == address.row)
            .is_some_and(|row| row.hidden)
    }

    /// What `Application.Union` was handed.
    fn union_ranges(&mut self, args: &[Value]) -> Result<Value, String> {
        let mut given = Vec::new();
        for value in args {
            if matches!(value, Value::Missing) {
                continue;
            }
            let Value::Object(object) = value else {
                return Err("Application.Union takes Ranges".to_string());
            };
            match self.range(object) {
                Some(range) => given.push(range),
                None => match self.blocks(object) {
                    Some(blocks) => given.extend_from_slice(blocks),
                    None => return Err("Application.Union takes Ranges".to_string()),
                },
            }
        }
        if given.len() < 2 {
            return Err("Application.Union needs two Ranges or more".to_string());
        }
        if given.iter().any(|block| block.sheet != given[0].sheet) {
            return Err("Application.Union cannot join ranges on different worksheets".to_string());
        }
        self.blocks_object(given)
    }

    /// What one of these answers to. Anything else says it is not available,
    /// rather than answering for the first block alone.
    fn blocks_member(
        &mut self,
        handle: usize,
        name: &str,
        args: &[Value],
    ) -> Result<Option<Value>, String> {
        let areas = self.blocks[handle].clone();
        if name.eq_ignore_ascii_case("areas") {
            return match args {
                [] | [Value::Missing] => Ok(Some(self.object(HostObject::Areas(handle)))),
                [wanted] => {
                    let at = positive_index(wanted, "index")? as usize;
                    let block = areas
                        .get(at - 1)
                        .ok_or_else(|| format!("this range has no area number {at}"))?;
                    Ok(Some(self.object(HostObject::Range(*block))))
                }
                _ => Err("Areas takes one number".to_string()),
            };
        }
        if name.eq_ignore_ascii_case("address") {
            let mut written = Vec::with_capacity(areas.len());
            for block in &areas {
                written.push(self.range_address_from_args(*block, args)?);
            }
            return Ok(Some(Value::String(written.join(","))));
        }
        if name.eq_ignore_ascii_case("count") {
            let mut total = 0u64;
            for block in &areas {
                total += Self::range_cell_count_large(*block)?;
            }
            return Ok(Some(Value::Integer(total as i64)));
        }
        // Excel answers for the FIRST block where a many-block range has to
        // give one answer: `Union(A1:A2, C1:C2).Rows.Count` is 2, and `.Row`
        // and `.Column` are the first block's corner.
        if name.eq_ignore_ascii_case("row") {
            return Ok(Some(Value::Integer(i64::from(areas[0].start_row))));
        }
        if name.eq_ignore_ascii_case("column") {
            return Ok(Some(Value::Integer(i64::from(areas[0].start_column) + 1)));
        }
        if name.eq_ignore_ascii_case("rows") || name.eq_ignore_ascii_case("columns") {
            let axis = if name.eq_ignore_ascii_case("rows") {
                RangeAxis::Rows
            } else {
                RangeAxis::Columns
            };
            return self
                .range_collection_object_or_item(areas[0], axis, args)
                .map(Some);
        }
        if name.eq_ignore_ascii_case("cells") {
            return self.range_cells_object(areas[0], args).map(Some);
        }
        if name.eq_ignore_ascii_case("worksheet") || name.eq_ignore_ascii_case("parent") {
            return Ok(Some(self.object(HostObject::Worksheet(areas[0].sheet))));
        }
        // Measured: `Range("A1,C1").Comment` answers the note on A1.
        if name.eq_ignore_ascii_case("comment") && args.is_empty() {
            return Ok(Some(self.comment_of(areas[0])));
        }
        // What a many-block range holds is its FIRST block's: asked of Excel,
        // `.Value` answers for that block alone. What it SHOWS is the uniform
        // answer over all of them, the same rule one block follows about its
        // own cells.
        if name.eq_ignore_ascii_case("value")
            || name.eq_ignore_ascii_case("value2")
            || name.eq_ignore_ascii_case("formula")
            || name.eq_ignore_ascii_case("formula2")
        {
            let first = self.object(HostObject::Range(areas[0]));
            let Value::Object(first) = first else {
                return Err("a block could not be spoken to".to_string());
            };
            return self.get(&first, name);
        }
        if name.eq_ignore_ascii_case("text") || name.eq_ignore_ascii_case("numberformat") {
            return self.get_from_every_block(handle, None, name);
        }
        // A dress worn by every block, not by the first alone: asked of Excel,
        // colouring `Union(A1:A2, C1:C2)` colours C2 as well as A1.
        if name.eq_ignore_ascii_case("font") {
            return Ok(Some(
                self.object(HostObject::BlocksStyle(handle, StyleFace::Font)),
            ));
        }
        if name.eq_ignore_ascii_case("interior") {
            return Ok(Some(
                self.object(HostObject::BlocksStyle(handle, StyleFace::Interior)),
            ));
        }
        if name.eq_ignore_ascii_case("borders") {
            let selection = match args {
                [] | [Value::Missing] => BorderSelection::All,
                [wanted] => border_selection(wanted)?,
                _ => return Err("Range.Borders takes one index".to_string()),
            };
            return Ok(Some(
                self.object(HostObject::BlocksStyle(handle, StyleFace::Borders(selection))),
            ));
        }
        Ok(None)
    }

    /// Ask every block what would be asked of one, and see whether they agree.
    ///
    /// Asked of Excel, `Union(A1:A2, C1:C2)` where both blocks are red answers
    /// 255, and where one is red and the other green it answers Null — save
    /// for a fill, which answers 0, the same one-off it makes about cells that
    /// disagree within one block.
    fn get_from_every_block(
        &mut self,
        handle: usize,
        face: Option<StyleFace>,
        name: &str,
    ) -> Result<Option<Value>, String> {
        let areas = self.blocks[handle].clone();
        let mut agreed: Option<Value> = None;
        for block in areas {
            let one = match face {
                None => self.object(HostObject::Range(block)),
                Some(StyleFace::Font) => self.object(HostObject::RangeFont(block)),
                Some(StyleFace::Interior) => self.object(HostObject::RangeInterior(block)),
                Some(StyleFace::Borders(selection)) => {
                    self.object(HostObject::RangeBorders(block, selection))
                }
            };
            let Value::Object(one) = one else {
                return Err("a block could not be spoken to".to_string());
            };
            let Some(said) = self.get(&one, name)? else {
                return Ok(None);
            };
            match &agreed {
                None => agreed = Some(said),
                Some(held) if *held == said => {}
                Some(_) => {
                    let fill = matches!(face, Some(StyleFace::Interior))
                        && name.eq_ignore_ascii_case("color");
                    return Ok(Some(if fill { Value::Integer(BLACK) } else { Value::Null }));
                }
            }
        }
        Ok(agreed)
    }

    /// Do to every block what would be done to one.
    ///
    /// The single-block path is the one that knows each member; this hands it
    /// the blocks one at a time so that the two cannot drift apart.
    fn set_on_every_block(
        &mut self,
        handle: usize,
        face: Option<StyleFace>,
        name: &str,
        value: Value,
    ) -> Result<bool, String> {
        let areas = self.blocks[handle].clone();
        let mut answered = false;
        for block in areas {
            let one = match face {
                None => self.object(HostObject::Range(block)),
                Some(StyleFace::Font) => self.object(HostObject::RangeFont(block)),
                Some(StyleFace::Interior) => self.object(HostObject::RangeInterior(block)),
                Some(StyleFace::Borders(selection)) => {
                    self.object(HostObject::RangeBorders(block, selection))
                }
            };
            let Value::Object(one) = one else {
                return Err("a block could not be spoken to".to_string());
            };
            answered = self.set(&one, name, value.clone())?;
        }
        Ok(answered)
    }

    fn is_names(&self, object: &ObjectRef) -> bool {
        matches!(self.objects.get(object.handle as usize), Some(HostObject::Names))
    }

    /// The text of the name a `Name` object was handed out for.
    fn held_name(&self, object: &ObjectRef) -> Option<&str> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::DefinedName(handle)) => {
                self.name_handles.get(*handle).map(String::as_str)
            }
            _ => None,
        }
    }

    fn name_object(&mut self, name: &str) -> Value {
        let handle = self.name_handles.len();
        self.name_handles.push(name.to_string());
        self.object(HostObject::DefinedName(handle))
    }

    /// Where the workbook keeps that name, whatever case it was asked in.
    /// Where a name is kept, whether it was asked for with its sheet or
    /// without.
    ///
    /// A sheet-scoped name is stored as Excel reports it, `Sheet1!loc`, and a
    /// macro that writes `Range("loc")` still has to find it. Asked with the
    /// sheet, only the exact one answers.
    fn name_at(&self, name: &str) -> Option<usize> {
        if let Some(at) = self
            .workbook
            .defined_names
            .iter()
            .position(|(held, _)| held.eq_ignore_ascii_case(name))
        {
            return Some(at);
        }
        if name.contains('!') {
            return None;
        }
        self.workbook.defined_names.iter().position(|(held, _)| {
            held.rsplit_once('!')
                .is_some_and(|(_, leaf)| leaf.eq_ignore_ascii_case(name))
        })
    }

    /// The theme colour and tint every cell of a range agrees on for one
    /// painted part: None when they disagree, Some(None) when none of them
    /// has one.
    fn uniform_theme_paint(
        &self,
        range: CellRange,
        paint: Paint,
    ) -> Result<Option<Option<(usize, f64)>>, String> {
        Self::range_cell_count(range)?;
        let mut first: Option<Option<(usize, f64)>> = None;
        for address in range.addresses() {
            let held = self.theme_paint.get(&(address, paint)).copied();
            if first.is_some_and(|seen| seen != held) {
                return Ok(None);
            }
            first = Some(held);
        }
        Ok(Some(first.flatten()))
    }

    fn forget_theme_paint(&mut self, range: CellRange, paint: Paint) {
        for address in self.touched(range) {
            self.theme_paint.remove(&(address, paint));
        }
    }

    /// Paint a part of every cell from the theme, and remember that it was.
    /// Measured: giving a theme colour puts the tint back to 0, and giving a
    /// tint keeps the theme colour -- or, where there was none, tints the
    /// part's plain colour, black for writing and edges.
    fn paint_from_theme(
        &mut self,
        range: CellRange,
        paint: Paint,
        theme: Option<usize>,
        tint: Option<f64>,
    ) -> Result<(), String> {
        Self::sized(range)?;
        for address in self.touched(range) {
            let held = self.theme_paint.get(&(address, paint)).copied();
            // A shade given to a cell that was coloured by NUMBER, not from
            // the theme, tints that plain colour and is not itself a theme
            // paint -- so `.TintAndShade = 0` after `.Color` leaves the
            // colour alone, as Excel does. A shade on a bare part tints the
            // theme's default.
            if theme.is_none() && held.is_none() {
                let plain = match paint {
                    Paint::Font => self.uniform_style(range, |style| style.font_color.clone())?.flatten(),
                    Paint::Interior => self.uniform_style(range, |style| style.bg_color.clone())?.flatten(),
                    Paint::Edge(_) => None,
                };
                if let Some(plain) = plain {
                    let shade = tint.unwrap_or(0.0);
                    let colour = colour_from_packed(tinted(colour_to_packed(Some(&plain)).unwrap_or(0), shade));
                    let one = CellRange::single(address);
                    match paint {
                        Paint::Font => self.set_range_style(one, |_, style| style.font_color = Some(colour.clone()))?,
                        Paint::Interior => self.set_range_style(one, |_, style| style.bg_color = Some(colour.clone()))?,
                        Paint::Edge(_) => {}
                    }
                    continue;
                }
            }
            let (held_theme, held_tint) = held.unwrap_or((if paint == Paint::Interior { 1 } else { 2 }, 0.0));
            let (theme, tint) = match (theme, tint) {
                (Some(theme), _) => (theme, 0.0),
                (None, Some(tint)) => (held_theme, tint),
                (None, None) => (held_theme, held_tint),
            };
            let colour = colour_from_packed(tinted(THEME_COLOURS[theme - 1], tint));
            let one = CellRange::single(address);
            match paint {
                Paint::Font => {
                    self.set_range_style(one, |_, style| style.font_color = Some(colour.clone()))?
                }
                Paint::Interior => {
                    self.set_range_style(one, |_, style| style.bg_color = Some(colour.clone()))?
                }
                Paint::Edge(selection) => self.set_range_style(one, |at, style| {
                    recolour_selected_borders(style, at, range, selection, Some(&colour));
                })?,
            }
            self.theme_paint
                .insert((address, paint), (theme, quantised_tint(tint)));
        }
        Ok(())
    }

    fn style_index(&self, object: &ObjectRef) -> Option<usize> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::Style(index)) => Some(*index),
            _ => None,
        }
    }

    fn is_styles(&self, object: &ObjectRef) -> bool {
        matches!(self.objects.get(object.handle as usize), Some(HostObject::Styles))
    }

    /// The style a range wears: the one its cells all wear, or Nothing when
    /// they differ -- measured, `Range("C3:C6").Style.Name` over a Percent
    /// cell and a Comma cell is error 91.
    fn style_of(&mut self, range: CellRange) -> Value {
        let mut seen: Option<usize> = None;
        for address in range.addresses() {
            let held = self.styled.get(&address).copied().unwrap_or(NORMAL_STYLE);
            match seen {
                None => seen = Some(held),
                Some(first) if first == held => {}
                Some(_) => return Value::Nothing,
            }
        }
        self.object(HostObject::Style(seen.unwrap_or(NORMAL_STYLE)))
    }

    /// The styles the workbook lists, in the order `Styles(n)` counts them:
    /// the table's, with `Hyperlink` left out until a hyperlink has been
    /// added and then in its alphabetical place.
    fn listed_styles(&self) -> Vec<usize> {
        let mut listed: Vec<usize> = (0..HYPERLINK_STYLE).collect();
        if self.linked_once {
            listed.insert(HYPERLINK_LISTED_AT, HYPERLINK_STYLE);
        }
        listed
    }

    /// `Styles(n)` / `Styles("Percent")`.
    fn style_item(&mut self, wanted: &Value) -> Result<Value, String> {
        let index = match wanted {
            Value::String(name) => built_in_style(name)
                .filter(|index| *index != HYPERLINK_STYLE || self.linked_once)
                .ok_or_else(|| host_error(450, format!("there is no style {name:?}")))?,
            value => {
                let index = positive_index(value, "Styles index")? as usize;
                let listed = self.listed_styles();
                *listed
                    .get(index - 1)
                    .ok_or_else(|| format!("the workbook has no style number {index}"))?
            }
        };
        Ok(self.object(HostObject::Style(index)))
    }

    /// What a Style answers to.
    fn style_member(&mut self, index: usize, name: &str) -> Result<Option<Value>, String> {
        let style = &BUILT_IN_STYLES[index];
        let answer = if name.eq_ignore_ascii_case("name") || name.eq_ignore_ascii_case("value") {
            Value::String(style.name.to_string())
        } else if name.eq_ignore_ascii_case("namelocal") {
            Value::String(style.local.to_string())
        } else if name.eq_ignore_ascii_case("builtin") {
            Value::Boolean(true)
        } else if name.eq_ignore_ascii_case("includenumber") {
            Value::Boolean(style.number.is_some())
        } else if name.eq_ignore_ascii_case("includefont") {
            Value::Boolean(style.font.is_some())
        } else if name.eq_ignore_ascii_case("includealignment") {
            Value::Boolean(style.alignment)
        } else if name.eq_ignore_ascii_case("includeborder") {
            Value::Boolean(style.borders.is_some())
        } else if name.eq_ignore_ascii_case("includepatterns") {
            Value::Boolean(style.fill.is_some())
        } else if name.eq_ignore_ascii_case("includeprotection") {
            Value::Boolean(style.protection)
        } else if name.eq_ignore_ascii_case("numberformat") {
            Value::String(style.number.unwrap_or("General").to_string())
        } else {
            return Ok(None);
        };
        Ok(Some(answer))
    }

    /// `Range.Style = "Percent"`: put the style's parts onto every cell and
    /// remember which style it was.
    fn apply_style(&mut self, range: CellRange, index: usize) -> Result<(), String> {
        Self::sized(range)?;
        let style = &BUILT_IN_STYLES[index];
        let font = style.font.as_ref().map(|font| {
            (
                font.bold,
                font.italic,
                font.underline,
                font.size,
                font.name.map(str::to_string),
                font.color.map(colour_from_packed),
            )
        });
        let fill = style.fill.map(|fill| fill.map(colour_from_packed));
        let borders = style.borders.map(|edges| {
            edges.map(|edge| {
                edge.map(|(kind, colour)| BorderLine {
                    style: kind.to_string(),
                    color: Some(colour_from_packed(colour)),
                })
            })
        });
        let number = style.number.map(|format| {
            if format == "General" { None } else { Some(format.to_string()) }
        });
        let alignment = style.alignment;
        self.set_range_style(range, |_, held| {
            if let Some(number) = &number {
                held.number_format = number.clone();
            }
            if let Some((bold, italic, underline, size, name, color)) = &font {
                held.bold = *bold;
                held.italic = *italic;
                held.underline = *underline;
                held.strikethrough = false;
                held.font_size = if *size == 11.0 { None } else { Some(*size) };
                held.font_name = name.clone();
                held.font_color = color.clone();
            }
            if let Some(fill) = &fill {
                held.bg_color = fill.clone();
            }
            if let Some([left, top, bottom, right]) = &borders {
                held.border_left = left.clone();
                held.border_top = top.clone();
                held.border_bottom = bottom.clone();
                held.border_right = right.clone();
            }
            if alignment {
                held.horizontal_align = None;
                held.vertical_align = None;
                held.wrap_text = false;
                held.indent = 0;
            }
        })?;
        if style.protection {
            for address in self.touched(range) {
                self.unlocked.remove(&address);
            }
        }
        let (font_theme, fill_theme, paints_font, paints_fill) = (
            style.font_theme,
            style.fill_theme,
            style.font.is_some(),
            style.fill.is_some(),
        );
        for address in self.touched(range) {
            if index == NORMAL_STYLE {
                self.styled.remove(&address);
            } else {
                self.styled.insert(address, index);
            }
            if paints_font {
                match font_theme {
                    Some(theme) => {
                        self.theme_paint.insert((address, Paint::Font), (theme, 0.0));
                    }
                    None => {
                        self.theme_paint.remove(&(address, Paint::Font));
                    }
                }
            }
            if paints_fill {
                match fill_theme {
                    Some((theme, shade)) => {
                        self.theme_paint
                            .insert((address, Paint::Interior), (theme, quantised_tint(shade)));
                    }
                    None => {
                        self.theme_paint.remove(&(address, Paint::Interior));
                    }
                }
            }
        }
        Ok(())
    }

    fn link_id(&self, object: &ObjectRef) -> Option<u64> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::Hyperlink(id)) => Some(*id),
            _ => None,
        }
    }

    fn hyperlink_scope(&self, object: &ObjectRef) -> Option<HyperlinkScope> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::Hyperlinks(scope)) => Some(*scope),
            _ => None,
        }
    }

    /// The hyperlinks a scope reaches, in the order they were added --
    /// measured, `Hyperlinks(1)` is the first one added, not the highest on
    /// the sheet.
    fn links_in(&self, scope: HyperlinkScope) -> Vec<u64> {
        self.links
            .iter()
            .filter(|link| match scope {
                HyperlinkScope::Sheet(sheet) => link.anchor.sheet == sheet,
                HyperlinkScope::Range(range) => ranges_overlap(link.anchor, range),
            })
            .map(|link| link.id)
            .collect()
    }

    fn link_index(&self, id: u64) -> Option<usize> {
        self.links.iter().position(|link| link.id == id)
    }

    /// `Hyperlinks.Add Anchor, Address, SubAddress, ScreenTip, TextToDisplay`.
    ///
    /// Measured: the anchor's first cell shows `TextToDisplay` when given;
    /// else, when it is empty, the address as kept, or the sub-address for a
    /// link with no address; a cell with something in it keeps it. The cells
    /// are dressed in the `Hyperlink`
    /// style -- the theme's hyperlink colour, underlined. A second link on the
    /// same anchor takes the first one's place and leaves the text alone.
    fn add_hyperlink(&mut self, args: &[Value]) -> Result<Value, String> {
        let given = |index: usize| match args.get(index) {
            Some(Value::Missing) | None => None,
            Some(value) => Some(value),
        };
        let anchor = match given(0) {
            Some(Value::Object(object)) => self
                .range(object)
                .ok_or_else(|| "Hyperlinks.Add needs a Range as its anchor".to_string())?,
            _ => return Err("Hyperlinks.Add needs a Range as its anchor".to_string()),
        };
        let text_of = |value: Option<&Value>| -> Result<String, String> {
            match value {
                None => Ok(String::new()),
                Some(Value::String(text)) => Ok(text.clone()),
                Some(value) if any_number(value).is_some() => Ok(shown_text(value, None)),
                Some(_) => Err("Hyperlinks.Add takes text".to_string()),
            }
        };
        let address = kept_address(&text_of(given(1))?);
        let sub_address = text_of(given(2))?;
        let screen_tip = text_of(given(3))?;
        let shown = match given(4) {
            None => None,
            Some(value) => Some(text_of(Some(value))?),
        };
        let corner = CellAddress {
            sheet: anchor.sheet,
            row: anchor.start_row,
            column: anchor.start_column,
        };
        let empty = self
            .cell_here(corner.sheet, corner.row, corner.column)
            .is_none_or(|cell| matches!(cell.value, CellValue::Empty) && cell.formula.is_none());
        let text = match shown {
            Some(text) => Some(text),
            None if empty => Some(if address.is_empty() {
                sub_address.clone()
            } else {
                address.clone()
            }),
            None => None,
        };
        if let Some(text) = text {
            self.set_cell_value(corner, CellValue::String(text))?;
        }
        // A link added where one already hangs takes its place -- the same
        // number, the same position in the list: measured, `Hyperlinks(1)` is
        // still the first cell after a second `Add` on it.
        let id = match self.links.iter_mut().find(|link| ranges_equal(link.anchor, anchor)) {
            Some(link) => {
                link.address = address;
                link.sub_address = sub_address;
                link.screen_tip = screen_tip;
                link.id
            }
            None => {
                let id = self.next_link;
                self.next_link += 1;
                self.links.push(Link {
                    id,
                    anchor,
                    address,
                    sub_address,
                    screen_tip,
                });
                id
            }
        };
        self.linked_once = true;
        self.apply_style(anchor, HYPERLINK_STYLE)?;
        Ok(self.object(HostObject::Hyperlink(id)))
    }

    /// Take the hyperlinks off; the cells go back to `Normal`, as measured,
    /// unless told to keep their dress -- `ClearContents` does that.
    fn delete_links(&mut self, ids: &[u64], keep_dress: bool) -> Result<(), String> {
        for id in ids {
            let Some(index) = self.link_index(*id) else {
                continue;
            };
            let anchor = self.links.remove(index).anchor;
            if !keep_dress {
                self.apply_style(anchor, NORMAL_STYLE)?;
            }
        }
        Ok(())
    }

    /// What one hyperlink answers to.
    fn hyperlink_member(
        &mut self,
        id: u64,
        name: &str,
        args: &[Value],
    ) -> Result<Option<Value>, String> {
        let Some(index) = self.link_index(id) else {
            return Err("the hyperlink has been deleted".to_string());
        };
        let corner = CellAddress {
            sheet: self.links[index].anchor.sheet,
            row: self.links[index].anchor.start_row,
            column: self.links[index].anchor.start_column,
        };
        let answer = if name.eq_ignore_ascii_case("address") || name.eq_ignore_ascii_case("name")
        {
            Value::String(self.links[index].address.clone())
        } else if name.eq_ignore_ascii_case("subaddress") {
            Value::String(self.links[index].sub_address.clone())
        } else if name.eq_ignore_ascii_case("screentip") {
            Value::String(self.links[index].screen_tip.clone())
        } else if name.eq_ignore_ascii_case("texttodisplay") {
            self.range_text(CellRange::single(corner))
        } else if name.eq_ignore_ascii_case("range") || name.eq_ignore_ascii_case("parent") {
            let anchor = self.links[index].anchor;
            self.object(HostObject::Range(anchor))
        } else if name.eq_ignore_ascii_case("type") {
            // msoHyperlinkRange.
            Value::Integer(1)
        } else if name.eq_ignore_ascii_case("delete") {
            if !args.is_empty() {
                return Err("Hyperlink.Delete does not accept arguments".to_string());
            }
            self.delete_links(&[id], false)?;
            Value::Empty
        } else if name.eq_ignore_ascii_case("follow") {
            // Nothing here can open it; the macro goes on.
            Value::Empty
        } else {
            return Ok(None);
        };
        Ok(Some(answer))
    }

    /// `Hyperlinks(n)` for a scope.
    fn hyperlink_item(&mut self, scope: HyperlinkScope, wanted: &Value) -> Result<Value, String> {
        let index = positive_index(wanted, "Hyperlinks index")? as usize;
        let held = self.links_in(scope);
        let Some(&id) = held.get(index - 1) else {
            return Err(format!("there is no hyperlink number {index} here"));
        };
        Ok(self.object(HostObject::Hyperlink(id)))
    }

    /// What a `Hyperlinks` collection answers to.
    fn hyperlinks_member(
        &mut self,
        scope: HyperlinkScope,
        name: &str,
        args: &[Value],
    ) -> Result<Option<Value>, String> {
        if name.eq_ignore_ascii_case("count") {
            return Ok(Some(Value::Integer(self.links_in(scope).len() as i64)));
        }
        if name.eq_ignore_ascii_case("item") {
            let [wanted] = args else {
                return Err("Hyperlinks.Item takes one number".to_string());
            };
            return self.hyperlink_item(scope, wanted).map(Some);
        }
        if name.eq_ignore_ascii_case("add") {
            return self.add_hyperlink(args).map(Some);
        }
        if name.eq_ignore_ascii_case("delete") {
            let ids = self.links_in(scope);
            self.delete_links(&ids, false)?;
            return Ok(Some(Value::Empty));
        }
        Ok(None)
    }

    fn page_setup_sheet(&self, object: &ObjectRef) -> Option<usize> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::PageSetup(sheet)) => Some(*sheet),
            _ => None,
        }
    }

    /// How the print area is written: every block absolute, joined by
    /// commas.
    fn print_area_text(&self, sheet: usize) -> String {
        self.page_setups
            .get(&sheet)
            .map(|setup| {
                setup
                    .print_area
                    .iter()
                    .map(|block| format_range_address(*block, true, true))
                    .collect::<Vec<_>>()
                    .join(",")
            })
            .unwrap_or_default()
    }

    /// Keep the sheet-scoped names Excel keeps for these: `Print_Area` for
    /// the print area and `Print_Titles` for the title columns, then rows.
    /// Measured: `PrintArea = "$A$1:$C$5"` makes `Sheet1!Print_Area` with
    /// `=Sheet1!$A$1:$C$5`, and clearing it takes the name away.
    fn refresh_print_names(&mut self, sheet: usize) {
        let sheet_name = self.workbook.sheets[sheet].name.clone();
        let quoted = quoted_sheet(&sheet_name);
        let setup = self.page_setups.get(&sheet).cloned().unwrap_or_default();
        let area_name = format!("{sheet_name}!Print_Area");
        let titles_name = format!("{sheet_name}!Print_Titles");
        self.workbook
            .defined_names
            .retain(|(name, _)| !name.eq_ignore_ascii_case(&area_name) && !name.eq_ignore_ascii_case(&titles_name));
        if !setup.print_area.is_empty() {
            let refers_to = setup
                .print_area
                .iter()
                .map(|block| format!("{quoted}!{}", format_range_address(*block, true, true)))
                .collect::<Vec<_>>()
                .join(",");
            self.workbook.defined_names.push((area_name, refers_to));
        }
        let mut titles = Vec::new();
        if let Some((first, last)) = setup.print_title_columns {
            titles.push(format!(
                "{quoted}!${}:${}",
                oxicells_core::editor::col_to_letter(first),
                oxicells_core::editor::col_to_letter(last)
            ));
        }
        if let Some((first, last)) = setup.print_title_rows {
            titles.push(format!("{quoted}!${first}:${last}"));
        }
        if !titles.is_empty() {
            self.workbook.defined_names.push((titles_name, titles.join(",")));
        }
    }

    /// What `PageSetup` answers to.
    fn page_setup_member(&mut self, sheet: usize, name: &str) -> Result<Option<Value>, String> {
        let setup = self.page_setups.get(&sheet).cloned().unwrap_or_default();
        let answer = match name.to_ascii_lowercase().as_str() {
            "orientation" => Value::Integer(setup.orientation),
            "papersize" => Value::Integer(setup.paper_size),
            "zoom" => match setup.zoom {
                Some(zoom) => Value::Integer(zoom),
                None => Value::Boolean(false),
            },
            "fittopageswide" => match setup.fit_to_pages_wide {
                Some(pages) => Value::Integer(pages),
                None => Value::Boolean(false),
            },
            "fittopagestall" => match setup.fit_to_pages_tall {
                Some(pages) => Value::Integer(pages),
                None => Value::Boolean(false),
            },
            "leftmargin" => Value::Double(setup.left_margin),
            "rightmargin" => Value::Double(setup.right_margin),
            "topmargin" => Value::Double(setup.top_margin),
            "bottommargin" => Value::Double(setup.bottom_margin),
            "headermargin" => Value::Double(setup.header_margin),
            "footermargin" => Value::Double(setup.footer_margin),
            "printarea" => Value::String(self.print_area_text(sheet)),
            "printtitlerows" => Value::String(
                setup
                    .print_title_rows
                    .map(|(first, last)| format!("${first}:${last}"))
                    .unwrap_or_default(),
            ),
            "printtitlecolumns" => Value::String(
                setup
                    .print_title_columns
                    .map(|(first, last)| {
                        format!(
                            "${}:${}",
                            oxicells_core::editor::col_to_letter(first),
                            oxicells_core::editor::col_to_letter(last)
                        )
                    })
                    .unwrap_or_default(),
            ),
            "centerhorizontally" => Value::Boolean(setup.center_horizontally),
            "centervertically" => Value::Boolean(setup.center_vertically),
            "leftheader" => Value::String(setup.headers[0].clone()),
            "centerheader" => Value::String(setup.headers[1].clone()),
            "rightheader" => Value::String(setup.headers[2].clone()),
            "leftfooter" => Value::String(setup.headers[3].clone()),
            "centerfooter" => Value::String(setup.headers[4].clone()),
            "rightfooter" => Value::String(setup.headers[5].clone()),
            "printgridlines" => Value::Boolean(setup.print_gridlines),
            "printheadings" => Value::Boolean(setup.print_headings),
            "firstpagenumber" => Value::Integer(setup.first_page_number),
            "order" => Value::Integer(setup.order),
            "blackandwhite" => Value::Boolean(setup.black_and_white),
            "draft" => Value::Boolean(setup.draft),
            "printerrors" => Value::Integer(setup.print_errors),
            "printcomments" => Value::Integer(setup.print_comments),
            "scalewithdocheaderfooter" => Value::Boolean(setup.scale_with_doc),
            "alignmarginsheaderfooter" => Value::Boolean(setup.align_margins),
            "differentfirstpageheaderfooter" => Value::Boolean(setup.different_first_page),
            "oddandevenpagesheaderfooter" => Value::Boolean(setup.odd_and_even),
            "parent" => self.object(HostObject::Worksheet(sheet)),
            _ => return Ok(None),
        };
        Ok(Some(answer))
    }

    /// Set one part of a sheet's page setup. Measured: Orientation takes 1
    /// or 2 and is 1004 for 3; Zoom takes 10 to 400, whole, or False; a
    /// pages count takes 1 up or False; PaperSize 0 or 300 is 1004; a margin
    /// takes any number, -1 and 10000 included, and text is 1004; Order is
    /// 1 or 2; PrintErrors 0 to 3 and 9 is error 5.
    /// A recorder writes every PageSetup member; the ones this build does
    /// not keep are taken without a word.
    fn set_page_setup(&mut self, sheet: usize, name: &str, value: Value) -> Result<bool, String> {
        // The recorder-written members this build keeps nothing of, taken
        // without a word (the ones it DOES keep are handled below).
        if matches!(
            name.to_ascii_lowercase().as_str(),
            "printcomments" | "printquality" | "scale"
                | "oddandevenpagesheaderfooter" | "differentfirstpageheaderfooter"
                | "scaletofitpages" | "alignmargins" | "papersize2"
        ) {
            return Ok(true);
        }
        let mut setup = self.page_setups.get(&sheet).cloned().unwrap_or_default();
        let number = || -> Result<f64, String> {
            any_number(&value).ok_or_else(|| "PageSetup takes a number here".to_string())
        };
        let flag = || style_face_boolean(&value, "PageSetup");
        let text = || -> Result<String, String> {
            match &value {
                Value::String(text) => Ok(text.clone()),
                other if any_number(other).is_some() => Ok(shown_text(other, None)),
                _ => Err("PageSetup takes text here".to_string()),
            }
        };
        // A count that may be False: pages wide or tall.
        let pages = |held: Option<i64>| -> Result<Option<i64>, String> {
            if matches!(value, Value::Boolean(false)) {
                return Ok(None);
            }
            let asked = number()?;
            if asked < 1.0 {
                return Err("a page count starts at 1".to_string());
            }
            let _ = held;
            Ok(Some(asked as i64))
        };
        let lower = name.to_ascii_lowercase();
        match lower.as_str() {
            "orientation" => {
                let asked = number()? as i64;
                if !(1..=2).contains(&asked) {
                    return Err("Orientation is xlPortrait or xlLandscape".to_string());
                }
                setup.orientation = asked;
            }
            "papersize" => {
                let asked = number()? as i64;
                if !((1..=118).contains(&asked) || asked == 256) {
                    return Err(format!("{asked} is not a paper size"));
                }
                setup.paper_size = asked;
            }
            "zoom" => {
                if matches!(value, Value::Boolean(false)) {
                    setup.zoom = None;
                } else {
                    let asked = number()?.trunc() as i64;
                    if !(10..=400).contains(&asked) {
                        return Err("Zoom runs from 10 to 400".to_string());
                    }
                    setup.zoom = Some(asked);
                }
            }
            "fittopageswide" => setup.fit_to_pages_wide = pages(setup.fit_to_pages_wide)?,
            "fittopagestall" => setup.fit_to_pages_tall = pages(setup.fit_to_pages_tall)?,
            "leftmargin" => setup.left_margin = number()?,
            "rightmargin" => setup.right_margin = number()?,
            "topmargin" => setup.top_margin = number()?,
            "bottommargin" => setup.bottom_margin = number()?,
            "headermargin" => setup.header_margin = number()?,
            "footermargin" => setup.footer_margin = number()?,
            "printarea" => {
                // Measured: `""` and False clear it; `A1:B2` is kept as
                // `$A$1:$B$2`; several blocks keep their commas; text that
                // is no address is 1004 and leaves what was there.
                if matches!(value, Value::Boolean(false)) {
                    setup.print_area.clear();
                } else {
                    let asked = text()?;
                    if asked.trim().is_empty() {
                        setup.print_area.clear();
                    } else {
                        let mut blocks = Vec::new();
                        for piece in asked.split(',') {
                            let object = self.range_object(
                                sheet,
                                &[Value::String(piece.trim().to_string())],
                                NameReach::ThisSheet,
                            )?;
                            let Value::Object(object) = object else {
                                return Err("the print area is not an address".to_string());
                            };
                            match self.range(&object) {
                                Some(block) => blocks.push(block),
                                None => match self.blocks(&object) {
                                    Some(held) => blocks.extend(held.iter().copied()),
                                    None => return Err("the print area is not an address".to_string()),
                                },
                            }
                        }
                        setup.print_area = blocks;
                    }
                }
            }
            "printtitlerows" | "printtitlecolumns" => {
                // Measured: `$1:$2`, `1:1` and `A3:B4` all set rows -- the
                // last as `$3:$4` -- and two row bands are 1004; `""` clears.
                let asked = text()?;
                let held = if asked.trim().is_empty() {
                    None
                } else {
                    if asked.contains(',') {
                        return Err("the print titles are one band of rows or columns".to_string());
                    }
                    let object = self.range_object(
                        sheet,
                        &[Value::String(asked.trim().to_string())],
                        NameReach::ThisSheet,
                    )?;
                    let Value::Object(object) = object else {
                        return Err("the print titles are not an address".to_string());
                    };
                    let block = self
                        .range(&object)
                        .ok_or_else(|| "the print titles are one band of rows or columns".to_string())?;
                    Some(if lower == "printtitlerows" {
                        (block.start_row, block.end_row)
                    } else {
                        (block.start_column, block.end_column)
                    })
                };
                if lower == "printtitlerows" {
                    setup.print_title_rows = held;
                } else {
                    setup.print_title_columns = held;
                }
            }
            "centerhorizontally" => setup.center_horizontally = flag()?.unwrap_or(setup.center_horizontally),
            "centervertically" => setup.center_vertically = flag()?.unwrap_or(setup.center_vertically),
            "leftheader" => setup.headers[0] = text()?,
            "centerheader" => setup.headers[1] = text()?,
            "rightheader" => setup.headers[2] = text()?,
            "leftfooter" => setup.headers[3] = text()?,
            "centerfooter" => setup.headers[4] = text()?,
            "rightfooter" => setup.headers[5] = text()?,
            "printgridlines" => setup.print_gridlines = flag()?.unwrap_or(setup.print_gridlines),
            "printheadings" => setup.print_headings = flag()?.unwrap_or(setup.print_headings),
            "firstpagenumber" => setup.first_page_number = number()? as i64,
            "order" => {
                let asked = number()? as i64;
                if !(1..=2).contains(&asked) {
                    return Err("Order is xlDownThenOver or xlOverThenDown".to_string());
                }
                setup.order = asked;
            }
            "blackandwhite" => setup.black_and_white = flag()?.unwrap_or(setup.black_and_white),
            "draft" => setup.draft = flag()?.unwrap_or(setup.draft),
            "printerrors" => {
                let asked = number()? as i64;
                if !(0..=3).contains(&asked) {
                    return Err(host_error(5, "that is not a way of printing errors"));
                }
                setup.print_errors = asked;
            }
            "printcomments" => setup.print_comments = number()? as i64,
            "scalewithdocheaderfooter" => setup.scale_with_doc = flag()?.unwrap_or(setup.scale_with_doc),
            "alignmarginsheaderfooter" => setup.align_margins = flag()?.unwrap_or(setup.align_margins),
            "differentfirstpageheaderfooter" => {
                setup.different_first_page = flag()?.unwrap_or(setup.different_first_page)
            }
            "oddandevenpagesheaderfooter" => setup.odd_and_even = flag()?.unwrap_or(setup.odd_and_even),
            _ => return Ok(false),
        }
        self.page_setups.insert(sheet, setup);
        if matches!(lower.as_str(), "printarea" | "printtitlerows" | "printtitlecolumns") {
            self.refresh_print_names(sheet);
        }
        Ok(true)
    }

    fn list_objects_sheet(&self, object: &ObjectRef) -> Option<usize> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::ListObjects(sheet)) => Some(*sheet),
            _ => None,
        }
    }

    /// The table handle an object speaks for, and which part of the table.
    fn table_part(&self, object: &ObjectRef) -> Option<(u64, TablePart)> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::ListObject(id)) => Some((*id, TablePart::Whole)),
            Some(HostObject::ListRows(id)) => Some((*id, TablePart::Rows)),
            Some(HostObject::ListRow(id, index)) => Some((*id, TablePart::Row(*index))),
            Some(HostObject::ListColumns(id)) => Some((*id, TablePart::Columns)),
            Some(HostObject::ListColumn(id, index)) => Some((*id, TablePart::Column(*index))),
            _ => None,
        }
    }

    /// The handle of a sheet's table by its name, made if it has none yet:
    /// a table the file brought in gets a handle the first time it is asked
    /// for.
    fn table_handle(&mut self, sheet: usize, name: &str) -> u64 {
        if let Some((id, _, _)) = self
            .table_handles
            .iter()
            .find(|(_, held_sheet, held)| *held_sheet == sheet && held == name)
        {
            return *id;
        }
        let id = self.next_table;
        self.next_table += 1;
        self.table_handles.push((id, sheet, name.to_string()));
        id
    }

    /// Where a handle's table is: its sheet and its place in the sheet's
    /// tables, or 424 once it is gone -- measured, a deleted table's `Name`
    /// is error 424.
    fn table_at(&self, id: u64) -> Result<(usize, usize), String> {
        let (_, sheet, name) = self
            .table_handles
            .iter()
            .find(|(held, _, _)| *held == id)
            .ok_or_else(|| host_error(424, "the table has been deleted"))?;
        let index = self.workbook.sheets[*sheet]
            .tables
            .iter()
            .position(|table| table.name == *name)
            .ok_or_else(|| host_error(424, "the table has been deleted"))?;
        Ok((*sheet, index))
    }

    fn table_range(&self, sheet: usize, table: &Table) -> CellRange {
        CellRange {
            sheet,
            start_row: table.start_row,
            start_column: table.start_col,
            end_row: table.end_row,
            end_column: table.end_col,
        }
    }

    /// The table a cell lies in, if any.
    fn table_holding(&self, at: CellAddress) -> Option<(usize, usize)> {
        let sheet = self.workbook.sheets.get(at.sheet)?;
        sheet
            .tables
            .iter()
            .position(|table| {
                (table.start_row..=table.end_row).contains(&at.row)
                    && (table.start_col..=table.end_col).contains(&at.column)
            })
            .map(|index| (at.sheet, index))
    }

    /// How many rows at the bottom are the totals row.
    fn totals_rows(&self, id: u64) -> u32 {
        u32::from(self.table_extra.get(&id).is_some_and(|extra| extra.totals))
    }

    /// `ListObjects.Add(SourceType, Source, LinkSource, HasHeaders,
    /// Destination)`.
    ///
    /// Measured: the table takes the source's first row as its header when
    /// told so, or when left to guess and the first row is text over
    /// something else; otherwise a header row is put in above the data,
    /// which moves down, headed 列1, 列2, ...; the table is named テーブル1
    /// and on, dressed TableStyleMedium2 with banded rows and a filter; one
    /// overlapping a table is 1004.
    fn add_list_object(&mut self, sheet: usize, args: &[Value]) -> Result<Value, String> {
        let given = |index: usize| match args.get(index) {
            Some(Value::Missing) | None => None,
            Some(value) => Some(value),
        };
        if let Some(kind) = given(0) {
            if sort_number(kind, "ListObjects SourceType")? != 1 {
                return Err("only a range can be made a table here".to_string());
            }
        }
        let source = match given(1) {
            Some(Value::Object(object)) => self
                .range(object)
                .ok_or_else(|| "ListObjects.Add needs a Range as its source".to_string())?,
            _ => return Err("ListObjects.Add needs a Range as its source".to_string()),
        };
        Self::range_cell_count(source)?;
        if source.sheet != sheet {
            return Err("the source must be on this worksheet".to_string());
        }
        if self.workbook.sheets[sheet]
            .tables
            .iter()
            .any(|table| ranges_overlap(self.table_range(sheet, table), source))
        {
            return Err("a table cannot overlap another table".to_string());
        }
        let has_headers = match given(3) {
            None => 0,
            Some(value) => sort_number(value, "ListObjects HasHeaders")?,
        };
        let first_row_is_header = match has_headers {
            1 => true,
            2 => false,
            _ => {
                // The guess: every cell of the first row is text, and the row
                // under it is not all text.
                let texts = |row: u32| -> Vec<Option<CellValue>> {
                    (source.start_column..=source.end_column)
                        .map(|column| self.cell_here(sheet, row, column).map(|cell| cell.value))
                        .collect()
                };
                let first = texts(source.start_row);
                let all_text = first
                    .iter()
                    .all(|value| matches!(value, Some(CellValue::String(text)) if !text.is_empty()));
                let second = if source.end_row > source.start_row {
                    texts(source.start_row + 1)
                } else {
                    Vec::new()
                };
                let second_all_text = !second.is_empty()
                    && second
                        .iter()
                        .all(|value| matches!(value, Some(CellValue::String(text)) if !text.is_empty()));
                all_text && !second_all_text
            }
        };
        let mut range = source;
        if !first_row_is_header {
            // Put a header row in above the data: the data moves down within
            // the table's columns.
            let header_line = CellRange {
                end_row: source.start_row,
                ..source
            };
            self.shift_cells(header_line, false, true)?;
            range.end_row += 1;
        }
        // The column names: the header cells' text, a numbered name where a
        // header is empty.
        let mut columns: Vec<String> = Vec::new();
        let mut auto_named: Vec<bool> = Vec::new();
        for column in range.start_column..=range.end_column {
            let at = CellAddress {
                sheet,
                row: range.start_row,
                column,
            };
            let shown = self
                .cell_here(sheet, at.row, at.column)
                .map(|cell| shown_text(&from_cell_value(&cell.value), cell.style.number_format.as_deref()))
                .unwrap_or_default();
            let blank = shown.is_empty();
            let name = if blank { next_column_name(&columns) } else { shown };
            if blank {
                self.set_cell_value(at, CellValue::String(name.clone()))?;
            }
            columns.push(name);
            auto_named.push(blank);
        }
        self.table_counter += 1;
        let name = format!("テーブル{}", self.table_counter);
        let style = "TableStyleMedium2";
        let (accent, band, rule) = table_colours(style);
        self.workbook.sheets[sheet].tables.push(Table {
            name: name.clone(),
            columns,
            start_row: range.start_row,
            start_col: range.start_column,
            end_row: range.end_row,
            end_col: range.end_column,
            style: Some(style.to_string()),
            header_rows: 1,
            banded_rows: true,
            accent,
            band,
            rule,
            outline: None,
        });
        let id = self.table_handle(sheet, &name);
        let width = (range.end_column - range.start_column + 1) as usize;
        self.table_extra.insert(
            id,
            TableExtra {
                totals: false,
                calculations: vec![0; width],
                auto_named,
            },
        );
        self.wrote = true;
        Ok(self.object(HostObject::ListObject(id)))
    }

    /// Grow a table when something is typed just under it or just right of
    /// it. Measured: a value in the row under the last data row, or in the
    /// column right of the last column within the table's rows, brings that
    /// row or column into the table -- a new column headed 列1 -- while one
    /// under the totals row, one row further down, or on the corner does not.
    fn grow_table_toward(&mut self, at: CellAddress) -> Result<(), String> {
        let Some(sheet) = self.workbook.sheets.get(at.sheet) else {
            return Ok(());
        };
        let Some(index) = sheet.tables.iter().position(|table| {
            let under = at.row == table.end_row + 1
                && (table.start_col..=table.end_col).contains(&at.column);
            let beside = at.column == table.end_col + 1
                && (table.start_row..=table.end_row).contains(&at.row);
            under || beside
        }) else {
            return Ok(());
        };
        let name = sheet.tables[index].name.clone();
        let id = self.table_handle(at.sheet, &name);
        let (start_row, end_row, end_col) = {
            let table = &self.workbook.sheets[at.sheet].tables[index];
            (table.start_row, table.end_row, table.end_col)
        };
        if at.row == end_row + 1 {
            if self.totals_rows(id) > 0 {
                return Ok(());
            }
            self.workbook.sheets[at.sheet].tables[index].end_row += 1;
            return Ok(());
        }
        if at.column == end_col + 1 {
            let header = CellAddress {
                sheet: at.sheet,
                row: start_row,
                column: at.column,
            };
            let shown = self
                .cell_here(header.sheet, header.row, header.column)
                .map(|cell| shown_text(&from_cell_value(&cell.value), cell.style.number_format.as_deref()))
                .unwrap_or_default();
            let columns = self.workbook.sheets[at.sheet].tables[index].columns.clone();
            let name = if shown.is_empty() { next_column_name(&columns) } else { shown.clone() };
            if shown.is_empty() {
                self.set_cell_value(header, CellValue::String(name.clone()))?;
            }
            let table = &mut self.workbook.sheets[at.sheet].tables[index];
            table.end_col += 1;
            table.columns.push(name);
            if let Some(extra) = self.table_extra.get_mut(&id) {
                extra.calculations.push(0);
                extra.auto_named.push(shown.is_empty());
            }
        }
        Ok(())
    }

    /// Put the totals row on or take it off. Measured: the row appears under
    /// the data with 集計 in the first column and `=SUBTOTAL(103,[Last])` --
    /// a count -- under the last column, or `SUBTOTAL(109, ...)`, a sum, when
    /// that column is numbers; taking the row off clears it.
    fn show_table_totals(&mut self, id: u64, shown: bool) -> Result<(), String> {
        let (sheet, index) = self.table_at(id)?;
        let already = self.totals_rows(id) > 0;
        if shown == already {
            return Ok(());
        }
        let (name, start_col, end_col, end_row, columns) = {
            let table = &self.workbook.sheets[sheet].tables[index];
            (
                table.name.clone(),
                table.start_col,
                table.end_col,
                table.end_row,
                table.columns.clone(),
            )
        };
        if shown {
            let row = end_row + 1;
            // Measured: the row goes in under the data and whatever was
            // there moves down within the table's columns; taking the row
            // out brings it back up.
            self.shift_cells(
                CellRange {
                    sheet,
                    start_row: row,
                    end_row: row,
                    start_column: start_col,
                    end_column: end_col,
                },
                false,
                true,
            )?;
            self.workbook.sheets[sheet].tables[index].end_row = row;
            let width = columns.len();
            let last = width - 1;
            let last_is_numbers = (self.workbook.sheets[sheet].tables[index].start_row + 1..row)
                .filter_map(|held| self.cell_here(sheet, held, end_col))
                .all(|cell| matches!(cell.value, CellValue::Number(_)));
            {
                let extra = self.table_extra.entry(id).or_default();
                extra.totals = true;
                extra.calculations.resize(width, 0);
                extra.calculations[last] = if last_is_numbers { 1 } else { 3 };
            }
            self.set_cell_value(
                CellAddress {
                    sheet,
                    row,
                    column: start_col,
                },
                CellValue::String("集計".to_string()),
            )?;
            let function = if last_is_numbers { 109 } else { 103 };
            self.set_cell_formula(
                CellAddress {
                    sheet,
                    row,
                    column: end_col,
                },
                format!("SUBTOTAL({function},{name}[{}])", columns[last]),
            )?;
        } else {
            let row = end_row;
            self.workbook.sheets[sheet].tables[index].end_row = row - 1;
            if let Some(extra) = self.table_extra.get_mut(&id) {
                extra.totals = false;
            }
            self.shift_cells(
                CellRange {
                    sheet,
                    start_row: row,
                    end_row: row,
                    start_column: start_col,
                    end_column: end_col,
                },
                false,
                false,
            )?;
        }
        Ok(())
    }

    /// The table's data rows: from under the header to above the totals.
    fn table_data_rows(&self, id: u64, sheet: usize, index: usize) -> (u32, u32) {
        let table = &self.workbook.sheets[sheet].tables[index];
        (
            table.start_row + table.header_rows,
            table.end_row - self.totals_rows(id),
        )
    }

    /// What a table, its rows and its columns answer to.
    fn table_member(
        &mut self,
        id: u64,
        part: TablePart,
        name: &str,
        args: &[Value],
    ) -> Result<Option<Value>, String> {
        let (sheet, index) = self.table_at(id)?;
        let (first_data, last_data) = self.table_data_rows(id, sheet, index);
        let table = self.workbook.sheets[sheet].tables[index].clone();
        let whole = self.table_range(sheet, &table);
        let data_range = |column_from: u32, column_to: u32| -> Option<CellRange> {
            (first_data <= last_data).then_some(CellRange {
                sheet,
                start_row: first_data,
                end_row: last_data,
                start_column: column_from,
                end_column: column_to,
            })
        };
        match part {
            TablePart::Whole => {
                let answer = if name.eq_ignore_ascii_case("name") {
                    Value::String(table.name.clone())
                } else if name.eq_ignore_ascii_case("range") {
                    self.object(HostObject::Range(whole))
                } else if name.eq_ignore_ascii_case("headerrowrange") {
                    self.object(HostObject::Range(CellRange {
                        end_row: whole.start_row,
                        ..whole
                    }))
                } else if name.eq_ignore_ascii_case("databodyrange") {
                    match data_range(whole.start_column, whole.end_column) {
                        Some(range) => self.object(HostObject::Range(range)),
                        None => Value::Nothing,
                    }
                } else if name.eq_ignore_ascii_case("totalsrowrange") {
                    if self.totals_rows(id) == 0 {
                        return Err("the table shows no totals row".to_string());
                    }
                    self.object(HostObject::Range(CellRange {
                        start_row: whole.end_row,
                        ..whole
                    }))
                } else if name.eq_ignore_ascii_case("listrows") {
                    match args {
                        [] => self.object(HostObject::ListRows(id)),
                        [wanted] => {
                            let index = positive_index(wanted, "ListRows index")?;
                            if index > last_data.saturating_sub(first_data) + 1 || first_data > last_data {
                                return Err(format!("the table has no row {index}"));
                            }
                            self.object(HostObject::ListRow(id, index))
                        }
                        _ => return Err("ListRows expects zero or one argument".to_string()),
                    }
                } else if name.eq_ignore_ascii_case("listcolumns") {
                    match args {
                        [] => self.object(HostObject::ListColumns(id)),
                        [wanted] => self.list_column_item(id, &table, wanted)?,
                        _ => return Err("ListColumns expects zero or one argument".to_string()),
                    }
                } else if name.eq_ignore_ascii_case("tablestyle") {
                    Value::String(table.style.clone().unwrap_or_default())
                } else if name.eq_ignore_ascii_case("showheaders") {
                    Value::Boolean(table.header_rows > 0)
                } else if name.eq_ignore_ascii_case("showtotals") {
                    Value::Boolean(self.totals_rows(id) > 0)
                } else if name.eq_ignore_ascii_case("showautofilter") {
                    Value::Boolean(true)
                } else if name.eq_ignore_ascii_case("showtablestylerowstripes") {
                    Value::Boolean(table.banded_rows)
                } else if name.eq_ignore_ascii_case("showtablestylecolumnstripes")
                    || name.eq_ignore_ascii_case("showtablestylefirstcolumn")
                    || name.eq_ignore_ascii_case("showtablestylelastcolumn")
                {
                    Value::Boolean(false)
                } else if name.eq_ignore_ascii_case("parent") {
                    self.object(HostObject::Worksheet(sheet))
                } else if name.eq_ignore_ascii_case("resize") {
                    let [Value::Object(object)] = args else {
                        return Err("ListObject.Resize takes the new Range".to_string());
                    };
                    let asked = self
                        .range(object)
                        .ok_or_else(|| "ListObject.Resize takes the new Range".to_string())?;
                    if asked.sheet != sheet || asked.start_row != whole.start_row {
                        return Err("a table keeps its header row when resized".to_string());
                    }
                    // A column the table headed itself loses that header when
                    // it is dropped; one that was named keeps it.
                    let dropped: Vec<u32> = (whole.start_column..=whole.end_column)
                        .filter(|column| !(asked.start_column..=asked.end_column).contains(column))
                        .collect();
                    for column in dropped {
                        let slot = (column - whole.start_column) as usize;
                        let auto = self
                            .table_extra
                            .get(&id)
                            .and_then(|extra| extra.auto_named.get(slot).copied())
                            .unwrap_or(false);
                        if auto {
                            self.set_cell_value(
                                CellAddress {
                                    sheet,
                                    row: whole.start_row,
                                    column,
                                },
                                CellValue::Empty,
                            )?;
                        }
                    }
                    let held = &mut self.workbook.sheets[sheet].tables[index];
                    held.start_col = asked.start_column;
                    held.end_col = asked.end_column;
                    held.end_row = asked.end_row;
                    let width = (asked.end_column - asked.start_column + 1) as usize;
                    let mut columns = Vec::with_capacity(width);
                    for column in asked.start_column..=asked.end_column {
                        let shown = self
                            .cell_here(sheet, asked.start_row, column)
                            .map(|cell| shown_text(&from_cell_value(&cell.value), cell.style.number_format.as_deref()))
                            .unwrap_or_default();
                        columns.push(if shown.is_empty() { next_column_name(&columns) } else { shown });
                    }
                    let auto_named: Vec<bool> = (asked.start_column..=asked.end_column)
                        .map(|column| {
                            let slot = column.checked_sub(whole.start_column).map(|slot| slot as usize);
                            slot.and_then(|slot| {
                                self.table_extra
                                    .get(&id)
                                    .and_then(|extra| extra.auto_named.get(slot).copied())
                            })
                            .unwrap_or(false)
                        })
                        .collect();
                    self.workbook.sheets[sheet].tables[index].columns = columns;
                    if let Some(extra) = self.table_extra.get_mut(&id) {
                        extra.calculations.resize(width, 0);
                        extra.auto_named = auto_named;
                    }
                    Value::Empty
                } else if name.eq_ignore_ascii_case("unlist") {
                    // The look stays as the cells' own: measured, the header
                    // is still bold after `Unlist`.
                    self.bake_table_dress(sheet, index);
                    self.workbook.sheets[sheet].tables.remove(index);
                    self.table_handles.retain(|(held, _, _)| *held != id);
                    Value::Empty
                } else if name.eq_ignore_ascii_case("delete") {
                    self.workbook.sheets[sheet].tables.remove(index);
                    self.table_handles.retain(|(held, _, _)| *held != id);
                    self.clear_range(whole, true, true)?;
                    Value::Empty
                } else {
                    return Ok(None);
                };
                Ok(Some(answer))
            }
            TablePart::Rows => {
                let count = if first_data > last_data { 0 } else { last_data - first_data + 1 };
                let answer = if name.eq_ignore_ascii_case("count") {
                    Value::Integer(i64::from(count))
                } else if name.eq_ignore_ascii_case("item") {
                    let [wanted] = args else {
                        return Err("ListRows.Item takes one number".to_string());
                    };
                    let index = positive_index(wanted, "ListRows index")?;
                    if index > count {
                        return Err(format!("the table has no row {index}"));
                    }
                    self.object(HostObject::ListRow(id, index))
                } else if name.eq_ignore_ascii_case("add") {
                    // `Add [Position]`: a row under the data, or put in at the
                    // position with the rows from there moving down within the
                    // table's columns.
                    let position = match args.first() {
                        None | Some(Value::Missing) => None,
                        Some(value) => Some(positive_index(value, "ListRows.Add Position")?),
                    };
                    let at_row = match position {
                        Some(position) if position <= count => first_data + position - 1,
                        _ => last_data + 1,
                    };
                    let line = CellRange {
                        sheet,
                        start_row: at_row,
                        end_row: at_row,
                        start_column: whole.start_column,
                        end_column: whole.end_column,
                    };
                    // The row is put in, whatever sat there moving down within
                    // the table's columns; inside the table the shift takes
                    // the table's end along, under it the table grows to it.
                    self.shift_cells(line, false, true)?;
                    if at_row > whole.end_row {
                        self.workbook.sheets[sheet].tables[index].end_row += 1;
                    }
                    let made = if position.is_some_and(|position| position <= count) {
                        position.unwrap_or(1)
                    } else {
                        count + 1
                    };
                    self.object(HostObject::ListRow(id, made))
                } else if name.eq_ignore_ascii_case("parent") {
                    self.object(HostObject::ListObject(id))
                } else {
                    return Ok(None);
                };
                Ok(Some(answer))
            }
            TablePart::Row(row_index) => {
                let row = first_data + row_index - 1;
                if row > last_data {
                    return Err(host_error(424, "the row has been deleted"));
                }
                let line = CellRange {
                    sheet,
                    start_row: row,
                    end_row: row,
                    start_column: whole.start_column,
                    end_column: whole.end_column,
                };
                let answer = if name.eq_ignore_ascii_case("range") {
                    self.object(HostObject::Range(line))
                } else if name.eq_ignore_ascii_case("index") {
                    Value::Integer(i64::from(row_index))
                } else if name.eq_ignore_ascii_case("delete") {
                    // The shift takes the table's end up with the cells.
                    self.shift_cells(line, false, false)?;
                    Value::Empty
                } else if name.eq_ignore_ascii_case("parent") {
                    self.object(HostObject::ListObject(id))
                } else {
                    return Ok(None);
                };
                Ok(Some(answer))
            }
            TablePart::Columns => {
                let answer = if name.eq_ignore_ascii_case("count") {
                    Value::Integer(table.columns.len() as i64)
                } else if name.eq_ignore_ascii_case("item") {
                    let [wanted] = args else {
                        return Err("ListColumns.Item takes one name or number".to_string());
                    };
                    self.list_column_item(id, &table, wanted)?
                } else if name.eq_ignore_ascii_case("add") {
                    // `Add [Position]`: a column on the right, headed with the
                    // first free 列N, or put in at the position with the
                    // columns from there moving right within the table's rows.
                    let count = table.columns.len() as u32;
                    let position = match args.first() {
                        None | Some(Value::Missing) => None,
                        Some(value) => Some(positive_index(value, "ListColumns.Add Position")?),
                    };
                    let at_column = match position {
                        Some(position) if position <= count => whole.start_column + position - 1,
                        _ => whole.end_column + 1,
                    };
                    // The column is put in, whatever sat there moving right
                    // within the table's rows -- measured, a cell beside the
                    // table moves over when a column is added on that side.
                    let band = CellRange {
                        sheet,
                        start_row: whole.start_row,
                        end_row: whole.end_row,
                        start_column: at_column,
                        end_column: at_column,
                    };
                    self.shift_cells(band, true, true)?;
                    if at_column > whole.end_column {
                        self.workbook.sheets[sheet].tables[index].end_col += 1;
                    }
                    let new_name = next_column_name(&table.columns);
                    self.set_cell_value(
                        CellAddress {
                            sheet,
                            row: whole.start_row,
                            column: at_column,
                        },
                        CellValue::String(new_name.clone()),
                    )?;
                    let slot = (at_column - whole.start_column) as usize;
                    let held = &mut self.workbook.sheets[sheet].tables[index];
                    held.columns.insert(slot, new_name);
                    if let Some(extra) = self.table_extra.get_mut(&id) {
                        extra.calculations.insert(slot, 0);
                        extra.auto_named.resize(slot, false);
                        extra.auto_named.insert(slot, true);
                    }
                    self.object(HostObject::ListColumn(id, slot as u32 + 1))
                } else if name.eq_ignore_ascii_case("parent") {
                    self.object(HostObject::ListObject(id))
                } else {
                    return Ok(None);
                };
                Ok(Some(answer))
            }
            TablePart::Column(column_index) => {
                let slot = column_index as usize - 1;
                let Some(column_name) = table.columns.get(slot).cloned() else {
                    return Err(host_error(424, "the column has been deleted"));
                };
                let column = whole.start_column + column_index - 1;
                let answer = if name.eq_ignore_ascii_case("name") {
                    Value::String(column_name)
                } else if name.eq_ignore_ascii_case("index") {
                    Value::Integer(i64::from(column_index))
                } else if name.eq_ignore_ascii_case("range") {
                    self.object(HostObject::Range(CellRange {
                        sheet,
                        start_row: whole.start_row,
                        end_row: whole.end_row,
                        start_column: column,
                        end_column: column,
                    }))
                } else if name.eq_ignore_ascii_case("databodyrange") {
                    match data_range(column, column) {
                        Some(range) => self.object(HostObject::Range(range)),
                        None => Value::Nothing,
                    }
                } else if name.eq_ignore_ascii_case("totalscalculation") {
                    Value::Integer(
                        self.table_extra
                            .get(&id)
                            .and_then(|extra| extra.calculations.get(slot).copied())
                            .unwrap_or(0),
                    )
                } else if name.eq_ignore_ascii_case("delete") {
                    let band = CellRange {
                        sheet,
                        start_row: whole.start_row,
                        end_row: whole.end_row,
                        start_column: column,
                        end_column: column,
                    };
                    // The shift takes the table's right edge in.
                    self.shift_cells(band, true, false)?;
                    let held = &mut self.workbook.sheets[sheet].tables[index];
                    held.columns.remove(slot);
                    if let Some(extra) = self.table_extra.get_mut(&id) {
                        if slot < extra.calculations.len() {
                            extra.calculations.remove(slot);
                        }
                        if slot < extra.auto_named.len() {
                            extra.auto_named.remove(slot);
                        }
                    }
                    Value::Empty
                } else if name.eq_ignore_ascii_case("parent") {
                    self.object(HostObject::ListObject(id))
                } else {
                    return Ok(None);
                };
                Ok(Some(answer))
            }
        }
    }

    /// What `Worksheet.ListObjects` answers to.
    fn list_objects_member(
        &mut self,
        sheet: usize,
        name: &str,
        args: &[Value],
    ) -> Result<Option<Value>, String> {
        if name.eq_ignore_ascii_case("count") {
            return Ok(Some(Value::Integer(self.workbook.sheets[sheet].tables.len() as i64)));
        }
        if name.eq_ignore_ascii_case("item") {
            let [wanted] = args else {
                return Err("ListObjects.Item takes one name or number".to_string());
            };
            let table_name = match wanted {
                Value::String(named) => self.workbook.sheets[sheet]
                    .tables
                    .iter()
                    .find(|table| table.name.eq_ignore_ascii_case(named))
                    .map(|table| table.name.clone())
                    .ok_or_else(|| format!("the sheet has no table {named:?}"))?,
                value => {
                    let index = positive_index(value, "ListObjects index")? as usize;
                    self.workbook.sheets[sheet]
                        .tables
                        .get(index - 1)
                        .map(|table| table.name.clone())
                        .ok_or_else(|| format!("the sheet has no table number {index}"))?
                }
            };
            let id = self.table_handle(sheet, &table_name);
            return Ok(Some(self.object(HostObject::ListObject(id))));
        }
        if name.eq_ignore_ascii_case("add") {
            return self.add_list_object(sheet, args).map(Some);
        }
        if name.eq_ignore_ascii_case("parent") {
            return Ok(Some(self.object(HostObject::Worksheet(sheet))));
        }
        Ok(None)
    }

    /// `Range.ListObject`: the table the range's first cell lies in, or
    /// Nothing.
    fn list_object_of(&mut self, range: CellRange) -> Value {
        let at = CellAddress {
            sheet: range.sheet,
            row: range.start_row,
            column: range.start_column,
        };
        match self.table_holding(at) {
            Some((sheet, index)) => {
                let name = self.workbook.sheets[sheet].tables[index].name.clone();
                let id = self.table_handle(sheet, &name);
                self.object(HostObject::ListObject(id))
            }
            None => Value::Nothing,
        }
    }

    /// `ListColumns(n)` / `ListColumns("Name")`.
    fn list_column_item(&mut self, id: u64, table: &Table, wanted: &Value) -> Result<Value, String> {
        let index = match wanted {
            Value::String(name) => table
                .columns
                .iter()
                .position(|held| held.eq_ignore_ascii_case(name))
                .map(|slot| slot as u32 + 1)
                .ok_or_else(|| format!("the table has no column {name:?}"))?,
            value => positive_index(value, "ListColumns index")?,
        };
        if index as usize > table.columns.len() {
            return Err(format!("the table has no column {index}"));
        }
        Ok(self.object(HostObject::ListColumn(id, index)))
    }

    /// Set a part of a table: its name, a column's name, its style, whether
    /// its totals or stripes show, or what a column totals.
    fn set_table(&mut self, id: u64, part: TablePart, name: &str, value: Value) -> Result<bool, String> {
        let (sheet, index) = self.table_at(id)?;
        match part {
            TablePart::Whole => {
                if name.eq_ignore_ascii_case("name") {
                    let Value::String(new_name) = &value else {
                        return Err("a table's name is text".to_string());
                    };
                    check_name(new_name)?;
                    let old = self.workbook.sheets[sheet].tables[index].name.clone();
                    if self.workbook.sheets.iter().flat_map(|held| held.tables.iter()).any(|table| {
                        table.name.eq_ignore_ascii_case(new_name) && table.name != old
                    }) {
                        return Err(format!("there is already a table named {new_name:?}"));
                    }
                    self.workbook.sheets[sheet].tables[index].name = new_name.clone();
                    if let Some(handle) = self.table_handles.iter_mut().find(|(held, _, _)| *held == id) {
                        handle.2 = new_name.clone();
                    }
                    // Formulas naming the table follow it.
                    for held in &mut self.workbook.sheets {
                        for row in &mut held.rows {
                            for cell in &mut row.cells {
                                if let Some(formula) = cell.formula.as_mut() {
                                    if formula.contains(&format!("{old}[")) {
                                        *formula = formula.replace(&format!("{old}["), &format!("{new_name}["));
                                    }
                                }
                            }
                        }
                    }
                    return Ok(true);
                }
                if name.eq_ignore_ascii_case("tablestyle") {
                    let Value::String(style) = &value else {
                        return Err(host_error(450, "a table style is named"));
                    };
                    if !known_table_style(style) {
                        return Err(host_error(450, format!("there is no table style {style:?}")));
                    }
                    let (accent, band, rule) = table_colours(style);
                    let table = &mut self.workbook.sheets[sheet].tables[index];
                    table.style = Some(style.clone());
                    table.accent = accent;
                    table.band = band;
                    table.rule = rule;
                    return Ok(true);
                }
                if name.eq_ignore_ascii_case("showtotals") {
                    if let Some(shown) = style_face_boolean(&value, "ListObject.ShowTotals")? {
                        self.show_table_totals(id, shown)?;
                    }
                    return Ok(true);
                }
                if name.eq_ignore_ascii_case("showtablestylerowstripes") {
                    if let Some(banded) = style_face_boolean(&value, "ListObject.ShowTableStyleRowStripes")? {
                        self.workbook.sheets[sheet].tables[index].banded_rows = banded;
                    }
                    return Ok(true);
                }
                if name.eq_ignore_ascii_case("showautofilter")
                    || name.eq_ignore_ascii_case("showheaders")
                    || name.eq_ignore_ascii_case("showtablestylecolumnstripes")
                    || name.eq_ignore_ascii_case("showtablestylefirstcolumn")
                    || name.eq_ignore_ascii_case("showtablestylelastcolumn")
                {
                    return Ok(true);
                }
                Ok(false)
            }
            TablePart::Column(column_index) => {
                let slot = column_index as usize - 1;
                let table = &self.workbook.sheets[sheet].tables[index];
                let (start_row, column) = (table.start_row, table.start_col + column_index - 1);
                if slot >= table.columns.len() {
                    return Err(host_error(424, "the column has been deleted"));
                }
                if name.eq_ignore_ascii_case("name") {
                    let Value::String(new_name) = &value else {
                        return Err("a column's name is text".to_string());
                    };
                    self.workbook.sheets[sheet].tables[index].columns[slot] = new_name.clone();
                    if let Some(extra) = self.table_extra.get_mut(&id) {
                        if slot < extra.auto_named.len() {
                            extra.auto_named[slot] = false;
                        }
                    }
                    self.set_cell_value(
                        CellAddress {
                            sheet,
                            row: start_row,
                            column,
                        },
                        CellValue::String(new_name.clone()),
                    )?;
                    return Ok(true);
                }
                if name.eq_ignore_ascii_case("totalscalculation") {
                    let calculation = sort_number(&value, "ListColumn.TotalsCalculation")?;
                    if !(0..=8).contains(&calculation) {
                        return Err("that is not a totals calculation".to_string());
                    }
                    if self.totals_rows(id) == 0 {
                        return Err("the table shows no totals row".to_string());
                    }
                    let (table_name, column_name, totals_row) = {
                        let table = &self.workbook.sheets[sheet].tables[index];
                        (table.name.clone(), table.columns[slot].clone(), table.end_row)
                    };
                    if let Some(extra) = self.table_extra.get_mut(&id) {
                        extra.calculations.resize(slot + 1, 0);
                        extra.calculations[slot] = calculation;
                    }
                    let at = CellAddress {
                        sheet,
                        row: totals_row,
                        column,
                    };
                    match subtotal_function(calculation) {
                        Some(function) => self.set_cell_formula(
                            at,
                            format!("SUBTOTAL({function},{table_name}[{column_name}])"),
                        )?,
                        None => self.set_cell_value(at, CellValue::Empty)?,
                    }
                    return Ok(true);
                }
                Ok(false)
            }
            _ => Ok(false),
        }
    }

    /// Write a table's look into its cells' own dress, for a table being
    /// unlisted: the header bold and white on the accent, the odd data rows
    /// on the band.
    fn bake_table_dress(&mut self, sheet: usize, index: usize) {
        let table = self.workbook.sheets[sheet].tables[index].clone();
        let dark_header = table
            .style
            .as_deref()
            .is_some_and(|style| !style.starts_with("TableStyleLight"));
        let accent = table.accent.clone().filter(|_| dark_header);
        let header = CellRange {
            sheet,
            start_row: table.start_row,
            end_row: table.start_row,
            start_column: table.start_col,
            end_column: table.end_col,
        };
        let _ = self.set_range_style(header, |_, style| {
            style.bold = true;
            if let Some(accent) = &accent {
                style.font_color = Some("FFFFFF".to_string());
                style.bg_color = Some(accent.clone());
            }
        });
        if let Some(band) = table.band.clone().filter(|_| table.banded_rows) {
            for (step, row) in (table.start_row + table.header_rows..=table.end_row).enumerate() {
                if step % 2 != 0 {
                    continue;
                }
                let line = CellRange {
                    sheet,
                    start_row: row,
                    end_row: row,
                    start_column: table.start_col,
                    end_column: table.end_col,
                };
                let _ = self.set_range_style(line, |_, style| style.bg_color = Some(band.clone()));
            }
        }
    }

    fn conditions_range(&self, object: &ObjectRef) -> Option<CellRange> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::FormatConditions(range)) => Some(*range),
            _ => None,
        }
    }

    fn condition_id(&self, object: &ObjectRef) -> Option<(u64, Option<StyleFace>)> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::FormatCondition(id)) => Some((*id, None)),
            Some(HostObject::ConditionFont(id)) => Some((*id, Some(StyleFace::Font))),
            Some(HostObject::ConditionInterior(id)) => Some((*id, Some(StyleFace::Interior))),
            _ => None,
        }
    }

    fn display_format_of(&self, object: &ObjectRef) -> Option<(CellRange, Option<StyleFace>)> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::DisplayFormat(range)) => Some((*range, None)),
            Some(HostObject::DisplayFont(range)) => Some((*range, Some(StyleFace::Font))),
            Some(HostObject::DisplayInterior(range)) => Some((*range, Some(StyleFace::Interior))),
            _ => None,
        }
    }

    fn condition_index(&self, id: u64) -> Result<usize, String> {
        self.conditions
            .iter()
            .position(|condition| condition.id == id)
            .ok_or_else(|| "the conditional format has been deleted".to_string())
    }

    /// The conditions reaching a range, in priority order -- measured,
    /// `Range("A1:B4").FormatConditions.Count` is 1 for a condition on A1:A4
    /// and `Range("B1").FormatConditions.Count` is 0.
    fn conditions_reaching(&self, range: CellRange) -> Vec<u64> {
        self.conditions
            .iter()
            .filter(|condition| {
                condition.sheet == range.sheet
                    && condition
                        .applies
                        .iter()
                        .any(|block| ranges_overlap(*block, range))
            })
            .map(|condition| condition.id)
            .collect()
    }

    /// Take a range out of every condition's reach, dropping a condition
    /// left with nothing.
    fn drop_conditions_on(&mut self, range: CellRange) {
        for condition in &mut self.conditions {
            if condition.sheet != range.sheet {
                continue;
            }
            let mut kept = Vec::new();
            for block in condition.applies.drain(..) {
                if !ranges_overlap(block, range) {
                    kept.push(block);
                    continue;
                }
                // What is left of the block once the range is cut out, as up
                // to four blocks around the hole.
                let hole = CellRange {
                    sheet: block.sheet,
                    start_row: block.start_row.max(range.start_row),
                    end_row: block.end_row.min(range.end_row),
                    start_column: block.start_column.max(range.start_column),
                    end_column: block.end_column.min(range.end_column),
                };
                if hole.start_row > block.start_row {
                    kept.push(CellRange { end_row: hole.start_row - 1, ..block });
                }
                if hole.end_row < block.end_row {
                    kept.push(CellRange { start_row: hole.end_row + 1, ..block });
                }
                if hole.start_column > block.start_column {
                    kept.push(CellRange {
                        start_row: hole.start_row,
                        end_row: hole.end_row,
                        end_column: hole.start_column - 1,
                        ..block
                    });
                }
                if hole.end_column < block.end_column {
                    kept.push(CellRange {
                        start_row: hole.start_row,
                        end_row: hole.end_row,
                        start_column: hole.end_column + 1,
                        ..block
                    });
                }
            }
            condition.applies = kept;
        }
        self.conditions.retain(|condition| !condition.applies.is_empty());
    }

    /// `FormatConditions.Add(Type, Operator, Formula1, Formula2, String,
    /// TextOperator)` and the shorter `AddColorScale`, `AddDatabar`,
    /// `AddIconSetCondition`, `AddTop10`, `AddUniqueValues`,
    /// `AddAboveAverage`.
    ///
    /// Measured: a cell-value condition wants an operator and Formula1, and
    /// Formula2 for `Between`, each missing one being 449; an expression
    /// wants Formula1; a type or operator outside the known ones is 5;
    /// `StopIfTrue` starts True; the new condition comes last in priority.
    fn add_condition(
        &mut self,
        range: CellRange,
        kind: i64,
        args: &[Value],
    ) -> Result<Value, String> {
        Self::range_cell_count(range)?;
        let given = |index: usize| match args.get(index) {
            Some(Value::Missing) | None => None,
            Some(value) => Some(value),
        };
        let text_of = |value: &Value| -> Result<String, String> {
            match value {
                Value::String(text) => Ok(text.clone()),
                value if any_number(value).is_some() => Ok(shown_text(value, None)),
                _ => Err("a condition's formula is text".to_string()),
            }
        };
        let (operator, formula1, formula2, text, text_operator) = match kind {
            1 => {
                let operator = match given(1) {
                    None => return Err(host_error(449, "Operator is not optional")),
                    Some(value) => sort_number(value, "FormatConditions Operator")?,
                };
                if !(1..=8).contains(&operator) {
                    return Err(host_error(5, format!("{operator} is not a condition operator")));
                }
                let formula1 = match given(2) {
                    None => return Err(host_error(449, "Formula1 is not optional")),
                    Some(value) => kept_condition_formula(&text_of(value)?),
                };
                let formula2 = match given(3) {
                    None if matches!(operator, 1 | 2) => {
                        return Err(host_error(449, "Formula2 is not optional"))
                    }
                    None => None,
                    Some(value) => Some(kept_condition_formula(&text_of(value)?)),
                };
                (Some(operator), Some(formula1), formula2, None, None)
            }
            2 => {
                let formula1 = match given(2) {
                    None => return Err(host_error(449, "Formula1 is not optional")),
                    Some(value) => kept_condition_formula(&text_of(value)?),
                };
                (None, Some(formula1), None, None, None)
            }
            9 => {
                let text = match given(4) {
                    None => return Err(host_error(449, "String is not optional")),
                    Some(value) => text_of(value)?,
                };
                let text_operator = match given(5) {
                    None => 0,
                    Some(value) => sort_number(value, "FormatConditions TextOperator")?,
                };
                (None, None, None, Some(text), Some(text_operator))
            }
            3..=6 | 8 | 10 | 12 | 13 | 16 | 17 => (None, None, None, None, None),
            other => return Err(host_error(5, format!("{other} is not a kind of condition"))),
        };
        let id = self.next_condition;
        self.next_condition += 1;
        let priority = self.last_condition_priority(range.sheet) + 1;
        self.conditions.push(Condition {
            id,
            sheet: range.sheet,
            applies: vec![range],
            kind,
            operator,
            formula1,
            formula2,
            text,
            text_operator,
            rank: 10,
            dupe_unique: 0,
            stop_if_true: true,
            priority,
            bold: None,
            italic: None,
            underline: None,
            strikethrough: None,
            font_color: None,
            fill: None,
        });
        Ok(self.object(HostObject::FormatCondition(id)))
    }

    /// Whether a condition holds for one cell.
    fn condition_holds(&self, condition: &Condition, at: CellAddress) -> bool {
        let cell = self.cell_here(at.sheet, at.row, at.column);
        let value = cell
            .as_ref()
            .map(|cell| from_cell_value(&cell.value))
            .unwrap_or(Value::Empty);
        // Formulas are written against the top-left cell of the block the
        // condition applies to, and move with the cell: measured, `=F1>1` on
        // F1:F3 is `=F2>1` for F2.
        let corner = condition
            .applies
            .first()
            .map(|block| (block.start_row, block.start_column))
            .unwrap_or((at.row, at.column));
        let worked_out = |formula: &str| -> Option<Value> {
            let expression = formula.strip_prefix('=').unwrap_or(formula);
            let moved = translate_formula_references(
                expression,
                i64::from(at.row) - i64::from(corner.0),
                i64::from(at.column) - i64::from(corner.1),
            )
            .unwrap_or_else(|_| expression.to_string());
            match oxicells_core::formula::evaluate_expression(
                self.workbook,
                at.sheet,
                &moved,
                self.now,
            )? {
                oxicells_calc::Value::Number(number) => Some(Value::Double(number)),
                oxicells_calc::Value::Text(text) => Some(Value::String(text)),
                oxicells_calc::Value::Logical(state) => Some(Value::Boolean(state)),
                oxicells_calc::Value::Blank => Some(Value::Empty),
                oxicells_calc::Value::Error(_) => None,
            }
        };
        match condition.kind {
            1 => {
                let Some(first) = condition.formula1.as_deref().and_then(worked_out) else {
                    return false;
                };
                let held = if matches!(value, Value::Empty) { Value::Double(0.0) } else { value };
                let against_first = compare_as_excel(&held, &first);
                match condition.operator.unwrap_or(3) {
                    1 | 2 => {
                        let Some(second) = condition.formula2.as_deref().and_then(worked_out) else {
                            return false;
                        };
                        let (low, high) = if compare_as_excel(&first, &second) == Ordering::Greater {
                            (second, first)
                        } else {
                            (first, second)
                        };
                        let inside = compare_as_excel(&held, &low) != Ordering::Less
                            && compare_as_excel(&held, &high) != Ordering::Greater;
                        if condition.operator == Some(1) { inside } else { !inside }
                    }
                    3 => against_first == Ordering::Equal,
                    4 => against_first != Ordering::Equal,
                    5 => against_first == Ordering::Greater,
                    6 => against_first == Ordering::Less,
                    7 => against_first != Ordering::Less,
                    _ => against_first != Ordering::Greater,
                }
            }
            2 => matches!(
                condition.formula1.as_deref().and_then(worked_out),
                Some(Value::Boolean(true))
            ) || matches!(
                condition.formula1.as_deref().and_then(worked_out),
                Some(Value::Double(number)) if number != 0.0
            ),
            9 => {
                let shown = cell
                    .as_ref()
                    .map(|cell| {
                        shown_text(&from_cell_value(&cell.value), cell.style.number_format.as_deref())
                    })
                    .unwrap_or_default()
                    .to_lowercase();
                let wanted = condition.text.clone().unwrap_or_default().to_lowercase();
                match condition.text_operator.unwrap_or(0) {
                    1 => !shown.contains(&wanted),
                    2 => shown.starts_with(&wanted),
                    3 => shown.ends_with(&wanted),
                    _ => shown.contains(&wanted),
                }
            }
            10 => matches!(value, Value::Empty),
            13 => !matches!(value, Value::Empty),
            16 => matches!(value, Value::Error(_)),
            17 => !matches!(value, Value::Error(_)),
            _ => false,
        }
    }

    /// The dress a cell shows once its conditions are worked out: the
    /// conditions in priority order, each that holds putting on what it sets
    /// and has not been set by one above it, and a `StopIfTrue` condition
    /// that holds ending the walk.
    fn displayed_dress(&self, at: CellAddress) -> (Dress, Option<String>, bool) {
        let base = self
            .cell_here(at.sheet, at.row, at.column)
            .map(|cell| (Dress::of_style(&cell.style), cell.style.bg_color.clone(), cell.style.strikethrough))
            .unwrap_or_else(|| (Dress::of_style(&CellStyle::default()), None, false));
        let (mut dress, mut fill, mut strikethrough) = base;
        let (mut set_bold, mut set_italic, mut set_underline, mut set_strike, mut set_colour, mut set_fill) =
            (false, false, false, false, false, false);
        // A table dresses its cells under everything else: measured, a
        // TableStyleMedium2 header shows bold, white on the accent, and the
        // first data row shows the band.
        if let Some((_, index)) = self.table_holding(at) {
            let table = &self.workbook.sheets[at.sheet].tables[index];
            let dark_header = table
                .style
                .as_deref()
                .is_some_and(|style| !style.starts_with("TableStyleLight"));
            if at.row < table.start_row + table.header_rows {
                dress.bold = true;
                if let (Some(accent), true) = (table.accent.clone(), dark_header) {
                    dress.color = Some("FFFFFF".to_string());
                    fill = Some(accent);
                }
            } else if table.banded_rows && (at.row - table.start_row - table.header_rows) % 2 == 0 {
                if let Some(band) = table.band.clone() {
                    fill = Some(band);
                }
            }
        }
        for condition in self.conditions.iter().filter(|condition| {
            condition.sheet == at.sheet
                && condition
                    .applies
                    .iter()
                    .any(|block| range_within(CellRange::single(at), *block))
        }) {
            if !self.condition_holds(condition, at) {
                continue;
            }
            if let (Some(bold), false) = (condition.bold, set_bold) {
                dress.bold = bold;
                set_bold = true;
            }
            if let (Some(italic), false) = (condition.italic, set_italic) {
                dress.italic = italic;
                set_italic = true;
            }
            if let (Some(underline), false) = (condition.underline, set_underline) {
                dress.underline = underline;
                set_underline = true;
            }
            if let (Some(struck), false) = (condition.strikethrough, set_strike) {
                strikethrough = struck;
                set_strike = true;
            }
            if let (Some(colour), false) = (&condition.font_color, set_colour) {
                dress.color = Some(colour.clone());
                set_colour = true;
            }
            if let (Some(colour), false) = (&condition.fill, set_fill) {
                fill = Some(colour.clone());
                set_fill = true;
            }
            if condition.stop_if_true {
                break;
            }
        }
        (dress, fill, strikethrough)
    }

    /// What `FormatConditions` answers to.
    fn conditions_member(
        &mut self,
        range: CellRange,
        name: &str,
        args: &[Value],
    ) -> Result<Option<Value>, String> {
        if name.eq_ignore_ascii_case("count") {
            return Ok(Some(Value::Integer(self.conditions_reaching(range).len() as i64)));
        }
        if name.eq_ignore_ascii_case("item") {
            let [wanted] = args else {
                return Err("FormatConditions.Item takes one number".to_string());
            };
            let index = positive_index(wanted, "FormatConditions index")? as usize;
            let reaching = self.conditions_reaching(range);
            let Some(&id) = reaching.get(index - 1) else {
                return Err(format!("there is no conditional format number {index} here"));
            };
            return Ok(Some(self.object(HostObject::FormatCondition(id))));
        }
        if name.eq_ignore_ascii_case("add") {
            let kind = match args.first() {
                None | Some(Value::Missing) => return Err(host_error(449, "Type is not optional")),
                Some(value) => sort_number(value, "FormatConditions Type")?,
            };
            return self.add_condition(range, kind, args).map(Some);
        }
        let shorter = [
            ("addcolorscale", 3),
            ("adddatabar", 4),
            ("addtop10", 5),
            ("addiconsetcondition", 6),
            ("adduniquevalues", 8),
            ("addaboveaverage", 12),
        ];
        if let Some((_, kind)) = shorter.iter().find(|(member, _)| name.eq_ignore_ascii_case(member)) {
            return self.add_condition(range, *kind, &[]).map(Some);
        }
        if name.eq_ignore_ascii_case("delete") {
            self.drop_conditions_on(range);
            return Ok(Some(Value::Empty));
        }
        if name.eq_ignore_ascii_case("parent") {
            return Ok(Some(self.object(HostObject::Range(range))));
        }
        Ok(None)
    }

    /// The highest priority number among a sheet's conditions, 0 for none.
    fn last_condition_priority(&self, sheet: usize) -> i64 {
        self.conditions
            .iter()
            .filter(|condition| condition.sheet == sheet)
            .map(|condition| condition.priority)
            .max()
            .unwrap_or(0)
    }

    /// Give a condition a priority, pushing the sheet's others at that
    /// number or below one further -- measured, moving the second of two to
    /// 1 leaves the first at 2, and moving it to 1 again after it went last
    /// (3) leaves the first at 3.
    fn set_condition_priority(&mut self, index: usize, priority: i64) {
        let sheet = self.conditions[index].sheet;
        let priority = priority.max(1);
        for (at, condition) in self.conditions.iter_mut().enumerate() {
            if at != index && condition.sheet == sheet && condition.priority >= priority {
                condition.priority += 1;
            }
        }
        self.conditions[index].priority = priority;
        self.conditions.sort_by_key(|condition| condition.priority);
    }

    /// What one conditional format answers to, and what its font and fill
    /// answer to.
    fn condition_member(
        &mut self,
        id: u64,
        face: Option<StyleFace>,
        name: &str,
        args: &[Value],
    ) -> Result<Option<Value>, String> {
        let index = self.condition_index(id)?;
        if let Some(face) = face {
            let condition = &self.conditions[index];
            // Measured: what a condition does not set reads False for the
            // Booleans and Null for the rest.
            let answer = match (face, name.to_ascii_lowercase().as_str()) {
                (StyleFace::Font, "bold") => Value::Boolean(condition.bold.unwrap_or(false)),
                (StyleFace::Font, "italic") => Value::Boolean(condition.italic.unwrap_or(false)),
                (StyleFace::Font, "strikethrough") => {
                    Value::Boolean(condition.strikethrough.unwrap_or(false))
                }
                (StyleFace::Font, "underline") => match condition.underline {
                    Some(true) => Value::Integer(UNDERLINE_SINGLE),
                    Some(false) => Value::Integer(UNDERLINE_NONE),
                    None => Value::Null,
                },
                (StyleFace::Font, "color") => match &condition.font_color {
                    Some(colour) => Value::Integer(colour_to_packed(Some(colour)).unwrap_or(0)),
                    None => Value::Null,
                },
                (StyleFace::Font, "colorindex") => match &condition.font_color {
                    Some(colour) => Value::Integer(
                        colour_to_packed(Some(colour)).map(nearest_palette_index).unwrap_or(1),
                    ),
                    None => Value::Null,
                },
                (StyleFace::Font, "size" | "name") => Value::Null,
                (StyleFace::Interior, "color") => match &condition.fill {
                    Some(colour) => Value::Integer(colour_to_packed(Some(colour)).unwrap_or(0)),
                    None => Value::Null,
                },
                (StyleFace::Interior, "colorindex") => match &condition.fill {
                    Some(colour) => Value::Integer(
                        colour_to_packed(Some(colour)).map(nearest_palette_index).unwrap_or(1),
                    ),
                    None => Value::Null,
                },
                (StyleFace::Interior, "pattern") => Value::Null,
                (_, "parent") => self.object(HostObject::FormatCondition(id)),
                _ => return Ok(None),
            };
            return Ok(Some(answer));
        }
        let condition = &self.conditions[index];
        let answer = if name.eq_ignore_ascii_case("type") {
            Value::Integer(condition.kind)
        } else if name.eq_ignore_ascii_case("operator") {
            match condition.operator {
                Some(operator) => Value::Integer(operator),
                None => return Err("this kind of condition has no operator".to_string()),
            }
        } else if name.eq_ignore_ascii_case("formula1") {
            match &condition.formula1 {
                Some(formula) => Value::String(formula.clone()),
                None => return Err("this condition has no Formula1".to_string()),
            }
        } else if name.eq_ignore_ascii_case("formula2") {
            match &condition.formula2 {
                Some(formula) => Value::String(formula.clone()),
                None => return Err("this condition has no Formula2".to_string()),
            }
        } else if name.eq_ignore_ascii_case("text") {
            Value::String(condition.text.clone().unwrap_or_default())
        } else if name.eq_ignore_ascii_case("textoperator") {
            Value::Integer(condition.text_operator.unwrap_or(0))
        } else if name.eq_ignore_ascii_case("rank") {
            Value::Integer(condition.rank)
        } else if name.eq_ignore_ascii_case("dupeunique") {
            Value::Integer(condition.dupe_unique)
        } else if name.eq_ignore_ascii_case("stopiftrue") {
            Value::Boolean(condition.stop_if_true)
        } else if name.eq_ignore_ascii_case("priority") {
            Value::Integer(condition.priority)
        } else if name.eq_ignore_ascii_case("appliesto") {
            let applies = condition.applies.clone();
            if applies.len() == 1 {
                self.object(HostObject::Range(applies[0]))
            } else {
                self.blocks_object(applies)?
            }
        } else if name.eq_ignore_ascii_case("parent") {
            let first = condition.applies[0];
            self.object(HostObject::Range(first))
        } else if name.eq_ignore_ascii_case("font") {
            self.object(HostObject::ConditionFont(id))
        } else if name.eq_ignore_ascii_case("interior") {
            self.object(HostObject::ConditionInterior(id))
        } else if name.eq_ignore_ascii_case("setfirstpriority") {
            self.set_condition_priority(index, 1);
            Value::Empty
        } else if name.eq_ignore_ascii_case("setlastpriority") {
            let last = self.last_condition_priority(condition.sheet) + 1;
            self.conditions[index].priority = last;
            self.conditions.sort_by_key(|condition| condition.priority);
            Value::Empty
        } else if name.eq_ignore_ascii_case("delete") {
            self.conditions.remove(index);
            Value::Empty
        } else if name.eq_ignore_ascii_case("modify") {
            // `Modify Type, Operator, Formula1, Formula2`: the same reading as
            // Add, put over what is there, keeping the dress and the place.
            let held = self.conditions[index].clone();
            let kind = match args.first() {
                None | Some(Value::Missing) => held.kind,
                Some(value) => sort_number(value, "FormatCondition Type")?,
            };
            let range = held.applies[0];
            let made = self.add_condition(range, kind, args)?;
            let Value::Object(made) = made else {
                return Err("the modified condition could not be made".to_string());
            };
            let made_index = self.condition_id(&made).and_then(|(id, _)| self.condition_index(id).ok());
            let Some(made_index) = made_index else {
                return Err("the modified condition could not be found".to_string());
            };
            // Measured: a modified condition goes to the end of the
            // priorities, which is where the fresh one already is.
            let mut fresh = self.conditions.remove(made_index);
            fresh.id = held.id;
            fresh.applies = held.applies;
            fresh.stop_if_true = held.stop_if_true;
            fresh.bold = held.bold;
            fresh.italic = held.italic;
            fresh.underline = held.underline;
            fresh.strikethrough = held.strikethrough;
            fresh.font_color = held.font_color;
            fresh.fill = held.fill;
            let index = self.condition_index(held.id)?;
            self.conditions.remove(index);
            self.conditions.push(fresh);
            Value::Empty
        } else {
            return Ok(None);
        };
        Ok(Some(answer))
    }

    /// Set a part of a conditional format: its `StopIfTrue`, its `Priority`,
    /// or what its font and fill put on. Measured: a condition's font takes
    /// no size and no name -- both are 1004.
    fn set_condition(
        &mut self,
        id: u64,
        face: Option<StyleFace>,
        name: &str,
        value: Value,
    ) -> Result<bool, String> {
        let index = self.condition_index(id)?;
        match face {
            None => {
                if name.eq_ignore_ascii_case("stopiftrue") {
                    if let Some(stop) = style_face_boolean(&value, "FormatCondition.StopIfTrue")? {
                        self.conditions[index].stop_if_true = stop;
                    }
                    return Ok(true);
                }
                if name.eq_ignore_ascii_case("priority") {
                    let priority = sort_number(&value, "FormatCondition.Priority")?;
                    self.set_condition_priority(index, priority);
                    return Ok(true);
                }
                Ok(false)
            }
            Some(StyleFace::Font) => {
                let condition = &mut self.conditions[index];
                if name.eq_ignore_ascii_case("bold") {
                    condition.bold = style_face_boolean(&value, "Font.Bold")?.or(condition.bold);
                } else if name.eq_ignore_ascii_case("italic") {
                    condition.italic = style_face_boolean(&value, "Font.Italic")?.or(condition.italic);
                } else if name.eq_ignore_ascii_case("strikethrough") {
                    condition.strikethrough =
                        style_face_boolean(&value, "Font.Strikethrough")?.or(condition.strikethrough);
                } else if name.eq_ignore_ascii_case("underline") {
                    condition.underline = Some(match &value {
                        Value::Boolean(held) => *held,
                        value if any_whole_number(value).is_some() => {
                            any_whole_number(value).unwrap_or_default() != UNDERLINE_NONE
                        }
                        _ => return Err("Font.Underline takes True, False, or an underline style".to_string()),
                    });
                } else if name.eq_ignore_ascii_case("color") {
                    condition.font_color = style_color(&value, "Font.Color")?;
                } else if name.eq_ignore_ascii_case("colorindex") {
                    condition.font_color = palette_choice(&value, COLOUR_AUTOMATIC, "Font.ColorIndex")?;
                } else if name.eq_ignore_ascii_case("size") || name.eq_ignore_ascii_case("name") {
                    return Err("a conditional format cannot change the font's size or face".to_string());
                } else {
                    return Ok(false);
                }
                Ok(true)
            }
            Some(StyleFace::Interior) => {
                let condition = &mut self.conditions[index];
                if name.eq_ignore_ascii_case("color") {
                    condition.fill = style_color(&value, "Interior.Color")?;
                } else if name.eq_ignore_ascii_case("colorindex") {
                    condition.fill = palette_choice(&value, COLOUR_NONE, "Interior.ColorIndex")?;
                } else if name.eq_ignore_ascii_case("pattern") {
                    // Solid or none is all the fill this build keeps.
                    if any_whole_number(&value) == Some(COLOUR_NONE) {
                        condition.fill = None;
                    }
                } else {
                    return Ok(false);
                }
                Ok(true)
            }
            Some(StyleFace::Borders(_)) => Ok(false),
        }
    }

    /// What `Range.DisplayFormat` and its font and fill answer to: the dress
    /// every cell shows, or Null where the cells differ.
    fn display_format_member(
        &mut self,
        range: CellRange,
        face: Option<StyleFace>,
        name: &str,
    ) -> Result<Option<Value>, String> {
        Self::range_cell_count(range)?;
        match face {
            None => {
                if name.eq_ignore_ascii_case("font") {
                    return Ok(Some(self.object(HostObject::DisplayFont(range))));
                }
                if name.eq_ignore_ascii_case("interior") {
                    return Ok(Some(self.object(HostObject::DisplayInterior(range))));
                }
                if name.eq_ignore_ascii_case("parent") {
                    return Ok(Some(self.object(HostObject::Range(range))));
                }
                Ok(None)
            }
            Some(face) => {
                let shown: Vec<(Dress, Option<String>, bool)> =
                    range.addresses().map(|at| self.displayed_dress(at)).collect();
                let uniform = |pick: &dyn Fn(&(Dress, Option<String>, bool)) -> Value| -> Value {
                    let first = pick(&shown[0]);
                    if shown.iter().all(|one| pick(one) == first) { first } else { Value::Null }
                };
                let answer = match (face, name.to_ascii_lowercase().as_str()) {
                    (StyleFace::Font, "bold") => uniform(&|one| Value::Boolean(one.0.bold)),
                    (StyleFace::Font, "italic") => uniform(&|one| Value::Boolean(one.0.italic)),
                    (StyleFace::Font, "strikethrough") => uniform(&|one| Value::Boolean(one.2)),
                    (StyleFace::Font, "underline") => uniform(&|one| {
                        Value::Integer(if one.0.underline { UNDERLINE_SINGLE } else { UNDERLINE_NONE })
                    }),
                    (StyleFace::Font, "color") => uniform(&|one| {
                        Value::Integer(colour_to_packed(one.0.color.as_deref()).unwrap_or(BLACK))
                    }),
                    (StyleFace::Interior, "color") => uniform(&|one| {
                        Value::Integer(colour_to_packed(one.1.as_deref()).unwrap_or(WHITE))
                    }),
                    (StyleFace::Interior, "colorindex") => uniform(&|one| match colour_to_packed(one.1.as_deref()) {
                        Some(packed) => Value::Integer(nearest_palette_index(packed)),
                        None => Value::Integer(COLOUR_NONE),
                    }),
                    (StyleFace::Interior, "pattern") => uniform(&|one| {
                        Value::Integer(if one.1.is_some() { 1 } else { COLOUR_NONE })
                    }),
                    (_, "parent") => self.object(HostObject::DisplayFormat(range)),
                    _ => return Ok(None),
                };
                Ok(Some(answer))
            }
        }
    }

    fn validation_range(&self, object: &ObjectRef) -> Option<CellRange> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::Validation(range)) => Some(*range),
            _ => None,
        }
    }

    /// The one validation every cell of a range carries, or the 1004 Excel
    /// raises for a cell without one and for a range whose cells differ --
    /// measured, `Range("D3:D5").Validation.Type` with D5 bare is 1004.
    fn shared_validation(&self, range: CellRange) -> Result<Validation, String> {
        Self::range_cell_count(range)?;
        let mut shared: Option<&Validation> = None;
        for address in range.addresses() {
            let held = self
                .validations
                .get(&address)
                .ok_or_else(|| "the range has no data validation".to_string())?;
            if shared.is_some_and(|shared| shared != held) {
                return Err("the cells of the range are validated differently".to_string());
            }
            shared = Some(held);
        }
        shared
            .cloned()
            .ok_or_else(|| "the range has no data validation".to_string())
    }

    /// `Validation.Add Type, AlertStyle, Operator, Formula1, Formula2`, and
    /// `Modify` with the same arguments over what is there.
    ///
    /// Measured: Add on cells already validated is 1004 (Delete first);
    /// a type outside 0..7, an operator outside 1..8, a numeric type with no
    /// Formula1 or one that is not a number, a `Between` with no Formula2,
    /// and a list with an empty Formula1 are 1004 too; Operator left out is
    /// xlBetween and AlertStyle left out is xlValidAlertStop; the flags all
    /// start True.
    fn add_validation(
        &mut self,
        range: CellRange,
        args: &[Value],
        modifying: bool,
    ) -> Result<(), String> {
        Self::range_cell_count(range)?;
        let given = |index: usize| match args.get(index) {
            Some(Value::Missing) | None => None,
            Some(value) => Some(value),
        };
        let existing = if modifying {
            Some(self.shared_validation(range)?)
        } else {
            if range.addresses().any(|address| self.validations.contains_key(&address)) {
                return Err("the range already has data validation; delete it first".to_string());
            }
            None
        };
        let number_or = |index: usize, held: i64| -> Result<i64, String> {
            match given(index) {
                None => Ok(held),
                Some(value) => sort_number(value, "Validation"),
            }
        };
        let text_or = |index: usize, held: &str| -> Result<String, String> {
            match given(index) {
                None => Ok(held.to_string()),
                Some(Value::String(text)) => Ok(text.clone()),
                Some(value) if any_number(value).is_some() => Ok(shown_text(value, None)),
                Some(_) => Err("a validation's formula is text".to_string()),
            }
        };
        let base = existing.clone().unwrap_or(Validation {
            kind: 0,
            alert: 1,
            operator: 1,
            formula1: String::new(),
            formula2: String::new(),
            in_cell_dropdown: true,
            ignore_blank: true,
            show_input: true,
            show_error: true,
            input_title: String::new(),
            input_message: String::new(),
            error_title: String::new(),
            error_message: String::new(),
        });
        let kind = number_or(0, base.kind)?;
        if !(0..=7).contains(&kind) {
            return Err(format!("{kind} is not a kind of data validation"));
        }
        let alert = number_or(1, base.alert)?;
        if !(1..=3).contains(&alert) {
            return Err(format!("{alert} is not a validation alert style"));
        }
        let operator = number_or(2, base.operator)?;
        if !(1..=8).contains(&operator) {
            return Err(format!("{operator} is not a validation operator"));
        }
        let formula1 = text_or(3, &base.formula1)?;
        let formula2 = text_or(4, &base.formula2)?;
        if kind != 0 && formula1.is_empty() {
            return Err("this kind of data validation needs Formula1".to_string());
        }
        if matches!(kind, 1 | 2 | 4 | 5 | 6) {
            for formula in [&formula1, &formula2] {
                if !formula.is_empty() && formula_number(formula).is_none() && !formula.starts_with('=') {
                    return Err(format!("{formula:?} is not a number a validation can compare with"));
                }
            }
            // Measured: `Between` and `NotBetween` want both bounds --
            // `Add Type:=xlValidateWholeNumber, Formula1:="1"` alone is 1004.
            if matches!(operator, 1 | 2) && formula2.is_empty() {
                return Err("Between and NotBetween need Formula2 as well".to_string());
            }
        }
        let validation = Validation {
            kind,
            alert,
            operator,
            formula1: kept_validation_formula(kind, &formula1),
            formula2: kept_validation_formula(kind, &formula2),
            ..base
        };
        for address in range.addresses() {
            self.validations.insert(address, validation.clone());
        }
        Ok(())
    }

    /// Whether the cell's value passes its validation, as `Validation.Value`
    /// answers. Measured: a blank passes with `IgnoreBlank` and fails without;
    /// a whole number is not 15.5 and not text; a list is matched exactly in
    /// case, on the cell's text with its ends trimmed, against items kept as
    /// written; `Between` takes its bounds either way round; a formula in
    /// Formula1 is worked out afresh.
    fn validation_passes(&self, at: CellAddress, validation: &Validation) -> bool {
        let cell = self.cell_here(at.sheet, at.row, at.column);
        let value = cell
            .as_ref()
            .map(|cell| from_cell_value(&cell.value))
            .unwrap_or(Value::Empty);
        if matches!(value, Value::Empty) {
            return validation.ignore_blank;
        }
        let number = |formula: &str| -> Option<f64> {
            match formula.strip_prefix('=') {
                Some(expression) => match oxicells_core::formula::evaluate_expression(
                    self.workbook,
                    at.sheet,
                    expression,
                    self.now,
                ) {
                    Some(oxicells_calc::Value::Number(number)) => Some(number),
                    Some(oxicells_calc::Value::Logical(state)) => Some(f64::from(state)),
                    _ => None,
                },
                None => formula_number(formula),
            }
        };
        let compare = |held: f64| -> bool {
            let Some(first) = number(&validation.formula1) else {
                return false;
            };
            let second = number(&validation.formula2);
            match validation.operator {
                1 | 2 => {
                    let Some(second) = second else {
                        return false;
                    };
                    let (low, high) = (first.min(second), first.max(second));
                    let inside = held >= low && held <= high;
                    if validation.operator == 1 { inside } else { !inside }
                }
                3 => held == first,
                4 => held != first,
                5 => held > first,
                6 => held < first,
                7 => held >= first,
                _ => held <= first,
            }
        };
        match validation.kind {
            0 => true,
            1 | 2 | 4 | 5 => match value {
                Value::Double(held) => {
                    if validation.kind == 1 && held.fract() != 0.0 {
                        return false;
                    }
                    compare(held)
                }
                Value::Integer(held) => compare(held as f64),
                _ => false,
            },
            6 => compare(shown_text(&value, None).chars().count() as f64),
            3 => {
                let shown = cell
                    .as_ref()
                    .map(|cell| {
                        shown_text(&from_cell_value(&cell.value), cell.style.number_format.as_deref())
                    })
                    .unwrap_or_default();
                let shown = shown.trim();
                self.list_items(at.sheet, &validation.formula1)
                    .iter()
                    .any(|item| item == shown)
            }
            _ => match validation.formula1.strip_prefix('=') {
                Some(expression) => matches!(
                    oxicells_core::formula::evaluate_expression(
                        self.workbook,
                        at.sheet,
                        expression,
                        self.now,
                    ),
                    Some(oxicells_calc::Value::Logical(true))
                ) || matches!(
                    oxicells_core::formula::evaluate_expression(
                        self.workbook,
                        at.sheet,
                        expression,
                        self.now,
                    ),
                    Some(oxicells_calc::Value::Number(number)) if number != 0.0
                ),
                None => false,
            },
        }
    }

    /// The items a list validation offers: the pieces between commas, kept
    /// with their spaces, or the shown text of the cells a reference names.
    fn list_items(&self, sheet: usize, formula: &str) -> Vec<String> {
        match formula.strip_prefix('=') {
            None => formula.split(',').map(str::to_string).collect(),
            Some(reference) => {
                let reference = reference.replace('$', "");
                let (sheet, reference) = match reference.rsplit_once('!') {
                    Some((named, rest)) => {
                        let named = named.trim_matches('\'');
                        match self
                            .workbook
                            .sheets
                            .iter()
                            .position(|held| held.name.eq_ignore_ascii_case(named))
                        {
                            Some(sheet) => (sheet, rest.to_string()),
                            None => return Vec::new(),
                        }
                    }
                    None => (sheet, reference),
                };
                let Ok(((start_column, start_row), (end_column, end_row))) =
                    parse_range_reference(&reference)
                else {
                    return Vec::new();
                };
                let mut items = Vec::new();
                for row in start_row..=end_row {
                    for column in start_column..=end_column {
                        let shown = self
                            .cell_here(sheet, row, column)
                            .map(|cell| {
                                shown_text(
                                    &from_cell_value(&cell.value),
                                    cell.style.number_format.as_deref(),
                                )
                            })
                            .unwrap_or_default();
                        items.push(shown);
                    }
                }
                items
            }
        }
    }

    /// What `Range.Validation` answers to.
    fn validation_member(
        &mut self,
        range: CellRange,
        name: &str,
        args: &[Value],
    ) -> Result<Option<Value>, String> {
        if name.eq_ignore_ascii_case("add") {
            self.add_validation(range, args, false)?;
            return Ok(Some(Value::Empty));
        }
        if name.eq_ignore_ascii_case("modify") {
            self.add_validation(range, args, true)?;
            return Ok(Some(Value::Empty));
        }
        // Measured: deleting where there is nothing to delete is no error.
        if name.eq_ignore_ascii_case("delete") {
            Self::range_cell_count(range)?;
            for address in range.addresses() {
                self.validations.remove(&address);
            }
            return Ok(Some(Value::Empty));
        }
        if name.eq_ignore_ascii_case("parent") {
            return Ok(Some(self.object(HostObject::Range(range))));
        }
        // Measured: a cell with no validation passes.
        if name.eq_ignore_ascii_case("value") && self.shared_validation(range).is_err() {
            return Ok(Some(Value::Boolean(true)));
        }
        let held = self.shared_validation(range)?;
        let answer = if name.eq_ignore_ascii_case("type") {
            Value::Integer(held.kind)
        } else if name.eq_ignore_ascii_case("alertstyle") {
            Value::Integer(held.alert)
        } else if name.eq_ignore_ascii_case("operator") {
            Value::Integer(held.operator)
        } else if name.eq_ignore_ascii_case("formula1") {
            Value::String(held.formula1.clone())
        } else if name.eq_ignore_ascii_case("formula2") {
            Value::String(held.formula2.clone())
        } else if name.eq_ignore_ascii_case("incelldropdown") {
            Value::Boolean(held.in_cell_dropdown)
        } else if name.eq_ignore_ascii_case("ignoreblank") {
            Value::Boolean(held.ignore_blank)
        } else if name.eq_ignore_ascii_case("showinput") {
            Value::Boolean(held.show_input)
        } else if name.eq_ignore_ascii_case("showerror") {
            Value::Boolean(held.show_error)
        } else if name.eq_ignore_ascii_case("inputtitle") {
            Value::String(held.input_title.clone())
        } else if name.eq_ignore_ascii_case("inputmessage") {
            Value::String(held.input_message.clone())
        } else if name.eq_ignore_ascii_case("errortitle") {
            Value::String(held.error_title.clone())
        } else if name.eq_ignore_ascii_case("errormessage") {
            Value::String(held.error_message.clone())
        } else if name.eq_ignore_ascii_case("value") {
            Value::Boolean(
                range
                    .addresses()
                    .all(|address| self.validation_passes(address, &held)),
            )
        } else {
            return Ok(None);
        };
        Ok(Some(answer))
    }

    /// Set one part of the validation every cell of a range carries.
    fn set_validation(&mut self, range: CellRange, name: &str, value: Value) -> Result<bool, String> {
        let mut held = self.shared_validation(range)?;
        let flag = || style_face_boolean(&value, "Validation");
        let text = || -> Result<String, String> {
            match &value {
                Value::String(text) => Ok(text.clone()),
                value if any_number(value).is_some() => Ok(shown_text(value, None)),
                _ => Err("a validation's messages are text".to_string()),
            }
        };
        if name.eq_ignore_ascii_case("incelldropdown") {
            held.in_cell_dropdown = flag()?.unwrap_or(held.in_cell_dropdown);
        } else if name.eq_ignore_ascii_case("ignoreblank") {
            held.ignore_blank = flag()?.unwrap_or(held.ignore_blank);
        } else if name.eq_ignore_ascii_case("showinput") {
            held.show_input = flag()?.unwrap_or(held.show_input);
        } else if name.eq_ignore_ascii_case("showerror") {
            held.show_error = flag()?.unwrap_or(held.show_error);
        } else if name.eq_ignore_ascii_case("inputtitle") {
            held.input_title = text()?;
        } else if name.eq_ignore_ascii_case("inputmessage") {
            held.input_message = text()?;
        } else if name.eq_ignore_ascii_case("errortitle") {
            held.error_title = text()?;
        } else if name.eq_ignore_ascii_case("errormessage") {
            held.error_message = text()?;
        } else {
            return Ok(false);
        }
        for address in range.addresses() {
            self.validations.insert(address, held.clone());
        }
        Ok(true)
    }

    fn characters_of(&self, object: &ObjectRef) -> Option<(CellAddress, u32, Option<u32>)> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::Characters(at, start, length)) => Some((*at, *start, *length)),
            _ => None,
        }
    }

    fn characters_font_of(&self, object: &ObjectRef) -> Option<(CellAddress, u32, Option<u32>)> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::CharactersFont(at, start, length)) => Some((*at, *start, *length)),
            _ => None,
        }
    }

    /// `Range.Characters([Start], [Length])`, on one cell.
    fn characters_object(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        if !range.is_single() {
            return Err("Range.Characters needs a single cell".to_string());
        }
        let given = |index: usize| match args.get(index) {
            Some(Value::Missing) | None => None,
            Some(value) => Some(value),
        };
        let start = match given(0) {
            None => 1,
            Some(value) => sort_number(value, "Characters Start")?.max(0) as u32,
        };
        let length = match given(1) {
            None => None,
            Some(value) => Some(sort_number(value, "Characters Length")?.max(0) as u32),
        };
        let at = CellAddress {
            sheet: range.sheet,
            row: range.start_row,
            column: range.start_column,
        };
        Ok(self.object(HostObject::Characters(at, start, length)))
    }

    /// The cell a stretch of characters belongs to, made if it is not there.
    fn cell_for_characters(&mut self, at: CellAddress) -> Result<&mut Cell, String> {
        if self.cell_here(at.sheet, at.row, at.column).is_none() {
            self.set_cell_value(at, CellValue::Empty)?;
        }
        self.workbook.sheets[at.sheet]
            .rows
            .iter_mut()
            .find(|row| row.index == at.row)
            .and_then(|row| row.cells.iter_mut().find(|cell| cell.col == at.column))
            .ok_or_else(|| "the cell could not be reached".to_string())
    }

    /// Put text in place of a stretch of a cell's characters, the new text
    /// dressed as the first character it replaces was -- or, when it replaces
    /// nothing, as the character before it. Measured: `Characters(6, 0).Insert
    /// "-"` between a bold black `o` and a red `T` comes out bold and black.
    fn replace_characters(
        &mut self,
        at: CellAddress,
        start: u32,
        length: Option<u32>,
        with: &str,
    ) -> Result<(), String> {
        if self.write_is_protected(at) {
            return Err(
                "the cell is locked and the sheet is protected; unprotect it first".to_string(),
            );
        }
        let cell = self.cell_for_characters(at)?;
        if !matches!(cell.value, CellValue::String(_) | CellValue::Empty) || cell.formula.is_some() {
            return Err("Characters can only be replaced in a cell holding text".to_string());
        }
        let text: Vec<char> = cell_text_of(cell).chars().collect();
        let mut dresses = dresses_of(cell);
        let (from, to) = character_span(start, length, text.len());
        let dress = dresses
            .get(from)
            .filter(|_| to > from)
            .or_else(|| from.checked_sub(1).and_then(|before| dresses.get(before)))
            .or_else(|| dresses.first())
            .cloned()
            .unwrap_or_else(|| Dress::of_style(&cell.style));
        let mut new_text: String = text[..from].iter().collect();
        new_text.push_str(with);
        new_text.extend(text[to..].iter());
        let inserted: Vec<Dress> = with.chars().map(|_| dress.clone()).collect();
        dresses.splice(from..to, inserted);
        redress(cell, &new_text, &dresses);
        self.wrote = true;
        Ok(())
    }

    /// Dress a stretch of a cell's characters. A cell holding a number or a
    /// formula has no characters of its own to dress, and the whole cell is
    /// dressed instead -- measured, `Characters(1, 2).Font.Bold = True` on
    /// 12345 leaves the cell bold and a Double.
    fn dress_characters(
        &mut self,
        at: CellAddress,
        start: u32,
        length: Option<u32>,
        update: impl Fn(&mut Dress),
    ) -> Result<(), String> {
        self.guard_formats(at.sheet, "formatting characters")?;
        let cell = self.cell_for_characters(at)?;
        if !matches!(cell.value, CellValue::String(_)) || cell.formula.is_some() {
            let mut dress = Dress::of_style(&cell.style);
            update(&mut dress);
            cell.style.bold = dress.bold;
            cell.style.italic = dress.italic;
            cell.style.underline = dress.underline;
            cell.style.font_size = dress.size;
            cell.style.font_name = dress.font;
            cell.style.font_color = dress.color;
            return Ok(());
        }
        let text = cell_text_of(cell);
        let mut dresses = dresses_of(cell);
        let (from, to) = character_span(start, length, dresses.len());
        for dress in &mut dresses[from..to] {
            update(dress);
        }
        redress(cell, &text, &dresses);
        Ok(())
    }

    /// The dress every character of a stretch shares, or None where they
    /// differ.
    fn uniform_character_dress<T: PartialEq + Clone>(
        &self,
        at: CellAddress,
        start: u32,
        length: Option<u32>,
        read: impl Fn(&Dress) -> T,
    ) -> Option<T> {
        let Some(cell) = self.cell_here(at.sheet, at.row, at.column) else {
            return Some(read(&Dress::of_style(&CellStyle::default())));
        };
        let dresses = dresses_of(&cell);
        let (from, to) = character_span(start, length, dresses.len());
        if from >= to {
            return Some(read(&Dress::of_style(&cell.style)));
        }
        let mut first: Option<T> = None;
        for dress in &dresses[from..to] {
            let value = read(dress);
            if first.as_ref().is_some_and(|held| *held != value) {
                return None;
            }
            first = Some(value);
        }
        first
    }

    /// The font attribute every character of every cell of a range shares,
    /// looking inside the runs of a cell dressed unevenly -- measured, a
    /// cell whose first word alone is bold answers Null to `Font.Bold`.
    fn uniform_font<T: PartialEq + Clone>(
        &self,
        range: CellRange,
        read: impl Fn(&Dress) -> T,
    ) -> Result<Option<T>, String> {
        // A whole sheet, column or row: the cells that exist, and the dress
        // every other cell there would wear.
        let addresses: Vec<CellAddress> = if Self::band_of(range) == Band::Cells {
            Self::range_cell_count(range)?;
            range.addresses().collect()
        } else {
            let mut listed = self.existing_cells_in(range);
            listed.push(CellAddress { sheet: range.sheet, row: MAX_WORKSHEET_ROW, column: MAX_WORKSHEET_COLUMN });
            listed
        };
        let mut first: Option<T> = None;
        for address in addresses {
            let values: Vec<T> = match self.cell_here(address.sheet, address.row, address.column) {
                None => vec![read(&Dress::of_style(&self.template_style(address)))],
                Some(cell) if cell.runs.is_empty() => vec![read(&Dress::of_style(&cell.style))],
                Some(cell) => cell
                    .runs
                    .iter()
                    .map(|run| read(&Dress::of_run(run, &cell.style)))
                    .collect(),
            };
            for value in values {
                if first.as_ref().is_some_and(|held| *held != value) {
                    return Ok(None);
                }
                first = Some(value);
            }
        }
        Ok(first)
    }

    /// One answer for every cell of a range, read from the cell's dress AND
    /// the marks the host keeps on it, or None where the cells disagree.
    fn uniform_marked<T: PartialEq + Clone>(
        &self,
        range: CellRange,
        read: impl Fn(&CellStyle, CellMarks) -> T,
    ) -> Result<Option<T>, String> {
        Self::range_cell_count(range)?;
        let mut first: Option<T> = None;
        for address in range.addresses() {
            let style = self
                .cell_here(address.sheet, address.row, address.column)
                .map(|cell| cell.style)
                .unwrap_or_else(|| self.template_style(address));
            let value = read(&style, self.marks_of(address));
            if first.as_ref().is_some_and(|held| *held != value) {
                return Ok(None);
            }
            first = Some(value);
        }
        Ok(first)
    }

    /// Carry a whole-cell font change into the runs of a cell dressed
    /// unevenly, keeping what else they wear -- measured, `Font.Bold = True`
    /// on such a cell leaves its red word red.
    fn redress_runs(&mut self, range: CellRange, update: impl Fn(&mut Dress)) {
        for address in self.touched(range) {
            let Some(sheet) = self.workbook.sheets.get_mut(address.sheet) else {
                continue;
            };
            let Some(cell) = sheet
                .rows
                .iter_mut()
                .find(|row| row.index == address.row)
                .and_then(|row| row.cells.iter_mut().find(|cell| cell.col == address.column))
            else {
                continue;
            };
            if cell.runs.is_empty() {
                continue;
            }
            let text = cell_text_of(cell);
            let mut dresses = dresses_of(cell);
            for dress in &mut dresses {
                update(dress);
            }
            redress(cell, &text, &dresses);
        }
    }

    /// What a stretch of characters answers to.
    fn characters_member(
        &mut self,
        at: CellAddress,
        start: u32,
        length: Option<u32>,
        name: &str,
        args: &[Value],
    ) -> Result<Option<Value>, String> {
        let text_of = || -> String {
            self.cell_here(at.sheet, at.row, at.column)
                .map(|cell| {
                    let text: Vec<char> = cell_text_of(&cell).chars().collect();
                    let (from, to) = character_span(start, length, text.len());
                    text[from..to].iter().collect()
                })
                .unwrap_or_default()
        };
        if name.eq_ignore_ascii_case("text") || name.eq_ignore_ascii_case("caption") {
            return Ok(Some(Value::String(text_of())));
        }
        if name.eq_ignore_ascii_case("count") {
            // Not the length of the stretch. Measured: `Characters(1, 5).Count`
            // is 1, `Characters(3, 100).Count` is 3, `Characters(100, 2).Count`
            // is 100 -- the START -- and with no length given it is the
            // length of the whole text: `Characters(7).Count` of an
            // eleven-letter text is 11.
            let count = match length {
                Some(_) => i64::from(start),
                None => self
                    .cell_here(at.sheet, at.row, at.column)
                    .map(|cell| cell_text_of(&cell).chars().count() as i64)
                    .unwrap_or(0),
            };
            return Ok(Some(Value::Integer(count)));
        }
        if name.eq_ignore_ascii_case("parent") {
            return Ok(Some(self.object(HostObject::Range(CellRange::single(at)))));
        }
        if name.eq_ignore_ascii_case("font") {
            return Ok(Some(self.object(HostObject::CharactersFont(at, start, length))));
        }
        if name.eq_ignore_ascii_case("insert") {
            let [with] = args else {
                return Err("Characters.Insert takes the text to put in".to_string());
            };
            let with = match with {
                Value::String(text) => text.clone(),
                value if any_number(value).is_some() => shown_text(value, None),
                _ => return Err("Characters.Insert takes text".to_string()),
            };
            self.replace_characters(at, start, length, &with)?;
            return Ok(Some(Value::Empty));
        }
        if name.eq_ignore_ascii_case("delete") {
            self.replace_characters(at, start, length, "")?;
            return Ok(Some(Value::Empty));
        }
        Ok(None)
    }

    /// What the font of a stretch of characters answers to.
    fn characters_font_member(
        &mut self,
        at: CellAddress,
        start: u32,
        length: Option<u32>,
        name: &str,
    ) -> Result<Option<Value>, String> {
        let default_name = self
            .workbook
            .default_style
            .font_name
            .clone()
            .unwrap_or_else(|| "Calibri".to_string());
        let default_size = self.workbook.default_style.font_size.unwrap_or(11.0);
        let answer = if name.eq_ignore_ascii_case("bold") {
            self.uniform_character_dress(at, start, length, |dress| dress.bold)
                .map(Value::Boolean)
        } else if name.eq_ignore_ascii_case("italic") {
            self.uniform_character_dress(at, start, length, |dress| dress.italic)
                .map(Value::Boolean)
        } else if name.eq_ignore_ascii_case("underline") {
            self.uniform_character_dress(at, start, length, |dress| dress.underline)
                .map(|held| Value::Integer(if held { UNDERLINE_SINGLE } else { UNDERLINE_NONE }))
        } else if name.eq_ignore_ascii_case("size") {
            self.uniform_character_dress(at, start, length, |dress| dress.size)
                .map(|held| Value::Double(f64::from(held.unwrap_or(default_size))))
        } else if name.eq_ignore_ascii_case("name") {
            self.uniform_character_dress(at, start, length, |dress| dress.font.clone())
                .map(|held| Value::String(held.unwrap_or(default_name)))
        } else if name.eq_ignore_ascii_case("color") {
            self.uniform_character_dress(at, start, length, |dress| dress.color.clone())
                .map(|held| style_color_value(Some(held), BLACK))
        } else if name.eq_ignore_ascii_case("colorindex") {
            self.uniform_character_dress(at, start, length, |dress| dress.color.clone())
                .map(|held| match colour_to_packed(held.as_deref()) {
                    None => Value::Integer(1),
                    Some(packed) => Value::Integer(nearest_palette_index(packed)),
                })
        } else if name.eq_ignore_ascii_case("superscript") {
            self.uniform_character_dress(at, start, length, |dress| {
                dress.vert_align.as_deref() == Some("superscript")
            })
            .map(Value::Boolean)
        } else if name.eq_ignore_ascii_case("subscript") {
            self.uniform_character_dress(at, start, length, |dress| {
                dress.vert_align.as_deref() == Some("subscript")
            })
            .map(Value::Boolean)
        } else if name.eq_ignore_ascii_case("parent") {
            return Ok(Some(self.object(HostObject::Characters(at, start, length))));
        } else {
            return Ok(None);
        };
        Ok(Some(answer.unwrap_or(Value::Null)))
    }

    /// Set one attribute of the font of a stretch of characters.
    fn set_characters_font(
        &mut self,
        at: CellAddress,
        start: u32,
        length: Option<u32>,
        name: &str,
        value: Value,
    ) -> Result<bool, String> {
        if name.eq_ignore_ascii_case("bold") {
            let Some(held) = style_face_boolean(&value, "Font.Bold")? else {
                return Ok(true);
            };
            self.dress_characters(at, start, length, |dress| dress.bold = held)?;
        } else if name.eq_ignore_ascii_case("italic") {
            let Some(held) = style_face_boolean(&value, "Font.Italic")? else {
                return Ok(true);
            };
            self.dress_characters(at, start, length, |dress| dress.italic = held)?;
        } else if name.eq_ignore_ascii_case("underline") {
            let held = match &value {
                Value::Boolean(held) => *held,
                value if any_whole_number(value).is_some() => {
                    any_whole_number(value).unwrap_or_default() != UNDERLINE_NONE
                }
                _ => return Err("Font.Underline takes True, False, or an underline style".to_string()),
            };
            self.dress_characters(at, start, length, |dress| dress.underline = held)?;
        } else if name.eq_ignore_ascii_case("size") {
            let held = font_size(&value)?;
            self.dress_characters(at, start, length, |dress| dress.size = held)?;
        } else if name.eq_ignore_ascii_case("name") {
            let held = match &value {
                Value::String(named) if named.is_empty() => None,
                Value::String(named) => Some(named.clone()),
                _ => return Err("Font.Name must be a name".to_string()),
            };
            self.dress_characters(at, start, length, |dress| dress.font = held.clone())?;
        } else if name.eq_ignore_ascii_case("color") {
            let held = style_color(&value, "Font.Color")?;
            self.dress_characters(at, start, length, |dress| dress.color = held.clone())?;
        } else if name.eq_ignore_ascii_case("colorindex") {
            let held = palette_choice(&value, COLOUR_AUTOMATIC, "Font.ColorIndex")?;
            self.dress_characters(at, start, length, |dress| dress.color = held.clone())?;
        } else if name.eq_ignore_ascii_case("superscript") || name.eq_ignore_ascii_case("subscript")
        {
            let Some(held) = style_face_boolean(&value, "Font.Superscript")? else {
                return Ok(true);
            };
            let which = if name.eq_ignore_ascii_case("superscript") { "superscript" } else { "subscript" };
            self.dress_characters(at, start, length, |dress| {
                dress.vert_align = if held { Some(which.to_string()) } else { None };
            })?;
        } else {
            return Ok(false);
        }
        Ok(true)
    }

    fn comment_cell(&self, object: &ObjectRef) -> Option<CellAddress> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::Comment(at)) => Some(*at),
            _ => None,
        }
    }

    fn comments_sheet(&self, object: &ObjectRef) -> Option<usize> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::Comments(sheet)) => Some(*sheet),
            _ => None,
        }
    }

    fn note_at(&self, at: CellAddress) -> Option<usize> {
        self.notes.iter().position(|note| note.at == at)
    }

    /// The notes on a sheet, in the order `Comments(1)` counts them.
    fn notes_on(&self, sheet: usize) -> Vec<usize> {
        let mut held: Vec<usize> = (0..self.notes.len())
            .filter(|&index| self.notes[index].at.sheet == sheet)
            .collect();
        // ORDER_RULE
        held.sort_by_key(|&index| (self.notes[index].at.row, self.notes[index].at.column));
        held
    }

    /// The note a range answers for: the one on its cell, or Nothing. A
    /// range of several cells is Nothing whatever is on them -- measured,
    /// `Range("A1:B2").Comment` is Nothing with a note on A1.
    fn comment_of(&mut self, range: CellRange) -> Value {
        if !range.is_single() {
            return Value::Nothing;
        }
        let at = CellAddress {
            sheet: range.sheet,
            row: range.start_row,
            column: range.start_column,
        };
        match self.note_at(at) {
            Some(_) => self.object(HostObject::Comment(at)),
            None => Value::Nothing,
        }
    }

    /// `Range.TextToColumns Destination, DataType, TextQualifier,
    /// ConsecutiveDelimiter, Tab, Semicolon, Comma, Space, Other, OtherChar,
    /// FieldInfo, DecimalSeparator, ThousandsSeparator, TrailingMinusNumbers`.
    ///
    /// Measured against Excel: the source must be one column (two are 1004);
    /// each cell's text is split and the pieces written from the destination
    /// rightwards, over whatever was there, each piece read the way typing it
    /// would be -- `2.5` a number, `TRUE` a Boolean, `5%` a percentage -- unless
    /// `FieldInfo` says a field is text (2) or is to be skipped (9); a cell
    /// holding a formula is left alone; an empty piece between two delimiters
    /// leaves an empty cell unless `ConsecutiveDelimiter`; runs of SPACES are
    /// treated as one either way; a trailing delimiter adds nothing; a piece
    /// fenced by the qualifier keeps its delimiters; `3-` is text unless
    /// `TrailingMinusNumbers`; fixed width (`DataType:=2`) cuts at the
    /// character positions `FieldInfo` names, counted from 0. The settings
    /// stick for the next call, and it answers True.
    fn text_to_columns(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        if range.start_column != range.end_column {
            return Err("Range.TextToColumns needs a single column".to_string());
        }
        let given = |index: usize| match args.get(index) {
            Some(Value::Missing) | None => None,
            Some(value) => Some(value),
        };
        let flag = |index: usize, held: bool| -> Result<bool, String> {
            match given(index) {
                None => Ok(held),
                Some(value) => {
                    Ok(style_face_boolean(value, "Range.TextToColumns")?.unwrap_or(held))
                }
            }
        };
        let mut split = self.split.clone();
        if let Some(kind) = given(1) {
            split.delimited = match sort_number(kind, "TextToColumns DataType")? {
                1 => true,
                2 => false,
                other => return Err(format!("Range.TextToColumns cannot read DataType {other}")),
            };
        }
        if let Some(kind) = given(2) {
            split.qualifier = match sort_number(kind, "TextToColumns TextQualifier")? {
                1 => Some('"'),
                2 => Some('\''),
                -4142 => None,
                other => {
                    return Err(format!("Range.TextToColumns cannot read TextQualifier {other}"))
                }
            };
        }
        split.consecutive = flag(3, split.consecutive)?;
        split.tab = flag(4, split.tab)?;
        split.semicolon = flag(5, split.semicolon)?;
        split.comma = flag(6, split.comma)?;
        split.space = flag(7, split.space)?;
        if given(8).is_some() || given(9).is_some() {
            let wanted = flag(8, split.other.is_some())?;
            let character = match given(9) {
                Some(Value::String(text)) => text.chars().next(),
                Some(_) => return Err("Range.TextToColumns OtherChar must be text".to_string()),
                None => split.other,
            };
            split.other = if wanted { character } else { None };
        }
        split.trailing_minus = flag(13, split.trailing_minus)?;
        let rules = match given(10) {
            None => Vec::new(),
            Some(value) => field_rules(value)?,
        };
        if !split.delimited && rules.is_empty() {
            return Err("Range.TextToColumns needs FieldInfo to cut fixed widths".to_string());
        }
        let destination = match given(0) {
            None => CellAddress {
                sheet: range.sheet,
                row: range.start_row,
                column: range.start_column,
            },
            Some(Value::Object(object)) => {
                let target = self
                    .range(object)
                    .ok_or_else(|| "Range.TextToColumns Destination must be a Range".to_string())?;
                CellAddress {
                    sheet: target.sheet,
                    row: target.start_row,
                    column: target.start_column,
                }
            }
            Some(_) => return Err("Range.TextToColumns Destination must be a Range".to_string()),
        };

        for (step, address) in range.addresses().enumerate() {
            let Some(cell) = self.cell_here(address.sheet, address.row, address.column) else {
                continue;
            };
            // A formula is split as WRITTEN, not as it works out: measured,
            // `="f,g"` gives `="f` and `g"`, the first kept as text since it
            // is no formula any more.
            let text = match cell.formula.as_deref() {
                Some(formula) => format!("={formula}"),
                None if matches!(cell.value, CellValue::Empty) => continue,
                None => shown_text(
                    &from_cell_value(&cell.value),
                    cell.style.number_format.as_deref(),
                ),
            };
            let pieces = if split.delimited {
                split_delimited(&text, &split)
            } else {
                split_fixed(&text, &rules)
            };
            let row = destination.row + step as u32;
            let mut column = destination.column;
            for (index, piece) in pieces.into_iter().enumerate() {
                let rule = rules.iter().find(|rule| {
                    if split.delimited {
                        rule.at == index + 1
                    } else {
                        rule.at == index
                    }
                });
                let kind = rule.map(|rule| rule.kind).unwrap_or(1);
                if kind == 9 {
                    continue;
                }
                if column > MAX_WORKSHEET_COLUMN {
                    return Err("Range.TextToColumns runs off the right of the sheet".to_string());
                }
                let landing = CellAddress {
                    sheet: destination.sheet,
                    row,
                    column,
                };
                column += 1;
                if kind == 2 {
                    self.set_cell_value(landing, CellValue::String(piece))?;
                    continue;
                }
                let piece = match piece.strip_suffix('-') {
                    Some(body) if split.trailing_minus && !body.is_empty() => {
                        format!("-{}", body.trim())
                    }
                    _ => piece,
                };
                if piece.is_empty() {
                    self.set_cell_value(landing, CellValue::Empty)?;
                    continue;
                }
                let typed = self.set_range_input(
                    CellRange::single(landing),
                    Value::String(piece.clone()),
                    "Range.TextToColumns",
                    FormulaStyle::A1,
                );
                if typed.is_err() && piece.starts_with('=') {
                    self.set_cell_value(landing, CellValue::String(piece))?;
                    continue;
                }
                typed?;
            }
        }
        self.split = split;
        Ok(Value::Boolean(true))
    }

    /// `Range.AddComment [Text]`: one cell, not yet carrying a note.
    fn add_comment(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        if !range.is_single() {
            return Err(host_error(5, "Range.AddComment needs a single cell"));
        }
        let at = CellAddress {
            sheet: range.sheet,
            row: range.start_row,
            column: range.start_column,
        };
        if self.note_at(at).is_some() {
            return Err("the cell already has a comment".to_string());
        }
        if self.objects_protected(at.sheet) {
            return Err("the sheet is protected; unprotect it first".to_string());
        }
        // Only text: measured, `AddComment 42` and `AddComment True` are both
        // 1004 and leave the cell without a note.
        let text = match args.first() {
            None | Some(Value::Missing) => String::new(),
            Some(Value::String(text)) => text.clone(),
            Some(_) => return Err("Range.AddComment needs text".to_string()),
        };
        self.notes.push(Note {
            at,
            text,
            visible: false,
        });
        Ok(self.object(HostObject::Comment(at)))
    }

    /// Take the notes off every cell of a range.
    fn clear_comments(&mut self, range: CellRange) {
        self.notes.retain(|note| {
            note.at.sheet != range.sheet
                || !(range.start_row..=range.end_row).contains(&note.at.row)
                || !(range.start_column..=range.end_column).contains(&note.at.column)
        });
    }

    /// What one note answers to.
    fn comment_member(
        &mut self,
        at: CellAddress,
        name: &str,
        args: &[Value],
    ) -> Result<Option<Value>, String> {
        let Some(index) = self.note_at(at) else {
            return Err("the comment has been deleted".to_string());
        };
        if name.eq_ignore_ascii_case("text") {
            // Under protection a note is read but not written, and the write
            // is passed over in SILENCE: measured, `Comment.Text "edited"` on
            // a protected sheet raises nothing and changes nothing, while
            // `Visible` and `Delete` both go through.
            let writing = args.first().is_some_and(|value| !matches!(value, Value::Missing));
            if writing && self.objects_protected(at.sheet) {
                return Ok(Some(Value::String(self.notes[index].text.clone())));
            }
            return self.note_text(index, args).map(Some);
        }
        if name.eq_ignore_ascii_case("visible") {
            return Ok(Some(Value::Boolean(self.notes[index].visible)));
        }
        if name.eq_ignore_ascii_case("parent") {
            return Ok(Some(self.object(HostObject::Range(CellRange::single(at)))));
        }
        if name.eq_ignore_ascii_case("delete") {
            self.notes.remove(index);
            return Ok(Some(Value::Empty));
        }
        Ok(None)
    }

    /// `Comment.Text [Text], [Start], [Overwrite]`, as Excel actually does it,
    /// which is not as its documentation says.
    ///
    /// Measured on a note reading `hello world`: with no text, or an empty
    /// one, it answers what the note says and changes nothing. With text and
    /// no start it replaces the whole. With a start and `Overwrite` LEFT OUT
    /// the text goes in at that character and everything after it is
    /// dropped -- `"Z", 6` gives `helloZ`; a start past the end appends,
    /// without complaint. With `Overwrite:=False` given, the text goes in at
    /// that character and the rest is kept -- `"AB", 3, False` gives
    /// `heABllo world`. `Overwrite:=True` is error 5 however it is asked, as
    /// is a start of 0. A text that is not a string is 1004. What it answers
    /// is the text after the change.
    fn note_text(&mut self, index: usize, args: &[Value]) -> Result<Value, String> {
        let given = |index: usize| match args.get(index) {
            Some(Value::Missing) | None => None,
            Some(value) => Some(value),
        };
        let text = match given(0) {
            None => return Ok(Value::String(self.notes[index].text.clone())),
            Some(Value::String(text)) if text.is_empty() => {
                return Ok(Value::String(self.notes[index].text.clone()))
            }
            Some(Value::String(text)) => text.clone(),
            Some(_) => return Err("Comment.Text needs text".to_string()),
        };
        let overwrite = match given(2) {
            None => None,
            Some(value) => style_face_boolean(value, "Comment.Text Overwrite")?,
        };
        if overwrite == Some(true) {
            return Err(host_error(5, "Comment.Text cannot overwrite"));
        }
        let held = &mut self.notes[index].text;
        let Some(start) = given(1) else {
            *held = text;
            return Ok(Value::String(held.clone()));
        };
        let start = sort_number(start, "Comment.Text Start")?;
        if start < 1 {
            return Err(host_error(5, "Comment.Text cannot start before the first character"));
        }
        let before: String = held.chars().take(start as usize - 1).collect();
        let after: String = if overwrite == Some(false) {
            held.chars().skip(start as usize - 1).collect()
        } else {
            String::new()
        };
        *held = format!("{before}{text}{after}");
        Ok(Value::String(held.clone()))
    }

    fn is_window(&self, object: &ObjectRef) -> bool {
        matches!(
            self.objects.get(object.handle as usize),
            Some(HostObject::Window)
        )
    }

    fn is_application(&self, object: &ObjectRef) -> bool {
        matches!(
            self.objects.get(object.handle as usize),
            Some(HostObject::Application)
        )
    }

    fn is_workbooks(&self, object: &ObjectRef) -> bool {
        matches!(self.objects.get(object.handle as usize), Some(HostObject::Workbooks))
    }

    /// `Workbooks`, `Workbooks(1)`, `Workbooks("Book1")`: there is one, and
    /// the browser cannot open or add another. Measured: Count 1, Item(1)
    /// is the Workbook, `Workbooks.Add` makes a second in Excel -- which is
    /// the one thing here that must refuse.
    fn workbooks_member(&mut self, args: &[Value]) -> Result<Value, String> {
        match args {
            [] | [Value::Missing] => Ok(self.object(HostObject::Workbooks)),
            [index] => self.workbook_item(index),
            _ => Err("Workbooks takes one index".to_string()),
        }
    }

    fn workbook_item(&mut self, index: &Value) -> Result<Value, String> {
        let own = self.file_name.clone().unwrap_or_else(|| "Book1".to_string());
        let found = match index {
            Value::String(name) => name.eq_ignore_ascii_case(&own),
            value => any_whole_number(value) == Some(1),
        };
        if found {
            Ok(self.object(HostObject::Workbook))
        } else {
            Err(host_error(9, "there is no such workbook open"))
        }
    }

    fn outline_sheet(&self, object: &ObjectRef) -> Option<usize> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::Outline(sheet)) => Some(*sheet),
            _ => None,
        }
    }

    fn tab_sheet(&self, object: &ObjectRef) -> Option<usize> {
        match self.objects.get(object.handle as usize) {
            Some(HostObject::Tab(sheet)) => Some(*sheet),
            _ => None,
        }
    }

    fn tab_member(&self, sheet: usize, name: &str) -> Option<Value> {
        let tab = self.tabs.get(&sheet).copied();
        Some(match name.to_ascii_lowercase().as_str() {
            "color" => match tab {
                Some(tab) => Value::Integer(tab.colour),
                None => Value::Boolean(false),
            },
            "colorindex" => match tab {
                Some(tab) => Value::Integer(nearest_palette_index(tab.colour)),
                None => Value::Integer(COLOUR_NONE),
            },
            "themecolor" => Value::Integer(tab.and_then(|tab| tab.theme).map_or(0, |theme| theme as i64)),
            "tintandshade" => Value::Double(tab.map_or(0.0, |tab| tab.tint)),
            _ => return None,
        })
    }

    fn set_tab_member(&mut self, sheet: usize, name: &str, value: &Value) -> Result<bool, String> {
        if name.eq_ignore_ascii_case("color") {
            let Some(colour) = color_number(value, "Tab.Color")? else {
                self.tabs.remove(&sheet);
                return Ok(true);
            };
            self.tabs.insert(sheet, TabColour { colour: colour as i64, theme: None, tint: 0.0 });
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("colorindex") {
            match palette_choice(value, COLOUR_NONE, "Tab.ColorIndex")? {
                Some(colour) => {
                    let colour = colour_to_packed(Some(&colour)).unwrap_or(0);
                    self.tabs.insert(sheet, TabColour { colour, theme: None, tint: 0.0 });
                }
                None => {
                    self.tabs.remove(&sheet);
                }
            }
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("themecolor") {
            let theme = theme_colour(value)?;
            self.tabs.insert(sheet, TabColour { colour: THEME_COLOURS[theme - 1], theme: Some(theme), tint: 0.0 });
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("tintandshade") {
            let tint = tint_asked(value)?;
            if let Some(tab) = self.tabs.get_mut(&sheet) {
                tab.tint = tint;
                if let Some(theme) = tab.theme {
                    tab.colour = tinted(THEME_COLOURS[theme - 1], tint);
                }
            }
            return Ok(true);
        }
        Ok(false)
    }

    /// The marks on a cell, as they stand.
    fn marks_of(&self, at: CellAddress) -> CellMarks {
        CellMarks {
            rotation: self.rotations.get(&at).copied(),
            underline: self.underlines.get(&at).copied(),
            hatching: self.hatchings.get(&at).copied(),
            indented: self.indented.contains(&at),
        }
    }

    /// The marks on a cell, lifted off it.
    fn take_marks(&mut self, at: CellAddress) -> CellMarks {
        CellMarks {
            rotation: self.rotations.remove(&at),
            underline: self.underlines.remove(&at),
            hatching: self.hatchings.remove(&at),
            indented: self.indented.remove(&at),
        }
    }

    /// Put marks on a cell in place of whatever it had.
    fn put_marks(&mut self, at: CellAddress, marks: CellMarks) {
        match marks.rotation {
            Some(turn) => {
                self.rotations.insert(at, turn);
            }
            None => {
                self.rotations.remove(&at);
            }
        }
        match marks.underline {
            Some(rule) => {
                self.underlines.insert(at, rule);
            }
            None => {
                self.underlines.remove(&at);
            }
        }
        match marks.hatching {
            Some(hatching) => {
                self.hatchings.insert(at, hatching);
            }
            None => {
                self.hatchings.remove(&at);
            }
        }
        if marks.indented {
            self.indented.insert(at);
        } else {
            self.indented.remove(&at);
        }
    }

    /// A window property written: what the window shows of the sheet in
    /// front. `Ok(None)` means the name is not one of them.
    ///
    /// Measured: Zoom takes 10 to 400 and refuses 5 and 401 with 1004;
    /// 80.6 reads back as 80. ScrollRow refuses 0 and 2,000,000, and
    /// ScrollColumn 20,000, the same way.
    fn set_view(&mut self, name: &str, value: &Value) -> Result<Option<bool>, String> {
        let sheet = self.active_sheet;
        let flag = |what: &str| style_face_boolean(value, what).map(|flag| flag.unwrap_or(false));
        let whole = |what: &str| -> Result<i64, String> {
            match any_number(value) {
                Some(number) if number.is_finite() => Ok(number.trunc() as i64),
                _ => Err(format!("Window.{what} takes a number")),
            }
        };
        let set = if name.eq_ignore_ascii_case("zoom") {
            let asked = whole("Zoom")?;
            if !(10..=400).contains(&asked) {
                return Err(host_error(1004, "Window.Zoom takes 10 to 400"));
            }
            self.views.entry(sheet).or_default().zoom = asked as f64;
            true
        } else if name.eq_ignore_ascii_case("displaygridlines") {
            self.views.entry(sheet).or_default().gridlines = flag("Window.DisplayGridlines")?;
            true
        } else if name.eq_ignore_ascii_case("displayheadings") {
            self.views.entry(sheet).or_default().headings = flag("Window.DisplayHeadings")?;
            true
        } else if name.eq_ignore_ascii_case("displayformulas") {
            self.views.entry(sheet).or_default().formulas = flag("Window.DisplayFormulas")?;
            true
        } else if name.eq_ignore_ascii_case("displayzeros") {
            self.views.entry(sheet).or_default().zeros = flag("Window.DisplayZeros")?;
            true
        } else if name.eq_ignore_ascii_case("scrollrow") {
            let asked = whole("ScrollRow")?;
            if asked < 1 || asked > i64::from(MAX_WORKSHEET_ROW) {
                return Err(host_error(1004, "Window.ScrollRow is off the sheet"));
            }
            self.views.entry(sheet).or_default().scroll_row = asked as u32;
            true
        } else if name.eq_ignore_ascii_case("scrollcolumn") {
            let asked = whole("ScrollColumn")?;
            if asked < 1 || asked > i64::from(MAX_WORKSHEET_COLUMN) + 1 {
                return Err(host_error(1004, "Window.ScrollColumn is off the sheet"));
            }
            self.views.entry(sheet).or_default().scroll_column = asked as u32;
            true
        } else {
            return Ok(None);
        };
        Ok(Some(set))
    }

    /// The level of every row or column of a whole band, or None where the
    /// range is not a band of whole rows or whole columns -- which Excel
    /// refuses with 1004: measured, `Range("A7").OutlineLevel` raises.
    fn outline_band(range: CellRange) -> Option<(ShiftAxis, u32, u32)> {
        match Self::hidden_band(range).ok()? {
            ShiftAxis::Rows => Some((ShiftAxis::Rows, range.start_row, range.end_row)),
            ShiftAxis::Columns => {
                Some((ShiftAxis::Columns, range.start_column, range.end_column))
            }
        }
    }

    fn outline_level(&self, sheet: usize, axis: ShiftAxis, index: u32) -> u8 {
        let Some(outline) = self.outlines.get(&sheet) else {
            return 1;
        };
        let levels = match axis {
            ShiftAxis::Rows => &outline.rows,
            ShiftAxis::Columns => &outline.columns,
        };
        levels.get(&index).copied().unwrap_or(1)
    }

    fn set_outline_level(&mut self, sheet: usize, axis: ShiftAxis, index: u32, level: u8) {
        let outline = self.outlines.entry(sheet).or_default();
        let levels = match axis {
            ShiftAxis::Rows => &mut outline.rows,
            ShiftAxis::Columns => &mut outline.columns,
        };
        if level <= 1 {
            levels.remove(&index);
        } else {
            levels.insert(index, level);
        }
    }

    /// `Range.Group` / `Range.Ungroup`: every row or column of the range
    /// goes one level deeper, or one level up.
    ///
    /// Measured: whole rows group rows and whole columns group columns; a
    /// range that is neither groups its COLUMNS -- `Range("A9:A10").Group`
    /// and then `Range("A11:B12").Group` leave column A at level 3 and B at
    /// 2, with rows 9 to 12 still at 1. Grouping past the eighth level, and
    /// ungrouping what is at the first, are both refused with 1004.
    fn group_range(&mut self, range: CellRange, deeper: bool) -> Result<Value, String> {
        let (axis, first, last) = match Self::outline_band(range) {
            Some(band) => band,
            None => (ShiftAxis::Columns, range.start_column, range.end_column),
        };
        let levels: Vec<u8> = (first..=last)
            .map(|index| self.outline_level(range.sheet, axis, index))
            .collect();
        if deeper && levels.iter().any(|level| *level >= 8) {
            return Err(host_error(1004, "an outline goes no deeper than eight levels"));
        }
        if !deeper && levels.iter().any(|level| *level <= 1) {
            return Err(host_error(1004, "the rows or columns are not grouped"));
        }
        for (index, level) in (first..=last).zip(levels) {
            let level = if deeper { level + 1 } else { level - 1 };
            self.set_outline_level(range.sheet, axis, index, level);
        }
        Ok(Value::Boolean(true))
    }

    /// `Outline.ShowLevels RowLevels, ColumnLevels`: what is grouped deeper
    /// than the level asked for is hidden, and the rest of the grouped
    /// rows are shown. Measured: after `ShowLevels RowLevels:=1` rows at
    /// levels 2 and 3 are hidden; after `RowLevels:=2` the level-2 rows are
    /// back and the level-3 rows still hidden. A row nobody grouped is left
    /// as it was either way.
    fn show_outline_levels(&mut self, sheet: usize, args: &[Value]) -> Result<Value, String> {
        let asked = |index: usize| -> Result<Option<u8>, String> {
            match args.get(index) {
                None | Some(Value::Missing) | Some(Value::Empty) => Ok(None),
                Some(value) => match any_whole_number(value) {
                    Some(level) if (0..=8).contains(&level) => Ok(Some(level as u8)),
                    _ => Err(host_error(1004, "Outline.ShowLevels takes a level from 1 to 8")),
                },
            }
        };
        let (rows, columns) = (asked(0)?, asked(1)?);
        if rows.is_none() && columns.is_none() {
            return Err(host_error(1004, "Outline.ShowLevels needs RowLevels or ColumnLevels"));
        }
        if let Some(shown) = rows.filter(|shown| *shown > 0) {
            let grouped: Vec<(u32, u8)> = self
                .outlines
                .get(&sheet)
                .map(|outline| outline.rows.iter().map(|(index, level)| (*index, *level)).collect())
                .unwrap_or_default();
            for (index, level) in grouped {
                let band = CellRange {
                    sheet,
                    start_row: index,
                    end_row: index,
                    start_column: 0,
                    end_column: MAX_WORKSHEET_COLUMN,
                };
                self.set_range_hidden(band, level > shown)?;
            }
        }
        if let Some(shown) = columns.filter(|shown| *shown > 0) {
            let grouped: Vec<(u32, u8)> = self
                .outlines
                .get(&sheet)
                .map(|outline| outline.columns.iter().map(|(index, level)| (*index, *level)).collect())
                .unwrap_or_default();
            for (index, level) in grouped {
                let band = CellRange {
                    sheet,
                    start_row: 1,
                    end_row: MAX_WORKSHEET_ROW,
                    start_column: index,
                    end_column: index,
                };
                self.set_range_hidden(band, level > shown)?;
            }
        }
        Ok(Value::Boolean(true))
    }

    /// `Range.ClearOutline`: the levels of the range's rows and columns go
    /// back to one. What was hidden stays hidden.
    fn clear_outline(&mut self, range: CellRange) {
        let Some(outline) = self.outlines.get_mut(&range.sheet) else {
            return;
        };
        outline
            .rows
            .retain(|index, _| !(range.start_row..=range.end_row).contains(index));
        outline
            .columns
            .retain(|index, _| !(range.start_column..=range.end_column).contains(index));
    }

    /// The fill was coloured, or uncoloured: a solid of automatic colour
    /// gives way to the colour, a hatching stays over it -- measured,
    /// `Color = 65280` over gray50 leaves the pattern gray50 -- and taking
    /// the colour away takes any pattern with it.
    fn fill_coloured(&mut self, range: CellRange, coloured: bool) {
        for at in self.touched(range) {
            match self.hatchings.get(&at) {
                Some(Hatching { kind: 1, .. }) if coloured => {
                    self.hatchings.remove(&at);
                }
                Some(_) if !coloured => {
                    self.hatchings.remove(&at);
                }
                _ => {}
            }
        }
    }

    /// Give the pattern over every cell a colour. A cell with no pattern
    /// gets a solid one to carry it.
    fn paint_pattern(&mut self, range: CellRange, colour: Option<i64>) -> Result<(), String> {
        Self::sized(range)?;
        for at in self.touched(range) {
            let kind = self.hatchings.get(&at).map(|held| held.kind).unwrap_or(1);
            self.hatchings.insert(at, Hatching { kind, colour });
        }
        Ok(())
    }

    /// What the fill sees of a cell.
    fn seed_of(&self, at: CellAddress) -> oxicells_core::fill::Seed {
        let Some(cell) = self.cell_here(at.sheet, at.row, at.column) else {
            return oxicells_core::fill::Seed::default();
        };
        oxicells_core::fill::Seed {
            number: match cell.value {
                CellValue::Number(number) => Some(number),
                _ => None,
            },
            text: match &cell.value {
                CellValue::Number(_) | CellValue::Empty => String::new(),
                other => other.display(),
            },
            formula: cell.formula.clone(),
            number_format: cell.style.number_format.clone(),
        }
    }

    /// Put one step of a fill down: its value or formula, and the dress of
    /// the cell it is patterned on, as the kind of fill allows.
    fn put_filled(
        &mut self,
        at: CellAddress,
        step: &oxicells_core::fill::Step,
        seat: CellAddress,
        values: bool,
        formats: bool,
    ) -> Result<(), String> {
        use oxicells_core::fill::Filled;
        if values {
            match &step.filled {
                Filled::Empty => self.set_cell_value(at, CellValue::Empty)?,
                Filled::Number(number) => self.set_cell_value(at, CellValue::Number(*number))?,
                Filled::Text(text) => self.set_cell_value(at, CellValue::String(text.clone()))?,
                Filled::Formula(formula) => self.set_cell_formula(at, formula.clone())?,
            }
        }
        if formats {
            let dress = self
                .cell_here(seat.sheet, seat.row, seat.column)
                .map(|cell| cell.style)
                .unwrap_or_default();
            self.set_range_style(CellRange::single(at), |_, style| *style = dress.clone())?;
            let marks = self.marks_of(seat);
            self.put_marks(at, marks);
        }
        Ok(())
    }

    /// `Range.AutoFill Destination, Type`.
    ///
    /// Measured (fill.vba, 2026-09-05): the destination must hold the source
    /// and be more than it, or it is 1004; a type past the ten is 1004; the
    /// answer is True. Pulled the other way (source A4:A5, destination
    /// A1:A5) the line runs backwards. A destination reaching both down and
    /// across fills only the cells outside the source's rows AND columns,
    /// with copies of the source's first cell: Y1 into Y1:Z3 fills Z2:Z3
    /// with Y1, and AD1:AE1 into AD1:AF3 fills AF2:AF3 with AD1.
    fn auto_fill(&mut self, source: CellRange, args: &[Value]) -> Result<Value, String> {
        use oxicells_core::fill::{continue_line, Along, How};
        let destination = match args.first() {
            Some(Value::Object(object)) => self
                .range(object)
                .ok_or_else(|| host_error(1004, "AutoFill takes a Range as its destination"))?,
            _ => return Err(host_error(1004, "AutoFill needs a destination Range")),
        };
        let how = match args.get(1) {
            None | Some(Value::Missing) | Some(Value::Empty) => How::Default,
            Some(value) => match any_whole_number(value) {
                Some(0) => How::Default,
                Some(1) => How::Copy,
                Some(2) => How::Series,
                Some(3) | Some(4) => How::Default,
                Some(5) => How::Days,
                Some(6) => How::Weekdays,
                Some(7) => How::Months,
                Some(8) => How::Years,
                Some(9) => How::LinearTrend,
                Some(10) => How::GrowthTrend,
                _ => return Err(host_error(1004, "AutoFill method of Range class failed")),
            },
        };
        let (values, formats) = match args.get(1).and_then(any_whole_number) {
            Some(3) => (false, true),
            Some(4) => (true, false),
            _ => (true, true),
        };
        if destination.sheet != source.sheet
            || !range_within(source, destination)
            || range_within(destination, source)
        {
            return Err(host_error(1004, "AutoFill method of Range class failed"));
        }
        Self::range_cell_count(destination)?;
        self.guard_locked_cells(destination, "Range.AutoFill")?;
        self.arrays_allow(destination, false)?;
        let above = source.start_row - destination.start_row;
        let below = destination.end_row - source.end_row;
        let left = source.start_column - destination.start_column;
        let right = destination.end_column - source.end_column;
        if (above > 0 || below > 0) && (left > 0 || right > 0) {
            let first = source.first();
            let corner = self.seed_of(first);
            let copied = continue_line(&[corner], 1, true, How::Copy, Along::Rows);
            let Some(step) = copied.first() else {
                return Ok(Value::Boolean(true));
            };
            for at in destination.addresses() {
                let in_rows = (source.start_row..=source.end_row).contains(&at.row);
                let in_columns = (source.start_column..=source.end_column).contains(&at.column);
                if in_rows || in_columns {
                    continue;
                }
                self.put_filled(at, step, first, values, formats)?;
            }
            return Ok(Value::Boolean(true));
        }
        if (above > 0 && below > 0) || (left > 0 && right > 0) {
            return Err(host_error(1004, "AutoFill method of Range class failed"));
        }
        let down = above > 0 || below > 0;
        let forwards = below > 0 || right > 0;
        let steps = if down { above.max(below) } else { left.max(right) } as usize;
        let sheet = source.sheet;
        let lanes: Vec<u32> = if down {
            (source.start_column..=source.end_column).collect()
        } else {
            (source.start_row..=source.end_row).collect()
        };
        for lane in lanes {
            let seats: Vec<CellAddress> = if down {
                (source.start_row..=source.end_row)
                    .map(|row| CellAddress { sheet, row, column: lane })
                    .collect()
            } else {
                (source.start_column..=source.end_column)
                    .map(|column| CellAddress { sheet, row: lane, column })
                    .collect()
            };
            let line: Vec<_> = seats.iter().map(|at| self.seed_of(*at)).collect();
            let along = if down { Along::Rows } else { Along::Columns };
            let filled = continue_line(&line, steps, forwards, how, along);
            for (k, step) in filled.iter().enumerate() {
                let k = k as u32 + 1;
                let at = match (down, forwards) {
                    (true, true) => CellAddress { sheet, row: source.end_row + k, column: lane },
                    (true, false) => CellAddress { sheet, row: source.start_row - k, column: lane },
                    (false, true) => CellAddress { sheet, row: lane, column: source.end_column + k },
                    (false, false) => CellAddress { sheet, row: lane, column: source.start_column - k },
                };
                self.put_filled(at, step, seats[step.seat], values, formats)?;
            }
        }
        Ok(Value::Boolean(true))
    }

    /// `FillDown` / `FillUp` / `FillRight` / `FillLeft`: the edge row or
    /// column copied into the rest of the range -- the edge alone, not the
    /// pattern: measured, J1:J2 holding 1 and 2 reads 1 and 1 after
    /// FillDown, and a range one row deep is 1004.
    fn fill_edge(&mut self, range: CellRange, edge: FillEdge) -> Result<Value, String> {
        use oxicells_core::fill::{continue_line, Along, How};
        Self::range_cell_count(range)?;
        let down = matches!(edge, FillEdge::Top | FillEdge::Bottom);
        let forwards = matches!(edge, FillEdge::Top | FillEdge::Left);
        let steps = if down {
            range.end_row - range.start_row
        } else {
            range.end_column - range.start_column
        } as usize;
        if steps == 0 {
            return Err(host_error(1004, "the range has only its edge to fill from"));
        }
        self.guard_locked_cells(range, "Range.FillDown")?;
        self.arrays_allow(range, false)?;
        let sheet = range.sheet;
        let lanes: Vec<u32> = if down {
            (range.start_column..=range.end_column).collect()
        } else {
            (range.start_row..=range.end_row).collect()
        };
        for lane in lanes {
            let seat = match edge {
                FillEdge::Top => CellAddress { sheet, row: range.start_row, column: lane },
                FillEdge::Bottom => CellAddress { sheet, row: range.end_row, column: lane },
                FillEdge::Left => CellAddress { sheet, row: lane, column: range.start_column },
                FillEdge::Right => CellAddress { sheet, row: lane, column: range.end_column },
            };
            let along = if down { Along::Rows } else { Along::Columns };
            let filled = continue_line(&[self.seed_of(seat)], steps, forwards, How::Copy, along);
            for (k, step) in filled.iter().enumerate() {
                let k = k as u32 + 1;
                let at = match edge {
                    FillEdge::Top => CellAddress { sheet, row: range.start_row + k, column: lane },
                    FillEdge::Bottom => CellAddress { sheet, row: range.end_row - k, column: lane },
                    FillEdge::Left => CellAddress { sheet, row: lane, column: range.start_column + k },
                    FillEdge::Right => CellAddress { sheet, row: lane, column: range.end_column - k },
                };
                self.put_filled(at, step, seat, true, true)?;
            }
        }
        Ok(Value::Boolean(true))
    }

    /// The rows of a range that hold subtotals -- a `SUBTOTAL(n, …)` formula
    /// in one of the range's columns -- each with the function number and
    /// the columns (within the range) it totals.
    fn subtotal_rows_in(&self, range: CellRange) -> Vec<(u32, Vec<(u32, i64)>)> {
        let mut found: Vec<(u32, Vec<(u32, i64)>)> = Vec::new();
        let Some(sheet) = self.workbook.sheets.get(range.sheet) else {
            return found;
        };
        for row in &sheet.rows {
            if !(range.start_row..=range.end_row).contains(&row.index) {
                continue;
            }
            let totals: Vec<(u32, i64)> = row
                .cells
                .iter()
                .filter(|cell| (range.start_column..=range.end_column).contains(&cell.col))
                .filter_map(|cell| {
                    let body = cell.formula.as_deref()?.trim_start_matches('=').trim_start();
                    if body.len() < 9 || !body[..9].eq_ignore_ascii_case("SUBTOTAL(") {
                        return None;
                    }
                    let number: String = body[9..].chars().take_while(|c| c.is_ascii_digit()).collect();
                    Some((cell.col - range.start_column, number.parse::<i64>().ok()?))
                })
                .collect();
            if !totals.is_empty() {
                found.push((row.index, totals));
            }
        }
        found
    }

    /// Take the subtotal rows out of a range, bottom-up, and bring its rows
    /// back to outline level one. Answers how many rows went.
    fn take_out_subtotals(&mut self, range: CellRange) -> Result<u32, String> {
        let rows: Vec<u32> = self.subtotal_rows_in(range).into_iter().map(|(row, _)| row).collect();
        for row in rows.iter().rev() {
            let whole = CellRange {
                sheet: range.sheet,
                start_row: *row,
                end_row: *row,
                start_column: 0,
                end_column: MAX_WORKSHEET_COLUMN,
            };
            self.shift_cells(whole, false, false)?;
        }
        if let Some(outline) = self.outlines.get_mut(&range.sheet) {
            outline.rows.retain(|row, _| !(range.start_row..=range.end_row).contains(row));
        }
        Ok(rows.len() as u32)
    }

    /// `Range.RemoveSubtotal`: the rows holding subtotals go, and the
    /// range's rows come back to outline level one. Measured: after it the
    /// data rows stand together again and `Rows(2).OutlineLevel` is 1.
    fn remove_subtotal(&mut self, range: CellRange) -> Result<Value, String> {
        let range = if range.is_single() { self.current_region(range)? } else { range };
        self.guard_structure(range.sheet, false, false)?;
        self.take_out_subtotals(range)?;
        Ok(Value::Boolean(true))
    }

    /// `Range.Subtotal GroupBy, Function, TotalList, Replace, PageBreaks,
    /// SummaryBelowData`, as Excel does it (measured on a Japanese Office,
    /// misc2/misc3.vba, 2026-09-05):
    ///
    /// The first row is the header. The rows under it are cut into groups
    /// wherever the GroupBy column's shown text changes -- compared without
    /// case and without surrounding space, so `a`, `A` and ` a` are one
    /// group -- and after each group (before it, with SummaryBelowData
    /// False) a row is put in holding `<key> 集計` in the GroupBy column,
    /// bold, and `=SUBTOTAL(9,C<first>:C<last>)` over the group's rows in
    /// every TotalList column. A `総計` row closes the range (opens it,
    /// summary above), its formulas running from the first data row to the
    /// last. A group whose key is blank gets no row of its own. Each
    /// function has its own two labels (Count: 個数 / 総合計, Average:
    /// 平均 / 全体の平均, …) and its own SUBTOTAL number. The put-in rows
    /// wear the formats of the row above, as any inserted row does -- a key
    /// that is a date labels in the date's format, `1/5/2024 集計`. Data
    /// rows go to outline level 3, group rows to 2, the grand row stays at 1.
    /// With Replace False the new subtotal joins the old, the rows of one
    /// group ordered by Excel's function order (Sum, Count, Average, Max,
    /// Min, Product, CountNums, StDev, StDevP, Var, VarP), the first of them
    /// innermost. Naming the GroupBy column alone in TotalList totals the
    /// last column instead; a column past the range, or GroupBy 0, is
    /// 1004; from one cell the range is the current region.
    fn subtotal(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        let given = |index: usize| match args.get(index) {
            Some(Value::Missing) | Some(Value::Empty) | None => None,
            Some(value) => Some(value),
        };
        let range = if range.is_single() { self.current_region(range)? } else { range };
        Self::range_cell_count(range)?;
        let width = range.end_column - range.start_column + 1;
        let group_by = match given(0).and_then(any_whole_number) {
            Some(column) if column >= 1 && column <= i64::from(width) => column as u32 - 1,
            _ => return Err(host_error(1004, "Subtotal method of Range class failed")),
        };
        let function = given(1)
            .and_then(any_whole_number)
            .ok_or_else(|| host_error(1004, "Subtotal needs a Function"))?;
        let Some(order) = SUBTOTAL_FUNCTIONS.iter().position(|(constant, ..)| *constant == function) else {
            return Err(host_error(1004, "Subtotal method of Range class failed"));
        };
        let mut totals: Vec<u32> = Vec::new();
        let mut take = |value: &Value| -> Result<(), String> {
            match any_whole_number(value) {
                Some(column) if column >= 1 && column <= i64::from(width) => {
                    let column = column as u32 - 1;
                    if !totals.contains(&column) {
                        totals.push(column);
                    }
                    Ok(())
                }
                _ => Err(host_error(1004, "Subtotal method of Range class failed")),
            }
        };
        match given(2) {
            Some(Value::Array(listed)) => {
                for value in &listed.values {
                    take(value)?;
                }
            }
            Some(value) => take(value)?,
            None => return Err(host_error(1004, "Subtotal needs a TotalList")),
        }
        let replace = match given(3) {
            None => true,
            Some(value) => style_face_boolean(value, "Subtotal Replace")?.unwrap_or(true),
        };
        let below = match given(5) {
            None => true,
            Some(value) => style_face_boolean(value, "Subtotal SummaryBelowData")?.unwrap_or(true),
        };
        self.guard_structure(range.sheet, false, true)?;
        self.guard_locked_cells(range, "Range.Subtotal")?;
        let sheet = range.sheet;

        // Totalling the GroupBy column itself leaves nowhere for the labels,
        // so Excel puts a column in before it for them: measured, with
        // GroupBy 1 and TotalList (1) the data stands one column to the
        // right afterwards, the labels in the new column, and the totals
        // over the key column read 0.
        let (range, group_by, totals, label_column) = if totals.contains(&group_by) {
            let key_column = range.start_column + group_by;
            let whole = CellRange {
                sheet,
                start_row: 1,
                end_row: MAX_WORKSHEET_ROW,
                start_column: key_column,
                end_column: key_column,
            };
            self.guard_structure(sheet, true, true)?;
            self.shift_cells(whole, true, true)?;
            let range = CellRange { end_column: range.end_column + 1, ..range };
            let totals: Vec<u32> = totals.iter().map(|column| if *column >= group_by { column + 1 } else { *column }).collect();
            (range, group_by + 1, totals, key_column)
        } else {
            (range, group_by, totals, range.start_column + group_by)
        };

        // What is there already, function by function -- kept when not
        // replacing -- and taken out so the whole can be laid again.
        let mut functions: Vec<(usize, Vec<u32>)> = Vec::new();
        if !replace {
            for (_, held) in self.subtotal_rows_in(range) {
                for (column, number) in held {
                    let Some(at) = SUBTOTAL_FUNCTIONS.iter().position(|(_, n, ..)| *n == number) else {
                        continue;
                    };
                    match functions.iter_mut().find(|(held, _)| *held == at) {
                        Some((_, columns)) => {
                            if !columns.contains(&column) {
                                columns.push(column);
                            }
                        }
                        None => functions.push((at, vec![column])),
                    }
                }
            }
        }
        let gone = self.take_out_subtotals(range)?;
        let range = CellRange { end_row: range.end_row - gone, ..range };
        match functions.iter_mut().find(|(held, _)| *held == order) {
            Some((_, columns)) => {
                for column in &totals {
                    if !columns.contains(column) {
                        columns.push(*column);
                    }
                }
            }
            None => functions.push((order, totals)),
        }
        functions.sort_by_key(|(order, _)| *order);
        let depth = functions.len() as u8;

        // The groups: runs of data rows sharing a key, with the key as shown.
        let key_column = range.start_column + group_by;
        let first_data = range.start_row + 1;
        let last_data = range.end_row;
        if last_data < first_data {
            return Ok(Value::Boolean(true));
        }
        let mut groups: Vec<(u32, u32, String, String)> = Vec::new();
        for row in first_data..=last_data {
            let shown = self
                .cell_here(sheet, row, key_column)
                .map(|cell| shown_text(&from_cell_value(&cell.value), cell.style.number_format.as_deref()))
                .unwrap_or_default();
            let key = shown.trim().to_lowercase();
            match groups.last_mut() {
                Some((_, last, held, _)) if *held == key => *last = row,
                _ => groups.push((row, row, key, shown)),
            }
        }

        // Where everything ends up, top to bottom: a data row's final row,
        // and each put-in row with what it totals.
        let mut final_of: std::collections::HashMap<u32, u32> = std::collections::HashMap::new();
        // (final row, function order, group: Some(first, last, shown key) or
        // None for the grand row)
        let mut puts: Vec<(u32, usize, Option<(u32, u32, String)>)> = Vec::new();
        let mut next = first_data;
        if !below {
            for (order, _) in &functions {
                puts.push((next, *order, None));
                next += 1;
            }
        }
        for (first, last, key, shown) in &groups {
            let totalled = !key.is_empty();
            if !below && totalled {
                for (order, _) in &functions {
                    puts.push((next, *order, Some((*first, *last, shown.clone()))));
                    next += 1;
                }
            }
            for row in *first..=*last {
                final_of.insert(row, next);
                next += 1;
            }
            if below && totalled {
                for (order, _) in &functions {
                    puts.push((next, *order, Some((*first, *last, shown.clone()))));
                    next += 1;
                }
            }
        }
        if below {
            for (order, _) in &functions {
                puts.push((next, *order, None));
                next += 1;
            }
        }

        // Put the rows in top-down: everything above a row being put in is
        // already where it will stay, and everything below still has the
        // later rows to move for. The rows are written only once they are
        // all in, since a formula written earlier would be moved by the
        // rows put in under it.
        for (row, _, _) in &puts {
            let row = *row;
            let whole = CellRange { sheet, start_row: row, end_row: row, start_column: 0, end_column: MAX_WORKSHEET_COLUMN };
            self.shift_cells(whole, false, true)?;
            for column in range.start_column..=range.end_column {
                let above = CellAddress { sheet, row: row - 1, column };
                let style = self.cell_here(sheet, row - 1, column).map(|cell| cell.style).unwrap_or_default();
                let at = CellAddress { sheet, row, column };
                self.set_range_style(CellRange::single(at), |_, held| *held = style.clone())?;
                let marks = self.marks_of(above);
                self.put_marks(at, marks);
            }
        }
        for (row, order, group) in &puts {
            let row = *row;
            let (_, number, label, grand_label) = SUBTOTAL_FUNCTIONS[*order];
            let (text, first, last) = match group {
                Some((first, last, shown)) => (format!("{shown} {label}"), final_of[first], final_of[last]),
                None => (grand_label.to_string(), final_of[&first_data], final_of[&last_data]),
            };
            let label_at = CellAddress { sheet, row, column: label_column };
            self.set_cell_value(label_at, CellValue::String(text))?;
            self.set_range_style(CellRange::single(label_at), |_, style| style.bold = true)?;
            let columns = functions
                .iter()
                .find(|(held, _)| held == order)
                .map(|(_, columns)| columns.clone())
                .unwrap_or_default();
            for column in columns {
                let column = range.start_column + column;
                let letter = oxicells_core::editor::col_to_letter(column);
                let at = CellAddress { sheet, row, column };
                self.set_cell_formula(at, format!("=SUBTOTAL({number},{letter}{first}:{letter}{last})"))?;
            }
        }

        // The outline: data rows deepest, then the group rows by function
        // order, the first of them innermost; the grand rows stay at one.
        for final_row in final_of.values() {
            self.set_outline_level(sheet, ShiftAxis::Rows, *final_row, 2 + depth);
        }
        for (row, order, group) in &puts {
            let level = match group {
                Some(_) => {
                    let k = functions.iter().position(|(held, _)| held == order).unwrap_or(0) as u8;
                    2 + depth - 1 - k
                }
                None => 1,
            };
            self.set_outline_level(sheet, ShiftAxis::Rows, *row, level);
        }
        self.outlines.entry(sheet).or_default().summary_row = if below { 1 } else { 0 };
        Ok(Value::Boolean(true))
    }

    /// `Range.BorderAround LineStyle, Weight, ColorIndex, Color, ThemeColor`:
    /// the four outer edges of the range. Measured: with a LineStyle and
    /// Weight xlMedium the left and right edges read -4138 and the inside
    /// edges none; with ColorIndex 3 and Weight 4 the top edge reads Color
    /// 255, Weight 4, LineStyle 1.
    fn border_around(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        let given = |index: usize| match args.get(index) {
            Some(Value::Missing) | Some(Value::Empty) | None => None,
            Some(value) => Some(value),
        };
        let line = match given(0) {
            Some(value) => any_whole_number(value)
                .ok_or_else(|| host_error(1004, "BorderAround LineStyle takes a line style"))?,
            None => LINE_CONTINUOUS,
        };
        let weight = match given(1) {
            Some(value) => border_weight(value)?,
            None => WEIGHT_THIN,
        };
        let colour = match (given(2), given(3)) {
            (_, Some(value)) => {
                let Some(asked) = any_number(value) else {
                    return Err(host_error(1004, "BorderAround Color takes an RGB number"));
                };
                (asked.is_finite() && (0.0..=16_777_215.0).contains(&asked))
                    .then(|| colour_from_packed(asked as i64))
            }
            (Some(value), None) => palette_choice(value, COLOUR_AUTOMATIC, "BorderAround ColorIndex")?,
            (None, None) => None,
        };
        let drawn = match border_after_line(line, weight) {
            Some(name) => name,
            None => return Ok(Value::Boolean(true)),
        };
        let drawn = match border_after_weight(line, weight).or(Some(drawn)) {
            Some(name) => name,
            None => drawn,
        };
        for selection in [
            BorderSelection::EdgeLeft,
            BorderSelection::EdgeTop,
            BorderSelection::EdgeBottom,
            BorderSelection::EdgeRight,
        ] {
            self.forget_theme_paint(range, Paint::Edge(selection));
            let colour = colour.clone();
            self.set_range_style(range, |address, style| {
                let edge = Some(BorderLine { style: drawn.to_string(), color: colour.clone() });
                match selection {
                    BorderSelection::EdgeLeft if address.column == range.start_column => {
                        style.border_left = edge;
                    }
                    BorderSelection::EdgeTop if address.row == range.start_row => {
                        style.border_top = edge;
                    }
                    BorderSelection::EdgeBottom if address.row == range.end_row => {
                        style.border_bottom = edge;
                    }
                    BorderSelection::EdgeRight if address.column == range.end_column => {
                        style.border_right = edge;
                    }
                    _ => {}
                }
            })?;
        }
        Ok(Value::Boolean(true))
    }

    /// How wide a digit of the workbook's standard font is, in pixels at 96
    /// dpi, which is the unit column widths are counted in. The renderer
    /// asks GDI; the browser has no GDI, so the faces Excel opens new
    /// workbooks in are written down: Calibri and Arial 7 (default column
    /// 64 pixels, 8.43), 游ゴシック, ＭＳ Ｐゴシック and Meiryo 8 (72 pixels,
    /// 8.38). Anything else is taken as 7.
    fn digit_width(&self) -> f32 {
        let face = self
            .workbook
            .default_style
            .font_name
            .clone()
            .or_else(|| self.workbook.sheets.first().and_then(|sheet| sheet.normal_font.clone()).map(|(face, _)| face))
            .unwrap_or_default();
        match face.as_str() {
            "游ゴシック" | "Yu Gothic" | "ＭＳ Ｐゴシック" | "MS PGothic" | "Meiryo" | "メイリオ" | "Meiryo UI"
            | "游明朝" | "Yu Mincho" | "ＭＳ Ｐ明朝" | "MS PMincho" => 8.0,
            _ => 7.0,
        }
    }

    /// A column's width in pixels, by the rule the renderer draws it with; a
    /// hidden column is 0.
    fn column_px(&self, sheet: usize, column: u32) -> f32 {
        let Some(held) = self.workbook.sheets.get(sheet) else {
            return 0.0;
        };
        if held.hidden_cols.contains(&column) {
            return 0.0;
        }
        let digit = self.digit_width();
        let stated = held.col_widths.get(column as usize).copied().filter(|width| *width > 0.0);
        match stated {
            Some(width) => column_pixels(width, digit),
            None if held.default_col_width > 0.0 => column_pixels(held.default_col_width, digit),
            None => (8.0 * digit + 8.0).trunc(),
        }
    }

    /// A row's height in pixels: what the sheet shows of a stated height,
    /// which is the whole pixels in it. Measured: RowHeight 25 shows 24.75,
    /// 20 shows 19.5, 0.5 shows nothing and reads as hidden.
    fn row_px(&self, sheet: usize, row: u32) -> f32 {
        let Some(held) = self.workbook.sheets.get(sheet) else {
            return 0.0;
        };
        let stated = held.rows.iter().find(|held| held.index == row);
        if stated.is_some_and(|row| row.hidden) {
            return 0.0;
        }
        let points = stated.and_then(|row| row.height).unwrap_or(held.default_row_height);
        ((points + 0.05) / 0.75).floor()
    }

    /// `Range.Left`, `Top`, `Width` and `Height`, in points, from the pixels
    /// the columns and rows take. Measured: A1 is 54 by 18.75; C3 sits at
    /// 117.75 with column B widened to 10; a hidden row adds nothing.
    fn range_extent(&self, range: CellRange, which: &str) -> Value {
        let sheet = range.sheet;
        let columns = |from: u32, to: u32| -> f32 {
            (from..=to).map(|column| self.column_px(sheet, column)).sum::<f32>()
        };
        let rows = |from: u32, to: u32| -> f32 {
            let Some(held) = self.workbook.sheets.get(sheet) else {
                return 0.0;
            };
            // The rows the sheet keeps are counted one by one; the rest are
            // the default, however many there are.
            let default_px = ((held.default_row_height + 0.05) / 0.75).floor();
            let mut total = f64::from(to - from + 1) * f64::from(default_px);
            for row in &held.rows {
                if row.index >= from && row.index <= to {
                    total += f64::from(self.row_px(sheet, row.index)) - f64::from(default_px);
                }
            }
            total as f32
        };
        let px = match which {
            "left" => columns(0, range.start_column).max(0.0) - self.column_px(sheet, range.start_column),
            "width" => columns(range.start_column, range.end_column),
            "top" => {
                if range.start_row <= 1 {
                    0.0
                } else {
                    rows(1, range.start_row - 1)
                }
            }
            _ => rows(range.start_row, range.end_row),
        };
        Value::Double(f64::from(px) * 0.75)
    }

    /// Rows that are not pinned at a height take the height their content
    /// asks for, the way Excel refits them when a font grows or a cell
    /// starts to wrap. Measured: `Font.Size = 20` takes the row to 33 and
    /// back to 18.75 at 11; a row set to 30 by hand stays 30.
    fn refit_rows(&mut self, range: CellRange) -> Result<(), String> {
        let sheet = range.sheet;
        let rows: Vec<u32> = self.workbook.sheets[sheet]
            .rows
            .iter()
            .filter(|row| (range.start_row..=range.end_row).contains(&row.index) && !row.custom_height)
            .map(|row| row.index)
            .collect();
        for row in rows {
            let band = CellRange { sheet, start_row: row, end_row: row, start_column: 0, end_column: MAX_WORKSHEET_COLUMN };
            self.auto_fit_rows(band)?;
        }
        Ok(())
    }

    fn band_of(range: CellRange) -> Band {
        let rows = range.start_row == 1 && range.end_row == MAX_WORKSHEET_ROW;
        let columns = range.start_column == 0 && range.end_column == MAX_WORKSHEET_COLUMN;
        match (rows, columns) {
            (true, true) => Band::Whole,
            (true, false) => Band::Columns,
            (false, true) => Band::Rows,
            (false, false) => Band::Cells,
        }
    }

    /// The dress a cell wears before anything is written on it: its row's,
    /// its column's, or its sheet's format, where one has been given.
    fn template_style(&self, at: CellAddress) -> CellStyle {
        if let Some(style) = self.templates.get(&FormatScope::Row(at.sheet, at.row)) {
            return style.clone();
        }
        if let Some(style) = self.templates.get(&FormatScope::Column(at.sheet, at.column)) {
            return style.clone();
        }
        self.templates
            .get(&FormatScope::Sheet(at.sheet))
            .cloned()
            .unwrap_or_default()
    }

    /// The cells of a sheet that exist inside a range, as addresses.
    fn existing_cells_in(&self, range: CellRange) -> Vec<CellAddress> {
        let Some(sheet) = self.workbook.sheets.get(range.sheet) else {
            return Vec::new();
        };
        sheet
            .rows
            .iter()
            .filter(|row| (range.start_row..=range.end_row).contains(&row.index))
            .flat_map(|row| {
                row.cells
                    .iter()
                    .filter(|cell| (range.start_column..=range.end_column).contains(&cell.col))
                    .map(move |cell| CellAddress { sheet: range.sheet, row: row.index, column: cell.col })
            })
            .collect()
    }

    /// The cap on a block's size, which a band of whole rows or columns is
    /// not held to: a change to one reaches only the cells that exist.
    fn sized(range: CellRange) -> Result<(), String> {
        if Self::band_of(range) == Band::Cells {
            Self::range_cell_count(range)?;
        }
        Ok(())
    }

    /// The cells a change to a range reaches, one address each: every cell
    /// of a block, but for whole rows, columns or the sheet only the cells
    /// that exist -- the rest are the template's business.
    fn touched(&self, range: CellRange) -> Vec<CellAddress> {
        if Self::band_of(range) == Band::Cells {
            range.addresses().collect()
        } else {
            self.existing_cells_in(range)
        }
    }

    /// Whether the object's worksheet has been deleted out from under it.
    fn gone(&self, object: &ObjectRef) -> bool {
        matches!(self.objects.get(object.handle as usize), Some(HostObject::Gone))
    }

    /// Every place a sheet is named by its position, brought up to date
    /// after the sheets were renumbered: `moved(old)` is the sheet's new
    /// position, or None for a sheet that is gone, whose entries go with it.
    ///
    /// Objects already handed out follow their sheet -- measured, a
    /// `Worksheet` held across `Worksheets.Add` still names Sheet1 and a
    /// `Range` held across it still writes there -- and the ones on a deleted
    /// sheet answer 424 from then on.
    fn sheets_renumbered(&mut self, moved: &dyn Fn(usize) -> Option<usize>) {
        let address = |at: CellAddress| moved(at.sheet).map(|sheet| CellAddress { sheet, ..at });
        let range = |held: CellRange| moved(held.sheet).map(|sheet| CellRange { sheet, ..held });

        let mut protected = Vec::new();
        protected.resize_with(self.workbook.sheets.len(), || None);
        for (was, protection) in std::mem::take(&mut self.protected).into_iter().enumerate() {
            if let Some(now) = moved(was) {
                if now < protected.len() {
                    protected[now] = protection;
                }
            }
        }
        self.protected = protected;
        self.unlocked = std::mem::take(&mut self.unlocked)
            .into_iter()
            .filter_map(address)
            .collect();
        self.notes = std::mem::take(&mut self.notes)
            .into_iter()
            .filter_map(|mut note| {
                note.at = address(note.at)?;
                Some(note)
            })
            .collect();
        self.links = std::mem::take(&mut self.links)
            .into_iter()
            .filter_map(|mut link| {
                link.anchor = range(link.anchor)?;
                Some(link)
            })
            .collect();
        self.validations = std::mem::take(&mut self.validations)
            .into_iter()
            .filter_map(|(at, validation)| Some((address(at)?, validation)))
            .collect();
        self.conditions = std::mem::take(&mut self.conditions)
            .into_iter()
            .filter_map(|mut condition| {
                condition.sheet = moved(condition.sheet)?;
                condition.applies = condition.applies.iter().filter_map(|held| range(*held)).collect();
                Some(condition)
            })
            .collect();
        let handles = std::mem::take(&mut self.table_handles);
        for (id, sheet, name) in handles {
            match moved(sheet) {
                Some(sheet) => self.table_handles.push((id, sheet, name)),
                None => {
                    self.table_extra.remove(&id);
                }
            }
        }
        self.page_setups = std::mem::take(&mut self.page_setups)
            .into_iter()
            .filter_map(|(sheet, setup)| Some((moved(sheet)?, setup)))
            .collect();
        self.styled = std::mem::take(&mut self.styled)
            .into_iter()
            .filter_map(|(at, style)| Some((address(at)?, style)))
            .collect();
        self.theme_paint = std::mem::take(&mut self.theme_paint)
            .into_iter()
            .filter_map(|((at, paint), colour)| Some(((address(at)?, paint), colour)))
            .collect();
        self.selections = std::mem::take(&mut self.selections)
            .into_iter()
            .filter_map(|(sheet, (selection, active))| {
                Some((moved(sheet)?, (range(selection)?, address(active)?)))
            })
            .collect();
        self.views = std::mem::take(&mut self.views)
            .into_iter()
            .filter_map(|(sheet, view)| Some((moved(sheet)?, view)))
            .collect();
        self.outlines = std::mem::take(&mut self.outlines)
            .into_iter()
            .filter_map(|(sheet, outline)| Some((moved(sheet)?, outline)))
            .collect();
        self.tabs = std::mem::take(&mut self.tabs)
            .into_iter()
            .filter_map(|(sheet, tab)| Some((moved(sheet)?, tab)))
            .collect();
        self.sorts = std::mem::take(&mut self.sorts)
            .into_iter()
            .filter_map(|(sheet, mut state)| {
                let sheet = moved(sheet)?;
                if let Some(range) = state.range {
                    state.range = moved(range.sheet).map(|sheet| CellRange { sheet, ..range });
                }
                Some((sheet, state))
            })
            .collect();
        self.shapes = std::mem::take(&mut self.shapes)
            .into_iter()
            .filter_map(|mut shape| {
                shape.sheet = moved(shape.sheet)?;
                Some(shape)
            })
            .collect();
        self.shape_counters = std::mem::take(&mut self.shape_counters)
            .into_iter()
            .filter_map(|(sheet, count)| Some((moved(sheet)?, count)))
            .collect();
        if self.shape_clipboard.is_some_and(|id| !self.shapes.iter().any(|shape| shape.id == id)) {
            self.shape_clipboard = None;
        }
        self.rotations = std::mem::take(&mut self.rotations)
            .into_iter()
            .filter_map(|(at, turn)| Some((address(at)?, turn)))
            .collect();
        self.underlines = std::mem::take(&mut self.underlines)
            .into_iter()
            .filter_map(|(at, rule)| Some((address(at)?, rule)))
            .collect();
        self.hatchings = std::mem::take(&mut self.hatchings)
            .into_iter()
            .filter_map(|(at, hatching)| Some((address(at)?, hatching)))
            .collect();
        self.indented = std::mem::take(&mut self.indented)
            .into_iter()
            .filter_map(address)
            .collect();
        self.templates = std::mem::take(&mut self.templates)
            .into_iter()
            .filter_map(|(scope, style)| {
                let scope = match scope {
                    FormatScope::Sheet(sheet) => FormatScope::Sheet(moved(sheet)?),
                    FormatScope::Column(sheet, column) => FormatScope::Column(moved(sheet)?, column),
                    FormatScope::Row(sheet, row) => FormatScope::Row(moved(sheet)?, row),
                };
                Some((scope, style))
            })
            .collect();
        if let Some(filter) = self.auto_filter.as_mut() {
            match range(filter.range) {
                Some(held) => filter.range = held,
                None => self.auto_filter = None,
            }
        }
        if let Some(cut) = self.pending_cut {
            self.pending_cut = range(cut);
        }
        if let Some(clipboard) = self.clipboard.as_mut() {
            match address(clipboard.origin) {
                Some(origin) => clipboard.origin = origin,
                None => self.clipboard = None,
            }
        }
        if let Some(find) = self.last_find.as_mut() {
            match range(find.range) {
                Some(held) => {
                    find.range = held;
                    find.last_found = find.last_found.and_then(address);
                }
                None => self.last_find = None,
            }
        }
        for blocks in &mut self.blocks {
            *blocks = blocks.iter().filter_map(|held| range(*held)).collect();
        }
        if let Some(active) = moved(self.active_sheet) {
            self.active_sheet = active;
        }
        match (range(self.selection), address(self.active_cell)) {
            (Some(selection), Some(active)) => {
                self.selection = selection;
                self.active_cell = active;
            }
            _ => {
                let sheet = self.active_sheet.min(self.workbook.sheets.len().saturating_sub(1));
                self.selection = CellRange::single(CellAddress { sheet, row: 1, column: 0 });
                self.active_cell = self.selection.first();
            }
        }
        for object in &mut self.objects {
            let followed = match *object {
                HostObject::Range(held) => range(held).map(HostObject::Range),
                HostObject::RangeFont(held) => range(held).map(HostObject::RangeFont),
                HostObject::RangeInterior(held) => range(held).map(HostObject::RangeInterior),
                HostObject::RangeBorders(held, selection) => {
                    range(held).map(|held| HostObject::RangeBorders(held, selection))
                }
                HostObject::RangeCollection(held, axis) => {
                    range(held).map(|held| HostObject::RangeCollection(held, axis))
                }
                HostObject::Worksheet(sheet) => moved(sheet).map(HostObject::Worksheet),
                HostObject::Hyperlinks(HyperlinkScope::Sheet(sheet)) => {
                    moved(sheet).map(|sheet| HostObject::Hyperlinks(HyperlinkScope::Sheet(sheet)))
                }
                HostObject::Hyperlinks(HyperlinkScope::Range(held)) => {
                    range(held).map(|held| HostObject::Hyperlinks(HyperlinkScope::Range(held)))
                }
                HostObject::PageSetup(sheet) => moved(sheet).map(HostObject::PageSetup),
                HostObject::ListObjects(sheet) => moved(sheet).map(HostObject::ListObjects),
                HostObject::Validation(held) => range(held).map(HostObject::Validation),
                HostObject::FormatConditions(held) => range(held).map(HostObject::FormatConditions),
                HostObject::DisplayFormat(held) => range(held).map(HostObject::DisplayFormat),
                HostObject::DisplayFont(held) => range(held).map(HostObject::DisplayFont),
                HostObject::DisplayInterior(held) => range(held).map(HostObject::DisplayInterior),
                HostObject::Characters(at, start, length) => {
                    address(at).map(|at| HostObject::Characters(at, start, length))
                }
                HostObject::CharactersFont(at, start, length) => {
                    address(at).map(|at| HostObject::CharactersFont(at, start, length))
                }
                HostObject::Comment(at) => address(at).map(HostObject::Comment),
                HostObject::Comments(sheet) => moved(sheet).map(HostObject::Comments),
                HostObject::Outline(sheet) => moved(sheet).map(HostObject::Outline),
                HostObject::Tab(sheet) => moved(sheet).map(HostObject::Tab),
                HostObject::Sort(sheet) => moved(sheet).map(HostObject::Sort),
                HostObject::SortFields(sheet) => moved(sheet).map(HostObject::SortFields),
                HostObject::Drawing(part) => part.renumbered(moved).map(HostObject::Drawing),
                HostObject::Blocks(_)
                | HostObject::Areas(_)
                | HostObject::BlocksStyle(..)
                | HostObject::Worksheets
                | HostObject::Names
                | HostObject::DefinedName(_)
                | HostObject::Workbook
                | HostObject::Application
                | HostObject::Workbooks
                | HostObject::WorksheetFunction
                | HostObject::DebugConsole
                | HostObject::Window
                | HostObject::Style(_)
                | HostObject::Styles
                | HostObject::Hyperlink(_)
                | HostObject::ListObject(_)
                | HostObject::ListRows(_)
                | HostObject::ListRow(..)
                | HostObject::ListColumns(_)
                | HostObject::ListColumn(..)
                | HostObject::FormatCondition(_)
                | HostObject::ConditionFont(_)
                | HostObject::ConditionInterior(_)
                | HostObject::Gone => continue,
            };
            *object = followed.unwrap_or(HostObject::Gone);
        }
    }

    /// Make `sheet` the active one, keeping the selection the sheet being
    /// left had for its return. Measured: each sheet keeps its own -- with
    /// A8:B9 selected on Sheet1, adding a sheet and coming back finds A8:B9
    /// selected still.
    fn activate_sheet(&mut self, sheet: usize) {
        if sheet == self.active_sheet && self.selection.sheet == sheet {
            return;
        }
        if self.selection.sheet == self.active_sheet {
            self.selections
                .insert(self.active_sheet, (self.selection, self.active_cell));
        }
        self.active_sheet = sheet;
        let home = CellRange::single(CellAddress { sheet, row: 1, column: 0 });
        let (selection, active) = self.selections.remove(&sheet).unwrap_or((home, home.first()));
        self.selection = selection;
        self.active_cell = active;
    }

    fn is_worksheet_function(&self, object: &ObjectRef) -> bool {
        matches!(
            self.objects.get(object.handle as usize),
            Some(HostObject::WorksheetFunction)
        )
    }

    fn is_debug_console(&self, object: &ObjectRef) -> bool {
        matches!(
            self.objects.get(object.handle as usize),
            Some(HostObject::DebugConsole)
        )
    }

    /// `Debug.Print` wants values, so a cell prints what it holds. A range of
    /// several cells holds an array, which is a type mismatch rather than
    /// something to print, and an object with nothing scalar behind it likewise.
    fn printed_value(&self, value: &Value) -> Result<Value, String> {
        let Value::Object(object) = value else {
            return Ok(value.clone());
        };
        let Some(range) = self.range(object) else {
            return Err(format!(
                "Debug.Print has no value to print for a {} object",
                object.kind
            ));
        };
        let value = self.range_value(range)?;
        if matches!(value, Value::Array(_)) {
            return Err(
                "Debug.Print cannot print a range of several cells as one value".to_string(),
            );
        }
        Ok(value)
    }

    fn take_debug_output(&mut self) -> Vec<String> {
        std::mem::take(&mut self.debug_output)
    }

    fn take_messages(&mut self) -> Vec<BrowserMessage> {
        std::mem::take(&mut self.messages)
    }

    fn show_message_box(&mut self, args: &[Value]) -> Result<Value, String> {
        if !(1..=5).contains(&args.len()) {
            return Err(format!(
                "MsgBox expects 1 to 5 arguments, received {}",
                args.len()
            ));
        }
        let buttons = match args.get(1) {
            None | Some(Value::Missing) | Some(Value::Empty) => 0,
            Some(Value::Integer(value)) => *value,
            Some(Value::Double(value)) if value.is_finite() && value.fract() == 0.0 => {
                *value as i64
            }
            Some(_) => return Err("MsgBox buttons must be an integer style".to_string()),
        };
        if buttons & 0x0f != 0 {
            return Err(
                "browser MsgBox supports vbOKOnly; interactive button styles are unavailable"
                    .to_string(),
            );
        }
        let title = match args.get(2) {
            None | Some(Value::Missing) | Some(Value::Empty) => "Oxi VBA".to_string(),
            Some(value) => format_debug_value(value),
        };
        self.messages.push(BrowserMessage {
            prompt: format_debug_value(&args[0]),
            title,
        });
        Ok(Value::Integer(1))
    }

    /// `Worksheets.Add` puts a sheet in front of the active one unless told
    /// otherwise, makes it active, and hands it back.
    fn add_worksheet(&mut self, args: &[Value]) -> Result<Value, String> {
        let given = |index: usize| match args.get(index) {
            Some(Value::Missing) | None => None,
            Some(value) => Some(value),
        };
        if args.len() > 3 {
            return Err("Worksheets.Add takes Before, After and Count".to_string());
        }
        // Count adds that many, each in front of the one before: measured,
        // `Worksheets.Add Count:=2` puts Sheet11 before Sheet10 and leaves
        // Sheet11 active.
        let count = match given(2) {
            None => 1,
            Some(value) => match any_whole_number(value) {
                Some(count) if count >= 1 => count,
                _ => return Err(host_error(1004, "Worksheets.Add Count must be at least one")),
            },
        };
        if count > 1 {
            let placing: Vec<Value> = args.iter().take(2).cloned().collect();
            let mut added = Value::Empty;
            for _ in 0..count {
                added = self.add_worksheet(&placing)?;
            }
            return Ok(added);
        }
        // Before and After name a sheet with the object itself, not its name.
        let placed = |host: &Self, value: &Value| match value {
            Value::Object(object) => host.worksheet(object).ok_or_else(|| {
                format!("Worksheets.Add expects a worksheet, not a {} object", object.kind)
            }),
            value => host.worksheet_from_value(value),
        };
        let before = given(0).map(|value| placed(self, value)).transpose()?;
        let after = given(1).map(|value| placed(self, value)).transpose()?;
        if before.is_some() && after.is_some() {
            return Err("Worksheets.Add takes Before or After, not both".to_string());
        }
        let at = match (before, after) {
            (Some(before), _) => before,
            (_, Some(after)) => after + 1,
            _ => self.active_sheet,
        };

        let name = self.next_sheet_name();
        let template = &self.workbook.sheets[self.active_sheet];
        let sheet = Sheet {
            name,
            visibility: oxicells_core::ir::Visibility::Visible,
            rows: Vec::new(),
            col_count: 0,
            col_widths: Vec::new(),
            default_col_width: template.default_col_width,
            default_row_height: template.default_row_height,
            default_row_custom: false,
            col_fonts: vec![],
            normal_font: None,
            first_font: None,
            frozen_rows: 0,
            frozen_cols: 0,
            merge_cells: Vec::new(),
            hidden_cols: Vec::new(),
            auto_filter: None,
            declared_range: None,
            tables: Vec::new(),
            drawings: Vec::new(),
            comments: Vec::new(),
            unsupported_elements: Vec::new(),
        };
        self.workbook.sheets.insert(at, sheet);
        self.sheets_renumbered(&|was| Some(if was >= at { was + 1 } else { was }));
        self.activate_sheet(at);
        Ok(self.object(HostObject::Worksheet(at)))
    }

    /// Excel numbers a new sheet from a counter that never goes back: the
    /// count of sheets made since the workbook was opened, plus one,
    /// skipping a number a sheet already wears. Measured: Sheet1 alone, add
    /// twice (Sheet2, Sheet3), delete both, add -> Sheet4; rename it Sheet9
    /// and add -> Sheet5; with a Sheet7 about, the counter steps past it to
    /// Sheet8; and a COPY takes a number too without wearing it -- after
    /// `X (2)` the next added sheet is Sheet13, not Sheet12.
    fn next_sheet_name(&mut self) -> String {
        loop {
            self.sheet_counter += 1;
            let candidate = format!("Sheet{}", self.sheet_counter);
            if !self
                .workbook
                .sheets
                .iter()
                .any(|sheet| sheet.name.eq_ignore_ascii_case(&candidate))
            {
                return candidate;
            }
        }
    }

    /// Where a sheet being copied or moved should land. Excel takes Before or
    /// After, never both, and in the browser there is no second workbook to
    /// send it to when neither is given.
    fn worksheet_destination(&self, args: &[Value], name: &str) -> Result<usize, String> {
        let given = |index: usize| match args.get(index) {
            Some(Value::Missing) | None => None,
            Some(value) => Some(value),
        };
        let placed = |value: &Value| match value {
            Value::Object(object) => self.worksheet(object).ok_or_else(|| {
                format!(
                    "Worksheet.{name} expects a worksheet, not a {} object",
                    object.kind
                )
            }),
            value => self.worksheet_from_value(value),
        };
        match (given(0), given(1)) {
            (Some(_), Some(_)) => Err(format!(
                "Worksheet.{name} takes Before or After, not both"
            )),
            (Some(before), None) => placed(before),
            (None, Some(after)) => placed(after).map(|after| after + 1),
            (None, None) => Err(format!(
                "Worksheet.{name} needs Before or After; the browser has one workbook"
            )),
        }
    }

    fn copy_worksheet(&mut self, sheet: usize, args: &[Value]) -> Result<(), String> {
        let at = self.worksheet_destination(args, "Copy")?;
        let mut copy = self.workbook.sheets[sheet].clone();
        copy.name = self.unused_copy_name(&self.workbook.sheets[sheet].name);
        self.sheet_counter += 1;
        self.workbook.sheets.insert(at, copy);
        self.sheets_renumbered(&|was| Some(if was >= at { was + 1 } else { was }));
        let from = if sheet >= at { sheet + 1 } else { sheet };
        self.duplicate_side_tables(from, at);
        self.activate_sheet(at);
        Ok(())
    }

    fn move_worksheet(&mut self, sheet: usize, args: &[Value]) -> Result<(), String> {
        let at = self.worksheet_destination(args, "Move")?;
        if at == sheet || at == sheet + 1 {
            return Ok(());
        }
        let moved = self.workbook.sheets.remove(sheet);
        // Taking it out shifts everything after it down one.
        let at = if at > sheet { at - 1 } else { at };
        self.workbook.sheets.insert(at, moved);
        let mut order: Vec<usize> = (0..self.workbook.sheets.len()).collect();
        let lifted = order.remove(sheet);
        order.insert(at, lifted);
        self.sheets_renumbered(&|was| order.iter().position(|held| *held == was));
        self.activate_sheet(at);
        Ok(())
    }

    /// Excel names a copy after the sheet it came from, numbered from two.
    fn unused_copy_name(&self, base: &str) -> String {
        (2..)
            .map(|number| format!("{base} ({number})"))
            .find(|candidate| {
                !self
                    .workbook
                    .sheets
                    .iter()
                    .any(|sheet| sheet.name.eq_ignore_ascii_case(candidate))
            })
            .expect("a workbook cannot hold every possible sheet name")
    }

    /// What a copied sheet takes with it that the workbook does not hold:
    /// its notes, unlocked cells, validation, conditions, hyperlinks, styles
    /// and page setup. Everything is copied fresh, with numbers of its own.
    fn duplicate_side_tables(&mut self, from: usize, to: usize) {
        let address = |at: CellAddress| CellAddress { sheet: to, ..at };
        let range = |held: CellRange| CellRange { sheet: to, ..held };
        if let Some(protection) = self.protected.get(from).cloned().flatten() {
            if to < self.protected.len() {
                self.protected[to] = Some(protection);
            }
        }
        let unlocked: Vec<CellAddress> = self
            .unlocked
            .iter()
            .filter(|at| at.sheet == from)
            .map(|at| address(*at))
            .collect();
        self.unlocked.extend(unlocked);
        let notes: Vec<Note> = self
            .notes
            .iter()
            .filter(|note| note.at.sheet == from)
            .map(|note| Note { at: address(note.at), ..note.clone() })
            .collect();
        self.notes.extend(notes);
        let links: Vec<Link> = self
            .links
            .iter()
            .filter(|link| link.anchor.sheet == from)
            .map(|link| Link { id: 0, anchor: range(link.anchor), ..link.clone() })
            .collect();
        for mut link in links {
            link.id = self.next_link;
            self.next_link += 1;
            self.links.push(link);
        }
        let validations: Vec<(CellAddress, Validation)> = self
            .validations
            .iter()
            .filter(|(at, _)| at.sheet == from)
            .map(|(at, validation)| (address(*at), validation.clone()))
            .collect();
        self.validations.extend(validations);
        let conditions: Vec<Condition> = self
            .conditions
            .iter()
            .filter(|condition| condition.sheet == from)
            .map(|condition| Condition {
                id: 0,
                sheet: to,
                applies: condition.applies.iter().map(|held| range(*held)).collect(),
                ..condition.clone()
            })
            .collect();
        for mut condition in conditions {
            condition.id = self.next_condition;
            self.next_condition += 1;
            self.conditions.push(condition);
        }
        if let Some(setup) = self.page_setups.get(&from).cloned() {
            self.page_setups.insert(to, setup);
        }
        let styled: Vec<(CellAddress, usize)> = self
            .styled
            .iter()
            .filter(|(at, _)| at.sheet == from)
            .map(|(at, style)| (address(*at), *style))
            .collect();
        self.styled.extend(styled);
        let painted: Vec<((CellAddress, Paint), (usize, f64))> = self
            .theme_paint
            .iter()
            .filter(|((at, _), _)| at.sheet == from)
            .map(|((at, paint), colour)| ((address(*at), *paint), *colour))
            .collect();
        self.theme_paint.extend(painted);
        if let Some(view) = self.views.get(&from).copied() {
            self.views.insert(to, view);
        }
        if let Some(outline) = self.outlines.get(&from).cloned() {
            self.outlines.insert(to, outline);
        }
        if let Some(tab) = self.tabs.get(&from).copied() {
            self.tabs.insert(to, tab);
        }
        let copied: Vec<shapes::ShapeRecord> =
            self.shapes.iter().filter(|shape| shape.sheet == from).cloned().collect();
        for mut shape in copied {
            shape.id = self.next_shape_id;
            self.next_shape_id += 1;
            shape.sheet = to;
            self.shapes.push(shape);
        }
        if let Some(count) = self.shape_counters.get(&from).copied() {
            self.shape_counters.insert(to, count);
        }
        let templates: Vec<(FormatScope, CellStyle)> = self
            .templates
            .iter()
            .filter_map(|(scope, style)| {
                let scope = match *scope {
                    FormatScope::Sheet(sheet) if sheet == from => FormatScope::Sheet(to),
                    FormatScope::Column(sheet, column) if sheet == from => FormatScope::Column(to, column),
                    FormatScope::Row(sheet, row) if sheet == from => FormatScope::Row(to, row),
                    _ => return None,
                };
                Some((scope, style.clone()))
            })
            .collect();
        self.templates.extend(templates);
        let marked: Vec<CellAddress> = self
            .rotations
            .keys()
            .chain(self.underlines.keys())
            .chain(self.hatchings.keys())
            .chain(self.indented.iter())
            .filter(|at| at.sheet == from)
            .copied()
            .collect();
        for at in marked {
            let marks = self.marks_of(at);
            self.put_marks(address(at), marks);
        }
    }

    fn delete_worksheet(&mut self, sheet: usize) -> Result<(), String> {
        if self.workbook.sheets.len() <= 1 {
            return Err("a workbook must keep at least one worksheet".to_string());
        }
        self.workbook.sheets.remove(sheet);
        self.selections.remove(&sheet);
        // Excel moves to the sheet after the deleted one, or to the last
        // when it was the last -- and where a sheet other than the active
        // one goes, the active one keeps its place.
        let next = match self.active_sheet.cmp(&sheet) {
            std::cmp::Ordering::Less => self.active_sheet,
            std::cmp::Ordering::Equal => sheet.min(self.workbook.sheets.len() - 1),
            std::cmp::Ordering::Greater => self.active_sheet - 1,
        };
        self.sheets_renumbered(&|was| match was.cmp(&sheet) {
            std::cmp::Ordering::Less => Some(was),
            std::cmp::Ordering::Equal => None,
            std::cmp::Ordering::Greater => Some(was - 1),
        });
        self.active_sheet = next;
        if self.selection.sheet != next {
            self.activate_sheet(next);
        }
        Ok(())
    }

    /// Measured: 31 characters are taken and 32 refused; `: \\ / ? * [ ]`
    /// are refused; an apostrophe inside is fine but one at either end is
    /// not; the empty name is refused and a name of spaces is not; `History`
    /// is fine on this Office and `履歴` -- its history sheet's own name --
    /// is refused. Each refusal is 1004 and leaves the name as it was.
    fn rename_worksheet(&mut self, sheet: usize, name: &str) -> Result<(), String> {
        let refused = name.is_empty()
            || name.chars().count() > 31
            || name.chars().any(|c| matches!(c, ':' | '\\' | '/' | '?' | '*' | '[' | ']'))
            || name.starts_with('\'')
            || name.ends_with('\'')
            || name == "履歴";
        if refused {
            return Err(host_error(1004, "that is not a name a sheet can have"));
        }
        if self
            .workbook
            .sheets
            .iter()
            .enumerate()
            .any(|(index, held)| index != sheet && held.name.eq_ignore_ascii_case(name))
        {
            return Err(format!("another worksheet is already called {name}"));
        }
        self.workbook.sheets[sheet].name = name.to_string();
        Ok(())
    }

    fn worksheet_object(&mut self, value: &Value) -> Result<Value, String> {
        let sheet = self.worksheet_from_value(value)?;
        Ok(self.object(HostObject::Worksheet(sheet)))
    }

    fn worksheets_object_or_item(&mut self, args: &[Value]) -> Result<Value, String> {
        match args {
            [] => Ok(self.object(HostObject::Worksheets)),
            // `Sheets(Array("Sheet1", "Sheet2"))` groups the sheets named;
            // what a macro then does with the group -- `.Select` -- lands on
            // the first, which is what this build keeps of it. Measured:
            // after it ActiveSheet is Sheet1.
            [Value::Array(listed)] => match listed.values.first() {
                Some(first) => self.worksheet_object(first),
                None => Err(host_error(1004, "Sheets takes at least one name")),
            },
            [value] => self.worksheet_object(value),
            _ => Err("Worksheets expects zero or one argument".to_string()),
        }
    }

    fn worksheet_from_value(&self, value: &Value) -> Result<usize, String> {
        match value {
            Value::String(name) => self
                .workbook
                .sheets
                .iter()
                .position(|sheet| sheet.name.eq_ignore_ascii_case(name))
                .ok_or_else(|| format!("worksheet not found: {name}")),
            value if any_number(value).is_some() => self.worksheet_from_number(any_number(value).unwrap_or_default()),
            Value::Double(index) => self.worksheet_from_number(*index),
            _ => Err("Worksheets expects a sheet name or one-based index".to_string()),
        }
    }

    fn worksheet_from_number(&self, index: f64) -> Result<usize, String> {
        if !index.is_finite() || index.fract() != 0.0 || index < 1.0 {
            return Err("worksheet index must be a positive integer".to_string());
        }
        let index = index as usize - 1;
        (index < self.workbook.sheets.len())
            .then_some(index)
            .ok_or_else(|| format!("worksheet index is out of range: {}", index + 1))
    }

    fn range_object(
        &mut self,
        sheet: usize,
        args: &[Value],
        reach: NameReach,
    ) -> Result<Value, String> {
        if let [Value::String(reference)] = args {
            // Blocks named together, which Excel writes with commas between
            // them: `Range("A1:A2,C1:C2")` is one range of two areas.
            if reference.contains(',') {
                let mut given = Vec::new();
                for part in reference.split(',') {
                    if let Some(band) = parse_band_reference(part.trim()) {
                        given.push(CellRange {
                            sheet,
                            start_row: band.0,
                            start_column: band.1,
                            end_row: band.2,
                            end_column: band.3,
                        });
                        continue;
                    }
                    let (start, end) = parse_range_reference(part.trim())?;
                    given.push(CellRange {
                        sheet,
                        start_row: start.1.min(end.1),
                        start_column: start.0.min(end.0),
                        end_row: start.1.max(end.1),
                        end_column: start.0.max(end.0),
                    });
                }
                return self.written_blocks_object(given);
            }
        }
        if let [Value::String(reference)] = args {
            if let Some(band) = parse_band_reference(reference) {
                return Ok(self.object(HostObject::Range(CellRange {
                    sheet,
                    start_row: band.0,
                    start_column: band.1,
                    end_row: band.2,
                    end_column: band.3,
                })));
            }
        }
        let (start, end) = match args {
            [Value::String(reference)] => match parse_range_reference(reference) {
                Ok(pair) => pair,
                // Not written as a reference, so it is meant as a name. Excel
                // will not let a name look like `A1`, so nothing is ambiguous.
                Err(unreadable) => {
                    let named = self.named_range(sheet, reference, reach, unreadable)?;
                    return Ok(self.object(HostObject::Range(named)));
                }
            },
            [Value::String(start), Value::String(end)] => {
                (parse_a1_reference(start)?, parse_a1_reference(end)?)
            }
            // `Range(Cells(1, 1), Cells(3, 3))`: the block the two span.
            [Value::Object(_), _] | [_, Value::Object(_)] => {
                let corner = |value: &Value| -> Result<CellRange, String> {
                    match value {
                        Value::Object(object) => self
                            .range(object)
                            .ok_or_else(|| host_error(1004, "Range takes two cells")),
                        Value::String(text) => {
                            let (column, row) = parse_a1_reference(text)?;
                            Ok(CellRange::single(CellAddress { sheet, row, column }))
                        }
                        _ => Err(host_error(1004, "Range takes two cells")),
                    }
                };
                let (one, other) = (corner(&args[0])?, corner(&args[1])?);
                if one.sheet != other.sheet {
                    return Err(host_error(1004, "Range takes two cells of one sheet"));
                }
                return Ok(self.object(HostObject::Range(CellRange {
                    sheet: one.sheet,
                    start_row: one.start_row.min(other.start_row),
                    start_column: one.start_column.min(other.start_column),
                    end_row: one.end_row.max(other.end_row),
                    end_column: one.end_column.max(other.end_column),
                })));
            }
            _ => return Err("Range expects one range reference or two cell references".to_string()),
        };
        let (start_column, start_row) = start;
        let (end_column, end_row) = end;
        Ok(self.object(HostObject::Range(CellRange {
            sheet,
            start_row: start_row.min(end_row),
            start_column: start_column.min(end_column),
            end_row: start_row.max(end_row),
            end_column: start_column.max(end_column),
        })))
    }

    /// The names a workbook keeps, or one of them.
    ///
    /// Excel hands them out in ALPHABETICAL order, not the order they were
    /// made in: with `Sales`, `Bare`, `Loose` and `FromRange` in the workbook,
    /// `Names(1)` is `Bare`.
    fn names_object_or_item(&mut self, args: &[Value]) -> Result<Value, String> {
        match args {
            [] | [Value::Missing] => Ok(self.object(HostObject::Names)),
            [value] => self.name_item(value),
            _ => Err("Names takes one name or one number".to_string()),
        }
    }

    fn name_item(&mut self, value: &Value) -> Result<Value, String> {
        let wanted = match value {
            Value::String(text) => text.clone(),
            value if any_number(value).is_some() => {
                let index = positive_index(value, "index")? as usize;
                let mut held = self
                    .workbook
                    .defined_names
                    .iter()
                    .map(|(name, _)| name.clone())
                    .collect::<Vec<_>>();
                held.sort_by(|one, other| compare_text_by_case(one, other));
                held.get(index - 1)
                    .cloned()
                    .ok_or_else(|| format!("the workbook has no name number {index}"))?
            }
            _ => return Err("a name is asked for by its text or its number".to_string()),
        };
        let Some(at) = self.name_at(&wanted) else {
            return Err(format!("the workbook has no name {wanted:?}"));
        };
        let held = self.workbook.defined_names[at].0.clone();
        Ok(self.name_object(&held))
    }

    /// Give a name to something, or write over a name already given.
    ///
    /// Asked of Excel: `RefersTo` is read as a formula, so a string WITHOUT a
    /// leading `=` is stored as text — `Names.Add "Bare", "Sheet1!$A$2"`
    /// leaves `="Sheet1!$A$2"`, which names no cells at all. A Range hands
    /// over its own address, written absolute.
    fn add_name(&mut self, args: &[Value]) -> Result<Value, String> {
        let (name, refers_to) = match args {
            [Value::String(name), refers_to] => (name.clone(), refers_to),
            _ => return Err("Names.Add needs a Name and what it RefersTo".to_string()),
        };
        // A name may carry the sheet it belongs to: asked of Excel,
            // `Names.Add Name:="Sheet1!loc", RefersTo:="=Sheet1!$A$2"` is
            // accepted, `Names(1).Name` answers `Sheet1!loc`, and
            // `Range("loc")` finds it from that sheet. Only the part after the
            // `!` is the name; the part before it has to be a sheet there is.
            match name.rsplit_once('!') {
                Some((sheet, leaf)) => {
                    let bare = sheet.trim_matches('\'');
                    if !self
                        .workbook
                        .sheets
                        .iter()
                        .any(|held| held.name.eq_ignore_ascii_case(bare))
                    {
                        return Err(format!("{bare:?} is not a worksheet in this workbook"));
                    }
                    check_name(leaf)?;
                }
                None => check_name(&name)?,
            }
        let refers_to = match refers_to {
            Value::String(written) => {
                let written = written.trim();
                match written.strip_prefix('=') {
                    Some(rest) => rest.trim().to_string(),
                    None => format!("\"{}\"", written.replace('"', "\"\"")),
                }
            }
            Value::Object(object) => {
                let range = self
                    .range(object)
                    .ok_or_else(|| "Names.Add RefersTo must be a Range".to_string())?;
                let sheet = self.workbook.sheets[range.sheet].name.clone();
                format!(
                    "{}!{}",
                    quoted_sheet(&sheet),
                    format_range_address(range, true, true)
                )
            }
            Value::Missing | Value::Empty => {
                return Err("Names.Add needs to say what the name RefersTo".to_string())
            }
            other => shown_text(other, None),
        };
        match self.name_at(&name) {
            Some(at) => self.workbook.defined_names[at] = (name.clone(), refers_to),
            None => self.workbook.defined_names.push((name.clone(), refers_to)),
        }
        Ok(self.name_object(&name))
    }

    /// How a name writes down the block it stands for: the sheet, then the
    /// address with every half absolute, which is what Excel stores.
    fn address_of(&self, range: CellRange) -> String {
        format!(
            "{}!{}",
            quoted_sheet(&self.workbook.sheets[range.sheet].name),
            format_range_address(range, true, true)
        )
    }

    /// What one of the workbook's names answers to.
    ///
    /// `Value` is the same as `RefersTo`, as Excel answers it, and
    /// `RefersToRange` is the block it stands for. A name that has since been
    /// deleted raises rather than answering with what it used to say.
    fn name_member(&mut self, held: &str, name: &str, args: &[Value]) -> Result<Value, String> {
        let Some(at) = self.name_at(held) else {
            return Err(format!("the name {held:?} is no longer in the workbook"));
        };
        if name.eq_ignore_ascii_case("name") {
            return Ok(Value::String(self.workbook.defined_names[at].0.clone()));
        }
        if name.eq_ignore_ascii_case("refersto") || name.eq_ignore_ascii_case("value") {
            return Ok(Value::String(format!(
                "={}",
                self.workbook.defined_names[at].1
            )));
        }
        // The names Excel writes for itself are hidden; the ones a macro adds
        // are not. Measured: `Sheet1!_FilterDatabase` answers False.
        if name.eq_ignore_ascii_case("visible") {
            let held = self.workbook.defined_names[at].0.clone();
            let leaf = held.rsplit('!').next().unwrap_or(&held).to_string();
            return Ok(Value::Boolean(
                !leaf.eq_ignore_ascii_case("_FilterDatabase")
                    && !leaf.to_ascii_lowercase().starts_with("_xlnm."),
            ));
        }
        if name.eq_ignore_ascii_case("referstorange") {
            let range = self.named_range(
                0,
                held,
                NameReach::Workbook,
                format!("the name {held:?} stands for no cells"),
            )?;
            return Ok(self.object(HostObject::Range(range)));
        }
        if name.eq_ignore_ascii_case("delete") {
            if !args.is_empty() {
                return Err("Name.Delete does not accept arguments".to_string());
            }
            self.workbook.defined_names.remove(at);
            return Ok(Value::Empty);
        }
        Err(format!("Name.{name} is not available in the browser"))
    }

    /// A block of cells the workbook has given a name to.
    ///
    /// Asked of Excel: the lookup ignores case, and a WORKSHEET answers only
    /// for the names pointing at itself — `Sheets("A").Range("NameOnB")`
    /// raises rather than reaching across — while `Application.Range` and
    /// `Evaluate` look through the whole workbook. A name standing for
    /// something that is not one block of cells, such as two scattered blocks
    /// or a plain number, is not a Range and raises too.
    fn named_range(
        &self,
        sheet: usize,
        name: &str,
        reach: NameReach,
        unreadable: String,
    ) -> Result<CellRange, String> {
        // Through `name_at`, which also finds a SHEET-SCOPED name asked for
        // without its sheet: `Range("loc")` has to reach `Sheet1!loc`. Reading
        // the list directly here found only the exact spelling, so a scoped
        // name could be added and then not be found by the name a macro writes.
        let Some((held, refers_to)) = self
            .name_at(name.trim())
            .and_then(|at| self.workbook.defined_names.get(at))
        else {
            return Err(format!(
                "{unreadable}, and the workbook has no name {name:?} either"
            ));
        };
        let refers_to = refers_to.trim();
        let refers_to = refers_to.strip_prefix('=').unwrap_or(refers_to).trim();
        if refers_to.contains(',') {
            return Err(format!(
                "the name {held:?} stands for more than one block of cells, \
                 which this build cannot hold in one Range"
            ));
        }
        let (named_sheet, reference) = split_sheet_reference(refers_to);
        let Some(named_sheet) = named_sheet else {
            return Err(format!(
                "the name {held:?} stands for {refers_to:?}, which does not say \
                 which worksheet it means"
            ));
        };
        let target = self
            .workbook
            .sheets
            .iter()
            .position(|candidate| candidate.name.eq_ignore_ascii_case(&named_sheet))
            .ok_or_else(|| {
                format!("the name {held:?} points at a worksheet this workbook does not have: {named_sheet}")
            })?;
        if matches!(reach, NameReach::ThisSheet) && target != sheet {
            return Err(format!(
                "the name {held:?} belongs to worksheet {named_sheet:?}, and a \
                 worksheet answers only for its own names"
            ));
        }
        let (start, end) = parse_range_reference(reference).map_err(|_| {
            format!("the name {held:?} stands for {refers_to:?}, which is not a block of cells")
        })?;
        let (start_column, start_row) = start;
        let (end_column, end_row) = end;
        Ok(CellRange {
            sheet: target,
            start_row: start_row.min(end_row),
            start_column: start_column.min(end_column),
            end_row: start_row.max(end_row),
            end_column: start_column.max(end_column),
        })
    }

    fn evaluate_object(&mut self, sheet: usize, args: &[Value]) -> Result<Value, String> {
        let [Value::String(expression)] = args else {
            return Err("Evaluate expects one String expression".to_string());
        };
        let expression = expression
            .trim()
            .strip_prefix('=')
            .unwrap_or(expression.trim());
        let expression = expression
            .strip_prefix('[')
            .and_then(|value| value.strip_suffix(']'))
            .unwrap_or(expression)
            .trim();
        let (sheet, reference) = match expression.rsplit_once('!') {
            Some((sheet_name, reference)) => {
                let mut sheet_name = sheet_name.trim();
                if let Some(workbook_end) = sheet_name.rfind(']') {
                    sheet_name = &sheet_name[workbook_end + 1..];
                }
                let sheet_name = if sheet_name.starts_with('\'')
                    && sheet_name.ends_with('\'')
                    && sheet_name.len() >= 2
                {
                    sheet_name[1..sheet_name.len() - 1].replace("''", "'")
                } else {
                    sheet_name.to_string()
                };
                let sheet = self
                    .workbook
                    .sheets
                    .iter()
                    .position(|candidate| candidate.name.eq_ignore_ascii_case(&sheet_name))
                    .ok_or_else(|| format!("worksheet not found: {sheet_name}"))?;
                (sheet, reference.trim())
            }
            None => (sheet, expression),
        };
        // A reference or a name first, since that is what Excel answers with
        // a Range: `Evaluate("A1")` hands back the cell, not what is in it.
        if let Ok(range) = self.range_object(
            sheet,
            &[Value::String(reference.to_string())],
            NameReach::Workbook,
        ) {
            return Ok(range);
        }
        // Anything else is a formula, worked out the way the sheet would work
        // it out. Measured in Excel 16.0: `1+1` and `=1+1` are both 2,
        // `SUM(B1:B2)` reads the cells, `LEN("abc")` is 3, and a failure comes
        // back as the value a cell would show — `1/0` is error 2007 and
        // `NOTAFN()` is 2029 — rather than stopping the macro.
        match oxicells_core::formula::evaluate_expression(
            self.workbook,
            sheet,
            reference,
            self.now,
        ) {
            Some(oxicells_calc::Value::Number(number)) => Ok(numeric_result(number)),
            Some(oxicells_calc::Value::Text(text)) => Ok(Value::String(text)),
            Some(oxicells_calc::Value::Logical(state)) => Ok(Value::Boolean(state)),
            Some(oxicells_calc::Value::Blank) => Ok(Value::Empty),
            Some(oxicells_calc::Value::Error(why)) => {
                Ok(Value::Error(spreadsheet_error_number(why.as_str())))
            }
            None => Err(format!("Evaluate cannot work out {reference:?}")),
        }
    }

    /// The rectangle a sheet's written cells fill.
    fn used_range(&self, sheet: usize) -> Result<CellRange, String> {
        let worksheet = self
            .workbook
            .sheets
            .get(sheet)
            .ok_or_else(|| "worksheet no longer exists".to_string())?;
        // A cell with nothing in it and nothing on it is not used: measured,
        // the range shrinks back after `Clear` and after `ClearFormats` on
        // a cell that was only bold, and does not count a cell that only
        // held a value once.
        let bare = CellStyle::default();
        let mut bounds = None::<(u32, u32, u32, u32)>;
        for row in &worksheet.rows {
            for cell in &row.cells {
                if matches!(cell.value, CellValue::Empty)
                    && cell.formula.is_none()
                    && cell.runs.is_empty()
                    && cell.style == bare
                {
                    continue;
                }
                bounds = Some(match bounds {
                    Some((start_row, start_column, end_row, end_column)) => (
                        start_row.min(row.index),
                        start_column.min(cell.col),
                        end_row.max(row.index),
                        end_column.max(cell.col),
                    ),
                    None => (row.index, cell.col, row.index, cell.col),
                });
            }
        }
        let (start_row, start_column, end_row, end_column) = bounds.unwrap_or((1, 0, 1, 0));
        Ok(CellRange { sheet, start_row, start_column, end_row, end_column })
    }

    fn used_range_object(&mut self, sheet: usize) -> Result<Value, String> {
        let CellRange { start_row, start_column, end_row, end_column, .. } =
            self.used_range(sheet)?;
        Ok(self.object(HostObject::Range(CellRange {
            sheet,
            start_row,
            start_column,
            end_row,
            end_column,
        })))
    }

    fn worksheet_axis_object_or_item(
        &mut self,
        sheet: usize,
        axis: RangeAxis,
        args: &[Value],
    ) -> Result<Value, String> {
        let range = CellRange {
            sheet,
            start_row: 1,
            start_column: 0,
            end_row: MAX_WORKSHEET_ROW,
            end_column: MAX_WORKSHEET_COLUMN,
        };
        self.range_collection_object_or_item(range, axis, args)
    }

    fn cells_object(&mut self, sheet: usize, args: &[Value]) -> Result<Value, String> {
        // One index counts across the whole sheet the same way it counts
        // across a range — by rows, 16384 to a row. Asked of Excel,
        // `Cells(16384)` is XFD1 and `Cells(16385)` is A2, and the last one it
        // will give is `Cells(17179869184)` = XFD1048576.
        // `Cells` alone, and `Cells(n)`, are the whole sheet and one cell
        // of it counted across the whole sheet.
        if matches!(args, [] | [Value::Missing] | [_]) {
            return self.range_cells_object(
                CellRange {
                    sheet,
                    start_row: 1,
                    start_column: 0,
                    end_row: MAX_WORKSHEET_ROW,
                    end_column: MAX_WORKSHEET_COLUMN,
                },
                args,
            );
        }
        let [row, column] = args else {
            return Err("Cells expects an index, or a row and a column".to_string());
        };
        let row = positive_index(row, "row")?;
        let column = column_index(column)? - 1;
        Ok(
            self.object(HostObject::Range(CellRange::single(CellAddress {
                sheet,
                row,
                column,
            }))),
        )
    }

    fn range_cells_object(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        // Nothing in the brackets means the range itself.
        if matches!(args, [] | [Value::Missing]) {
            return Ok(self.object(HostObject::Range(range)));
        }
        // One index counts across the range by rows and does not stop at its
        // edge: asked of Excel, the fifth cell of the two-wide `B2:C3` is
        // `B4`, a row below the block, and the noughth cell of `B2:D5` is
        // `A2` — the cell before the first, which walks back into the column
        // before. Both fall out of a truncating divide by the range's width.
        if let [index] = args {
            let wide = i64::from(range.end_column - range.start_column) + 1;
            let step = cells_index(index)? - 1;
            let down = step / wide;
            let across = step % wide;
            let row = i64::from(range.start_row) + down;
            let column = i64::from(range.start_column) + across;
            // Walking off the sheet is refused rather than wrapped: asked of
            // Excel, `Cells(17179869184)` is the last cell and one more than
            // that raises.
            if row < 1
                || column < 0
                || row > i64::from(MAX_WORKSHEET_ROW)
                || column > i64::from(MAX_WORKSHEET_COLUMN)
            {
                return Err("Range.Cells has no cell there".to_string());
            }
            return Ok(
                self.object(HostObject::Range(CellRange::single(CellAddress {
                    sheet: range.sheet,
                    row: row as u32,
                    column: column as u32,
                }))),
            );
        }
        let [row, column] = args else {
            return Err("Range.Cells expects an index, or a row and a column".to_string());
        };
        let row = positive_index(row, "row")? - 1;
        let column = column_index(column)? - 1;
        let row = range
            .start_row
            .checked_add(row)
            .ok_or_else(|| "Range.Cells row is too large".to_string())?;
        let column = range
            .start_column
            .checked_add(column)
            .ok_or_else(|| "Range.Cells column is too large".to_string())?;
        Ok(
            self.object(HostObject::Range(CellRange::single(CellAddress {
                sheet: range.sheet,
                row,
                column,
            }))),
        )
    }

    fn range_collection_object_or_item(
        &mut self,
        range: CellRange,
        axis: RangeAxis,
        args: &[Value],
    ) -> Result<Value, String> {
        match args {
            [] => Ok(self.object(HostObject::RangeCollection(range, axis))),
            [index] => self.range_collection_item(range, axis, index),
            _ => Err(format!(
                "Range.{} expects zero or one argument",
                range_axis_name(axis)
            )),
        }
    }

    fn range_collection_item(
        &mut self,
        range: CellRange,
        axis: RangeAxis,
        index: &Value,
    ) -> Result<Value, String> {
        // Written out, an index is still an index: asked of Excel,
        // `Range("C5:E10").Columns("B")` is D — the range's second column —
        // exactly as `Columns(2)` is, and `Columns("D")` is F, outside the
        // range altogether. A pair takes the span between the two.
        let (first, last) = match index {
            Value::String(text) => match parse_band_span(text) {
                Some(span) => span,
                None => return Err(format!("invalid {} index: {text}", range_axis_name(axis))),
            },
            _ => {
                let only = positive_index(index, range_axis_name(axis))?;
                (only, only)
            }
        };
        let (first, last) = (first - 1, last - 1);
        let item = match axis {
            RangeAxis::Rows => {
                let start = range
                    .start_row
                    .checked_add(first)
                    .ok_or_else(|| "Range.Rows index is too large".to_string())?;
                let end = range
                    .start_row
                    .checked_add(last)
                    .ok_or_else(|| "Range.Rows index is too large".to_string())?;
                CellRange {
                    start_row: start,
                    end_row: end,
                    ..range
                }
            }
            RangeAxis::Columns => {
                let start = range
                    .start_column
                    .checked_add(first)
                    .ok_or_else(|| "Range.Columns index is too large".to_string())?;
                let end = range
                    .start_column
                    .checked_add(last)
                    .ok_or_else(|| "Range.Columns index is too large".to_string())?;
                CellRange {
                    start_column: start,
                    end_column: end,
                    ..range
                }
            }
        };
        // The item keeps the sense it was indexed through: asked of Excel,
        // `Rows("1:3").Item(2)` is `$2:$2` and counts 1, not 16384.
        Ok(self.object(HostObject::RangeCollection(item, axis)))
    }

    fn cell_value(&self, address: CellAddress) -> Value {
        self.workbook
            .sheets
            .get(address.sheet)
            .and_then(|sheet| sheet.rows.iter().find(|row| row.index == address.row))
            .and_then(|row| row.cells.iter().find(|cell| cell.col == address.column))
            .map(|cell| from_cell_value(&cell.value))
            .unwrap_or(Value::Empty)
    }

    /// A cell's value AS THE MACRO RECEIVES IT, which its display format has a
    /// say in. See `shown_as`: a date-formatted cell hands over a Date and a
    /// dollar-formatted one a Currency, and only a number in a cell whose
    /// format claims neither arrives as a plain Double.
    fn cell_value_as_shown(&self, address: CellAddress) -> Value {
        let Some(cell) = self
            .workbook
            .sheets
            .get(address.sheet)
            .and_then(|sheet| sheet.rows.iter().find(|row| row.index == address.row))
            .and_then(|row| row.cells.iter().find(|cell| cell.col == address.column))
        else {
            return Value::Empty;
        };
        let value = from_cell_value(&cell.value);
        let CellValue::Number(number) = cell.value else {
            return value;
        };
        match shown_as(cell.style.number_format.as_deref()) {
            ShownAs::Plain => value,
            ShownAs::Moment => Value::Date(number),
            // Four places is all a Currency keeps: asked of Excel, 1.23456789
            // under `$0.00` comes back as 1.2346.
            ShownAs::Money => Value::Currency((number * 10_000.0).round_ties_even() as i64),
        }
    }

    fn range_cell_count(range: CellRange) -> Result<usize, String> {
        let count = Self::range_cell_count_large(range)?;
        if count > 1_000_000 {
            return Err("cell range exceeds the 1,000,000-cell execution limit".to_string());
        }
        Ok(count as usize)
    }

    fn range_cell_count_large(range: CellRange) -> Result<u64, String> {
        let rows = u64::from(range.end_row - range.start_row) + 1;
        let columns = u64::from(range.end_column - range.start_column) + 1;
        rows.checked_mul(columns)
            .ok_or_else(|| "cell range is too large".to_string())
    }

    fn range_value(&self, range: CellRange) -> Result<Value, String> {
        Self::range_cell_count(range)?;
        if range.is_single() {
            return Ok(self.cell_value_as_shown(range.addresses().next().unwrap()));
        }
        Ok(Value::Array(ArrayValue {
            dimensions: vec![
                ArrayDimension {
                    lower_bound: 1,
                    length: (range.end_row - range.start_row + 1) as usize,
                },
                ArrayDimension {
                    lower_bound: 1,
                    length: (range.end_column - range.start_column + 1) as usize,
                },
            ],
            values: range
                .addresses()
                .map(|address| self.cell_value_as_shown(address))
                .collect(),
            element_default: Box::new(Value::Empty),
            resizable: true,
        }))
    }

    fn append_worksheet_function_values(
        &self,
        value: &Value,
        values: &mut Vec<Value>,
    ) -> Result<(), String> {
        match value {
            Value::Array(array) => {
                for value in &array.values {
                    self.append_worksheet_function_values(value, values)?;
                }
            }
            Value::Object(object) => {
                let Some(range) = self.range(object) else {
                    return Err(format!(
                        "WorksheetFunction cannot aggregate a {} object",
                        object.kind
                    ));
                };
                let value = self.range_value(range)?;
                self.append_worksheet_function_values(&value, values)?;
            }
            value => values.push(value.clone()),
        }
        Ok(())
    }

    fn lookup_table(&self, value: &Value, name: &str) -> Result<LookupTable, String> {
        match value {
            Value::Object(object) => {
                let Some(range) = self.range(object) else {
                    return Err(format!(
                        "WorksheetFunction.{name} cannot search a {} object",
                        object.kind
                    ));
                };
                Self::range_cell_count(range)?;
                Ok(LookupTable {
                    rows: (range.end_row - range.start_row + 1) as usize,
                    columns: (range.end_column - range.start_column + 1) as usize,
                    values: range
                        .addresses()
                        .map(|address| self.cell_value(address))
                        .collect(),
                })
            }
            Value::Array(array) => {
                let (rows, columns) = match array.dimensions.as_slice() {
                    [columns] => (1, columns.length),
                    [rows, columns] => (rows.length, columns.length),
                    _ => {
                        return Err(format!(
                            "WorksheetFunction.{name} needs a one- or two-dimensional array"
                        ))
                    }
                };
                Ok(LookupTable {
                    rows,
                    columns,
                    values: array.values.clone(),
                })
            }
            value => Ok(LookupTable {
                rows: 1,
                columns: 1,
                values: vec![value.clone()],
            }),
        }
    }

    fn worksheet_lookup(
        &self,
        name: &str,
        args: &[Value],
        orientation: LookupOrientation,
    ) -> Result<Value, String> {
        let (needle, table, index) = match args {
            [needle, table, index] | [needle, table, index, _] => (needle, table, index),
            _ => {
                return Err(format!(
                    "WorksheetFunction.{name} expects three or four arguments"
                ))
            }
        };
        let approximate = lookup_boolean_argument(args.get(3), name)?;
        let index = lookup_index_argument(index, name)?;
        let table = self.lookup_table(table, name)?;
        let (lanes, depth) = match orientation {
            LookupOrientation::Vertical => (table.rows, table.columns),
            LookupOrientation::Horizontal => (table.columns, table.rows),
        };
        if index > depth {
            return Ok(Value::Error(ERROR_REF));
        }
        let key_at = |lane: usize| match orientation {
            LookupOrientation::Vertical => table.get(lane, 0),
            LookupOrientation::Horizontal => table.get(0, lane),
        };
        let lane = if approximate {
            sorted_lookup_position(lanes, false, key_at, needle).map(|position| position - 1)
        } else {
            (0..lanes).find(|lane| lookup_exact_matches(&key_at(*lane), needle))
        };
        let Some(lane) = lane else {
            return Ok(Value::Error(ERROR_NA));
        };
        Ok(match orientation {
            LookupOrientation::Vertical => table.get(lane, index - 1),
            LookupOrientation::Horizontal => table.get(index - 1, lane),
        })
    }

    /// `Index` over a cell range answers with a *reference*, so `Set` on the
    /// result and `Range.Address` both work and the result feeds back into
    /// other worksheet functions. Over a VBA array it answers with values.
    fn criteria_range(&self, value: &Value, name: &str) -> Result<CellRange, String> {
        let Value::Object(object) = value else {
            return Err(format!(
                "WorksheetFunction.{name} needs a cell range, not a value"
            ));
        };
        let Some(range) = self.range(object) else {
            return Err(format!(
                "WorksheetFunction.{name} cannot test a {} object",
                object.kind
            ));
        };
        Self::range_cell_count(range)?;
        Ok(range)
    }

    /// A criteria argument may itself be a cell, in which case Excel tests
    /// against that cell's value.
    fn criteria_value(&self, value: &Value) -> Result<Value, String> {
        match value {
            Value::Object(object) => match self.range(object) {
                Some(range) => self.range_value(range),
                None => Err(format!(
                    "WorksheetFunction cannot use a {} object as criteria",
                    object.kind
                )),
            },
            value => Ok(value.clone()),
        }
    }

    /// `SumIf` and `AverageIf` anchor their aggregated range at its top-left
    /// corner and stretch it to the shape of the range being tested, so
    /// `SumIf(A1:A4, ">15", C1)` aggregates `C1:C4`.
    fn stretched_range(
        &self,
        value: &Value,
        shape: CellRange,
        name: &str,
    ) -> Result<CellRange, String> {
        let source = self.criteria_range(value, name)?;
        let stretched = CellRange {
            sheet: source.sheet,
            start_row: source.start_row,
            start_column: source.start_column,
            end_row: source
                .start_row
                .saturating_add(shape.end_row - shape.start_row)
                .min(MAX_WORKSHEET_ROW),
            end_column: source
                .start_column
                .saturating_add(shape.end_column - shape.start_column)
                .min(MAX_WORKSHEET_COLUMN),
        };
        Self::range_cell_count(stretched)?;
        Ok(stretched)
    }

    fn worksheet_conditional(
        &self,
        name: &str,
        args: &[Value],
        kind: ConditionalKind,
    ) -> Result<Value, String> {
        let aggregates = kind != ConditionalKind::Count;
        if args.len() < 2 || args.len() > if aggregates { 3 } else { 2 } {
            return Err(format!(
                "WorksheetFunction.{name} expects {} arguments",
                if aggregates { "two or three" } else { "two" }
            ));
        }
        let tested = self.criteria_range(&args[0], name)?;
        let criteria = parse_criteria(&self.criteria_value(&args[1])?);
        let aggregated = match args.get(2) {
            Some(value) => self.stretched_range(value, tested, name)?,
            None => tested,
        };

        let mut matches = 0usize;
        let mut numbers = 0usize;
        let mut total = 0.0;
        for (tested, aggregated) in tested.addresses().zip(aggregated.addresses()) {
            if !criteria.matches(&self.cell_value(tested)) {
                continue;
            }
            matches += 1;
            if let Some(number) = criteria_number(&self.cell_value(aggregated)) {
                numbers += 1;
                total += number;
            }
        }
        conditional_result(name, kind, matches, numbers, total)
    }

    fn worksheet_conditional_set(
        &self,
        name: &str,
        args: &[Value],
        kind: ConditionalKind,
    ) -> Result<Value, String> {
        let (aggregated, pairs) = if kind == ConditionalKind::Count {
            (None, args)
        } else {
            let Some((aggregated, pairs)) = args.split_first() else {
                return Err(format!(
                    "WorksheetFunction.{name} expects a range to aggregate"
                ));
            };
            (Some(aggregated), pairs)
        };
        if pairs.len() < 2 {
            return Err(format!(
                "WorksheetFunction.{name} expects a range and criteria pair"
            ));
        }

        let mut tests = Vec::new();
        let mut shape = None;
        // Excel ignores a trailing range that has no criteria of its own.
        for pair in pairs.chunks(2) {
            let [tested, criteria] = pair else { continue };
            let tested = self.criteria_range(tested, name)?;
            let extent = (
                tested.end_row - tested.start_row,
                tested.end_column - tested.start_column,
            );
            match shape {
                None => shape = Some(extent),
                Some(shape) if shape == extent => {}
                Some(_) => {
                    return Err(format!(
                        "WorksheetFunction.{name} needs every criteria range to have one shape"
                    ))
                }
            }
            tests.push((tested, parse_criteria(&self.criteria_value(criteria)?)));
        }
        let Some((rows, columns)) = shape else {
            return Err(format!(
                "WorksheetFunction.{name} expects a range and criteria pair"
            ));
        };
        let aggregated = match aggregated {
            Some(value) => {
                let aggregated = self.criteria_range(value, name)?;
                if (
                    aggregated.end_row - aggregated.start_row,
                    aggregated.end_column - aggregated.start_column,
                ) != (rows, columns)
                {
                    return Err(format!(
                        "WorksheetFunction.{name} needs the aggregated range to match the criteria shape"
                    ));
                }
                Some(aggregated)
            }
            None => None,
        };

        let mut matches = 0usize;
        let mut numbers = 0usize;
        let mut total = 0.0;
        for row in 0..=rows {
            for column in 0..=columns {
                let matched = tests.iter().all(|(tested, criteria)| {
                    criteria.matches(&self.cell_value(CellAddress {
                        sheet: tested.sheet,
                        row: tested.start_row + row,
                        column: tested.start_column + column,
                    }))
                });
                if !matched {
                    continue;
                }
                matches += 1;
                let Some(aggregated) = aggregated else {
                    continue;
                };
                let value = self.cell_value(CellAddress {
                    sheet: aggregated.sheet,
                    row: aggregated.start_row + row,
                    column: aggregated.start_column + column,
                });
                if let Some(number) = criteria_number(&value) {
                    numbers += 1;
                    total += number;
                }
            }
        }
        conditional_result(name, kind, matches, numbers, total)
    }

    /// The rectangle every one of these ranges covers, or `Nothing` where
    /// they do not all meet.
    ///
    /// Asked of Excel, `_xlsx`-style, through `InvokeMember` — the method
    /// declares thirty optional arguments and a plain call cannot bind to it:
    ///
    /// ```text
    /// B2:D5 with C3:E7      C3:D5        no overlap at all     Nothing
    /// one inside another    the inner    edges that only touch Nothing
    /// C:C with 5:5          C5           C:E with D:G          D:E
    /// three that all meet   the corner   three, one apart      Nothing
    /// ONE argument          Nothing      ranges on two sheets  an error
    /// ```
    ///
    /// The single-argument answer is the odd one: Excel does not complain, it
    /// simply has nothing to hand back.
    fn intersect_ranges(&mut self, args: &[Value]) -> Result<Value, String> {
        let mut held: Option<CellRange> = None;
        let mut seen = 0;
        for value in args {
            if matches!(value, Value::Missing) {
                continue;
            }
            let Value::Object(object) = value else {
                return Err("Application.Intersect takes ranges".to_string());
            };
            let Some(range) = self.range(object) else {
                return Err(format!(
                    "Application.Intersect cannot take a {} object",
                    object.kind
                ));
            };
            seen += 1;
            let Some(so_far) = held else {
                held = Some(range);
                continue;
            };
            // Excel raises a run-time error rather than answering Nothing when
            // the ranges are not on one sheet, so the two are not the same
            // question and must not be answered the same way.
            if so_far.sheet != range.sheet {
                return Err(
                    "Application.Intersect needs ranges on the same worksheet".to_string(),
                );
            }
            let start_row = so_far.start_row.max(range.start_row);
            let end_row = so_far.end_row.min(range.end_row);
            let start_column = so_far.start_column.max(range.start_column);
            let end_column = so_far.end_column.min(range.end_column);
            if start_row > end_row || start_column > end_column {
                return Ok(Value::Nothing);
            }
            held = Some(CellRange {
                sheet: so_far.sheet,
                start_row,
                end_row,
                start_column,
                end_column,
            });
        }
        // One range has nothing to be intersected with.
        if seen < 2 {
            return Ok(Value::Nothing);
        }
        match held {
            Some(range) => Ok(self.object(HostObject::Range(range))),
            None => Ok(Value::Nothing),
        }
    }

    fn worksheet_index(&mut self, args: &[Value]) -> Result<Value, String> {
        let (array, row, column) = match args {
            [array, row] => (array, row, None),
            [array, row, column] => (array, row, Some(column)),
            _ => return Err("WorksheetFunction.Index expects two or three arguments".to_string()),
        };
        let row = index_argument(row, "row")?;
        let column = match column {
            None | Some(Value::Missing) => None,
            Some(column) => Some(index_argument(column, "column")?),
        };

        if let Value::Object(object) = array {
            if let Some(range) = self.range(object) {
                let rows = (range.end_row - range.start_row + 1) as usize;
                let columns = (range.end_column - range.start_column + 1) as usize;
                let (row, column) = index_selection(rows, columns, row, column, true)?;
                let selected = CellRange {
                    sheet: range.sheet,
                    start_row: range.start_row + row.saturating_sub(1) as u32,
                    end_row: if row == 0 {
                        range.end_row
                    } else {
                        range.start_row + row as u32 - 1
                    },
                    start_column: range.start_column + column.saturating_sub(1) as u32,
                    end_column: if column == 0 {
                        range.end_column
                    } else {
                        range.start_column + column as u32 - 1
                    },
                };
                return Ok(self.object(HostObject::Range(selected)));
            }
        }

        let table = self.lookup_table(array, "Index")?;
        let (row, column) = index_selection(table.rows, table.columns, row, column, false)?;
        let (first_row, last_row) = if row == 0 {
            (0, table.rows)
        } else {
            (row - 1, row)
        };
        let (first_column, last_column) = if column == 0 {
            (0, table.columns)
        } else {
            (column - 1, column)
        };
        let mut values = Vec::new();
        for row in first_row..last_row {
            for column in first_column..last_column {
                values.push(table.get(row, column));
            }
        }
        if values.len() == 1 {
            return Ok(values.remove(0));
        }
        let selected_rows = last_row - first_row;
        let selected_columns = last_column - first_column;
        let dimensions = if selected_rows > 1 && selected_columns > 1 {
            vec![
                ArrayDimension {
                    lower_bound: 1,
                    length: selected_rows,
                },
                ArrayDimension {
                    lower_bound: 1,
                    length: selected_columns,
                },
            ]
        } else {
            vec![ArrayDimension {
                lower_bound: 1,
                length: values.len(),
            }]
        };
        Ok(Value::Array(ArrayValue {
            dimensions,
            values,
            element_default: Box::new(Value::Empty),
            resizable: true,
        }))
    }

    fn worksheet_match(&self, args: &[Value]) -> Result<Value, String> {
        let (needle, array) = match args {
            [needle, array] | [needle, array, _] => (needle, array),
            _ => return Err("WorksheetFunction.Match expects two or three arguments".to_string()),
        };
        let match_type = match_type_argument(args.get(2))?;
        let table = self.lookup_table(array, "Match")?;
        if table.rows > 1 && table.columns > 1 {
            return Err(
                "WorksheetFunction.Match needs a single row or column to search".to_string(),
            );
        }
        let count = table.rows * table.columns;
        let value_at = |index: usize| table.get(index / table.columns, index % table.columns);
        let position = if match_type == 0 {
            (0..count)
                .find(|index| lookup_exact_matches(&value_at(*index), needle))
                .map(|index| index + 1)
        } else {
            sorted_lookup_position(count, match_type < 0, value_at, needle)
        };
        Ok(position
            .map(|position| Value::Integer(position as i64))
            .unwrap_or(Value::Error(ERROR_NA)))
    }

    /// The worksheet functions that read their arguments by position rather than
    /// aggregating everything handed to them.
    ///
    /// `Round` here is the worksheet's, which sends a half away from zero, so
    /// 2.5 becomes 3 and -2.5 becomes -3. VBA's own `Round` sends a half to the
    /// even neighbour instead and leaves 2.5 at 2; both are right, in their own
    /// language.
    fn worksheet_arithmetic(
        &self,
        name: &str,
        args: &[Value],
    ) -> Result<Option<Value>, String> {
        let rounding = ["round", "roundup", "rounddown"]
            .iter()
            .find(|candidate| name.eq_ignore_ascii_case(candidate));
        if let Some(rounding) = rounding {
            let (value, digits) = match args {
                [value] => (value, None),
                [value, digits] => (value, Some(digits)),
                _ => return Err(format!("WorksheetFunction.{name} expects a number and digits")),
            };
            let value = worksheet_number(value, name)?;
            let digits = match digits {
                None | Some(Value::Missing) => 0.0,
                Some(digits) => worksheet_number(digits, name)?.trunc(),
            };
            let scale = 10_f64.powf(digits);
            let scaled = value * scale;
            let rounded = match *rounding {
                "roundup" => scaled.abs().ceil() * scaled.signum(),
                "rounddown" => scaled.abs().floor() * scaled.signum(),
                _ => scaled.abs().round() * scaled.signum(),
            };
            return Ok(Some(numeric_result(rounded / scale)));
        }

        if name.eq_ignore_ascii_case("text") {
            let [value, format] = args else {
                return Err("WorksheetFunction.Text expects a value and a format".to_string());
            };
            let Value::String(format) = format else {
                return Err("WorksheetFunction.Text expects a format as text".to_string());
            };
            return Ok(Some(Value::String(shown_text(
                &self.criteria_value(value)?,
                Some(format),
            ))));
        }
        // The ranking family, which reads only the numbers: asked of Excel,
        // text, blanks and Booleans in the block are passed over, so
        // `Large` of 10, 30, 20, "text", blank, TRUE, 30 answers 30, 30, 20,
        // 10 and then refuses.
        let ranking = ["large", "small"]
            .iter()
            .find(|candidate| name.eq_ignore_ascii_case(candidate));
        if let Some(ranking) = ranking {
            let [block, wanted] = args else {
                return Err(format!(
                    "WorksheetFunction.{name} expects a block and which one to take"
                ));
            };
            let mut numbers = self.worksheet_numbers(block, name)?;
            // A fraction is cut down, not rounded: Excel answers the same for
            // 1.7 as for 1.
            let wanted = worksheet_number(wanted, name)?.trunc();
            numbers.sort_by(|one, other| one.partial_cmp(other).unwrap_or(Ordering::Equal));
            if *ranking == "large" {
                numbers.reverse();
            }
            let at = wanted - 1.0;
            if at < 0.0 || at >= numbers.len() as f64 {
                return Ok(Some(Value::Error(ERROR_NUM)));
            }
            return Ok(Some(numeric_result(numbers[at as usize])));
        }

        if name.eq_ignore_ascii_case("rank") {
            let (value, block, order) = match args {
                [value, block] => (value, block, None),
                [value, block, order] => (value, block, Some(order)),
                _ => return Err("WorksheetFunction.Rank expects a number and a block".to_string()),
            };
            let value = worksheet_number(value, name)?;
            let numbers = self.worksheet_numbers(block, name)?;
            if !numbers.iter().any(|held| *held == value) {
                return Err("WorksheetFunction.Rank cannot find that number".to_string());
            }
            let ascending = match order {
                None | Some(Value::Missing) => false,
                Some(order) => worksheet_number(order, name)? != 0.0,
            };
            // Equal numbers share the higher place and the next one is skipped:
            // asked of Excel, 30, 30, 20, 10 ranks 20 third, not second.
            let ahead = numbers
                .iter()
                .filter(|held| {
                    if ascending {
                        **held < value
                    } else {
                        **held > value
                    }
                })
                .count();
            return Ok(Some(Value::Integer(ahead as i64 + 1)));
        }

        // How far the numbers lie from their own middle. The plain names are
        // the SAMPLE, dividing by one less than the count; the `_P` ones take
        // the numbers as the whole population.
        let spread = [
            ("stdev", true, false),
            ("stdev_p", false, false),
            ("stdevp", false, false),
            ("var", true, true),
            ("var_p", false, true),
            ("varp", false, true),
        ]
        .into_iter()
        .find(|(candidate, _, _)| name.eq_ignore_ascii_case(candidate));
        if let Some((_, sample, squared)) = spread {
            let mut numbers = Vec::new();
            for value in args {
                numbers.extend(self.worksheet_numbers(value, name)?);
            }
            let count = numbers.len();
            if count == 0 || (sample && count < 2) {
                return Ok(Some(Value::Error(ERROR_DIV_ZERO)));
            }
            let middle = numbers.iter().sum::<f64>() / count as f64;
            let apart = numbers
                .iter()
                .map(|held| (held - middle) * (held - middle))
                .sum::<f64>();
            let over = if sample { count - 1 } else { count } as f64;
            let variance = apart / over;
            return Ok(Some(numeric_result(if squared {
                variance
            } else {
                variance.sqrt()
            })));
        }

        if name.eq_ignore_ascii_case("power") {
            let [base, exponent] = args else {
                return Err("WorksheetFunction.Power expects a number and a power".to_string());
            };
            let result = worksheet_number(base, name)?.powf(worksheet_number(exponent, name)?);
            if !result.is_finite() {
                return Err("WorksheetFunction.Power has no answer for those".to_string());
            }
            return Ok(Some(numeric_result(result)));
        }

        if name.eq_ignore_ascii_case("trim") {
            let [value] = args else {
                return Err("WorksheetFunction.Trim expects one value".to_string());
            };
            // The worksheet's Trim squeezes runs of spaces as well as stripping
            // the ends, where VBA's only strips the ends.
            let text = find_value_text(&self.criteria_value(value)?);
            return Ok(Some(Value::String(
                text.split_whitespace().collect::<Vec<_>>().join(" "),
            )));
        }

        if name.eq_ignore_ascii_case("proper") {
            let [value] = args else {
                return Err("WorksheetFunction.Proper expects one value".to_string());
            };
            let text = find_value_text(&self.criteria_value(value)?);
            let mut proper = String::with_capacity(text.len());
            let mut starting = true;
            for character in text.chars() {
                if starting {
                    proper.extend(character.to_uppercase());
                } else {
                    proper.extend(character.to_lowercase());
                }
                // Anything that is not a letter starts a new word, so an
                // apostrophe or a digit capitalises what follows it.
                starting = !character.is_alphabetic();
            }
            return Ok(Some(Value::String(proper)));
        }

        let ranking = ["large", "small"]
            .iter()
            .find(|candidate| name.eq_ignore_ascii_case(candidate));
        if let Some(ranking) = ranking {
            let [values, rank] = args else {
                return Err(format!("WorksheetFunction.{name} expects values and a rank"));
            };
            let rank = worksheet_number(rank, name)?.trunc();
            let mut numbers = self.worksheet_numbers(values, name)?;
            if rank < 1.0 || rank > numbers.len() as f64 {
                return Err(format!(
                    "WorksheetFunction.{name} has no value ranked {rank}"
                ));
            }
            numbers.sort_by(|left, right| left.partial_cmp(right).unwrap_or(Ordering::Equal));
            let index = if *ranking == "large" {
                numbers.len() - rank as usize
            } else {
                rank as usize - 1
            };
            return Ok(Some(numeric_result(numbers[index])));
        }

        if name.eq_ignore_ascii_case("median") {
            let mut numbers = Vec::new();
            for value in args {
                numbers.append(&mut self.worksheet_numbers(value, name)?);
            }
            if numbers.is_empty() {
                return Ok(Some(Value::Error(ERROR_NUM)));
            }
            numbers.sort_by(|left, right| left.partial_cmp(right).unwrap_or(Ordering::Equal));
            let middle = numbers.len() / 2;
            let median = if numbers.len() % 2 == 0 {
                (numbers[middle - 1] + numbers[middle]) / 2.0
            } else {
                numbers[middle]
            };
            return Ok(Some(numeric_result(median)));
        }

        if name.eq_ignore_ascii_case("transpose") {
            let [value] = args else {
                return Err("WorksheetFunction.Transpose expects one range or array".to_string());
            };
            let table = self.lookup_table(value, name)?;
            // One cell comes back as the value itself, not as an array of one:
            // asked of Excel, `Transpose(Range("A1"))` answers a Double where
            // `Transpose(Range("A1:A3"))` answers an array.
            if table.rows == 1 && table.columns == 1 {
                return Ok(Some(table.get(0, 0)));
            }
            let mut values = Vec::with_capacity(table.rows * table.columns);
            for column in 0..table.columns {
                for row in 0..table.rows {
                    values.push(table.get(row, column));
                }
            }
            // Always based at one, whatever the array that went in was based
            // at. A one-dimensional array counts as a ROW, so
            // `Transpose(Array(1, 2, 3))` comes back three rows by one column
            // -- which is what lets a macro write a list down a column in a
            // single assignment -- and a result that is one row comes back
            // ONE-dimensional: measured, `Transpose(Range("A1:A3"))` has
            // `LBound` 1, `UBound` 3 and answers `v(3)`, and transposing that
            // again gives (3, 1).
            let dimensions = if table.columns == 1 {
                vec![ArrayDimension { lower_bound: 1, length: table.rows }]
            } else {
                vec![
                    ArrayDimension { lower_bound: 1, length: table.columns },
                    ArrayDimension { lower_bound: 1, length: table.rows },
                ]
            };
            return Ok(Some(Value::Array(ArrayValue {
                dimensions,
                values,
                element_default: Box::new(Value::Empty),
                resizable: true,
            })));
        }

        if name.eq_ignore_ascii_case("sumproduct") {
            if args.len() < 2 {
                return Err("WorksheetFunction.SumProduct expects two or more ranges".to_string());
            }
            let columns = args
                .iter()
                .map(|value| self.worksheet_numbers(value, name))
                .collect::<Result<Vec<_>, _>>()?;
            let length = columns[0].len();
            if columns.iter().any(|column| column.len() != length) {
                return Err(
                    "WorksheetFunction.SumProduct needs ranges of the same size".to_string(),
                );
            }
            let total = (0..length)
                .map(|index| columns.iter().map(|column| column[index]).product::<f64>())
                .sum::<f64>();
            return Ok(Some(numeric_result(total)));
        }

        Ok(None)
    }

    /// The numbers inside a range or array, with text and blanks passed over
    /// the way the ranking functions do.
    fn worksheet_numbers(&self, value: &Value, name: &str) -> Result<Vec<f64>, String> {
        let mut values = Vec::new();
        self.append_worksheet_function_values(value, &mut values)
            .map_err(|_| format!("WorksheetFunction.{name} cannot read those values"))?;
        Ok(values.iter().filter_map(criteria_number).collect())
    }

    /// A worksheet function asked for through `WorksheetFunction`, which
    /// RAISES where the sheet itself would show an error.
    ///
    /// Measured in Excel 16.0, the same eleven failures both ways: a lookup
    /// that misses, an index past the end of its table, an average of nothing,
    /// a sum of text. `Application.VLookup` hands each back as an error value
    /// — 2042, 2023, 2007, 2015 — and `WorksheetFunction.VLookup` raises on
    /// every one of them. So the work is done once and this is where the
    /// answer is turned into a raise.
    fn worksheet_function(&mut self, name: &str, args: &[Value]) -> Result<Value, String> {
        match self.worksheet_function_value(name, args)? {
            Value::Error(number) => Err(format!(
                "WorksheetFunction.{name} answers {}",
                spreadsheet_error_text(number)
            )),
            answer => Ok(answer),
        }
    }

    /// The same function, answering the way the sheet would: a failure comes
    /// back as the error value a cell would show.
    /// A worksheet function's answer. Every number is a Double: measured,
    /// `TypeName` of `WorksheetFunction.Sum(1, 2)`, `CountA`, `Count`,
    /// `Match`, `Max`, `Round`, `CountIf`, `Power` and `Large` are all
    /// Double, where `Text` is a String, `IsNumber` a Boolean and `Index` of
    /// a range a Range.
    fn worksheet_function_value(
        &mut self,
        name: &str,
        args: &[Value],
    ) -> Result<Value, String> {
        Ok(match self.worksheet_function_raw(name, args)? {
            Value::Integer(number) => Value::Double(number as f64),
            other => other,
        })
    }

    fn worksheet_function_raw(
        &mut self,
        name: &str,
        args: &[Value],
    ) -> Result<Value, String> {
        if args.is_empty() {
            return Err(format!(
                "WorksheetFunction.{name} expects at least one argument"
            ));
        }
        // What it is about to work over may be a formula the macro has only
        // just written, and Excel would have settled that before answering.
        // This sits at the one door every function comes through, native and
        // engine-carried alike.
        self.settle_arguments(args);
        if name.eq_ignore_ascii_case("vlookup") {
            return self.worksheet_lookup(name, args, LookupOrientation::Vertical);
        }
        if name.eq_ignore_ascii_case("hlookup") {
            return self.worksheet_lookup(name, args, LookupOrientation::Horizontal);
        }
        if name.eq_ignore_ascii_case("match") {
            return self.worksheet_match(args);
        }
        if name.eq_ignore_ascii_case("index") {
            return self.worksheet_index(args);
        }
        if let Some(result) = self.worksheet_arithmetic(name, args)? {
            return Ok(result);
        }
        for (conditional, kind) in [
            ("countif", ConditionalKind::Count),
            ("sumif", ConditionalKind::Sum),
            ("averageif", ConditionalKind::Average),
        ] {
            if name.eq_ignore_ascii_case(conditional) {
                return self.worksheet_conditional(name, args, kind);
            }
            if name.len() == conditional.len() + 1
                && name[..conditional.len()].eq_ignore_ascii_case(conditional)
                && name.ends_with(['s', 'S'])
            {
                return self.worksheet_conditional_set(name, args, kind);
            }
        }
        let mut values = Vec::new();
        for value in args {
            self.append_worksheet_function_values(value, &mut values)?;
        }
        if name.eq_ignore_ascii_case("counta") {
            let count = values
                .iter()
                .filter(|value| {
                    !matches!(
                        value,
                        Value::Empty | Value::Missing | Value::Nothing | Value::Null
                    )
                })
                .count();
            return Ok(Value::Integer(count as i64));
        }
        if name.eq_ignore_ascii_case("countblank") {
            // The other side of CountA, and it counts only what is really
            // empty: asked of Excel, text and a Boolean are not blank.
            let count = values
                .iter()
                .filter(|value| {
                    matches!(
                        value,
                        Value::Empty | Value::Missing | Value::Nothing | Value::Null
                    )
                })
                .count();
            return Ok(Value::Integer(count as i64));
        }

        if name.eq_ignore_ascii_case("count") {
            // Count is one of the functions that IGNORES an error rather than
            // passing it on. Asked of Excel over cells holding 10, text, a
            // blank, 20 and #N/A: `Count` answers 2 where `Sum` over the very
            // same cells raises, and a sheet agrees -- `=COUNT` shows 2 where
            // `=SUM` shows #N/A. It counts numbers, so the text is not counted
            // either.
            let count = values
                .iter()
                .filter(|value| {
                    matches!(value, Value::Integer(_))
                        || matches!(value, Value::Double(value) if value.is_finite())
                })
                .count();
            return Ok(Value::Integer(count as i64));
        }

        // Everything past here adds the numbers up rather than counting them,
        // and those all pass an error on: Sum, Average, Min, Max, Product,
        // Median, Large, Small and StDev were each asked, and each raised.
        let mut numbers = Vec::new();
        for value in values {
            match value {
                value if any_number(&value).is_some() => numbers.push(any_number(&value).unwrap_or_default()),
                Value::Error(value) => {
                    return Err(format!(
                        "WorksheetFunction.{name} encountered Error {value}"
                    ));
                }
                _ => {}
            }
        }

        let result = if name.eq_ignore_ascii_case("sum") {
            numbers.iter().sum()
        } else if name.eq_ignore_ascii_case("average") {
            if numbers.is_empty() {
                return Ok(Value::Error(ERROR_DIV_ZERO));
            }
            numbers.iter().sum::<f64>() / numbers.len() as f64
        } else if name.eq_ignore_ascii_case("min") {
            numbers.into_iter().reduce(f64::min).unwrap_or(0.0)
        } else if name.eq_ignore_ascii_case("max") {
            numbers.into_iter().reduce(f64::max).unwrap_or(0.0)
        } else {
            return self.worksheet_function_from_engine(name, args);
        };
        Ok(numeric_result(result))
    }

    /// What a cell shows, with its number format applied.
    ///
    /// Excel answers Null for a range covering more than one cell, since there
    /// is no single text to give. Text cannot be written to; it only reports.
    /// What a person would see in the cell.
    ///
    /// A range of more than one cell answers Null only where the cells SHOW
    /// different things — two cells both holding 5 answer "5", the same
    /// uniform-or-Null convention Bold and NumberFormat follow. Asked of
    /// Excel, which returns DBNull for a pair showing different strings and
    /// the string itself for a pair showing the same one.
    ///
    /// One case this cannot answer: Excel shows `##` where a column is too
    /// narrow for the number in it, and says so through `.Text` as well. That
    /// needs the width of the rendered digits, which this side has no way to
    /// measure. Everything else — formats, dates, Booleans, errors, blanks —
    /// is the string Excel gives.
    fn range_text(&self, range: CellRange) -> Value {
        let mut seen: Option<String> = None;
        for address in range.addresses() {
            let shown = match self.workbook.sheets[address.sheet]
                .rows
                .iter()
                .find(|row| row.index == address.row)
                .and_then(|row| row.cells.iter().find(|cell| cell.col == address.column))
            {
                Some(cell) => shown_text(
                    &from_cell_value(&cell.value),
                    cell.style.number_format.as_deref(),
                ),
                None => String::new(),
            };
            match &seen {
                None => seen = Some(shown),
                Some(held) if *held == shown => {}
                Some(_) => return Value::Null,
            }
        }
        Value::String(seen.unwrap_or_default())
    }

    /// What a cell would show in the formula bar.
    ///
    /// A cell with no formula answers with its VALUE as text — not with the
    /// empty string, and not with the formatted text either. Asked of Excel:
    /// 1234.5 under `#,##0.00` answers `1234.5`, 0.15 under `0%` answers
    /// `0.15`, a date serial answers `45000`, a Boolean answers `TRUE`, and
    /// 1e20 answers all twenty-one digits where the General format would show
    /// it in exponent form. So this is the raw value written out, which is a
    /// different question from `.Text`.
    fn cell_formula(&self, address: CellAddress) -> Value {
        let Some(cell) = self
            .workbook
            .sheets
            .get(address.sheet)
            .and_then(|sheet| sheet.rows.iter().find(|row| row.index == address.row))
            .and_then(|row| row.cells.iter().find(|cell| cell.col == address.column))
        else {
            return Value::String(String::new());
        };
        if let Some(formula) = cell.formula.as_deref() {
            // Inside a table, a formula naming that table reads without the
            // name: measured, the totals row reads `=SUBTOTAL(103,[Note])`.
            let formula = match self.table_holding(address) {
                Some((sheet, index)) => {
                    let name = &self.workbook.sheets[sheet].tables[index].name;
                    formula.replace(&format!("{name}["), "[")
                }
                None => formula.to_string(),
            };
            return Value::String(format!("={formula}"));
        }
        Value::String(match from_cell_value(&cell.value) {
            Value::Empty | Value::Missing | Value::Null | Value::Nothing => String::new(),
            Value::String(held) => held,
            Value::Boolean(held) => {
                if held { "TRUE".to_string() } else { "FALSE".to_string() }
            }
            Value::Integer(held) => held.to_string(),
            Value::Double(held) => excel_number_text(held, FORMULA_TEXT_WIDTH),
            // Asked of Excel, a cell holding #N/A answers `#N/A` for its
            // formula, not a description of an error.
            Value::Error(held) => spreadsheet_error_text(held).to_string(),
            held => shown_text(&held, None),
        })
    }

    /// The same, said from where the formula sits.
    ///
    /// Only a cell that really holds a formula is rewritten. A cell holding the
    /// TEXT `=A1*3` — which is what a leading apostrophe leaves — answers with
    /// that text unchanged, as it does through `.Formula`.
    fn cell_formula_r1c1(&self, address: CellAddress) -> Result<Value, String> {
        let holds_formula = self
            .workbook
            .sheets
            .get(address.sheet)
            .and_then(|sheet| sheet.rows.iter().find(|row| row.index == address.row))
            .and_then(|row| row.cells.iter().find(|cell| cell.col == address.column))
            .is_some_and(|cell| cell.formula.is_some());
        match self.cell_formula(address) {
            Value::String(written) if holds_formula => formula_to_r1c1(
                &written,
                address.row.saturating_sub(1),
                address.column,
            )
            .map(Value::String),
            other => Ok(other),
        }
    }

    fn range_formula(&self, range: CellRange, style: FormulaStyle) -> Result<Value, String> {
        Self::range_cell_count(range)?;
        let written = |address| match style {
            FormulaStyle::A1 => Ok(self.cell_formula(address)),
            FormulaStyle::R1C1 => self.cell_formula_r1c1(address),
        };
        if range.is_single() {
            return written(range.addresses().next().unwrap());
        }
        Ok(Value::Array(ArrayValue {
            dimensions: vec![
                ArrayDimension {
                    lower_bound: 1,
                    length: (range.end_row - range.start_row + 1) as usize,
                },
                ArrayDimension {
                    lower_bound: 1,
                    length: (range.end_column - range.start_column + 1) as usize,
                },
            ],
            values: range
                .addresses()
                .map(written)
                .collect::<Result<Vec<_>, _>>()?,
            element_default: Box::new(Value::String(String::new())),
            resizable: true,
        }))
    }

    fn range_has_formula(&self, range: CellRange) -> Result<Value, String> {
        let total = Self::range_cell_count_large(range)?;
        let sheet = self
            .workbook
            .sheets
            .get(range.sheet)
            .ok_or_else(|| "worksheet no longer exists".to_string())?;
        let formulas = sheet
            .rows
            .iter()
            .filter(|row| (range.start_row..=range.end_row).contains(&row.index))
            .flat_map(|row| &row.cells)
            .filter(|cell| {
                (range.start_column..=range.end_column).contains(&cell.col)
                    && cell.formula.is_some()
            })
            .count() as u64;
        Ok(if formulas == 0 {
            Value::Boolean(false)
        } else if formulas == total {
            Value::Boolean(true)
        } else {
            Value::Null
        })
    }

    fn range_end(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        let [direction] = args else {
            return Err("Range.End expects one direction".to_string());
        };
        let direction = end_direction(direction)?;
        let worksheet = self
            .workbook
            .sheets
            .get(range.sheet)
            .ok_or_else(|| "worksheet no longer exists".to_string())?;
        let start = CellAddress {
            sheet: range.sheet,
            row: range.start_row,
            column: range.start_column,
        };
        let destination = match direction {
            EndDirection::Up | EndDirection::Down => {
                let mut occupied = worksheet
                    .rows
                    .iter()
                    .filter(|row| {
                        row.cells
                            .iter()
                            .any(|cell| cell.col == start.column && cell_has_content(cell))
                    })
                    .map(|row| row.index)
                    .collect::<Vec<_>>();
                occupied.sort_unstable();
                occupied.dedup();
                CellAddress {
                    row: ctrl_arrow_destination(
                        &occupied,
                        start.row,
                        1,
                        MAX_WORKSHEET_ROW,
                        matches!(direction, EndDirection::Down),
                    ),
                    ..start
                }
            }
            EndDirection::Left | EndDirection::Right => {
                let mut occupied = worksheet
                    .rows
                    .iter()
                    .find(|row| row.index == start.row)
                    .map(|row| {
                        row.cells
                            .iter()
                            .filter(|cell| cell_has_content(cell))
                            .map(|cell| cell.col)
                            .collect::<Vec<_>>()
                    })
                    .unwrap_or_default();
                occupied.sort_unstable();
                occupied.dedup();
                CellAddress {
                    column: ctrl_arrow_destination(
                        &occupied,
                        start.column,
                        0,
                        MAX_WORKSHEET_COLUMN,
                        matches!(direction, EndDirection::Right),
                    ),
                    ..start
                }
            }
        };
        Ok(self.object(HostObject::Range(CellRange::single(destination))))
    }

    fn find_in_range(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        if args.is_empty() || args.len() > 9 {
            return Err("Range.Find expects between one and nine arguments".to_string());
        }
        // A range of one cell is not a search of one cell: Excel takes it to
        // mean the whole sheet. Asked of Excel, `Range("A2").Find("far")`
        // answers `$C$5`, three columns away — which is why the usual way to
        // write this, `Cells.Find(...)`, works at all. The written cells are
        // as far as it can matter, and walking the sheet's full million would
        // spend the execution budget on empty ground.
        let range = if range.is_single() {
            self.used_range(range.sheet)?
        } else {
            range
        };
        Self::sized(range)?;
        let what = args
            .first()
            .filter(|value| !matches!(value, Value::Missing))
            .ok_or_else(|| "Range.Find What argument is required".to_string())?;
        let look_in = find_integer_argument(args.get(2), -4163, "LookIn")?;
        if !matches!(look_in, -4163 | -4123) {
            return Err(format!("unsupported Range.Find LookIn constant: {look_in}"));
        }
        let look_at = find_integer_argument(args.get(3), 2, "LookAt")?;
        if !matches!(look_at, 1 | 2) {
            return Err(format!("unsupported Range.Find LookAt constant: {look_at}"));
        }
        let search_order = find_integer_argument(args.get(4), 1, "SearchOrder")?;
        if !matches!(search_order, 1 | 2) {
            return Err(format!(
                "unsupported Range.Find SearchOrder constant: {search_order}"
            ));
        }
        let search_direction = find_integer_argument(args.get(5), 1, "SearchDirection")?;
        if !matches!(search_direction, 1 | 2) {
            return Err(format!(
                "unsupported Range.Find SearchDirection constant: {search_direction}"
            ));
        }
        let match_case = find_boolean_argument(args.get(6), false, "MatchCase")?;
        let match_byte = find_boolean_argument(args.get(7), false, "MatchByte")?;
        if find_boolean_argument(args.get(8), false, "SearchFormat")? {
            return Err(
                "Range.Find SearchFormat:=True is not supported in the browser".to_string(),
            );
        }

        let mut addresses = if search_order == 1 {
            range.addresses().collect::<Vec<_>>()
        } else {
            let mut addresses = Vec::with_capacity(Self::range_cell_count(range)?);
            for column in range.start_column..=range.end_column {
                for row in range.start_row..=range.end_row {
                    addresses.push(CellAddress {
                        sheet: range.sheet,
                        row,
                        column,
                    });
                }
            }
            addresses
        };
        let after = match args.get(1) {
            None | Some(Value::Missing) => addresses[0],
            Some(Value::Object(object)) => {
                let after = self
                    .range(object)
                    .filter(|range| range.is_single())
                    .ok_or_else(|| "Range.Find After must be a single cell".to_string())?;
                let address = after.addresses().next().unwrap();
                if !addresses.contains(&address) {
                    return Err("Range.Find After cell must be inside the search range".to_string());
                }
                address
            }
            _ => return Err("Range.Find After must be a single cell".to_string()),
        };
        let after_index = addresses
            .iter()
            .position(|address| *address == after)
            .unwrap();
        if search_direction == 1 {
            let address_count = addresses.len();
            addresses.rotate_left((after_index + 1) % address_count);
        } else {
            addresses.rotate_left(after_index);
            addresses.reverse();
        }
        let needle = find_value_text(what);
        let found = addresses.into_iter().find(|address| {
            let candidate = self.find_cell_text(*address, look_in);
            find_text_matches(&candidate, &needle, look_at == 1, match_case, match_byte)
        });
        let result = found
            .map(|address| self.object(HostObject::Range(CellRange::single(address))))
            .unwrap_or(Value::Nothing);
        self.last_find = Some(FindState {
            range,
            args: args.to_vec(),
            last_found: found,
        });
        Ok(result)
    }

    fn find_again(&mut self, args: &[Value], search_direction: i64) -> Result<Value, String> {
        if args.len() > 1 {
            return Err("Range.FindNext and FindPrevious expect zero or one argument".to_string());
        }
        let state = self
            .last_find
            .clone()
            .ok_or_else(|| "Range.FindNext requires a preceding Range.Find call".to_string())?;
        let after = match args.first() {
            Some(Value::Object(object)) => Value::Object(object.clone()),
            Some(_) => {
                return Err(
                    "Range.FindNext and FindPrevious After must be a single cell".to_string(),
                )
            }
            None => match state.last_found {
                Some(address) => self.object(HostObject::Range(CellRange::single(address))),
                None => return Ok(Value::Nothing),
            },
        };
        let mut find_args = state.args;
        find_args.resize(6, Value::Missing);
        find_args[1] = after;
        find_args[5] = Value::Integer(search_direction);
        self.find_in_range(state.range, &find_args)
    }

    fn find_cell_text(&self, address: CellAddress, look_in: i64) -> String {
        if look_in == -4123 {
            if let Some(formula) = self
                .workbook
                .sheets
                .get(address.sheet)
                .and_then(|sheet| sheet.rows.iter().find(|row| row.index == address.row))
                .and_then(|row| row.cells.iter().find(|cell| cell.col == address.column))
                .and_then(|cell| cell.formula.as_deref())
            {
                return format!("={formula}");
            }
        }
        find_value_text(&self.cell_value(address))
    }

    fn replace_in_range(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        if !(2..=8).contains(&args.len()) {
            return Err("Range.Replace expects between two and eight arguments".to_string());
        }
        Self::sized(range)?;
        let what = args
            .first()
            .filter(|value| !matches!(value, Value::Missing))
            .ok_or_else(|| "Range.Replace What argument is required".to_string())?;
        let replacement = args
            .get(1)
            .filter(|value| !matches!(value, Value::Missing))
            .ok_or_else(|| "Range.Replace Replacement argument is required".to_string())?;
        let look_at = find_integer_argument(args.get(2), 2, "LookAt")?;
        if !matches!(look_at, 1 | 2) {
            return Err(format!(
                "unsupported Range.Replace LookAt constant: {look_at}"
            ));
        }
        let search_order = find_integer_argument(args.get(3), 1, "SearchOrder")?;
        if !matches!(search_order, 1 | 2) {
            return Err(format!(
                "unsupported Range.Replace SearchOrder constant: {search_order}"
            ));
        }
        let match_case = find_boolean_argument(args.get(4), false, "MatchCase")?;
        let match_byte = find_boolean_argument(args.get(5), false, "MatchByte")?;
        if find_boolean_argument(args.get(6), false, "SearchFormat")? {
            return Err(
                "Range.Replace SearchFormat:=True is not supported in the browser".to_string(),
            );
        }
        if find_boolean_argument(args.get(7), false, "ReplaceFormat")? {
            return Err(
                "Range.Replace ReplaceFormat:=True is not supported in the browser".to_string(),
            );
        }

        let needle = find_value_text(what);
        let replacement_text = find_value_text(replacement);
        // Measured: `Replace` on a protected sheet changes nothing and raises
        // nothing -- not even in cells that are unlocked, and not even when
        // every cell of the range is.
        if self.cell_protection(range.sheet).is_some() {
            return Ok(Value::Boolean(false));
        }
        let mut changed = false;
        for address in self.touched(range) {
            let formula = self
                .workbook
                .sheets
                .get(address.sheet)
                .and_then(|sheet| sheet.rows.iter().find(|row| row.index == address.row))
                .and_then(|row| row.cells.iter().find(|cell| cell.col == address.column))
                .and_then(|cell| cell.formula.as_deref())
                .map(|formula| format!("={formula}"));
            let candidate = formula
                .clone()
                .unwrap_or_else(|| find_value_text(&self.cell_value(address)));
            let Some(replaced) = replace_matching_text(
                &candidate,
                &needle,
                &replacement_text,
                look_at == 1,
                match_case,
                match_byte,
            ) else {
                continue;
            };
            if formula.is_some() {
                if replaced.starts_with('=') {
                    self.set_cell_formula(address, replaced)?;
                } else {
                    self.set_cell_value(address, CellValue::String(replaced))?;
                }
            } else if look_at == 1 {
                self.set_cell_value(address, to_cell_value(replacement.clone())?)?;
            } else {
                self.set_cell_value(address, CellValue::String(replaced))?;
            }
            changed = true;
        }
        Ok(Value::Boolean(changed))
    }

    fn current_region_object(&mut self, range: CellRange) -> Result<Value, String> {
        let region = self.current_region(range)?;
        Ok(self.object(HostObject::Range(region)))
    }

    fn current_region(&self, range: CellRange) -> Result<CellRange, String> {
        let worksheet = self
            .workbook
            .sheets
            .get(range.sheet)
            .ok_or_else(|| "worksheet no longer exists".to_string())?;
        let mut occupied_rows = BTreeMap::<u32, BTreeSet<u32>>::new();
        let mut occupied_columns = BTreeMap::<u32, BTreeSet<u32>>::new();
        for row in &worksheet.rows {
            for cell in row.cells.iter().filter(|cell| cell_has_content(cell)) {
                occupied_rows.entry(row.index).or_default().insert(cell.col);
                occupied_columns
                    .entry(cell.col)
                    .or_default()
                    .insert(row.index);
            }
        }
        let mut region = range;
        loop {
            let outer_start_row = region.start_row.saturating_sub(1).max(1);
            let outer_start_column = region.start_column.saturating_sub(1);
            let outer_end_row = region.end_row.saturating_add(1).min(MAX_WORKSHEET_ROW);
            let outer_end_column = region
                .end_column
                .saturating_add(1)
                .min(MAX_WORKSHEET_COLUMN);
            let row_has_content = |row, start_column, end_column| {
                occupied_rows.get(&row).is_some_and(|columns| {
                    columns.range(start_column..=end_column).next().is_some()
                })
            };
            let column_has_content = |column, start_row, end_row| {
                occupied_columns
                    .get(&column)
                    .is_some_and(|rows| rows.range(start_row..=end_row).next().is_some())
            };
            let expand_top = region.start_row > 1
                && row_has_content(region.start_row - 1, outer_start_column, outer_end_column);
            let expand_bottom = region.end_row < MAX_WORKSHEET_ROW
                && row_has_content(region.end_row + 1, outer_start_column, outer_end_column);
            let expand_left = region.start_column > 0
                && column_has_content(region.start_column - 1, outer_start_row, outer_end_row);
            let expand_right = region.end_column < MAX_WORKSHEET_COLUMN
                && column_has_content(region.end_column + 1, outer_start_row, outer_end_row);
            if !expand_top && !expand_bottom && !expand_left && !expand_right {
                break;
            }
            region.start_row -= u32::from(expand_top);
            region.end_row += u32::from(expand_bottom);
            region.start_column -= u32::from(expand_left);
            region.end_column += u32::from(expand_right);
        }
        Ok(region)
    }

    fn offset_range(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        let (row_offset, column_offset) = match args {
            [] => (0, 0),
            [row] => (optional_integer_offset(row, 0, "row")?, 0),
            [row, column] => (
                optional_integer_offset(row, 0, "row")?,
                optional_integer_offset(column, 0, "column")?,
            ),
            _ => return Err("Range.Offset expects zero, one, or two offsets".to_string()),
        };
        let shift = |value: u32, offset: i64, label: &str| {
            i64::from(value)
                .checked_add(offset)
                .and_then(|value| u32::try_from(value).ok())
                .ok_or_else(|| format!("Range.Offset moves the {label} outside the worksheet"))
        };
        let start_row = shift(range.start_row, row_offset, "row")?;
        let end_row = shift(range.end_row, row_offset, "row")?;
        let start_column = shift(range.start_column, column_offset, "column")?;
        let end_column = shift(range.end_column, column_offset, "column")?;
        // Both ends have to land ON the sheet. Asked of Excel,
        // `Range("XFD1").Offset(0, 1)` raises rather than answering with a
        // column that is not there.
        if start_row == 0 || end_row > MAX_WORKSHEET_ROW {
            return Err("Range.Offset moves the row outside the worksheet".to_string());
        }
        if end_column > MAX_WORKSHEET_COLUMN {
            return Err("Range.Offset moves the column outside the worksheet".to_string());
        }
        Ok(self.object(HostObject::Range(CellRange {
            sheet: range.sheet,
            start_row,
            start_column,
            end_row,
            end_column,
        })))
    }

    fn resize_range(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        let current_columns = range.end_column - range.start_column + 1;
        let (rows, columns) = match args {
            [] => (range.end_row - range.start_row + 1, current_columns),
            [rows] => (
                optional_positive_index(rows, range.end_row - range.start_row + 1, "row size")?,
                current_columns,
            ),
            [rows, columns] => (
                optional_positive_index(rows, range.end_row - range.start_row + 1, "row size")?,
                optional_positive_index(columns, current_columns, "column size")?,
            ),
            _ => return Err("Range.Resize expects zero, one, or two sizes".to_string()),
        };
        // The far end has to land ON the sheet: asked of Excel,
        // `Range("XFC1").Resize(1, 3)` raises rather than reaching past XFD.
        let end_row = range
            .start_row
            .checked_add(rows - 1)
            .filter(|row| *row <= MAX_WORKSHEET_ROW)
            .ok_or_else(|| "Range.Resize row size is too large".to_string())?;
        let end_column = range
            .start_column
            .checked_add(columns - 1)
            .filter(|column| *column <= MAX_WORKSHEET_COLUMN)
            .ok_or_else(|| "Range.Resize column size is too large".to_string())?;
        Ok(self.object(HostObject::Range(CellRange {
            sheet: range.sheet,
            start_row: range.start_row,
            start_column: range.start_column,
            end_row,
            end_column,
        })))
    }

    /// The protection standing between a macro and a sheet's CELLS, if any:
    /// none when the sheet is not protected, when it was protected with
    /// `Contents:=False`, or with `UserInterfaceOnly:=True`.
    fn cell_protection(&self, sheet: usize) -> Option<&Protection> {
        self.protected
            .get(sheet)?
            .as_ref()
            .filter(|held| held.contents && !held.user_interface_only)
    }

    /// Whether the sheet's notes are protected. `UserInterfaceOnly` does not
    /// lift this one, and neither does `Contents:=False`.
    fn objects_protected(&self, sheet: usize) -> bool {
        self.protected
            .get(sheet)
            .and_then(Option::as_ref)
            .is_some_and(|held| held.drawing_objects)
    }

    /// Whether a sheet is protected against writing this cell.
    ///
    /// Asked of Excel, after `ActiveSheet.Protect "pw"` writing a locked cell
    /// is error 1004 and the cell keeps its value, writing an UNLOCKED cell
    /// goes through, and reading either is fine.
    fn write_is_protected(&self, address: CellAddress) -> bool {
        self.cell_protection(address.sheet).is_some() && !self.unlocked.contains(&address)
    }

    /// Refuse the whole of an operation that touches a locked cell: Clear,
    /// ClearFormats and a paste are all-or-nothing -- measured, a paste onto
    /// a block with one locked cell writes none of the block.
    fn guard_locked_cells(&self, range: CellRange, doing: &str) -> Result<(), String> {
        if self.cell_protection(range.sheet).is_none() {
            return Ok(());
        }
        // A band has more cells than could ever have been unlocked one by
        // one, so a locked one is in it.
        let cells = Self::range_cell_count_large(range).unwrap_or(u64::MAX);
        let all_unlocked = cells <= self.unlocked.len() as u64
            && range.addresses().all(|address| !self.write_is_protected(address));
        if !all_unlocked {
            return Err(format!(
                "{doing} touches a locked cell on a protected sheet; unprotect it first"
            ));
        }
        Ok(())
    }

    /// Formatting is refused on EVERY cell of a protected sheet, locked or
    /// not, unless `AllowFormattingCells` was given.
    fn guard_formats(&self, sheet: usize, doing: &str) -> Result<(), String> {
        match self.cell_protection(sheet) {
            Some(held) if !held.allow_formatting_cells => Err(format!(
                "{doing} is not allowed on a protected sheet; unprotect it first"
            )),
            _ => Ok(()),
        }
    }

    fn guard_column_formats(&self, sheet: usize, doing: &str) -> Result<(), String> {
        match self.cell_protection(sheet) {
            Some(held) if !held.allow_formatting_columns => Err(format!(
                "{doing} is not allowed on a protected sheet; unprotect it first"
            )),
            _ => Ok(()),
        }
    }

    fn guard_row_formats(&self, sheet: usize, doing: &str) -> Result<(), String> {
        match self.cell_protection(sheet) {
            Some(held) if !held.allow_formatting_rows => Err(format!(
                "{doing} is not allowed on a protected sheet; unprotect it first"
            )),
            _ => Ok(()),
        }
    }

    /// Inserting and deleting each have their own Allow flag, per axis.
    fn guard_structure(&self, sheet: usize, sideways: bool, inserting: bool) -> Result<(), String> {
        let Some(held) = self.cell_protection(sheet) else {
            return Ok(());
        };
        let allowed = match (sideways, inserting) {
            (true, true) => held.allow_inserting_columns,
            (false, true) => held.allow_inserting_rows,
            (true, false) => held.allow_deleting_columns,
            (false, false) => held.allow_deleting_rows,
        };
        if allowed {
            return Ok(());
        }
        Err(format!(
            "{} {} is not allowed on a protected sheet; unprotect it first",
            if inserting { "inserting" } else { "deleting" },
            if sideways { "columns" } else { "rows" },
        ))
    }

    /// A sort is refused on a protected sheet even over unlocked cells, unless
    /// `AllowSorting` was given -- and then only over unlocked ones.
    fn guard_sort(&self, range: CellRange) -> Result<(), String> {
        let Some(held) = self.cell_protection(range.sheet) else {
            return Ok(());
        };
        if !held.allow_sorting {
            return Err("sorting is not allowed on a protected sheet; unprotect it first".to_string());
        }
        self.guard_locked_cells(range, "Range.Sort")
    }

    fn set_cell_value(&mut self, address: CellAddress, value: CellValue) -> Result<(), String> {
        if self.write_is_protected(address) {
            return Err(
                "the cell is locked and the sheet is protected; unprotect it first".to_string(),
            );
        }
        self.wrote = true;
        self.saved = false;
        let starting = self.template_style(address);
        let sheet = self
            .workbook
            .sheets
            .get_mut(address.sheet)
            .ok_or_else(|| "worksheet no longer exists".to_string())?;
        sheet.col_count = sheet.col_count.max(address.column as usize + 1);
        let row_position = sheet.rows.iter().position(|row| row.index == address.row);
        let row = match row_position {
            Some(position) => &mut sheet.rows[position],
            None => {
                sheet.rows.push(Row {
                    index: address.row,
                    cells: Vec::new(),
                    height: None,
                    custom_height: false,
                    style_font: None,
                    thick_top: false,
                    thick_bottom: false,
                    hidden: false,
                });
                sheet.rows.sort_by_key(|row| row.index);
                sheet
                    .rows
                    .iter_mut()
                    .find(|row| row.index == address.row)
                    .unwrap()
            }
        };
        match row.cells.iter_mut().find(|cell| cell.col == address.column) {
            Some(cell) => {
                cell.value = value;
                cell.formula = None;
                cell.array_block = None;
                cell.runs.clear();
            }
            None => {
                row.cells.push(Cell {
                    array_block: None,
                    col: address.column,
                    value,
                    style: starting,
                    formula: None,
                    runs: Vec::new(),
                });
                row.cells.sort_by_key(|cell| cell.col);
            }
        }
        Ok(())
    }

    /// Give a cell the way of showing itself that the writing asked for —
    /// but only while the cell is still General. Asked of Excel, writing `50%`
    /// into a cell already showing `0.000` stores 0.5 and leaves `0.000`.
    fn ask_cell_format(&mut self, address: CellAddress, shown: &str) {
        let Some(sheet) = self.workbook.sheets.get_mut(address.sheet) else {
            return;
        };
        let Some(row) = sheet.rows.iter_mut().find(|row| row.index == address.row) else {
            return;
        };
        let Some(cell) = row.cells.iter_mut().find(|cell| cell.col == address.column) else {
            return;
        };
        if cell.style.number_format.is_none() {
            cell.style.number_format = Some(shown.to_string());
        }
    }

    fn set_cell_formula(&mut self, address: CellAddress, formula: String) -> Result<(), String> {
        self.wrote = true;
        self.saved = false;
        let starting = self.template_style(address);
        let sheet = self
            .workbook
            .sheets
            .get_mut(address.sheet)
            .ok_or_else(|| "worksheet no longer exists".to_string())?;
        sheet.col_count = sheet.col_count.max(address.column as usize + 1);
        let row = match sheet.rows.iter().position(|row| row.index == address.row) {
            Some(position) => &mut sheet.rows[position],
            None => {
                sheet.rows.push(Row {
                    index: address.row,
                    cells: Vec::new(),
                    height: None,
                    custom_height: false,
                    style_font: None,
                    thick_top: false,
                    thick_bottom: false,
                    hidden: false,
                });
                sheet.rows.sort_by_key(|row| row.index);
                sheet
                    .rows
                    .iter_mut()
                    .find(|row| row.index == address.row)
                    .unwrap()
            }
        };
        let formula = formula.strip_prefix('=').unwrap_or(&formula).to_string();
        let formula = (!formula.is_empty()).then_some(formula);
        match row.cells.iter_mut().find(|cell| cell.col == address.column) {
            Some(cell) => {
                cell.value = CellValue::Empty;
                cell.formula = formula;
                cell.array_block = None;
                cell.runs.clear();
            }
            None => {
                row.cells.push(Cell {
                    array_block: None,
                    col: address.column,
                    value: CellValue::Empty,
                    style: starting,
                    formula,
                    runs: Vec::new(),
                });
                row.cells.sort_by_key(|cell| cell.col);
            }
        }
        Ok(())
    }

    /// Write what was assigned into every cell of a block.
    ///
    /// `.Value`, `.Value2`, `.Formula` and `.Formula2` all arrive here because
    /// Excel reads a string the same way through any of them: asked of it,
    /// `.Formula = "0123"` leaves the number 123 with `HasFormula` False,
    /// `.Formula = "TRUE"` leaves a Boolean and `.Formula = "'=B1"` keeps its
    /// text — exactly what `.Value` does with the same strings. Only a leading
    /// `=` with something after it makes a formula, and `"="` alone does not.
    ///
    /// What was assigned is itself a block: a single value is one cell, and an
    /// array is its own shape, a one-dimensional one being a single ROW. Excel
    /// lays that block on the top-left corner and then, asked what fills the
    /// rest:
    ///
    /// - A side the block has only ONE of is free, and repeats by filling —
    ///   relative references move, so `Array("=A1*7")` down five rows leaves
    ///   `=A1*7 … =A5*7`, and a number simply repeats.
    /// - A side the block has SEVERAL of is fixed. Where the block falls
    ///   short, the cells beyond it are left `#N/A`; where it overruns, the
    ///   extra entries are dropped.
    /// The block of the array formula a cell is a member of, if any.
    fn array_of(&self, at: CellAddress) -> Option<(u32, u32, u32, u32)> {
        self.workbook
            .sheets
            .get(at.sheet)?
            .rows
            .iter()
            .find(|row| row.index == at.row)?
            .cells
            .iter()
            .find(|cell| cell.col == at.column)?
            .array_block
    }

    /// Every array formula's block on a sheet, each once.
    fn arrays_on(&self, sheet: usize) -> Vec<(u32, u32, u32, u32)> {
        let mut blocks: Vec<(u32, u32, u32, u32)> = Vec::new();
        if let Some(held) = self.workbook.sheets.get(sheet) {
            for row in &held.rows {
                for cell in &row.cells {
                    if let Some(block) = cell.array_block {
                        if !blocks.contains(&block) {
                            blocks.push(block);
                        }
                    }
                }
            }
        }
        blocks
    }

    /// Whether a change to `range` would cut an array formula's block --
    /// which Excel refuses: "You cannot change part of an array". A block
    /// the range covers whole may be replaced. `Ok(false)` means the change
    /// is to be dropped without a word: measured, `Range("C1").Value = 9`
    /// on one cell of C1:C2 raises nothing and changes nothing, where
    /// `Range("C1").ClearContents` is 1004 -- so a single-cell WRITE is
    /// silent (`quiet`) and everything else raises.
    fn arrays_allow(&self, range: CellRange, quiet: bool) -> Result<bool, String> {
        for block in self.arrays_on(range.sheet) {
            let (top, left, bottom, right) = block;
            let crosses = top <= range.end_row
                && bottom >= range.start_row
                && left <= range.end_column
                && right >= range.start_column;
            if !crosses {
                continue;
            }
            let whole = top >= range.start_row
                && bottom <= range.end_row
                && left >= range.start_column
                && right <= range.end_column;
            if whole {
                continue;
            }
            if quiet && range.is_single() {
                return Ok(false);
            }
            return Err(host_error(1004, "You cannot change part of an array."));
        }
        Ok(true)
    }

    /// `Range.FormulaArray = "=…"`: one formula dealt across every cell of
    /// the range, worked out once as a block. Measured: `=A1:A2*2` across
    /// C1:C2 gives 2 and 4 and both cells answer `HasArray` True and the
    /// formula's text; `=7` across two cells is 7 and 7; a malformed
    /// formula is 1004.
    fn set_formula_array(&mut self, range: CellRange, value: Value) -> Result<(), String> {
        Self::range_cell_count(range)?;
        let Value::String(written) = &value else {
            return Err("Range.FormulaArray takes the formula as text".to_string());
        };
        let formula = match written.strip_prefix('=') {
            Some(rest) if !rest.is_empty() && !formula_is_malformed(rest) => written.clone(),
            _ => return Err(host_error(1004, "the array formula cannot be read")),
        };
        if !self.arrays_allow(range, false)? {
            return Ok(());
        }
        self.guard_locked_cells(range, "Range.FormulaArray")?;
        let block = (range.start_row, range.start_column, range.end_row, range.end_column);
        for address in range.addresses() {
            self.set_cell_formula(address, formula.clone())?;
            if let Some(cell) = self.cell_mut(address) {
                cell.array_block = Some(block);
            }
        }
        Ok(())
    }

    fn cell_mut(&mut self, address: CellAddress) -> Option<&mut Cell> {
        self.workbook
            .sheets
            .get_mut(address.sheet)?
            .rows
            .iter_mut()
            .find(|row| row.index == address.row)?
            .cells
            .iter_mut()
            .find(|cell| cell.col == address.column)
    }

    /// `Range.FormulaArray` read. Measured: one cell reads as `Formula`
    /// does (`1`, `""`, `=A1+1`); a block reads the array formula of the
    /// first cell in it that is in one, even when the block only partly
    /// covers the array (C1:D2 over C1:C2 reads `=A1:A2*2`); and a block
    /// with no array formula in it is Null, whether its formulas agree
    /// (`=A1+1` over `=A2+1`) or not.
    fn range_formula_array(&self, range: CellRange) -> Result<Value, String> {
        Self::range_cell_count(range)?;
        if range.is_single() {
            return Ok(self.cell_formula(range.first()));
        }
        match range.addresses().find(|at| self.array_of(*at).is_some()) {
            Some(member) => Ok(self.cell_formula(member)),
            None => Ok(Value::Null),
        }
    }

    fn set_range_input(
        &mut self,
        range: CellRange,
        value: Value,
        operation: &str,
        style: FormulaStyle,
    ) -> Result<(), String> {
        Self::range_cell_count(range)?;
        if !self.arrays_allow(range, true)? {
            return Ok(());
        }
        let block = InputBlock::of(value, operation)?;
        // A block with a locked cell in it is not refused whole: measured,
        // `Range("A4:A6").Value = 3` over locked A4 and A6 and unlocked A5
        // writes A5 and then raises 1004. So each unlocked cell is written and
        // the refusal comes at the end.
        let mut refused = false;
        let mut header_writes: Vec<CellAddress> = Vec::new();
        for row_step in 0..=(range.end_row - range.start_row) {
            for column_step in 0..=(range.end_column - range.start_column) {
                let address = CellAddress {
                    sheet: range.sheet,
                    row: range.start_row + row_step,
                    column: range.start_column + column_step,
                };
                if self.write_is_protected(address) {
                    refused = true;
                    continue;
                }
                self.grow_table_toward(address)?;
                header_writes.push(address);
                let from_row = if block.rows == 1 { 0 } else { row_step as usize };
                let from_column = if block.columns == 1 {
                    0
                } else {
                    column_step as usize
                };
                let Some(value) = block.at(from_row, from_column) else {
                    // An array with NOTHING in it changes NOTHING: asked of
                    // Excel, a cell holding 7 still holds 7 afterwards and
                    // one holding text still holds its text. Writing Empty
                    // here cleared them, which only looked right while the
                    // measurement was made against a cell already empty.
                    //
                    // An array that merely does not reach as far as the
                    // range does still fill what is left with #N/A.
                    if block.values.is_empty() {
                        continue;
                    }
                    self.set_cell_value(address, CellValue::Error("#N/A".to_string()))?;
                    continue;
                };
                match cell_input(value, self.this_year())? {
                    CellInput::Formula(formula) => {
                        let placed = self.placed_formula(
                            address,
                            formula,
                            style,
                            row_step as i64 - from_row as i64,
                            column_step as i64 - from_column as i64,
                        )?;
                        self.set_cell_formula(address, placed)?;
                    }
                    CellInput::Constant(value, shown) => {
                        self.set_cell_value(address, value)?;
                        if let Some(shown) = shown {
                            self.ask_cell_format(address, shown);
                        }
                    }
                }
            }
        }
        for address in header_writes {
            self.rename_table_column_from_cell(address)?;
        }
        if refused {
            return Err(
                "the cell is locked and the sheet is protected; unprotect it first".to_string(),
            );
        }
        Ok(())
    }

    /// A table's column takes the name typed into its header cell. Measured:
    /// typing `Qty` over the header of a table whose second column is
    /// already `Qty` keeps the typed cell as it is and renames the OTHER
    /// column `Qty2`.
    fn rename_table_column_from_cell(&mut self, at: CellAddress) -> Result<(), String> {
        let Some((sheet, index)) = self.table_holding(at) else {
            return Ok(());
        };
        let table = &self.workbook.sheets[sheet].tables[index];
        if at.row != table.start_row || table.header_rows == 0 {
            return Ok(());
        }
        let slot = (at.column - table.start_col) as usize;
        let typed = self
            .cell_here(at.sheet, at.row, at.column)
            .map(|cell| shown_text(&from_cell_value(&cell.value), cell.style.number_format.as_deref()))
            .unwrap_or_default();
        let columns = table.columns.clone();
        let start_col = table.start_col;
        if typed.is_empty() || columns.get(slot).is_some_and(|held| *held == typed) {
            return Ok(());
        }
        let mut renamed: Vec<(usize, String)> = Vec::new();
        for (other, held) in columns.iter().enumerate() {
            if other != slot && *held == typed {
                let fresh = (2..)
                    .map(|number| format!("{typed}{number}"))
                    .find(|name| !columns.iter().any(|held| held == name))
                    .expect("the numbers do not run out");
                renamed.push((other, fresh));
            }
        }
        let table_name = table.name.clone();
        let table = &mut self.workbook.sheets[sheet].tables[index];
        table.columns[slot] = typed;
        for (other, fresh) in &renamed {
            table.columns[*other] = fresh.clone();
        }
        let id = self.table_handle(sheet, &table_name);
        if let Some(extra) = self.table_extra.get_mut(&id) {
            if slot < extra.auto_named.len() {
                extra.auto_named[slot] = false;
            }
        }
        for (other, fresh) in renamed {
            self.set_cell_value(
                CellAddress {
                    sheet,
                    row: at.row,
                    column: start_col + other as u32,
                },
                CellValue::String(fresh),
            )?;
        }
        Ok(())
    }

    /// Read a formula as it was written, and move it as far as the fill did.
    ///
    /// In A1 style a filled cell's relative references move with it and its
    /// absolute ones stay put — asked of Excel, `Range("F1:G2").Formula =
    /// "=A1"` leaves F1 `=A1`, G1 `=B1`, F2 `=A2` and G2 `=B2`, while
    /// `"=$A$1"` leaves all four alone. A cell the block itself named has not
    /// moved and keeps the text it was given, so a formula this build cannot
    /// read still reaches its own cell unharmed.
    ///
    /// R1C1 needs no moving at all: the text already says where to look from
    /// wherever it sits, so every cell reads it for itself.
    ///
    /// Where a reference would move off the sheet Excel writes `#REF!` into
    /// the formula; this build refuses the assignment instead, which is what
    /// the paste path already does with the same arithmetic.
    fn placed_formula(
        &self,
        address: CellAddress,
        formula: String,
        style: FormulaStyle,
        down: i64,
        across: i64,
    ) -> Result<String, String> {
        match style {
            FormulaStyle::R1C1 => {
                formula_from_r1c1(&formula, address.row.saturating_sub(1), address.column)
            }
            FormulaStyle::A1 if down == 0 && across == 0 => Ok(formula),
            FormulaStyle::A1 => translate_formula_references(&formula, down, across),
        }
    }

    fn set_range_style(
        &mut self,
        range: CellRange,
        mut update: impl FnMut(CellAddress, &mut CellStyle),
    ) -> Result<(), String> {
        self.guard_formats(range.sheet, "formatting cells")?;
        let band = Self::band_of(range);
        if band != Band::Cells {
            // Every cell there is, and the template for the rest.
            for address in self.existing_cells_in(range) {
                if let Some(cell) = self.cell_mut(address) {
                    update(address, &mut cell.style);
                }
            }
            let sheet = range.sheet;
            match band {
                Band::Whole => {
                    let mut scopes: Vec<FormatScope> = self
                        .templates
                        .keys()
                        .copied()
                        .filter(|scope| matches!(scope, FormatScope::Column(held, _) | FormatScope::Row(held, _) if *held == sheet))
                        .collect();
                    scopes.push(FormatScope::Sheet(sheet));
                    for scope in scopes {
                        let mut style = self.templates.get(&scope).cloned().unwrap_or_default();
                        update(CellAddress { sheet, row: 1, column: 0 }, &mut style);
                        self.templates.insert(scope, style);
                    }
                }
                Band::Columns => {
                    for column in range.start_column..=range.end_column {
                        let at = CellAddress { sheet, row: 1, column };
                        let mut style = self.template_style(at);
                        update(at, &mut style);
                        self.templates.insert(FormatScope::Column(sheet, column), style);
                    }
                }
                Band::Rows => {
                    for row in range.start_row..=range.end_row {
                        let at = CellAddress { sheet, row, column: 0 };
                        let mut style = self.template_style(at);
                        update(at, &mut style);
                        self.templates.insert(FormatScope::Row(sheet, row), style);
                    }
                }
                Band::Cells => {}
            }
            return Ok(());
        }
        Self::range_cell_count(range)?;
        for address in range.addresses() {
            let starting = self.template_style(address);
            let sheet = self
                .workbook
                .sheets
                .get_mut(address.sheet)
                .ok_or_else(|| "worksheet no longer exists".to_string())?;
            sheet.col_count = sheet.col_count.max(address.column as usize + 1);
            if !sheet.rows.iter().any(|row| row.index == address.row) {
                sheet.rows.push(Row {
                    index: address.row,
                    cells: Vec::new(),
                    height: None,
                    custom_height: false,
                    style_font: None,
                    thick_top: false,
                    thick_bottom: false,
                    hidden: false,
                });
                sheet.rows.sort_by_key(|row| row.index);
            }
            let row = sheet
                .rows
                .iter_mut()
                .find(|row| row.index == address.row)
                .expect("the destination row was created");
            if !row.cells.iter().any(|cell| cell.col == address.column) {
                row.cells.push(Cell {
                    array_block: None,
                    col: address.column,
                    value: CellValue::Empty,
                    style: starting,
                    formula: None,
                    runs: Vec::new(),
                });
                row.cells.sort_by_key(|cell| cell.col);
            }
            let cell = row
                .cells
                .iter_mut()
                .find(|cell| cell.col == address.column)
                .expect("the destination cell was created");
            update(address, &mut cell.style);
        }
        Ok(())
    }

    fn uniform_style<T: Clone + PartialEq>(
        &self,
        range: CellRange,
        read: impl Fn(&CellStyle) -> T,
    ) -> Result<Option<T>, String> {
        let mut first = None;
        let mut take = |value: T| -> bool {
            if first.as_ref().is_some_and(|held| held != &value) {
                return false;
            }
            first = Some(value);
            true
        };
        // Whole rows, columns or the sheet: the cells there are, and the
        // template every other cell there would wear.
        if Self::band_of(range) != Band::Cells {
            for address in self.existing_cells_in(range) {
                if let Some(cell) = self.cell_here(address.sheet, address.row, address.column) {
                    if !take(read(&cell.style)) {
                        return Ok(None);
                    }
                }
            }
            let blank = self.template_style(range.first());
            if !take(read(&blank)) {
                return Ok(None);
            }
            return Ok(first);
        }
        Self::range_cell_count(range)?;
        for address in range.addresses() {
            let style = match self.cell_here(address.sheet, address.row, address.column) {
                Some(cell) => cell.style,
                None => self.template_style(address),
            };
            if !take(read(&style)) {
                return Ok(None);
            }
        }
        Ok(first)
    }

    /// A cell's dress with the edges it shares filled in: an edge a cell
    /// draws nothing along is the neighbour's, if the neighbour draws one.
    /// Measured, the cell under a `見出し 1` cell answers its top border as
    /// that cell's thick bottom one.
    fn style_with_shared_edges(&self, address: CellAddress) -> CellStyle {
        let dress_at = |row: u32, column: u32| -> Option<CellStyle> {
            let sheet = self.workbook.sheets.get(address.sheet)?;
            let row = sheet.rows.iter().find(|held| held.index == row)?;
            let cell = row.cells.iter().find(|held| held.col == column)?;
            Some(cell.style.clone())
        };
        // Where both cells draw the shared edge, the heavier line is the one
        // seen: measured, a cell with a thin top under a cell with a double
        // bottom answers its top as the double line.
        let heavier = |own: Option<BorderLine>, other: Option<BorderLine>| -> Option<BorderLine> {
            let weight = |line: &Option<BorderLine>| match line {
                None => 0,
                Some(line) => match border_kind(Some(line)).1 {
                    1 => 1,
                    -4138 => 3,
                    4 => 4,
                    _ => 2,
                },
            };
            if weight(&other) > weight(&own) { other } else { own }
        };
        let mut style = dress_at(address.row, address.column).unwrap_or_default();
        if address.row > 1 {
            let above = dress_at(address.row - 1, address.column).and_then(|above| above.border_bottom);
            style.border_top = heavier(style.border_top.take(), above);
        }
        if address.column > 0 {
            let left = dress_at(address.row, address.column - 1).and_then(|left| left.border_right);
            style.border_left = heavier(style.border_left.take(), left);
        }
        let below = dress_at(address.row + 1, address.column).and_then(|below| below.border_top);
        style.border_bottom = heavier(style.border_bottom.take(), below);
        let right = dress_at(address.row, address.column + 1).and_then(|right| right.border_left);
        style.border_right = heavier(style.border_right.take(), right);
        style
    }

    fn uniform_border(
        &self,
        range: CellRange,
        selection: BorderSelection,
    ) -> Result<Option<(i64, i64)>, String> {
        Self::range_cell_count(range)?;
        let mut first = None;
        for address in range.addresses() {
            let style = self.style_with_shared_edges(address);
            for value in selected_borders(&style, address, range, selection) {
                if first.is_some_and(|first| first != value) {
                    return Ok(None);
                }
                first = Some(value);
            }
        }
        Ok(Some(first.unwrap_or((LINE_NONE, WEIGHT_THIN))))
    }

    /// The colour the selected edges share, or None when they disagree.
    fn uniform_border_colour(
        &self,
        range: CellRange,
        selection: BorderSelection,
    ) -> Result<Option<EdgeColour>, String> {
        Self::range_cell_count(range)?;
        let mut first: Option<EdgeColour> = None;
        for address in range.addresses() {
            let style = self.style_with_shared_edges(address);
            for edge in selected_border_lines(&style, address, range, selection) {
                let colour = match edge {
                    None => EdgeColour::NoLine,
                    Some(line) => match line.color {
                        Some(colour) => EdgeColour::Named(colour),
                        None => EdgeColour::Automatic,
                    },
                };
                if first.as_ref().is_some_and(|held| *held != colour) {
                    return Ok(None);
                }
                first = Some(colour);
            }
        }
        Ok(Some(first.unwrap_or(EdgeColour::NoLine)))
    }

    fn range_column_width(&self, range: CellRange) -> Result<Value, String> {
        let sheet = self
            .workbook
            .sheets
            .get(range.sheet)
            .ok_or_else(|| "worksheet no longer exists".to_string())?;
        // What a macro reads is characters of the standard font, worked
        // back from the pixels: measured, a fresh column is 8.38 (72 pixels
        // of an 8-pixel digit), one set to 10 reads 10 (85 pixels), one set
        // to 0.5 reads 0.54 (7 pixels), and a hidden one reads 0.
        let digit = self.digit_width();
        let _ = sheet;
        let mut first = None;
        for column in range.start_column..=range.end_column {
            let px = self.column_px(range.sheet, column);
            let width = characters_of_pixels(px, digit);
            if first.is_some_and(|first| first != width) {
                return Ok(Value::Null);
            }
            first = Some(width);
        }
        Ok(Value::Double(first.unwrap_or(0.0)))
    }

    fn set_range_column_width(&mut self, range: CellRange, value: Value) -> Result<(), String> {
        self.guard_column_formats(range.sheet, "setting a column width")?;
        let sheet = self
            .workbook
            .sheets
            .get_mut(range.sheet)
            .ok_or_else(|| "worksheet no longer exists".to_string())?;
        let width = optional_dimension(value, "Range.ColumnWidth", 255.0)
            .map_err(|why| host_error(1004, why))?;
        let required = range.end_column as usize + 1;
        if sheet.col_widths.len() < required {
            sheet.col_widths.resize(required, 0.0);
        }
        // Characters go in; the file's width -- pixels over the digit --
        // is what is kept, so that what is drawn is what Excel draws.
        // Measured: 10 is 85 pixels (10 x 8 + 5), 2.5 is 25, 100 is 805,
        // 0.99 and 1 are 13, 0.5 is 7 -- below one character the gutter
        // shrinks with the width -- and 0 hides the column.
        let digit = self.digit_width();
        let sheet = &mut self.workbook.sheets[range.sheet];
        for column in range.start_column..=range.end_column {
            match width {
                Some(width) if width <= 0.0 => {
                    if !sheet.hidden_cols.contains(&column) {
                        sheet.hidden_cols.push(column);
                        sheet.hidden_cols.sort_unstable();
                    }
                }
                Some(width) => {
                    let px = if width < 1.0 {
                        (width * (digit + 5.0)).round()
                    } else {
                        (width * digit + 5.0).trunc()
                    };
                    sheet.col_widths[column as usize] = (px * 256.0 / digit).trunc() / 256.0;
                    sheet.hidden_cols.retain(|held| *held != column);
                }
                None => sheet.col_widths[column as usize] = 0.0,
            }
        }
        sheet.col_count = sheet.col_count.max(required);
        Ok(())
    }

    fn range_row_height(&self, range: CellRange) -> Result<Value, String> {
        let sheet = self
            .workbook
            .sheets
            .get(range.sheet)
            .ok_or_else(|| "worksheet no longer exists".to_string())?;
        let selected_rows = u64::from(range.end_row - range.start_row) + 1;
        let rows = sheet
            .rows
            .iter()
            .filter(|row| (range.start_row..=range.end_row).contains(&row.index));
        let existing_rows = rows.clone().count() as u64;
        let mut first = (existing_rows < selected_rows).then_some(sheet.default_row_height);
        for row in rows {
            // Measured: a hidden row reads 0; one too short to show a pixel
            // still reads its height (0.5) though it counts as hidden.
            let height = if row.hidden {
                0.0
            } else {
                row.height.unwrap_or(sheet.default_row_height)
            };
            if first.is_some_and(|first| first != height) {
                return Ok(Value::Null);
            }
            first = Some(height);
        }
        Ok(Value::Double(f64::from(
            first.unwrap_or(sheet.default_row_height),
        )))
    }

    fn set_range_row_height(&mut self, range: CellRange, value: Value) -> Result<(), String> {
        self.guard_row_formats(range.sheet, "setting a row height")?;
        let sheet = self
            .workbook
            .sheets
            .get_mut(range.sheet)
            .ok_or_else(|| "worksheet no longer exists".to_string())?;
        let height = optional_dimension(value, "Range.RowHeight", 409.5)
            .map_err(|why| host_error(1004, why))?;
        // Excel keeps a height to the quarter point, and mostly the quarter
        // ABOVE: measured, 0.3 reads 0.5, 1.1 reads 1.25, 12.1 reads 12.25,
        // 0.76 reads 0.75 and 25 stays 25 -- though 20.12 and 20.3 read 20
        // and 20.25, which no one rule reached. The quarter above, with a
        // hundredth of tolerance, stands in. A height of nothing hides the
        // row.
        let height = height.map(|height| {
            if height <= 0.0 {
                0.0
            } else {
                ((height - 0.01) * 4.0).ceil() / 4.0
            }
        });
        if range.start_row == 1 && range.end_row == MAX_WORKSHEET_ROW {
            if let Some(height) = height {
                sheet.default_row_height = height;
            }
            for row in &mut sheet.rows {
                row.height = None;
            }
            return Ok(());
        }
        for row_index in range.start_row..=range.end_row {
            if !sheet.rows.iter().any(|row| row.index == row_index) {
                sheet.rows.push(Row {
                    index: row_index,
                    cells: Vec::new(),
                    height: None,
                    custom_height: false,
                    style_font: None,
                    thick_top: false,
                    thick_bottom: false,
                    hidden: false,
                });
            }
            let row = sheet
                .rows
                .iter_mut()
                .find(|row| row.index == row_index)
                .expect("the resized row was created");
            row.height = height;
            // A height given by hand is pinned; the default lets the row
            // fit its content again.
            row.custom_height = height.is_some();
            if height == Some(0.0) {
                row.hidden = true;
            }
        }
        sheet.rows.sort_by_key(|row| row.index);
        Ok(())
    }

    fn clear_range(
        &mut self,
        range: CellRange,
        clear_contents: bool,
        clear_formats: bool,
    ) -> Result<(), String> {
        let band = Self::band_of(range);
        if band == Band::Cells {
            Self::range_cell_count(range)?;
        } else if clear_formats {
            // The formats given to the whole band go with it.
            let sheet = range.sheet;
            self.templates.retain(|scope, _| match *scope {
                FormatScope::Sheet(held) => held != sheet || band != Band::Whole,
                FormatScope::Column(held, column) => {
                    held != sheet || !(band == Band::Whole || (band == Band::Columns && (range.start_column..=range.end_column).contains(&column)))
                }
                FormatScope::Row(held, row) => {
                    held != sheet || !(band == Band::Whole || (band == Band::Rows && (range.start_row..=range.end_row).contains(&row)))
                }
            });
        }
        // Measured: clearing one cell of an array is 1004, clearing the whole
        // of it goes through, and clearing one cell's FORMATS goes through.
        if clear_contents {
            self.arrays_allow(range, false)?;
        }
        // Measured: `Clear` over an unlocked cell and a locked one clears
        // neither and raises; over unlocked cells alone it goes through, even
        // though it takes the formats off, which `Font.Bold = True` on the
        // same cell may not.
        self.guard_locked_cells(range, if clear_contents { "Range.Clear" } else { "Range.ClearFormats" })?;
        // Locked is one of the formats, and comes back with the rest: measured
        // on an unprotected sheet, an unlocked cell reads Locked again after
        // `ClearFormats` and after `Clear`, and not after `ClearContents`.
        // Under protection the two part ways: `ClearFormats` still takes the
        // formats off and relocks the cell, and `Clear` takes only the
        // contents -- the cell stays unlocked and stays bold.
        let clear_formats = clear_formats
            && (!clear_contents || self.cell_protection(range.sheet).is_none());
        if clear_formats {
            self.drop_conditions_on(range);
            self.unlocked.retain(|held| {
                held.sheet != range.sheet
                    || !(range.start_row..=range.end_row).contains(&held.row)
                    || !(range.start_column..=range.end_column).contains(&held.column)
            });
            self.styled.retain(|held, _| {
                held.sheet != range.sheet
                    || !(range.start_row..=range.end_row).contains(&held.row)
                    || !(range.start_column..=range.end_column).contains(&held.column)
            });
            self.theme_paint.retain(|(held, _), _| {
                held.sheet != range.sheet
                    || !(range.start_row..=range.end_row).contains(&held.row)
                    || !(range.start_column..=range.end_column).contains(&held.column)
            });
            let outside = |held: &CellAddress| {
                held.sheet != range.sheet
                    || !(range.start_row..=range.end_row).contains(&held.row)
                    || !(range.start_column..=range.end_column).contains(&held.column)
            };
            self.rotations.retain(|held, _| outside(held));
            self.underlines.retain(|held, _| outside(held));
            self.hatchings.retain(|held, _| outside(held));
            self.indented.retain(outside);
        }
        let sheet = self
            .workbook
            .sheets
            .get_mut(range.sheet)
            .ok_or_else(|| "worksheet no longer exists".to_string())?;
        for row in &mut sheet.rows {
            if !(range.start_row..=range.end_row).contains(&row.index) {
                continue;
            }
            for cell in &mut row.cells {
                if !(range.start_column..=range.end_column).contains(&cell.col) {
                    continue;
                }
                if clear_contents {
                    cell.array_block = None;
                }
                if clear_contents {
                    cell.value = CellValue::Empty;
                    cell.formula = None;
                }
                if clear_formats {
                    cell.style = CellStyle::default();
                }
            }
        }
        Ok(())
    }

    /// Which way `Insert` and `Delete` move the cells around a range. Excel
    /// decides from the range's shape when the caller does not say: a range
    /// taller than it is wide moves sideways, anything else moves vertically.
    fn shift_direction(range: CellRange, args: &[Value], inserting: bool) -> Result<bool, String> {
        let sideways = match args {
            [] | [Value::Missing] => {
                (range.end_row - range.start_row) > (range.end_column - range.start_column)
            }
            [shift] => match shift {
                Value::Integer(-4121) if inserting => false,
                Value::Integer(-4161) if inserting => true,
                Value::Integer(-4162) if !inserting => false,
                Value::Integer(-4159) if !inserting => true,
                _ => {
                    return Err(format!(
                        "Range.{} does not understand that shift",
                        if inserting { "Insert" } else { "Delete" }
                    ))
                }
            },
            // A recorder writes the CopyOrigin beside the shift; it says
            // where the new cells take their format from, which is nothing
            // this build keeps, so the shift alone is read.
            [shift, _copy_origin] => return Self::shift_direction(range, std::slice::from_ref(shift), inserting),
            _ => {
                return Err(format!(
                    "Range.{} takes at most one shift and a CopyOrigin",
                    if inserting { "Insert" } else { "Delete" }
                ))
            }
        };
        Ok(sideways)
    }

    /// `Range.Insert Shift`. With a cut or a copy held and the shift SAID,
    /// what is held goes into the room made -- Excel's "Insert Cut Cells"
    /// and "Insert Copied Cells". Measured: one/two/three in X1:X3, X3 cut,
    /// `X1.Insert Shift:=xlDown` gives three/one/two with X4 empty and
    /// CutCopyMode 0; X1 copied and `X2.Insert Shift:=xlDown` gives
    /// three/three/one/two with CutCopyMode still 1; Y1:Y2 cut and
    /// `Z5.Insert Shift:=xlToRight` lands them in Z5:Z6. With no shift
    /// said the insert is a plain one and the cut stays held.
    fn insert_range(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        let sideways = Self::shift_direction(range, args, true)?;
        self.guard_structure(range.sheet, sideways, true)?;
        let shift_said = !matches!(args, [] | [Value::Missing]);
        if shift_said {
            if let Some(source) = self.pending_cut {
                let rows = source.end_row - source.start_row + 1;
                let columns = source.end_column - source.start_column + 1;
                let block = CellRange {
                    sheet: range.sheet,
                    start_row: range.start_row,
                    start_column: range.start_column,
                    end_row: range.start_row + rows - 1,
                    end_column: range.start_column + columns - 1,
                };
                if source.sheet == block.sheet && ranges_overlap(source, block) {
                    return Err(host_error(1004, "the cut cells cannot be inserted into themselves"));
                }
                // Make the room first, which may move the source itself
                // when it lies beyond the room on the same axis.
                self.shift_cells(block, sideways, true)?;
                let source = if source.sheet != block.sheet {
                    source
                } else if sideways {
                    let crossing = source.start_row <= block.end_row && source.end_row >= block.start_row;
                    if crossing && source.start_column >= block.start_column {
                        CellRange {
                            start_column: source.start_column + columns,
                            end_column: source.end_column + columns,
                            ..source
                        }
                    } else {
                        source
                    }
                } else {
                    let crossing = source.start_column <= block.end_column && source.end_column >= block.start_column;
                    if crossing && source.start_row >= block.start_row {
                        CellRange {
                            start_row: source.start_row + rows,
                            end_row: source.end_row + rows,
                            ..source
                        }
                    } else {
                        source
                    }
                };
                self.pending_cut = None;
                self.move_cells(source, block)?;
                // And close the hole the cut left, the same way round.
                self.shift_cells(source, sideways, false)?;
                return Ok(Value::Boolean(true));
            }
            if let Some((rows, columns)) = self.clipboard.as_ref().map(|held| (held.rows, held.columns)) {
                let block = CellRange {
                    sheet: range.sheet,
                    start_row: range.start_row,
                    start_column: range.start_column,
                    end_row: range.start_row + rows - 1,
                    end_column: range.start_column + columns - 1,
                };
                self.shift_cells(block, sideways, true)?;
                self.paste_special(block, &[])?;
                return Ok(Value::Boolean(true));
            }
        }
        self.shift_cells(range, sideways, true)?;
        // True, the way Excel answers every member that acts.
        Ok(Value::Boolean(true))
    }

    fn delete_range(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        let sideways = Self::shift_direction(range, args, false)?;
        self.guard_structure(range.sheet, sideways, false)?;
        self.shift_cells(range, sideways, false)?;
        Ok(Value::Empty)
    }

    /// Moves everything the range pushes ahead of it, drops what a removal
    /// covers, and rewrites the sheet's formulas to match.
    ///
    /// Only the rows or columns the range itself spans move, so inserting at
    /// `B2` leaves column C where it was.
    fn shift_cells(
        &mut self,
        range: CellRange,
        sideways: bool,
        inserting: bool,
    ) -> Result<(), String> {
        let axis = if sideways {
            ShiftAxis::Columns
        } else {
            ShiftAxis::Rows
        };
        let (at, span, across) = if sideways {
            (
                range.start_column + 1,
                range.end_column - range.start_column + 1,
                (range.start_row, range.end_row),
            )
        } else {
            (
                range.start_row,
                range.end_row - range.start_row + 1,
                (range.start_column + 1, range.end_column + 1),
            )
        };
        let count = if inserting {
            i64::from(span)
        } else {
            -i64::from(span)
        };

        let removed = if inserting { 0 } else { span };
        let past = at.saturating_add(removed);
        let moved = |value: u32| -> Option<u32> {
            if value < at {
                return Some(value);
            }
            if removed > 0 {
                if value < past {
                    return None;
                }
                return Some(value - removed);
            }
            Some(value.saturating_add(span))
        };
        // Only cells lying across the range's own width or height take part.
        let taking_part = |crossing: u32| crossing >= across.0 && crossing <= across.1;

        // An array formula's block moves whole or not at all. Measured: a
        // row put in at the block's first row moves it down; a row put in
        // inside it, or one of its rows taken out, is 1004.
        for (top, left, bottom, right) in self.arrays_on(range.sheet) {
            let (crossing, along) = if sideways {
                ((top, bottom), (left + 1, right + 1))
            } else {
                ((left + 1, right + 1), (top, bottom))
            };
            // A block wholly before the shift point is not moved at all,
            // whatever it lies across.
            if along.1 < at {
                continue;
            }
            let parts: Vec<bool> = (crossing.0..=crossing.1).map(taking_part).collect();
            if parts.iter().all(|part| !part) {
                continue;
            }
            let cut = parts.iter().any(|part| !part)
                || (inserting && at > along.0 && at <= along.1)
                || (!inserting && moved(along.0).is_some() != moved(along.1).is_some());
            if cut {
                return Err(host_error(1004, "You cannot change part of an array."));
            }
        }

        let Some(worksheet) = self.workbook.sheets.get_mut(range.sheet) else {
            return Err("worksheet is out of range".to_string());
        };
        if sideways {
            for row in &mut worksheet.rows {
                if !taking_part(row.index) {
                    continue;
                }
                row.cells.retain_mut(|cell| match moved(cell.col + 1) {
                    Some(column) => {
                        cell.col = column - 1;
                        true
                    }
                    None => false,
                });
            }
        } else {
            // A row only partly taking part has to be split, so cells move
            // between rows rather than rows moving whole.
            let mut carried: Vec<(u32, Cell)> = Vec::new();
            for row in &mut worksheet.rows {
                row.cells.retain_mut(|cell| {
                    if !taking_part(cell.col + 1) {
                        return true;
                    }
                    match moved(row.index) {
                        Some(index) if index == row.index => true,
                        Some(index) => {
                            carried.push((index, cell.clone()));
                            false
                        }
                        None => false,
                    }
                });
            }
            for (index, cell) in carried {
                let row = match worksheet.rows.iter().position(|row| row.index == index) {
                    Some(position) => &mut worksheet.rows[position],
                    None => {
                        worksheet.rows.push(Row {
                            index,
                            cells: Vec::new(),
                            height: None,
                            custom_height: false,
                            style_font: None,
                            thick_top: false,
                            thick_bottom: false,
                            hidden: false,
                        });
                        worksheet.rows.sort_by_key(|row| row.index);
                        worksheet
                            .rows
                            .iter_mut()
                            .find(|row| row.index == index)
                            .unwrap()
                    }
                };
                match row.cells.iter_mut().find(|held| held.col == cell.col) {
                    Some(held) => *held = cell,
                    None => {
                        row.cells.push(cell);
                        row.cells.sort_by_key(|cell| cell.col);
                    }
                }
            }
            worksheet.rows.retain(|row| !row.cells.is_empty());
        }
        // The blocks that moved say where they are now.
        for row in &mut worksheet.rows {
            for cell in &mut row.cells {
                let Some((top, left, bottom, right)) = cell.array_block else {
                    continue;
                };
                let took_part = if sideways { taking_part(top) } else { taking_part(left + 1) };
                if !took_part {
                    continue;
                }
                cell.array_block = if sideways {
                    match (moved(left + 1), moved(right + 1)) {
                        (Some(near), Some(far)) => Some((top, near - 1, bottom, far - 1)),
                        _ => None,
                    }
                } else {
                    match (moved(top), moved(bottom)) {
                        (Some(near), Some(far)) => Some((near, left, far, right)),
                        _ => None,
                    }
                };
            }
        }

        worksheet.merge_cells.retain_mut(|merge| {
            let (near, far) = if sideways {
                (merge.start_row, merge.end_row)
            } else {
                (merge.start_col + 1, merge.end_col + 1)
            };
            if !taking_part(near) && !taking_part(far) {
                return true;
            }
            // A band reaching only part of the way across a merge cannot carry
            // it, so Excel takes the merge apart and moves the cells alone.
            if !taking_part(near) || !taking_part(far) {
                return false;
            }
            let (start, end) = if sideways {
                (merge.start_col + 1, merge.end_col + 1)
            } else {
                (merge.start_row, merge.end_row)
            };
            // A merge the removal swallows whole goes; one it clips shrinks.
            let start = moved(start).unwrap_or(at);
            let end = moved(end).unwrap_or_else(|| at.saturating_sub(1));
            if start > end {
                return false;
            }
            if sideways {
                merge.start_col = start - 1;
                merge.end_col = end - 1;
            } else {
                merge.start_row = start;
                merge.end_row = end;
            }
            true
        });

        // The notes and the unlocking move with their cells, and go when
        // their cells go.
        let sheet = range.sheet;
        let relocate = |held: CellAddress| -> Option<CellAddress> {
            if held.sheet != sheet {
                return Some(held);
            }
            let (along, crossing) = if sideways {
                (held.column + 1, held.row)
            } else {
                (held.row, held.column + 1)
            };
            if !taking_part(crossing) {
                return Some(held);
            }
            let along = moved(along)?;
            Some(if sideways {
                CellAddress {
                    column: along - 1,
                    ..held
                }
            } else {
                CellAddress { row: along, ..held }
            })
        };
        self.unlocked = self.unlocked.iter().filter_map(|held| relocate(*held)).collect();
        self.styled = std::mem::take(&mut self.styled)
            .into_iter()
            .filter_map(|(held, style)| Some((relocate(held)?, style)))
            .collect();
        self.theme_paint = std::mem::take(&mut self.theme_paint)
            .into_iter()
            .filter_map(|((held, paint), painted)| Some(((relocate(held)?, paint), painted)))
            .collect();
        self.rotations = std::mem::take(&mut self.rotations)
            .into_iter()
            .filter_map(|(held, turn)| Some((relocate(held)?, turn)))
            .collect();
        self.underlines = std::mem::take(&mut self.underlines)
            .into_iter()
            .filter_map(|(held, rule)| Some((relocate(held)?, rule)))
            .collect();
        self.hatchings = std::mem::take(&mut self.hatchings)
            .into_iter()
            .filter_map(|(held, hatching)| Some((relocate(held)?, hatching)))
            .collect();
        self.indented = self.indented.iter().filter_map(|held| relocate(*held)).collect();
        // A whole band of rows or columns carries its outline levels along;
        // a band put in starts at level one.
        if let Some(outline) = self.outlines.get_mut(&sheet) {
            let whole = if sideways {
                across.0 == 1 && across.1 == MAX_WORKSHEET_ROW
            } else {
                across.0 == 1 && across.1 == MAX_WORKSHEET_COLUMN + 1
            };
            if whole {
                let levels = if sideways { &mut outline.columns } else { &mut outline.rows };
                *levels = std::mem::take(levels)
                    .into_iter()
                    .filter_map(|(index, level)| {
                        let along = if sideways { index + 1 } else { index };
                        let along = moved(along)?;
                        Some((if sideways { along - 1 } else { along }, level))
                    })
                    .collect();
            }
        }
        let moved_validations: Vec<(CellAddress, Validation)> = self
            .validations
            .drain()
            .filter_map(|(held, validation)| {
                if held.sheet != sheet {
                    return Some((held, validation));
                }
                let (along, crossing) = if sideways {
                    (held.column + 1, held.row)
                } else {
                    (held.row, held.column + 1)
                };
                if !taking_part(crossing) {
                    return Some((held, validation));
                }
                let along = moved(along)?;
                let landed = if sideways {
                    CellAddress {
                        column: along - 1,
                        ..held
                    }
                } else {
                    CellAddress { row: along, ..held }
                };
                Some((landed, validation))
            })
            .collect();
        self.validations = moved_validations.into_iter().collect();
        // A table in the way of the shift moves with its cells: a band of
        // rows or columns put in above or left of it, or through it, and one
        // taken out.
        self.workbook.sheets[sheet].tables.retain_mut(|table| {
            let (crossing_first, crossing_last) = if sideways {
                (table.start_row, table.end_row)
            } else {
                (table.start_col + 1, table.end_col + 1)
            };
            if !(crossing_first..=crossing_last).any(taking_part) {
                return true;
            }
            let (near, far) = if sideways {
                (table.start_col + 1, table.end_col + 1)
            } else {
                (table.start_row, table.end_row)
            };
            let (Some(near), Some(far)) = (moved(near), moved(far)) else {
                return false;
            };
            if sideways {
                table.start_col = near - 1;
                table.end_col = far - 1;
            } else {
                table.start_row = near;
                table.end_row = far;
            }
            true
        });
        for condition in &mut self.conditions {
            if condition.sheet != sheet {
                continue;
            }
            condition.applies.retain_mut(|block| {
                let (near, far, crossing) = if sideways {
                    (block.start_column + 1, block.end_column + 1, block.start_row)
                } else {
                    (block.start_row, block.end_row, block.start_column + 1)
                };
                if !taking_part(crossing) {
                    return true;
                }
                let (Some(near), Some(far)) = (moved(near), moved(far)) else {
                    return false;
                };
                if sideways {
                    block.start_column = near - 1;
                    block.end_column = far - 1;
                } else {
                    block.start_row = near;
                    block.end_row = far;
                }
                true
            });
        }
        self.conditions.retain(|condition| !condition.applies.is_empty());
        self.links.retain_mut(|link| {
            if link.anchor.sheet != sheet {
                return true;
            }
            let (near, far, crossing) = if sideways {
                (link.anchor.start_column + 1, link.anchor.end_column + 1, link.anchor.start_row)
            } else {
                (link.anchor.start_row, link.anchor.end_row, link.anchor.start_column + 1)
            };
            if !taking_part(crossing) {
                return true;
            }
            let (Some(near), Some(far)) = (moved(near), moved(far)) else {
                return false;
            };
            if sideways {
                link.anchor.start_column = near - 1;
                link.anchor.end_column = far - 1;
            } else {
                link.anchor.start_row = near;
                link.anchor.end_row = far;
            }
            true
        });
        self.notes.retain_mut(|note| {
            if note.at.sheet != sheet {
                return true;
            }
            let (along, crossing) = if sideways {
                (note.at.column + 1, note.at.row)
            } else {
                (note.at.row, note.at.column + 1)
            };
            if !taking_part(crossing) {
                return true;
            }
            let Some(along) = moved(along) else {
                return false;
            };
            if sideways {
                note.at.column = along - 1;
            } else {
                note.at.row = along;
            }
            true
        });

        // Every sheet's formulas are rewritten, not just this one: a formula on
        // another sheet naming this one follows the cells that moved.
        let moved_sheet = self.workbook.sheets[range.sheet].name.clone();
        for worksheet in &mut self.workbook.sheets {
            // Which sheet these formulas are written on decides what an
            // unqualified `A1` means: it is about THIS sheet, so it moves only
            // when this is the sheet the cells moved on. One shift for all of
            // them dragged every other sheet's references along.
            let shift = ReferenceShift {
                axis,
                at,
                count,
                across,
                sheet: Some(&moved_sheet),
                on_sheet: Some(worksheet.name.as_str()),
            };
            for row in &mut worksheet.rows {
                for cell in &mut row.cells {
                    let Some(formula) = cell.formula.as_ref() else {
                        continue;
                    };
                    // A formula this build cannot read is left as the author
                    // wrote it rather than silently half-moved.
                    if let Ok(shifted) = oxicells_core::shift_formula_references(formula, &shift) {
                        cell.formula = Some(shifted);
                    }
                }
            }
        }

        // A name points at cells too. Asked of Excel, a name standing for
        // `$B$3:$B$5` reads `$B$4:$B$6` after a row goes in above it,
        // `$B$3:$B$6` after one goes in the middle of it, and `#REF!` once all
        // three are taken out. A name always says which sheet it means, so
        // there is no home sheet to read it against.
        let named = ReferenceShift {
            axis,
            at,
            count,
            across,
            sheet: Some(&moved_sheet),
            on_sheet: None,
        };
        for (_, refers_to) in &mut self.workbook.defined_names {
            if let Ok(shifted) = oxicells_core::shift_formula_references(refers_to, &named) {
                *refers_to = shifted;
            }
        }
        Ok(())
    }

    /// Sorts the rows or columns of a range by up to three keys.
    ///
    /// Excel orders values by kind before value — numbers, then text, then
    /// Booleans — and leaves blanks at the end whichever way the sort runs.
    /// Text compares without regard to case, and equal values keep the order
    /// they were already in.
    ///
    /// Told to tell case apart, it still compares the letters without regard
    /// to case and puts the LOWER case first where they are the same:
    /// `b A a B` sorts to `a A b B`. See `compare_text_by_case`.
    /// `Range.RemoveDuplicates Columns:=..., Header:=...`
    ///
    /// The FIRST row carrying a given key stays and the later ones go, the
    /// survivors move up to close the gap, and what is left at the bottom is
    /// emptied. Measured against Excel on A1:B5 with a key column of
    /// 1, 2, 1, 3, 2: the rows keeping 1, 2 and 3 end up in rows 1 to 3 and
    /// rows 4 and 5 hold nothing.
    ///
    /// `Columns` is one number or an array of them, counted from the range's
    /// own left edge, and every named column has to match for two rows to be
    /// the same. `Header:=xlYes` leaves the first row where it is and starts
    /// comparing below it.
    /// `AutoFit` on the columns a range covers.
    ///
    /// It widens each column to the longest thing shown in it. The exact width
    /// Excel lands on is FONT-dependent and so not reproducible here: measured
    /// on a machine whose standard font is 游ゴシック 11, `abcde` gives 6.13,
    /// ten letters 11.63, five digits 5.88, and an empty column 5.88. The same
    /// column under Calibri 11 would answer differently, and the DEFAULT width
    /// already differs for the same reason -- 8.38 there against the 8.43 this
    /// host uses.
    ///
    /// So this matches the shape and not the number: characters plus one, with
    /// the empty column's width as the floor. What it must not do is what it
    /// did before, which was raise 438 and leave the macro broken -- a macro
    /// asking to autofit wants the column widened, and a width slightly
    /// different from Excel's is a far smaller wrong than no width at all.
    /// `Range.AutoFit`: the rows or the columns of the range, whichever it
    /// is -- `Rows(9).AutoFit`, `Columns("A").AutoFit`, or a block's
    /// `.Rows` / `.Columns`. Measured: a block that is neither is 1004.
    fn auto_fit(&mut self, range: CellRange, sense: Option<RangeAxis>) -> Result<Value, String> {
        let axis = match sense {
            Some(RangeAxis::Rows) => ShiftAxis::Rows,
            Some(RangeAxis::Columns) => ShiftAxis::Columns,
            None => Self::hidden_band(range)
                .map_err(|_| host_error(1004, "AutoFit method of Range class failed"))?,
        };
        match axis {
            ShiftAxis::Rows => self.auto_fit_rows(range),
            ShiftAxis::Columns => self.auto_fit_columns(range),
        }
    }

    /// The height a row takes to show what is in it: for each cell the row
    /// Excel gives that cell's font (the measured table the renderer draws
    /// by), times the lines a wrapped cell breaks into at its line breaks,
    /// and never less than the row the sheet's own font asks for.
    ///
    /// Measured: an empty row set to 30 comes back to 18.75; a 20-point
    /// cell asks 33; three wrapped lines of 11-point text ask 56.25. How
    /// many lines a long text wraps into at the column's width is not
    /// worked out here -- only the breaks the text carries -- which is the
    /// one thing this falls short of Excel on.
    fn auto_fit_rows(&mut self, range: CellRange) -> Result<Value, String> {
        use oxicells_core::row_defaults::font_default_row_px;
        let sheet_index = range.sheet;
        let (face, size) = {
            let sheet = &self.workbook.sheets[sheet_index];
            match sheet.normal_font.clone() {
                Some(font) => font,
                None => (
                    self.workbook.default_style.font_name.clone().unwrap_or_else(|| "Calibri".to_string()),
                    self.workbook.default_style.font_size.unwrap_or(11.0),
                ),
            }
        };
        let default_px = self.workbook.sheets[sheet_index].default_row_height / 0.75;
        let base_px = font_default_row_px(&face, size).map(f32::from).unwrap_or(default_px);
        let sheet = &mut self.workbook.sheets[sheet_index];
        for row in &mut sheet.rows {
            if !(range.start_row..=range.end_row).contains(&row.index) {
                continue;
            }
            let mut px = base_px;
            // A medium or thick rule along the top or the bottom of the row
            // takes a pixel of room each: measured, a row whose cell wears a
            // thick bottom border fits at 26 pixels, 19.5, where 25 is the
            // font's own.
            let heavy = |edge: &Option<BorderLine>| {
                edge.as_ref().is_some_and(|line| matches!(border_kind(Some(line)).1, -4138 | 4))
            };
            let thick_top = row.cells.iter().any(|cell| heavy(&cell.style.border_top));
            let thick_bottom = row.cells.iter().any(|cell| heavy(&cell.style.border_bottom));
            for cell in &row.cells {
                let cell_face = cell.style.font_name.as_deref().unwrap_or(&face);
                let cell_size = cell.style.font_size.unwrap_or(size);
                let Some(font_px) = font_default_row_px(cell_face, cell_size) else {
                    continue;
                };
                let lines = if cell.style.wrap_text {
                    cell.value.display().matches('\n').count() as f32 + 1.0
                } else {
                    1.0
                };
                px = px.max(f32::from(font_px) * lines);
            }
            px += f32::from(u8::from(thick_top)) + f32::from(u8::from(thick_bottom));
            row.height = Some(px * 0.75);
            row.custom_height = false;
        }
        Ok(Value::Boolean(true))
    }

    fn auto_fit_columns(&mut self, range: CellRange) -> Result<Value, String> {
        const FLOOR: f64 = 5.88;
        // `Cells.EntireColumn.AutoFit` fits every column there is; only the
        // ones with something in them can change.
        let last_used = self.workbook.sheets[range.sheet]
            .rows
            .iter()
            .flat_map(|row| row.cells.iter().map(|cell| cell.col))
            .max()
            .unwrap_or(0);
        let end_column = range.end_column.min(last_used.max(range.start_column));
        for column in range.start_column..=end_column {
            let mut widest = 0usize;
            let rows: Vec<u32> = self.workbook.sheets[range.sheet]
                .rows
                .iter()
                .map(|row| row.index)
                .collect();
            for row in rows {
                let Some(cell) = self.cell_here(range.sheet, row, column) else {
                    continue;
                };
                let shown = shown_text(
                    &from_cell_value(&cell.value),
                    cell.style.number_format.as_deref(),
                );
                widest = widest.max(shown.chars().count());
            }
            let width = if widest == 0 {
                FLOOR
            } else {
                widest as f64 + 1.0
            };
            let lane = CellRange {
                sheet: range.sheet,
                start_row: range.start_row,
                end_row: range.end_row,
                start_column: column,
                end_column: column,
            };
            self.set_range_column_width(lane, Value::Double(width))?;
        }
        Ok(Value::Boolean(true))
    }

    fn remove_duplicates(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        let given = |index: usize| match args.get(index) {
            Some(Value::Missing) | None => None,
            Some(value) => Some(value),
        };
        let width = range.end_column - range.start_column + 1;
        let mut lanes: Vec<u32> = Vec::new();
        match given(0) {
            None => lanes.extend(range.start_column..=range.end_column),
            Some(Value::Array(listed)) => {
                for value in &listed.values {
                    lanes.push(Self::duplicate_lane(value, range, width)?);
                }
            }
            Some(value) => lanes.push(Self::duplicate_lane(value, range, width)?),
        }
        if lanes.is_empty() {
            return Err("Range.RemoveDuplicates needs at least one column".to_string());
        }
        let header = match given(1) {
            None => false,
            Some(value) => match sort_number(value, "Header")? {
                // xlNo is 2, xlYes 1, xlGuess 0 -- and a guess reads the first
                // row as a header when it is text over numbers, which this
                // does not attempt: it takes the plain answer.
                1 => true,
                _ => false,
            },
        };
        let first = if header {
            range.start_row + 1
        } else {
            range.start_row
        };
        if first > range.end_row {
            return Ok(Value::Boolean(true));
        }

        // Read every row out first: the survivors are about to move.
        let taken: Vec<Vec<Option<Cell>>> = (first..=range.end_row)
            .map(|row| {
                (range.start_column..=range.end_column)
                    .map(|column| self.cell_here(range.sheet, row, column))
                    .collect()
            })
            .collect();
        let key_of = |held: &Vec<Option<Cell>>| -> Vec<String> {
            lanes
                .iter()
                .map(|lane| {
                    let at = (lane - range.start_column) as usize;
                    held.get(at)
                        .and_then(|cell| cell.as_ref())
                        .map(|cell| find_value_text(&from_cell_value(&cell.value)))
                        .unwrap_or_default()
                })
                .collect()
        };
        let mut seen: Vec<Vec<String>> = Vec::new();
        let mut kept: Vec<Vec<Option<Cell>>> = Vec::new();
        for held in taken {
            let key = key_of(&held);
            if seen.contains(&key) {
                continue;
            }
            seen.push(key);
            kept.push(held);
        }

        for (offset, row) in (first..=range.end_row).enumerate() {
            for (at, column) in (range.start_column..=range.end_column).enumerate() {
                let address = CellAddress {
                    sheet: range.sheet,
                    row,
                    column,
                };
                let held = kept.get(offset).and_then(|line| line.get(at).cloned()).flatten();
                match held {
                    Some(cell) => self.set_cell_value(address, cell.value)?,
                    None => self.set_cell_value(address, CellValue::Empty)?,
                }
            }
        }
        Ok(Value::Boolean(true))
    }

    /// Which column of the sheet a `Columns:=` number stands for.
    fn duplicate_lane(value: &Value, range: CellRange, width: u32) -> Result<u32, String> {
        let asked = sort_number(value, "RemoveDuplicates Columns")?;
        if asked < 1 || asked as u32 > width {
            return Err(format!(
                "Range.RemoveDuplicates column {asked} is outside the {width}-column range"
            ));
        }
        Ok(range.start_column + asked as u32 - 1)
    }

    /// The cell at a place, if there is one.
    fn cell_here(&self, sheet: usize, row: u32, column: u32) -> Option<Cell> {
        self.workbook
            .sheets
            .get(sheet)?
            .rows
            .iter()
            .find(|held| held.index == row)
            .and_then(|held| held.cells.iter().find(|cell| cell.col == column))
            .cloned()
    }

    /// `Worksheet.Sort.SetRange` / `.Apply`, and the members a recorder
    /// touches on the way. Measured: after building the fields, setting the
    /// range and Header, `.Apply` sorts the range and leaves the fields in
    /// place (Count stays).
    fn sort_object_call(&mut self, sheet: usize, name: &str, args: &[Value]) -> Result<Value, String> {
        match name.to_ascii_lowercase().as_str() {
            "sortfields" => Ok(self.object(HostObject::SortFields(sheet))),
            "setrange" => {
                let range = args
                    .first()
                    .and_then(|value| match value {
                        Value::Object(object) => self.range(object),
                        _ => None,
                    })
                    .ok_or_else(|| host_error(1004, "Sort.SetRange takes a Range"))?;
                self.sorts.entry(sheet).or_default().range = Some(range);
                Ok(Value::Empty)
            }
            "apply" => {
                let state = self.sorts.get(&sheet).cloned().unwrap_or_default();
                let Some(range) = state.range else {
                    return Err(host_error(1004, "Sort.Apply has no range set"));
                };
                if state.fields.is_empty() {
                    return Ok(Value::Empty);
                }
                self.guard_sort(range)?;
                let header = match state.header {
                    1 => true,
                    0 => self.guessed_header(range, state.sideways),
                    _ => false,
                };
                self.apply_sort(range, &state.fields, header, state.match_case, state.sideways)?;
                Ok(Value::Empty)
            }
            _ => Ok(Value::Empty),
        }
    }

    fn sort_fields_call(&mut self, sheet: usize, name: &str, args: &[Value]) -> Result<Value, String> {
        match name.to_ascii_lowercase().as_str() {
            "clear" => {
                self.sorts.entry(sheet).or_default().fields.clear();
                Ok(Value::Empty)
            }
            "count" => Ok(Value::Integer(
                self.sorts.get(&sheet).map_or(0, |state| state.fields.len() as i64),
            )),
            "add" | "add2" => {
                let key = args.first().and_then(|value| match value {
                    Value::Object(object) => self.range(object),
                    _ => None,
                });
                let Some(key) = key else {
                    return Err(host_error(1004, "SortFields.Add needs a key Range"));
                };
                let sideways = self.sorts.get(&sheet).is_some_and(|state| state.sideways);
                let lane = if sideways { key.start_row } else { key.start_column };
                // Order is the third argument: xlAscending 1, xlDescending 2.
                let descending = matches!(args.get(2).and_then(any_whole_number), Some(2));
                self.sorts.entry(sheet).or_default().fields.push((lane, descending));
                Ok(Value::Empty)
            }
            _ => Ok(Value::Empty),
        }
    }

    /// Reorder a range by its keys, each a (lane, descending) within the
    /// range -- a column top-to-bottom, a row when it runs sideways.
    /// Shared by `Range.Sort` and the recorder's `Worksheet.Sort` object.
    fn apply_sort(&mut self, range: CellRange, keys: &[(u32, bool)], header: bool, match_case: bool, sideways: bool) -> Result<(), String> {
        // Each line is one row of the range, or one column when sorting sideways.
        let (first, last) = if sideways {
            (range.start_column, range.end_column)
        } else {
            (range.start_row, range.end_row)
        };
        let first = if header { first + 1 } else { first };
        if first > last {
            return Ok(());
        }
        let mut lines: Vec<u32> = (first..=last).collect();
        let cell_at = |line: u32, lane: u32| {
            if sideways {
                CellAddress {
                    sheet: range.sheet,
                    row: lane,
                    column: line,
                }
            } else {
                CellAddress {
                    sheet: range.sheet,
                    row: line,
                    column: lane,
                }
            }
        };
        lines.sort_by(|left, right| {
            for (lane, descending) in keys {
                let ordering = sort_compare_cased(
                    &self.cell_value(cell_at(*left, *lane)),
                    &self.cell_value(cell_at(*right, *lane)),
                    *descending,
                    match_case,
                );
                if ordering != Ordering::Equal {
                    return ordering;
                }
            }
            Ordering::Equal
        });
        // Read every line out before writing any back, since they swap places.
        let across = if sideways {
            (range.start_row, range.end_row)
        } else {
            (range.start_column, range.end_column)
        };
        let taken: Vec<Vec<Option<Cell>>> = lines
            .iter()
            .map(|line| {
                (across.0..=across.1)
                    .map(|lane| {
                        let address = cell_at(*line, lane);
                        self.workbook.sheets[address.sheet]
                            .rows
                            .iter()
                            .find(|row| row.index == address.row)
                            .and_then(|row| row.cells.iter().find(|cell| cell.col == address.column))
                            .cloned()
                    })
                    .collect()
            })
            .collect();

        for (offset, held) in taken.into_iter().enumerate() {
            let line = first + offset as u32;
            for (lane, cell) in (across.0..=across.1).zip(held) {
                let address = cell_at(line, lane);
                let sheet = &mut self.workbook.sheets[address.sheet];
                let row = match sheet.rows.iter().position(|row| row.index == address.row) {
                    Some(position) => &mut sheet.rows[position],
                    None => {
                        sheet.rows.push(Row {
                            index: address.row,
                            cells: Vec::new(),
                            height: None,
                            custom_height: false,
                            style_font: None,
                            thick_top: false,
                            thick_bottom: false,
                            hidden: false,
                        });
                        sheet.rows.sort_by_key(|row| row.index);
                        sheet
                            .rows
                            .iter_mut()
                            .find(|row| row.index == address.row)
                            .unwrap()
                    }
                };
                row.cells.retain(|held| held.col != address.column);
                if let Some(mut cell) = cell {
                    cell.col = address.column;
                    row.cells.push(cell);
                    row.cells.sort_by_key(|cell| cell.col);
                }
            }
        }
        Ok(())
    }

    fn sort_range(&mut self, range: CellRange, args: &[Value]) -> Result<(), String> {
        self.guard_sort(range)?;
        let given = |index: usize| match args.get(index) {
            Some(Value::Missing) | None => None,
            Some(value) => Some(value),
        };
        let match_case = given(9).is_some_and(|value| matches!(value, Value::Boolean(true)));
        let sideways = match given(10) {
            None => false,
            Some(value) => match sort_number(value, "Orientation")? {
                1 => false,
                2 => true,
                other => return Err(format!("Range.Sort has no orientation {other}")),
            },
        };
        let header = match given(7) {
            None => false,
            Some(value) => match sort_number(value, "Header")? {
                2 => false,
                1 => true,
                0 => self.guessed_header(range, sideways),
                other => return Err(format!("Range.Sort has no header setting {other}")),
            },
        };

        let mut keys = Vec::new();
        for (key, order) in [(0, 1), (2, 4), (5, 6)] {
            let Some(key) = given(key) else { continue };
            let Value::Object(object) = key else {
                return Err("Range.Sort takes a cell as a key".to_string());
            };
            let Some(key) = self.range(object) else {
                return Err("Range.Sort takes a cell as a key".to_string());
            };
            let lane = if sideways {
                key.start_row
            } else {
                key.start_column
            };
            let (first, last) = if sideways {
                (range.start_row, range.end_row)
            } else {
                (range.start_column, range.end_column)
            };
            if lane < first || lane > last {
                // Excel quietly sorts nothing here; saying so is more use.
                return Err("Range.Sort was given a key outside the range".to_string());
            }
            let descending = match given(order) {
                None => false,
                Some(value) => match sort_number(value, "Order")? {
                    1 => false,
                    2 => true,
                    other => return Err(format!("Range.Sort has no order {other}")),
                },
            };
            keys.push((lane, descending));
        }
        if keys.is_empty() {
            return Err("Range.Sort expects at least one key".to_string());
        }

        self.apply_sort(range, &keys, header, match_case, sideways)
    }

    fn fill_clipboard(&mut self, source: CellRange) -> Result<(), String> {
        Self::range_cell_count(source)?;
        let cells = source
            .addresses()
            .map(|address| {
                self.workbook.sheets[address.sheet]
                    .rows
                    .iter()
                    .find(|row| row.index == address.row)
                    .and_then(|row| row.cells.iter().find(|cell| cell.col == address.column))
                    .cloned()
            })
            .collect();
        let notes = source
            .addresses()
            .map(|address| self.note_at(address).map(|index| self.notes[index].clone()))
            .collect();
        let unlocked = source
            .addresses()
            .map(|address| self.unlocked.contains(&address))
            .collect();
        self.clipboard = Some(Clipboard {
            cells,
            notes,
            unlocked,
            rows: source.end_row - source.start_row + 1,
            columns: source.end_column - source.start_column + 1,
            origin: CellAddress {
                sheet: source.sheet,
                row: source.start_row,
                column: source.start_column,
            },
        });
        Ok(())
    }

    /// Pastes what `Copy` set aside. `xlPasteValues` drops formulas and keeps
    /// the value each cell was holding, `xlPasteFormats` keeps only the styling,
    /// and the default brings everything, moving a formula's relative
    /// references by the distance it travelled.
    fn paste_special(&mut self, target: CellRange, args: &[Value]) -> Result<Value, String> {
        let given = |index: usize| match args.get(index) {
            Some(Value::Missing) | None => None,
            Some(value) => Some(value),
        };
        let kind = match given(0) {
            None => -4104,
            Some(value) => sort_number(value, "PasteSpecial")?,
        };
        let carries = PasteWhat::of(kind)?;
        let operation = match given(1) {
            None => None,
            Some(value) => match sort_number(value, "PasteSpecial")? {
                -4142 => None,
                2 => Some('+'),
                3 => Some('-'),
                4 => Some('*'),
                5 => Some('/'),
                other => {
                    return Err(format!("Range.PasteSpecial cannot combine with {other}"))
                }
            },
        };
        let skip_blanks = given(2).is_some_and(|value| matches!(value, Value::Boolean(true)));
        let transpose = given(3).is_some_and(|value| matches!(value, Value::Boolean(true)));

        let Some(clipboard) = self.clipboard.take() else {
            return Err("Range.PasteSpecial has nothing to paste".to_string());
        };
        let (rows, columns) = if transpose {
            (clipboard.columns, clipboard.rows)
        } else {
            (clipboard.rows, clipboard.columns)
        };

        // A target larger than the block takes whole copies of it, and nothing
        // else: Excel refuses a target the block does not divide.
        let target_rows = target.end_row - target.start_row + 1;
        let target_columns = target.end_column - target.start_column + 1;
        let (down, across) = if target_rows == 1 && target_columns == 1 {
            (1, 1)
        } else if target_rows % rows == 0 && target_columns % columns == 0 {
            (target_rows / rows, target_columns / columns)
        } else {
            return Err(
                "Range.PasteSpecial needs a target the copied block fits into evenly".to_string(),
            );
        };

        if !carries.column_widths {
            let landing = CellRange {
                sheet: target.sheet,
                start_row: target.start_row,
                start_column: target.start_column,
                end_row: target.start_row + down * rows - 1,
                end_column: target.start_column + across * columns - 1,
            };
            if let Err(refused) = self.guard_locked_cells(landing, "Range.PasteSpecial") {
                self.clipboard = Some(clipboard);
                return Err(refused);
            }
        }
        if carries.column_widths {
            // Nothing about the cells changes: only how wide the columns they
            // sit in are. The width crosses as the file keeps it, so it
            // reads back the same on the other side.
            let from_sheet = clipboard.origin.sheet;
            for block_column in 0..across {
                for column in 0..columns {
                    let taken = self.workbook.sheets[from_sheet]
                        .col_widths
                        .get((clipboard.origin.column + column) as usize)
                        .copied()
                        .unwrap_or(0.0);
                    let onto = target.start_column + block_column * columns + column;
                    self.guard_column_formats(target.sheet, "setting a column width")?;
                    let sheet = &mut self.workbook.sheets[target.sheet];
                    let required = onto as usize + 1;
                    if sheet.col_widths.len() < required {
                        sheet.col_widths.resize(required, 0.0);
                    }
                    sheet.col_widths[onto as usize] = taken;
                    sheet.col_count = sheet.col_count.max(required);
                }
            }
            self.clipboard = Some(clipboard);
            return Ok(Value::Boolean(true));
        }

        for block_row in 0..down {
            for block_column in 0..across {
                for row in 0..rows {
                    for column in 0..columns {
                        let taken = if transpose {
                            (column * clipboard.columns + row) as usize
                        } else {
                            (row * clipboard.columns + column) as usize
                        };
                        let held = clipboard.cells.get(taken);
                        let address = CellAddress {
                            sheet: target.sheet,
                            row: target.start_row + block_row * rows + row,
                            column: target.start_column + block_column * columns + column,
                        };
                        // A formula moves by how far its own cell travelled,
                        // not by where the block's corner landed.
                        let came_from = CellAddress {
                            sheet: clipboard.origin.sheet,
                            row: clipboard.origin.row + if transpose { column } else { row },
                            column: clipboard.origin.column
                                + if transpose { row } else { column },
                        };
                        self.paste_cell(
                            address,
                            held.and_then(|cell| cell.as_ref()),
                            came_from,
                            carries,
                            transpose,
                            skip_blanks,
                            operation,
                        )?;
                        // Locked is one of the formats, and comes with them.
                        if carries.styles && self.cell_protection(address.sheet).is_none() {
                            if clipboard.unlocked.get(taken).copied().unwrap_or(false) {
                                self.unlocked.insert(address);
                            } else {
                                self.unlocked.remove(&address);
                            }
                        }
                        if carries.comments && !self.objects_protected(address.sheet) {
                            if let Some(index) = self.note_at(address) {
                                self.notes.remove(index);
                            }
                            if let Some(Some(note)) = clipboard.notes.get(taken) {
                                let mut note = note.clone();
                                note.at = address;
                                self.notes.push(note);
                            }
                        }
                    }
                }
            }
        }
        self.clipboard = Some(clipboard);
        Ok(Value::Boolean(true))
    }

    #[allow(clippy::too_many_arguments)]
    fn paste_cell(
        &mut self,
        address: CellAddress,
        held: Option<&Cell>,
        came_from: CellAddress,
        carries: PasteWhat,
        transpose: bool,
        skip_blanks: bool,
        operation: Option<char>,
    ) -> Result<(), String> {
        // A blank in the copied block is not put down at all when asked to be
        // skipped: asked of Excel, the cell under it keeps what it had.
        let blank = held.is_none_or(|held| {
            held.formula.is_none() && matches!(held.value, CellValue::Empty)
        });
        if skip_blanks && blank {
            return Ok(());
        }
        // Measured: on a protected sheet a paste onto an unlocked cell puts
        // the value down and none of the dress -- not the bold, not the
        // number format, not Locked -- and `xlPasteFormats` there changes
        // nothing and raises nothing.
        let dressing = carries.styles && self.cell_protection(address.sheet).is_none();
        let sheet = &mut self.workbook.sheets[address.sheet];
        sheet.col_count = sheet.col_count.max(address.column as usize + 1);
        let row = match sheet.rows.iter().position(|row| row.index == address.row) {
            Some(position) => &mut sheet.rows[position],
            None => {
                sheet.rows.push(Row {
                    index: address.row,
                    cells: Vec::new(),
                    height: None,
                    custom_height: false,
                    style_font: None,
                    thick_top: false,
                    thick_bottom: false,
                    hidden: false,
                });
                sheet.rows.sort_by_key(|row| row.index);
                sheet
                    .rows
                    .iter_mut()
                    .find(|row| row.index == address.row)
                    .unwrap()
            }
        };
        if row.cells.iter().all(|cell| cell.col != address.column) {
            row.cells.push(Cell {
                array_block: None,
                col: address.column,
                value: CellValue::Empty,
                style: CellStyle::default(),
                formula: None,
                runs: Vec::new(),
            });
            row.cells.sort_by_key(|cell| cell.col);
        }
        let cell = row
            .cells
            .iter_mut()
            .find(|cell| cell.col == address.column)
            .unwrap();

        if dressing {
            let coming = held.map(|held| held.style.clone()).unwrap_or_default();
            // The edges are part of the dress, and one kind of paste leaves
            // them behind: asked of Excel, `xlPasteAllExceptBorders` carries
            // the fill and the number format but leaves the line under the
            // cell as it found it.
            cell.style = if carries.borders {
                coming
            } else {
                CellStyle {
                    border_top: cell.style.border_top.clone(),
                    border_bottom: cell.style.border_bottom.clone(),
                    border_left: cell.style.border_left.clone(),
                    border_right: cell.style.border_right.clone(),
                    border_diagonal: cell.style.border_diagonal.clone(),
                    diagonal_up: cell.style.diagonal_up,
                    diagonal_down: cell.style.diagonal_down,
                    ..coming
                }
            };
        } else if carries.number_format {
            // The one kind that carries a number format and nothing else.
            cell.style.number_format = held.and_then(|held| held.style.number_format.clone());
        }
        if !carries.values {
            return Ok(());
        }
        if let Some(operation) = operation {
            // The destination is the LEFT side of the sum and what is being
            // put down is the right: asked of Excel, 100 with 10 added answers
            // 110, and `=A5+1` with `=C5*2` added answers `=(A5+1)+(C5*2)`.
            let held_formula = held
                .and_then(|held| held.formula.as_ref())
                .filter(|_| carries.formulas)
                .map(|formula| {
                    let row_offset = i64::from(address.row) - i64::from(came_from.row);
                    let column_offset =
                        i64::from(address.column) - i64::from(came_from.column);
                    oxicells_core::translate_formula_references(
                        formula,
                        row_offset,
                        column_offset,
                    )
                    .unwrap_or_else(|_| formula.clone())
                });
            let source = match held_formula {
                Some(formula) => Operand::Formula(formula),
                // A blank carries nothing, and nothing is worth zero.
                None => match held {
                    Some(held) => Operand::of(&held.value),
                    None => Operand::Number(0.0),
                },
            };
            let destination = match cell.formula.as_ref() {
                Some(formula) => Operand::Formula(formula.clone()),
                None => Operand::of(&cell.value),
            };
            if let Some(combined) = destination.combined(operation, &source) {
                match combined {
                    Combined::Value(value) => {
                        cell.value = value;
                        cell.formula = None;
                    }
                    Combined::Formula(formula) => {
                        cell.value = CellValue::Empty;
                        cell.formula = Some(formula);
                    }
                }
            }
            // Anything the sum cannot take part in — text, a Boolean, an
            // error, on either side — leaves the cell's own content alone.
            return Ok(());
        }
        let Some(held) = held else {
            cell.value = CellValue::Empty;
            cell.formula = None;
            cell.array_block = None;
            return Ok(());
        };
        cell.value = held.value.clone();
        cell.formula = None;
        // A copied array formula is an array formula where it lands, its
        // block moved with it: measured, P1:P2 copied onto Q1 answers
        // `CurrentArray` Q1:Q2. A block copied only in part, or turned,
        // comes down as its values.
        cell.array_block = match held.array_block {
            Some((top, left, bottom, right)) if carries.formulas && !transpose && !skip_blanks => {
                let down = i64::from(address.row) - i64::from(came_from.row);
                let across = i64::from(address.column) - i64::from(came_from.column);
                Some((
                    (i64::from(top) + down) as u32,
                    (i64::from(left) + across) as u32,
                    (i64::from(bottom) + down) as u32,
                    (i64::from(right) + across) as u32,
                ))
            }
            _ => None,
        };
        // Not every paste carries the formula; the ones that do move it with
        // the cell.
        if carries.formulas {
            if let Some(formula) = held.formula.as_ref() {
                let turned = if transpose {
                    // A relative reference is a distance, and turning the
                    // block a quarter turn swaps the two halves of it.
                    oxicells_core::transpose_formula_references(
                        formula,
                        (came_from.row.saturating_sub(1), came_from.column),
                        (address.row.saturating_sub(1), address.column),
                    )
                } else {
                    let row_offset = i64::from(address.row) - i64::from(came_from.row);
                    let column_offset = i64::from(address.column) - i64::from(came_from.column);
                    oxicells_core::translate_formula_references(
                        formula,
                        row_offset,
                        column_offset,
                    )
                };
                cell.formula = Some(turned.unwrap_or_else(|_| formula.clone()));
                cell.value = CellValue::Empty;
            }
        }
        Ok(())
    }

    /// Whether a range covers whole rows or whole columns, which is all that
    /// `Hidden` can speak about. Excel refuses part of a row, and refuses a
    /// range covering the whole sheet as well — `Cells.Hidden` raises either
    /// way round.
    fn hidden_band(range: CellRange) -> Result<ShiftAxis, String> {
        let whole_row = range.start_column == 0 && range.end_column == MAX_WORKSHEET_COLUMN;
        let whole_column = range.start_row == 1 && range.end_row == MAX_WORKSHEET_ROW;
        if whole_row && !whole_column {
            return Ok(ShiftAxis::Rows);
        }
        if whole_column && !whole_row {
            return Ok(ShiftAxis::Columns);
        }
        Err("Range.Hidden needs whole rows or whole columns".to_string())
    }

    /// True only when every row or column the range covers is hidden; a block
    /// with one visible line among them reads as False.
    fn range_hidden(&self, range: CellRange) -> Result<Value, String> {
        let sheet = &self.workbook.sheets[range.sheet];
        let hidden = match Self::hidden_band(range)? {
            // Measured: a row too short to show a pixel reads as hidden.
            ShiftAxis::Rows => (range.start_row..=range.end_row).all(|index| {
                sheet
                    .rows
                    .iter()
                    .find(|row| row.index == index)
                    .is_some_and(|row| row.hidden || self.row_px(range.sheet, index) == 0.0)
            }),
            ShiftAxis::Columns => (range.start_column..=range.end_column)
                .all(|column| sheet.hidden_cols.contains(&column)),
        };
        Ok(Value::Boolean(hidden))
    }

    fn set_range_hidden(&mut self, range: CellRange, hidden: bool) -> Result<(), String> {
        let axis = Self::hidden_band(range)?;
        let sheet = &mut self.workbook.sheets[range.sheet];
        match axis {
            ShiftAxis::Rows => {
                for index in range.start_row..=range.end_row {
                    match sheet.rows.iter_mut().find(|row| row.index == index) {
                        Some(row) => {
                            row.hidden = hidden;
                            // Measured: a row hidden by a height of 0 comes
                            // back at the default height when it is shown.
                            if !hidden && row.height.is_some_and(|height| height <= 0.0) {
                                row.height = None;
                                row.custom_height = false;
                            }
                        }
                        // A row with nothing in it still remembers being hidden.
                        None if hidden => {
                            sheet.rows.push(Row {
                                index,
                                cells: Vec::new(),
                                height: None,
                                custom_height: false,
                                style_font: None,
                                thick_top: false,
                                thick_bottom: false,
                                hidden: true,
                            });
                            sheet.rows.sort_by_key(|row| row.index);
                        }
                        None => {}
                    }
                }
            }
            ShiftAxis::Columns => {
                for column in range.start_column..=range.end_column {
                    let held = sheet.hidden_cols.contains(&column);
                    if hidden && !held {
                        sheet.hidden_cols.push(column);
                    } else if !hidden && held {
                        sheet.hidden_cols.retain(|candidate| *candidate != column);
                    }
                }
                sheet.hidden_cols.sort_unstable();
            }
        }
        Ok(())
    }

    /// Filters a range, hiding the rows that fail the test.
    ///
    /// With no arguments it turns filtering off and shows everything again.
    /// The header row is never hidden, and rows outside the range are left
    /// alone.
/// The hidden name Excel writes down when a filter goes on.
    ///
    /// Applying an AutoFilter creates a sheet-scoped `_FilterDatabase` over
    /// the filtered block. Measured: after `Range("A1:B4").AutoFilter Field:=1,
    /// Criteria1:=">2"`, `ActiveWorkbook.Names.Count` is 1, the one name is
    /// `Sheet1!_FilterDatabase`, it refers to `=Sheet1!$A$1:$B$4`, and its
    /// Visible is False.
    ///
    /// It is written ONCE. Filtering the same block again leaves one, and so
    /// does filtering a different block -- and when the second block is
    /// filtered the name still refers to the FIRST. Turning the filter off
    /// does not take it away either: the name outlives the filter that made
    /// it.
    fn note_filter_database(&mut self, range: CellRange) {
        let held = format!(
            "{}!_FilterDatabase",
            quoted_sheet(&self.workbook.sheets[range.sheet].name)
        );
        if self.name_at(&held).is_some() {
            return;
        }
        let refers_to = self.address_of(range);
        self.workbook.defined_names.push((held, refers_to));
    }

    fn auto_filter(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        let given = |index: usize| match args.get(index) {
            Some(Value::Missing) | None => None,
            Some(value) => Some(value),
        };
        if args.iter().all(|value| matches!(value, Value::Missing)) {
            // Excel treats a bare call as a switch: on becomes off.
            if self.auto_filter.is_some() {
                self.auto_filter = None;
                self.workbook.sheets[range.sheet].auto_filter = None;
                self.show_all_rows(range.sheet)?;
            } else {
                self.auto_filter = Some(AutoFilter {
                    range,
                    fields: Vec::new(),
                });
                self.note_filter_database(range);
            }
            return Ok(Value::Boolean(true));
        }

        self.note_filter_database(range);
        let Some(field) = given(0) else {
            return Err("Range.AutoFilter needs a field to filter on".to_string());
        };
        let field = positive_index(field, "AutoFilter field")?;
        let width = range.end_column - range.start_column + 1;
        if field > width {
            return Err(format!(
                "Range.AutoFilter field {field} is outside the {width}-column range"
            ));
        }
        let first = match given(1) {
            Some(value) => parse_criteria(&self.criteria_value(value)?),
            None => {
                return Err("Range.AutoFilter needs criteria to test against".to_string());
            }
        };
        let operator = match given(2) {
            None => 1,
            Some(value) => sort_number(value, "AutoFilter operator")?,
        };
        // A list of values is the same question asked of each of them:
        // `Array("10", "banana")` with xlFilterValues keeps a row holding
        // either, which is what two criteria joined by xlOr already mean.
        if operator == 7 {
            let Some(Value::Array(listed)) = given(1) else {
                return Err(
                    "Range.AutoFilter with xlFilterValues needs an array of values".to_string(),
                );
            };
            let criteria = listed
                .values
                .iter()
                .map(parse_criteria)
                .collect::<Vec<_>>();
            if criteria.is_empty() {
                return Err("Range.AutoFilter was given no values to keep".to_string());
            }
            return self.filter_on(range, field, criteria, true);
        }
        let either = match operator {
            1 => false,
            2 => true,
            other => return Err(format!("Range.AutoFilter cannot join criteria with {other}")),
        };
        let second = match given(3) {
            Some(value) => Some(parse_criteria(&self.criteria_value(value)?)),
            None => None,
        };

        let criteria = [Some(first), second].into_iter().flatten().collect();
        self.filter_on(range, field, criteria, either)
    }

    /// Put one column's test in place, keeping whatever the other columns ask.
    fn filter_on(
        &mut self,
        range: CellRange,
        field: u32,
        criteria: Vec<Criteria>,
        either: bool,
    ) -> Result<Value, String> {
        let mut filter = match self.auto_filter.take() {
            Some(filter) if ranges_equal(filter.range, range) => filter,
            _ => AutoFilter {
                range,
                fields: Vec::new(),
            },
        };
        filter.fields.retain(|held| held.field != field);
        filter.fields.push(FieldTest {
            field,
            criteria,
            either,
        });
        self.apply_auto_filter(&filter)?;
        self.record_auto_filter(&filter);
        self.auto_filter = Some(filter);
        Ok(Value::Boolean(true))
    }

    /// Whether the first line of a range reads as a heading.
    ///
    /// Asked of Excel with `xlGuess`: a first row that DIFFERS from the row
    /// under it is a heading, and it differs either in what it holds — text
    /// over numbers — or in how it is dressed. Bold, a fill, a larger face and
    /// an underline each made Excel keep the first row where it was, while a
    /// plain row like the ones below it was sorted with them. A first row that
    /// is empty is not a heading, whatever is under it.
    fn guessed_header(&self, range: CellRange, sideways: bool) -> bool {
        let (along, across) = if sideways {
            (range.end_column - range.start_column, range.end_row - range.start_row)
        } else {
            (range.end_row - range.start_row, range.end_column - range.start_column)
        };
        if along == 0 {
            return false;
        }
        let at = |first: bool, step: u32| {
            let (row, column) = if sideways {
                (range.start_row + step, range.start_column + u32::from(!first))
            } else {
                (range.start_row + u32::from(!first), range.start_column + step)
            };
            self.workbook
                .sheets
                .get(range.sheet)
                .and_then(|sheet| sheet.rows.iter().find(|held| held.index == row))
                .and_then(|held| held.cells.iter().find(|cell| cell.col == column))
        };
        let kind = |cell: Option<&Cell>| match cell.map(|cell| &cell.value) {
            None | Some(CellValue::Empty) => 0,
            Some(CellValue::Number(_)) => 1,
            Some(CellValue::Boolean(_)) => 2,
            Some(CellValue::Error(_)) => 3,
            _ => 4,
        };
        if (0..=across).all(|step| kind(at(true, step)) == 0) {
            return false;
        }
        (0..=across).any(|step| {
            let (head, below) = (at(true, step), at(false, step));
            kind(head) != kind(below)
                || head.map(|cell| &cell.style) != below.map(|cell| &cell.style)
        })
    }

    fn apply_auto_filter(&mut self, filter: &AutoFilter) -> Result<(), String> {
        // The first row of the range holds the headings, and stays put.
        for row in (filter.range.start_row + 1)..=filter.range.end_row {
            let showing = filter.fields.iter().all(|test| {
                let value = self.cell_value(CellAddress {
                    sheet: filter.range.sheet,
                    row,
                    column: filter.range.start_column + test.field - 1,
                });
                if test.either {
                    test.criteria.iter().any(|one| one.matches(&value))
                } else {
                    test.criteria.iter().all(|one| one.matches(&value))
                }
            });
            self.set_row_visible(filter.range.sheet, row, showing);
        }
        Ok(())
    }

    /// Writes the filter onto the sheet, so saving the workbook keeps it.
    fn record_auto_filter(&mut self, filter: &AutoFilter) {
        let columns = filter
            .fields
            .iter()
            .map(|test| oxicells_core::ir::AutoFilterColumn {
                field: test.field,
                criteria: test.criteria.iter().map(criteria_text).collect(),
                either: test.either,
            })
            .collect();
        self.workbook.sheets[filter.range.sheet].auto_filter =
            Some(oxicells_core::ir::AutoFilter {
                start_row: filter.range.start_row,
                start_col: filter.range.start_column,
                end_row: filter.range.end_row,
                end_col: filter.range.end_column,
                columns,
            });
    }

    fn set_row_visible(&mut self, sheet: usize, row: u32, showing: bool) {
        let Some(worksheet) = self.workbook.sheets.get_mut(sheet) else {
            return;
        };
        match worksheet.rows.iter_mut().find(|held| held.index == row) {
            Some(held) => held.hidden = !showing,
            None if !showing => {
                worksheet.rows.push(Row {
                    index: row,
                    cells: Vec::new(),
                    height: None,
                    custom_height: false,
                    style_font: None,
                    thick_top: false,
                    thick_bottom: false,
                    hidden: true,
                });
                worksheet.rows.sort_by_key(|row| row.index);
            }
            None => {}
        }
    }

    fn show_all_rows(&mut self, sheet: usize) -> Result<(), String> {
        let Some(worksheet) = self.workbook.sheets.get_mut(sheet) else {
            return Err("worksheet is out of range".to_string());
        };
        for row in &mut worksheet.rows {
            row.hidden = false;
        }
        Ok(())
    }

    fn merge_range(&mut self, range: CellRange) -> Result<(), String> {
        if range.is_single() {
            return Ok(());
        }
        self.guard_formats(range.sheet, "merging cells")?;
        let sheet = self
            .workbook
            .sheets
            .get_mut(range.sheet)
            .ok_or_else(|| "worksheet no longer exists".to_string())?;
        for existing in &sheet.merge_cells {
            let existing = merge_range(range.sheet, existing);
            if ranges_overlap(range, existing) {
                if ranges_equal(range, existing) {
                    return Ok(());
                }
                return Err("Range.Merge overlaps an existing merged range".to_string());
            }
        }
        for row in &mut sheet.rows {
            if !(range.start_row..=range.end_row).contains(&row.index) {
                continue;
            }
            for cell in &mut row.cells {
                if (range.start_column..=range.end_column).contains(&cell.col)
                    && !(row.index == range.start_row && cell.col == range.start_column)
                {
                    cell.value = CellValue::Empty;
                    cell.formula = None;
                }
            }
        }
        sheet.merge_cells.push(MergeCell {
            start_row: range.start_row,
            start_col: range.start_column,
            end_row: range.end_row,
            end_col: range.end_column,
        });
        sheet.merge_cells.sort_by_key(|merge| {
            (
                merge.start_row,
                merge.start_col,
                merge.end_row,
                merge.end_col,
            )
        });
        Ok(())
    }

    fn unmerge_range(&mut self, range: CellRange) -> Result<(), String> {
        let sheet = self
            .workbook
            .sheets
            .get_mut(range.sheet)
            .ok_or_else(|| "worksheet no longer exists".to_string())?;
        sheet
            .merge_cells
            .retain(|merge| !ranges_overlap(range, merge_range(range.sheet, merge)));
        Ok(())
    }

    fn range_merge_state(&self, range: CellRange) -> Result<Value, String> {
        let sheet = self
            .workbook
            .sheets
            .get(range.sheet)
            .ok_or_else(|| "worksheet no longer exists".to_string())?;
        let mut overlaps = sheet
            .merge_cells
            .iter()
            .map(|merge| merge_range(range.sheet, merge))
            .filter(|merge| ranges_overlap(range, *merge));
        let Some(merge) = overlaps.next() else {
            return Ok(Value::Boolean(false));
        };
        if overlaps.next().is_none() && range_contains(merge, range) {
            Ok(Value::Boolean(true))
        } else {
            Ok(Value::Null)
        }
    }

    /// Move a block of cells, taking the references that named them along.
    ///
    /// A cut is not a copy. The cells LEAVE — value, formula and format — and
    /// every reference that named one of them follows it, absolute halves and
    /// other sheets included: asked of Excel, cutting `A2:B3` onto `D2` leaves
    /// `=SUM(A2:B3)` reading `=SUM(D2:E3)` and `=$A$2` reading `=$D$2`, while
    /// `=SUM(A1:B4)`, which reaches past the block, is left alone. A reference
    /// to a cell the block LANDS on has nothing left to name and becomes
    /// `#REF!`.
    ///
    /// Only the destination's top-left corner is used. Asked of Excel, two
    /// cells cut onto a five-cell destination fill the first two and leave the
    /// rest as they were, and one cell cut onto a block fills its corner.
    fn cut_range(&mut self, source: CellRange, args: &[Value]) -> Result<Value, String> {
        let destination = match args {
            [] | [Value::Missing] => {
                // Nothing said about where: the block waits for a Paste, and
                // Excel says so through `Application.CutCopyMode`.
                Self::range_cell_count(source)?;
                self.clipboard = None;
                self.pending_cut = Some(source);
                return Ok(Value::Boolean(true));
            }
            [Value::Object(destination)] => self
                .range(destination)
                .ok_or_else(|| "Range.Cut destination must be a Range".to_string())?,
            _ => return Err("Range.Cut takes one destination Range".to_string()),
        };
        self.move_cells(source, destination)
    }

    /// Put down whatever Copy or Cut set aside.
    ///
    /// Asked of Excel: with no destination it lands on the selection; what a
    /// COPY set aside can be put down again and again, while what a CUT set
    /// aside is MOVED, and `CutCopyMode` goes back to nothing afterwards.
    /// Pasting with nothing held raises.
    fn paste_held(&mut self, args: &[Value]) -> Result<Value, String> {
        let target = match args {
            [] | [Value::Missing] => self.selection,
            [Value::Object(destination)] => self
                .range(destination)
                .ok_or_else(|| "Worksheet.Paste destination must be a Range".to_string())?,
            _ => return Err("Worksheet.Paste takes one destination Range".to_string()),
        };
        if let Some(source) = self.pending_cut.take() {
            return self.move_cells(source, target);
        }
        if self.clipboard.is_none() {
            return Err("Worksheet.Paste has nothing to put down".to_string());
        }
        self.paste_special(target, &[])
    }

    /// Carry a block to where the destination's corner is, references and all.
    fn move_cells(&mut self, source: CellRange, destination: CellRange) -> Result<Value, String> {
        Self::range_cell_count(source)?;
        let row_count = source.end_row - source.start_row + 1;
        let column_count = source.end_column - source.start_column + 1;
        destination
            .start_row
            .checked_add(row_count - 1)
            .filter(|row| *row <= MAX_WORKSHEET_ROW)
            .ok_or_else(|| "Range.Cut destination extends beyond the worksheet rows".to_string())?;
        destination
            .start_column
            .checked_add(column_count - 1)
            .filter(|column| *column <= MAX_WORKSHEET_COLUMN)
            .ok_or_else(|| {
                "Range.Cut destination extends beyond the worksheet columns".to_string()
            })?;
        let down = i64::from(destination.start_row) - i64::from(source.start_row);
        let across = i64::from(destination.start_column) - i64::from(source.start_column);
        if down == 0 && across == 0 && destination.sheet == source.sheet {
            return Ok(Value::Empty);
        }
        self.arrays_allow(source, false)?;
        let landing_range = CellRange {
            sheet: destination.sheet,
            start_row: destination.start_row,
            start_column: destination.start_column,
            end_row: destination.start_row + row_count - 1,
            end_column: destination.start_column + column_count - 1,
        };
        self.arrays_allow(landing_range, false)?;

        // Lift the whole block before putting any of it down, so that a move
        // onto its own cells does not eat what it has not carried yet.
        let carried = source
            .addresses()
            .map(|address| self.take_cell(address))
            .collect::<Vec<_>>();
        let notes = source
            .addresses()
            .map(|address| self.note_at(address).map(|index| self.notes.remove(index)))
            .collect::<Vec<_>>();
        let unlocked = source
            .addresses()
            .map(|address| self.unlocked.remove(&address))
            .collect::<Vec<_>>();
        let marks = source
            .addresses()
            .map(|address| self.take_marks(address))
            .collect::<Vec<_>>();
        for ((((address, cell), note), was_unlocked), marks) in source
            .addresses()
            .zip(carried)
            .zip(notes)
            .zip(unlocked)
            .zip(marks)
        {
            let landing = CellAddress {
                sheet: destination.sheet,
                row: (i64::from(address.row) + down) as u32,
                column: (i64::from(address.column) + across) as u32,
            };
            self.put_cell(landing, cell)?;
            if let Some(cell) = self.cell_mut(landing) {
                if let Some((top, left, bottom, right)) = cell.array_block {
                    cell.array_block = Some((
                        (i64::from(top) + down) as u32,
                        (i64::from(left) + across) as u32,
                        (i64::from(bottom) + down) as u32,
                        (i64::from(right) + across) as u32,
                    ));
                }
            }
            self.put_marks(landing, marks);
            if let Some(index) = self.note_at(landing) {
                self.notes.remove(index);
            }
            if let Some(mut note) = note {
                note.at = landing;
                self.notes.push(note);
            }
            if was_unlocked {
                self.unlocked.insert(landing);
            } else {
                self.unlocked.remove(&landing);
            }
        }

        let from_sheet = self.workbook.sheets[source.sheet].name.clone();
        let to_sheet = self.workbook.sheets[destination.sheet].name.clone();
        let corners = (
            source.start_row.saturating_sub(1),
            source.start_column,
            source.end_row.saturating_sub(1),
            source.end_column,
        );

        // A name is a reference too, and it follows the cells the same way.
        // Asked of Excel, a name standing for `Sheet2!$A$1:$A$5` reads
        // `=Sheet2!$D$1:$D$5` once those cells are cut onto D1. A name always
        // says which sheet it means, so it is read and written against none.
        let names = CellMove {
            first_row: corners.0,
            first_column: corners.1,
            last_row: corners.2,
            last_column: corners.3,
            down,
            across,
            from_sheet: Some(from_sheet.as_str()),
            to_sheet: Some(to_sheet.as_str()),
            read_as: None,
            written_on: None,
        };
        for (_, refers_to) in &mut self.workbook.defined_names {
            if let Ok(rewritten) = move_formula_references(refers_to, &names) {
                *refers_to = rewritten;
            }
        }
        let landed_rows = (source.start_row as i64 + down)..=(source.end_row as i64 + down);
        let landed_columns =
            (source.start_column as i64 + across)..=(source.end_column as i64 + across);
        for (index, worksheet) in self.workbook.sheets.iter_mut().enumerate() {
            let written_on = worksheet.name.clone();
            for row in &mut worksheet.rows {
                for cell in &mut row.cells {
                    let Some(formula) = cell.formula.as_deref() else {
                        continue;
                    };
                    // A formula that TRAVELLED still says what it said on the
                    // sheet it came from, so that is where its unqualified
                    // references have to be read.
                    let carried = index == destination.sheet
                        && landed_rows.contains(&i64::from(row.index))
                        && landed_columns.contains(&i64::from(cell.col));
                    let moved = CellMove {
                        first_row: corners.0,
                        first_column: corners.1,
                        last_row: corners.2,
                        last_column: corners.3,
                        down,
                        across,
                        from_sheet: Some(from_sheet.as_str()),
                        to_sheet: Some(to_sheet.as_str()),
                        read_as: Some(if carried {
                            from_sheet.as_str()
                        } else {
                            written_on.as_str()
                        }),
                        written_on: Some(written_on.as_str()),
                    };
                    // A formula this build cannot read is left exactly as it
                    // was: half a rewrite would move some of its references
                    // and not the others.
                    if let Ok(rewritten) = move_formula_references(formula, &moved) {
                        cell.formula = Some(rewritten);
                    }
                }
            }
        }
        Ok(Value::Empty)
    }

    /// Lift a cell off the sheet, leaving nothing behind — not its value, not
    /// its formula, and not the face it was wearing.
    fn take_cell(&mut self, address: CellAddress) -> Option<Cell> {
        self.wrote = true;
        let sheet = self.workbook.sheets.get_mut(address.sheet)?;
        let row = sheet.rows.iter_mut().find(|row| row.index == address.row)?;
        let at = row.cells.iter().position(|cell| cell.col == address.column)?;
        Some(row.cells.remove(at))
    }

    /// Put one down, or clear what is there when the block carried a blank.
    fn put_cell(&mut self, address: CellAddress, cell: Option<Cell>) -> Result<(), String> {
        self.take_cell(address);
        let Some(cell) = cell else {
            return Ok(());
        };
        self.set_cell_value(address, CellValue::Empty)?;
        let sheet = &mut self.workbook.sheets[address.sheet];
        let landed = sheet
            .rows
            .iter_mut()
            .find(|row| row.index == address.row)
            .and_then(|row| row.cells.iter_mut().find(|held| held.col == address.column))
            .expect("set_cell_value creates the cell");
        *landed = Cell {
            col: address.column,
            ..cell
        };
        Ok(())
    }

    fn copy_range(&mut self, source: CellRange, args: &[Value]) -> Result<Value, String> {
        if args.is_empty() || matches!(args, [Value::Missing]) {
            self.fill_clipboard(source)?;
            return Ok(Value::Boolean(true));
        }
        let [Value::Object(destination)] = args else {
            return Err("Range.Copy expects one destination Range".to_string());
        };
        let destination = self
            .range(destination)
            .ok_or_else(|| "Range.Copy destination must be a Range".to_string())?;
        Self::range_cell_count(source)?;
        let row_count = source.end_row - source.start_row + 1;
        let column_count = source.end_column - source.start_column + 1;
        let end_row = destination
            .start_row
            .checked_add(row_count - 1)
            .filter(|row| *row <= MAX_WORKSHEET_ROW)
            .ok_or_else(|| {
                "Range.Copy destination extends beyond the worksheet rows".to_string()
            })?;
        let end_column = destination
            .start_column
            .checked_add(column_count - 1)
            .filter(|column| *column <= MAX_WORKSHEET_COLUMN)
            .ok_or_else(|| {
                "Range.Copy destination extends beyond the worksheet columns".to_string()
            })?;
        let destination = CellRange {
            sheet: destination.sheet,
            start_row: destination.start_row,
            start_column: destination.start_column,
            end_row,
            end_column,
        };
        let row_offset = i64::from(destination.start_row) - i64::from(source.start_row);
        let column_offset = i64::from(destination.start_column) - i64::from(source.start_column);
        self.guard_locked_cells(destination, "Range.Copy")?;
        let worksheet = self
            .workbook
            .sheets
            .get(source.sheet)
            .ok_or_else(|| "worksheet no longer exists".to_string())?;
        let copied = source
            .addresses()
            .map(|address| {
                worksheet
                    .rows
                    .iter()
                    .find(|row| row.index == address.row)
                    .and_then(|row| row.cells.iter().find(|cell| cell.col == address.column))
                    .map(|cell| {
                        let formula = cell
                            .formula
                            .as_deref()
                            .map(|formula| {
                                oxicells_core::translate_formula_references(
                                    formula,
                                    row_offset,
                                    column_offset,
                                )
                                .map_err(|error| {
                                    format!("Range.Copy cannot adjust formula {formula:?}: {error}")
                                })
                            })
                            .transpose()?;
                        // An array formula's block goes along when the whole
                        // of it is copied; a part of one comes down as values.
                        let block = cell.array_block.filter(|(top, left, bottom, right)| {
                            *top >= source.start_row
                                && *bottom <= source.end_row
                                && *left >= source.start_column
                                && *right <= source.end_column
                        });
                        let (formula, block) = match block {
                            Some((top, left, bottom, right)) => (
                                cell.formula.clone(),
                                Some((
                                    (i64::from(top) + row_offset) as u32,
                                    (i64::from(left) + column_offset) as u32,
                                    (i64::from(bottom) + row_offset) as u32,
                                    (i64::from(right) + column_offset) as u32,
                                )),
                            ),
                            None if cell.array_block.is_some() => (None, None),
                            None => (formula, None),
                        };
                        Ok::<_, String>((
                            cell.value.clone(),
                            cell.style.clone(),
                            formula,
                            cell.runs.clone(),
                            block,
                        ))
                    })
                    .unwrap_or_else(|| {
                        Ok((CellValue::Empty, CellStyle::default(), None, Vec::new(), None))
                    })
            })
            .collect::<Result<Vec<_>, _>>()?;
        self.arrays_allow(destination, false)?;
        // On a protected sheet the value arrives and the dress does not; see
        // `paste_cell`.
        let dressing = self.cell_protection(destination.sheet).is_none();
        for (address, (value, style, formula, runs, block)) in destination.addresses().zip(copied) {
            self.set_cell_value(address, value)?;
            let sheet = &mut self.workbook.sheets[address.sheet];
            let cell = sheet
                .rows
                .iter_mut()
                .find(|row| row.index == address.row)
                .and_then(|row| row.cells.iter_mut().find(|cell| cell.col == address.column))
                .expect("set_cell_value creates the destination cell");
            if dressing {
                cell.style = style;
                cell.runs = runs;
            }
            if formula.is_some() {
                cell.value = CellValue::Empty;
            }
            cell.formula = formula;
            cell.array_block = block;
        }
        if dressing {
            self.carry_side_tables(source, destination);
        } else if !self.objects_protected(destination.sheet) {
            self.carry_notes(source, destination);
        }
        Ok(Value::Empty)
    }

    /// The notes alone, for a copy whose dress is not allowed through.
    fn carry_notes(&mut self, source: CellRange, destination: CellRange) {
        let pairs: Vec<(CellAddress, CellAddress)> =
            source.addresses().zip(destination.addresses()).collect();
        for (from, to) in pairs {
            if from == to {
                continue;
            }
            if let Some(index) = self.note_at(to) {
                self.notes.remove(index);
            }
            if let Some(index) = self.note_at(from) {
                let mut note = self.notes[index].clone();
                note.at = to;
                self.notes.push(note);
            }
        }
    }

    /// What a copy carries besides the cells: the note on each, and whether
    /// each is locked -- Locked being a format, and a note going with its
    /// cell.
    fn carry_side_tables(&mut self, source: CellRange, destination: CellRange) {
        let pairs: Vec<(CellAddress, CellAddress)> =
            source.addresses().zip(destination.addresses()).collect();
        for (from, to) in pairs {
            if from == to {
                continue;
            }
            if self.unlocked.contains(&from) {
                self.unlocked.insert(to);
            } else {
                self.unlocked.remove(&to);
            }
            match self.styled.get(&from).copied() {
                Some(style) => {
                    self.styled.insert(to, style);
                }
                None => {
                    self.styled.remove(&to);
                }
            }
            let paints: Vec<(Paint, (usize, f64))> = self
                .theme_paint
                .iter()
                .filter(|((held, _), _)| *held == from)
                .map(|((_, paint), painted)| (*paint, *painted))
                .collect();
            self.theme_paint.retain(|(held, _), _| *held != to);
            for (paint, painted) in paints {
                self.theme_paint.insert((to, paint), painted);
            }
            let marks = self.marks_of(from);
            self.put_marks(to, marks);
            if let Some(index) = self.note_at(to) {
                self.notes.remove(index);
            }
            if let Some(index) = self.note_at(from) {
                let mut note = self.notes[index].clone();
                note.at = to;
                self.notes.push(note);
            }
            match self.validations.get(&from).cloned() {
                Some(validation) => {
                    self.validations.insert(to, validation);
                }
                None => {
                    self.validations.remove(&to);
                }
            }
            // The conditions on the cell come along as conditions of their
            // own on the new cell: measured, a copied cell answers
            // `AppliesTo.Address` for itself alone.
            let to_one = CellRange::single(to);
            self.drop_conditions_on(to_one);
            let carried: Vec<Condition> = self
                .conditions
                .iter()
                .filter(|condition| {
                    condition.sheet == from.sheet
                        && condition
                            .applies
                            .iter()
                            .any(|block| range_within(CellRange::single(from), *block))
                })
                .cloned()
                .collect();
            for mut condition in carried {
                condition.id = self.next_condition;
                self.next_condition += 1;
                condition.sheet = to.sheet;
                condition.applies = vec![to_one];
                condition.priority = self.last_condition_priority(to.sheet) + 1;
                self.conditions.push(condition);
            }
            let (from_one, to_one) = (CellRange::single(from), CellRange::single(to));
            self.links.retain(|link| !ranges_equal(link.anchor, to_one));
            if let Some(link) = self.links.iter().find(|link| ranges_equal(link.anchor, from_one)) {
                let mut link = link.clone();
                link.id = self.next_link;
                link.anchor = to_one;
                self.next_link += 1;
                self.links.push(link);
            }
        }
    }

    /// `Comments(n)` / `Comments.Item(n)`.
    fn comment_item(&mut self, sheet: usize, wanted: &Value) -> Result<Value, String> {
        let index = positive_index(wanted, "Comments index")? as usize;
        let held = self.notes_on(sheet);
        let Some(&note) = held.get(index - 1) else {
            return Err(format!("the sheet has no comment number {index}"));
        };
        let at = self.notes[note].at;
        Ok(self.object(HostObject::Comment(at)))
    }

    /// `Range.NoteText [Text], [Start], [Length]`, on the range's top-left
    /// cell.
    ///
    /// Reading with a start and length answers that slice of the note.
    /// Writing with a start puts the text in at that character and drops the
    /// rest, the way `Comment.Text` does with `Overwrite` left out --
    /// measured, `NoteText "xyz", 2` on `n2` gives `nxyz`.
    fn note_text_member(&mut self, range: CellRange, args: &[Value]) -> Result<Value, String> {
        let at = CellAddress {
            sheet: range.sheet,
            row: range.start_row,
            column: range.start_column,
        };
        let given = |index: usize| match args.get(index) {
            Some(Value::Missing) | None => None,
            Some(value) => Some(value),
        };
        let start = match given(1) {
            None => None,
            Some(value) => Some(sort_number(value, "Range.NoteText Start")?),
        };
        if let Some(start) = start {
            if start < 1 {
                return Err(host_error(5, "Range.NoteText cannot start before the first character"));
            }
        }
        match given(0) {
            None => {
                let held = self
                    .note_at(at)
                    .map(|index| self.notes[index].text.clone())
                    .unwrap_or_default();
                let from = start.unwrap_or(1) as usize - 1;
                let taken: String = match given(2) {
                    None => held.chars().skip(from).collect(),
                    Some(length) => {
                        let length = sort_number(length, "Range.NoteText Length")?;
                        if length < 0 {
                            return Err(host_error(5, "Range.NoteText cannot take a negative length"));
                        }
                        held.chars().skip(from).take(length as usize).collect()
                    }
                };
                Ok(Value::String(taken))
            }
            Some(text) => {
                // The old door is guarded like the cell: measured, `NoteText
                // "nt"` on a locked cell of a protected sheet is 1004.
                if self.write_is_protected(at) {
                    return Err(
                        "the cell is locked and the sheet is protected; unprotect it first"
                            .to_string(),
                    );
                }
                let text = shown_text(text, None);
                // An empty text takes the note away altogether.
                if text.is_empty() {
                    self.clear_comments(CellRange::single(at));
                    return Ok(Value::String(text));
                }
                let text = match (self.note_at(at), start) {
                    (Some(index), Some(start)) => {
                        let kept: String =
                            self.notes[index].text.chars().take(start as usize - 1).collect();
                        format!("{kept}{text}")
                    }
                    _ => text,
                };
                match self.note_at(at) {
                    Some(index) => self.notes[index].text = text.clone(),
                    None => {
                        self.add_comment(CellRange::single(at), &[Value::String(text.clone())])?;
                    }
                }
                Ok(Value::String(text))
            }
        }
    }
}

impl Host for WorkbookHost<'_> {
    fn call(
        &mut self,
        receiver: Option<&ObjectRef>,
        name: &str,
        args: &[Value],
    ) -> Result<Option<Value>, String> {
        if let Some(receiver) = receiver {
            if self.gone(receiver) {
                return Err(host_error(424, "the object's worksheet has been deleted"));
            }
            if let Some(sheet) = self.outline_sheet(receiver) {
                if name.eq_ignore_ascii_case("showlevels") {
                    return self.show_outline_levels(sheet, args).map(Some);
                }
                return Ok(None);
            }
            if let Some(part) = self.drawing_part(receiver) {
                return self.drawing_call(part, name, args);
            }
            if let Some(HostObject::Sort(sheet)) = self.objects.get(receiver.handle as usize).copied() {
                return self.sort_object_call(sheet, name, args).map(Some);
            }
            if let Some(HostObject::SortFields(sheet)) = self.objects.get(receiver.handle as usize).copied() {
                return self.sort_fields_call(sheet, name, args).map(Some);
            }
            if self.is_workbooks(receiver) {
                return match name.to_ascii_lowercase().as_str() {
                    "item" => match args {
                        [index] => self.workbook_item(index).map(Some),
                        _ => Err("Workbooks.Item takes one index".to_string()),
                    },
                    "count" => Ok(Some(Value::Integer(1))),
                    "add" | "open" | "opentext" => Err(host_error(
                        1004,
                        "the browser has one workbook open and cannot open another",
                    )),
                    _ => Ok(None),
                };
            }
            // EVERY Excel object can be asked for the Application, and it
            // always answers the same one. Measured: `Range("A1").Application`,
            // `ActiveSheet.Application` and `ActiveWorkbook.Application` are
            // all an Application, and so is `ActiveWorkbook.Parent` and
            // `Application.Parent` -- the Application being its own parent is
            // where the chain stops.
            //
            // It was reachable only as a bare global before, so every one of
            // those answered 438: the object was there and no door led to it.
            if name.eq_ignore_ascii_case("application") && args.is_empty() {
                return Ok(Some(self.object(HostObject::Application)));
            }
            if name.eq_ignore_ascii_case("parent")
                && args.is_empty()
                && (self.is_workbook(receiver) || self.is_application(receiver))
            {
                return Ok(Some(self.object(HostObject::Application)));
            }
            if self.is_application(receiver) && name.eq_ignore_ascii_case("name") {
                // What Excel calls itself, which is also the Application's
                // default member -- `CStr(Range("A1").Application)` is
                // `Microsoft Excel`.
                return Ok(Some(Value::String("Microsoft Excel".to_string())));
            }
            // What the Excel this host is measured against says about
            // itself. A macro that asks is usually deciding whether a member
            // exists, and 16.0 has them all.
            if self.is_application(receiver) && name.eq_ignore_ascii_case("version") {
                return Ok(Some(Value::String("16.0".to_string())));
            }
            if self.is_application(receiver) && name.eq_ignore_ascii_case("operatingsystem") {
                return Ok(Some(Value::String("Windows (64-bit) NT 10.00".to_string())));
            }
            if self.is_application(receiver) && name.eq_ignore_ascii_case("build") {
                return Ok(Some(Value::Integer(20326)));
            }
            // The two rulers page setup is measured with: measured,
            // `InchesToPoints(1)` is 72 and `CentimetersToPoints(2)` is
            // 56.6929133858268.
            if self.is_application(receiver)
                && (name.eq_ignore_ascii_case("inchestopoints")
                    || name.eq_ignore_ascii_case("centimeterstopoints"))
            {
                let [measure] = args else {
                    return Err(format!("Application.{name} takes one number"));
                };
                let measure = any_number(measure)
                    .ok_or_else(|| format!("Application.{name} takes one number"))?;
                let points = if name.eq_ignore_ascii_case("inchestopoints") {
                    measure * 72.0
                } else {
                    measure * 72.0 / 2.54
                };
                return Ok(Some(Value::Double(points)));
            }
            if self.is_worksheet_function(receiver) {
                // Measured: `WorksheetFunction.Sqrt` is error 438 -- VBA has
                // `Sqr`, and Excel leaves such names off the object.
                if vba_has_its_own(name) {
                    return Ok(None);
                }
                return self.worksheet_function(name, args).map(Some);
            }
            if self.is_debug_console(receiver) && name.eq_ignore_ascii_case("print") {
                let mut printed = Vec::with_capacity(args.len());
                for value in args {
                    printed.push(format_debug_value(&self.printed_value(value)?));
                }
                self.debug_output.push(printed.join("\t"));
                return Ok(Some(Value::Empty));
            }
            if let Some(sheet) = self.worksheet(receiver) {
                if name.eq_ignore_ascii_case("paste") {
                    if sheet != self.active_sheet {
                        return Err(
                            "Worksheet.Paste requires its worksheet to be active".to_string()
                        );
                    }
                    if let Some(pasted) = self.paste_shape(sheet)? {
                        return Ok(Some(pasted));
                    }
                    return self.paste_held(args).map(Some);
                }
                // True, like every other member that DOES something: asked
                // of Excel, `r = ActiveSheet.Calculate` and
                // `r = ActiveSheet.Activate` are both Booleans.
                if name.eq_ignore_ascii_case("calculate") {
                    self.recalculate();
                    return Ok(Some(Value::Boolean(true)));
                }
                if name.eq_ignore_ascii_case("comments") {
                    return match args {
                        [] => Ok(Some(self.object(HostObject::Comments(sheet)))),
                        [wanted] => self.comment_item(sheet, wanted).map(Some),
                        _ => Err("Comments expects zero or one argument".to_string()),
                    };
                }
                if name.eq_ignore_ascii_case("hyperlinks") {
                    let scope = HyperlinkScope::Sheet(sheet);
                    return match args {
                        [] => Ok(Some(self.object(HostObject::Hyperlinks(scope)))),
                        [wanted] => self.hyperlink_item(scope, wanted).map(Some),
                        _ => Err("Hyperlinks expects zero or one argument".to_string()),
                    };
                }
                if name.eq_ignore_ascii_case("listobjects") {
                    return match args {
                        [] => Ok(Some(self.object(HostObject::ListObjects(sheet)))),
                        [wanted] => self.list_objects_member(sheet, "item", std::slice::from_ref(wanted)),
                        _ => Err("ListObjects expects zero or one argument".to_string()),
                    };
                }
                if name.eq_ignore_ascii_case("pagesetup") && args.is_empty() {
                    return Ok(Some(self.object(HostObject::PageSetup(sheet))));
                }
                // `Protect [password, ...]` and `Unprotect [password]`.
                // Measured: a wrong password on Unprotect is error 1004 and
                // leaves the sheet protected; no password either way is fine;
                // `Protect` on a sheet already protected changes nothing, not
                // even the password; and `r = ActiveSheet.Protect("pw")`
                // answers Empty, not the True the doing-members give.
                if name.eq_ignore_ascii_case("protect") {
                    let asked = Protection::asked(args)?;
                    if self.protected.len() <= sheet {
                        self.protected.resize(sheet + 1, None);
                    }
                    if self.protected[sheet].is_none() {
                        self.protected[sheet] = Some(asked);
                    }
                    return Ok(Some(Value::Empty));
                }
                if name.eq_ignore_ascii_case("unprotect") {
                    let offered = match args.first() {
                        None | Some(Value::Missing) => String::new(),
                        Some(value) => shown_text(value, None),
                    };
                    if let Some(Some(held)) = self.protected.get(sheet) {
                        if held.password != offered {
                            return Err(
                                "the password supplied is not correct for this sheet".to_string(),
                            );
                        }
                        self.protected[sheet] = None;
                    }
                    return Ok(Some(Value::Empty));
                }
                // Selecting a sheet is activating it, and it answers True:
                // asked of Excel, `r = ActiveSheet.Select` is a Boolean.
                if name.eq_ignore_ascii_case("select") {
                    if !args.is_empty() {
                        return Err("Worksheet.Select does not accept arguments".to_string());
                    }
                    self.activate_sheet(sheet);
                    return Ok(Some(Value::Boolean(true)));
                }
                // `Shapes(1)`, `ChartObjects("Chart 1")`: the collection with
                // an index is its item.
                if name.eq_ignore_ascii_case("shapes")
                    || name.eq_ignore_ascii_case("drawingobjects")
                    || name.eq_ignore_ascii_case("chartobjects")
                {
                    let part = if name.eq_ignore_ascii_case("chartobjects") {
                        shapes::DrawingPart::ChartObjects(sheet)
                    } else {
                        shapes::DrawingPart::Shapes(sheet)
                    };
                    if args.is_empty() || matches!(args, [Value::Missing]) {
                        return Ok(Some(self.object(HostObject::Drawing(part))));
                    }
                    return self.drawing_call(part, "item", args);
                }
                if name.eq_ignore_ascii_case("showalldata") {
                    // Nothing hidden, nothing to show: asked of Excel,
                    // `ShowAllData` is error 1004 on a sheet with no rows
                    // hidden -- and 1004 even after an AutoFilter has been
                    // applied, as long as it has hidden nothing. It asks about
                    // the hidden ROWS, not about the filter.
                    //
                    // Only the member refuses. Turning a filter off goes
                    // through the same helper and must not, which is what a
                    // test caught when the refusal was put down there.
                    let anything_hidden = self
                        .workbook
                        .sheets
                        .get(sheet)
                        .is_some_and(|worksheet| worksheet.rows.iter().any(|row| row.hidden));
                    if !anything_hidden {
                        return Err(host_error(1004, "no filtered data to show on this worksheet"));
                    }
                    self.show_all_rows(sheet)?;
                    if let Some(filter) = self.auto_filter.as_mut() {
                        if filter.range.sheet == sheet {
                            filter.fields.clear();
                        }
                    }
                    return Ok(Some(Value::Empty));
                }
                if name.eq_ignore_ascii_case("delete") {
                    return self.delete_worksheet(sheet).map(|()| Some(Value::Empty));
                }
                if name.eq_ignore_ascii_case("copy") {
                    return self.copy_worksheet(sheet, args).map(|()| Some(Value::Empty));
                }
                if name.eq_ignore_ascii_case("move") {
                    return self.move_worksheet(sheet, args).map(|()| Some(Value::Empty));
                }
                if name.eq_ignore_ascii_case("evaluate") {
                    return self.evaluate_object(sheet, args).map(Some);
                }
                if name.eq_ignore_ascii_case("range") {
                    return self.range_object(sheet, args, NameReach::ThisSheet).map(Some);
                }
                if name.eq_ignore_ascii_case("cells") {
                    return self.cells_object(sheet, args).map(Some);
                }
                if name.eq_ignore_ascii_case("activate") {
                    if !args.is_empty() {
                        return Err("Worksheet.Activate does not accept arguments".to_string());
                    }
                    self.activate_sheet(sheet);
                    self.active_cell = self.selection.first();
                    return Ok(Some(Value::Boolean(true)));
                }
                if name.eq_ignore_ascii_case("usedrange") {
                    if !args.is_empty() {
                        return Err("Worksheet.UsedRange does not accept arguments".to_string());
                    }
                    return self.used_range_object(sheet).map(Some);
                }
                if name.eq_ignore_ascii_case("rows") {
                    return self
                        .worksheet_axis_object_or_item(sheet, RangeAxis::Rows, args)
                        .map(Some);
                }
                if name.eq_ignore_ascii_case("columns") {
                    return self
                        .worksheet_axis_object_or_item(sheet, RangeAxis::Columns, args)
                        .map(Some);
                }
                return Ok(None);
            }
            if (self.is_workbook(receiver) || self.is_application(receiver))
                && (name.eq_ignore_ascii_case("worksheets") || name.eq_ignore_ascii_case("sheets"))
            {
                return self.worksheets_object_or_item(args).map(Some);
            }
            if (self.is_workbook(receiver) || self.is_application(receiver))
                && name.eq_ignore_ascii_case("names")
            {
                return self.names_object_or_item(args).map(Some);
            }
            if let Some(at) = self.comment_cell(receiver) {
                return self.comment_member(at, name, args);
            }
            if let Some((at, start, length)) = self.characters_of(receiver) {
                return self.characters_member(at, start, length, name, args);
            }
            if let Some(range) = self.validation_range(receiver) {
                return self.validation_member(range, name, args);
            }
            if let Some(range) = self.conditions_range(receiver) {
                return self.conditions_member(range, name, args);
            }
            if let Some(sheet) = self.list_objects_sheet(receiver) {
                return self.list_objects_member(sheet, name, args);
            }
            if let Some(sheet) = self.page_setup_sheet(receiver) {
                return self.page_setup_member(sheet, name);
            }
            if let Some((id, part)) = self.table_part(receiver) {
                return self.table_member(id, part, name, args);
            }
            if let Some((id, face)) = self.condition_id(receiver) {
                return self.condition_member(id, face, name, args);
            }
            if let Some((range, face)) = self.display_format_of(receiver) {
                return self.display_format_member(range, face, name);
            }
            if let Some((at, start, length)) = self.characters_font_of(receiver) {
                return self.characters_font_member(at, start, length, name);
            }
            if let Some(id) = self.link_id(receiver) {
                return self.hyperlink_member(id, name, args);
            }
            if let Some(scope) = self.hyperlink_scope(receiver) {
                return self.hyperlinks_member(scope, name, args);
            }
            if let Some(index) = self.style_index(receiver) {
                return self.style_member(index, name);
            }
            if self.is_styles(receiver) {
                if name.eq_ignore_ascii_case("count") {
                    return Ok(Some(Value::Integer(self.listed_styles().len() as i64)));
                }
                if name.eq_ignore_ascii_case("item") {
                    let [wanted] = args else {
                        return Err("Styles.Item takes one name or one number".to_string());
                    };
                    return self.style_item(wanted).map(Some);
                }
                return Ok(None);
            }
            if (self.is_workbook(receiver) || self.is_application(receiver))
                && name.eq_ignore_ascii_case("styles")
            {
                return match args {
                    [] => Ok(Some(self.object(HostObject::Styles))),
                    [wanted] => self.style_item(wanted).map(Some),
                    _ => Err("Styles expects zero or one argument".to_string()),
                };
            }
            if let Some(sheet) = self.comments_sheet(receiver) {
                if name.eq_ignore_ascii_case("count") {
                    return Ok(Some(Value::Integer(self.notes_on(sheet).len() as i64)));
                }
                if name.eq_ignore_ascii_case("item") {
                    let [wanted] = args else {
                        return Err("Comments.Item takes one number".to_string());
                    };
                    return self.comment_item(sheet, wanted).map(Some);
                }
                return Ok(None);
            }
            if self.is_names(receiver) {
                if name.eq_ignore_ascii_case("add") {
                    return self.add_name(args).map(Some);
                }
                if name.eq_ignore_ascii_case("item") {
                    let [wanted] = args else {
                        return Err("Names.Item takes one name or one number".to_string());
                    };
                    return self.name_item(wanted).map(Some);
                }
                if name.eq_ignore_ascii_case("count") {
                    return Ok(Some(Value::Integer(
                        self.workbook.defined_names.len() as i64
                    )));
                }
                return Ok(None);
            }
            if let Some(HostObject::Blocks(handle)) = self.objects.get(receiver.handle as usize) {
                return self.blocks_member(*handle, name, args);
            }
            if let Some(HostObject::Areas(handle)) = self.objects.get(receiver.handle as usize) {
                let handle = *handle;
                let areas = self.blocks[handle].clone();
                if name.eq_ignore_ascii_case("count") {
                    return Ok(Some(Value::Integer(areas.len() as i64)));
                }
                if name.eq_ignore_ascii_case("item") {
                    let [wanted] = args else {
                        return Err("Areas.Item takes one number".to_string());
                    };
                    let at = positive_index(wanted, "index")? as usize;
                    let block = areas
                        .get(at - 1)
                        .ok_or_else(|| format!("this range has no area number {at}"))?;
                    return Ok(Some(self.object(HostObject::Range(*block))));
                }
                return Ok(None);
            }
            if let Some(held) = self.held_name(receiver).map(str::to_string) {
                return self.name_member(&held, name, args).map(Some);
            }
            if self.is_application(receiver) && name.eq_ignore_ascii_case("range") {
                return self
                    .range_object(self.active_sheet, args, NameReach::Workbook)
                    .map(Some);
            }
            if self.is_application(receiver) && name.eq_ignore_ascii_case("evaluate") {
                return self.evaluate_object(self.active_sheet, args).map(Some);
            }
            if self.is_application(receiver)
                && (name.eq_ignore_ascii_case("selection")
                    || name.eq_ignore_ascii_case("activecell"))
            {
                if !args.is_empty() {
                    return Err(format!("Application.{name} does not accept arguments"));
                }
                let range = if name.eq_ignore_ascii_case("activecell") {
                    CellRange::single(self.active_cell)
                } else {
                    self.selection
                };
                return Ok(Some(self.object(HostObject::Range(range))));
            }
            if self.is_application(receiver) && name.eq_ignore_ascii_case("calculate") {
                self.recalculate();
                return Ok(Some(Value::Empty));
            }
            // Measured: `Application.Wait` comes back True once the moment
            // has passed; nothing here can hold the page, so it comes back
            // at once.
            if self.is_application(receiver) && name.eq_ignore_ascii_case("wait") {
                return Ok(Some(Value::Boolean(true)));
            }
            // Measured: a macro run by hand has no caller -- `Application.Caller`
            // is Error 2023 -- and `Volatile` does nothing outside a function
            // a cell calls.
            if self.is_application(receiver) && name.eq_ignore_ascii_case("caller") {
                return Ok(Some(Value::Error(2023)));
            }
            if self.is_application(receiver) && name.eq_ignore_ascii_case("volatile") {
                return Ok(Some(Value::Empty));
            }
            if self.is_application(receiver) && name.eq_ignore_ascii_case("international") {
                let [asked] = args else {
                    return Err("Application.International takes one index".to_string());
                };
                return international(sort_number(asked, "International")?).map(Some);
            }

            // `Application.Goto` brings a range to the front: its sheet is
            // activated, the range selected, and the active cell is its first.
            // Measured: `Goto Range("B2:C3")` leaves Selection B2:C3 and
            // ActiveCell B2, and `Goto Worksheets("Sheet1").Range("A4")` from
            // another sheet activates Sheet1 with A4 active. A second argument
            // asks to scroll, which a browser host has nothing to scroll, and
            // a STRING reference is error 1004 there.
            if self.is_application(receiver) && name.eq_ignore_ascii_case("goto") {
                let Some(first) = args.first() else {
                    return Err("Application.Goto needs a Range".to_string());
                };
                // A recorder writes the destination as an R1C1 STRING:
                // `Application.Goto Reference:="R2C2"` lands on B2.
                let range = match first {
                    Value::Object(object) => self
                        .range(object)
                        .ok_or_else(|| "Application.Goto takes a Range object".to_string())?,
                    Value::String(text) => {
                        let (column, row) = parse_r1c1_cell(text)
                            .or_else(|| parse_a1_reference(text).ok())
                            .ok_or_else(|| host_error(1004, "Application.Goto cannot read that reference"))?;
                        CellRange::single(CellAddress { sheet: self.active_sheet, row, column })
                    }
                    _ => return Err("Application.Goto takes a Range object".to_string()),
                };
                self.activate_sheet(range.sheet);
                self.selection = range;
                self.active_cell = range.first();
                return Ok(Some(Value::Empty));
            }
            if self.is_window(receiver)
                && matches!(name.to_ascii_lowercase().as_str(), "smallscroll" | "largescroll")
            {
                // Down / Up / ToRight / ToLeft, by rows and columns for the
                // small scroll and by screenfuls for the large. Measured:
                // ScrollRow 1, `SmallScroll Down:=3` -> 4. A screen stands
                // in for the large scroll at the window Excel opens at.
                let at = |index: usize| args.get(index).and_then(any_whole_number).unwrap_or(0);
                let (row_step, col_step) = if name.eq_ignore_ascii_case("largescroll") { (21, 13) } else { (1, 1) };
                let down = (at(0) - at(1)) * row_step;
                let right = (at(2) - at(3)) * col_step;
                let view = self.views.entry(self.active_sheet).or_default();
                view.scroll_row = (i64::from(view.scroll_row) + down).max(1) as u32;
                view.scroll_column = (i64::from(view.scroll_column) + right).max(1) as u32;
                return Ok(Some(Value::Empty));
            }
            if self.is_window(receiver)
                && matches!(name.to_ascii_lowercase().as_str(), "scrollintoview" | "activate" | "activatenext" | "activateprevious" | "close")
            {
                return Ok(Some(Value::Empty));
            }
            if self.is_application(receiver) && name.eq_ignore_ascii_case("union") {
                return self.union_ranges(args).map(Some);
            }
            if self.is_application(receiver) && name.eq_ignore_ascii_case("intersect") {
                return self.intersect_ranges(args).map(Some);
            }
            if self.is_application(receiver) && name.eq_ignore_ascii_case("rows") {
                return self
                    .worksheet_axis_object_or_item(self.active_sheet, RangeAxis::Rows, args)
                    .map(Some);
            }
            if self.is_application(receiver) && name.eq_ignore_ascii_case("columns") {
                return self
                    .worksheet_axis_object_or_item(self.active_sheet, RangeAxis::Columns, args)
                    .map(Some);
            }
            // Every worksheet function is on Application itself as well, and
            // the difference is what a failure looks like: measured in Excel
            // 16.0, `Application.VLookup` on a miss hands back error 2042
            // where `WorksheetFunction.VLookup` raises, which is why
            // `If IsError(Application.Match(...))` is how a macro asks whether
            // something is there at all. The names Excel leaves off — the ones
            // VBA has of its own, `Len` and `Abs` among them — are left off
            // here too, so they fall through to "no such member".
            if self.is_application(receiver) && !vba_has_its_own(name) {
                let answered = self.worksheet_function_value(name, args);
                if !matches!(&answered, Err(why) if why.ends_with("is not supported in the browser"))
                {
                    return answered.map(Some);
                }
            }
            if self.is_worksheets(receiver) && name.eq_ignore_ascii_case("add") {
                return self.add_worksheet(args).map(Some);
            }
            if self.is_worksheets(receiver) && name.eq_ignore_ascii_case("item") {
                let [value] = args else {
                    return Err("Worksheets.Item expects one sheet name or index".to_string());
                };
                return self.worksheet_object(value).map(Some);
            }
            if let Some((range, axis)) = self.range_collection(receiver) {
                if name.eq_ignore_ascii_case("item") {
                    let [index] = args else {
                        return Err(format!(
                            "Range.{}.Item expects one index",
                            range_axis_name(axis)
                        ));
                    };
                    return self.range_collection_item(range, axis, index).map(Some);
                }
                // As with Count, every other call a range takes it takes too.
            }
            if let Some(range) = self.range(receiver) {
                if name.eq_ignore_ascii_case("borders") {
                    return self.borders_object(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("copy") {
                    return self.copy_range(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("cut") {
                    return self.cut_range(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("addcomment") {
                    return self.add_comment(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("calculate") {
                    self.recalculate();
                    return Ok(Some(Value::Boolean(true)));
                }
                if name.eq_ignore_ascii_case("texttocolumns") {
                    return self.text_to_columns(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("comment") && args.is_empty() {
                    return Ok(Some(self.comment_of(range)));
                }
                if name.eq_ignore_ascii_case("style") && args.is_empty() {
                    return Ok(Some(self.style_of(range)));
                }
                if name.eq_ignore_ascii_case("characters") {
                    return self.characters_object(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("validation") && args.is_empty() {
                    return Ok(Some(self.object(HostObject::Validation(range))));
                }
                if name.eq_ignore_ascii_case("formatconditions") {
                    return match args {
                        [] => Ok(Some(self.object(HostObject::FormatConditions(range)))),
                        [wanted] => self.conditions_member(range, "item", std::slice::from_ref(wanted)),
                        _ => Err("FormatConditions expects zero or one argument".to_string()),
                    };
                }
                if name.eq_ignore_ascii_case("displayformat") && args.is_empty() {
                    return Ok(Some(self.object(HostObject::DisplayFormat(range))));
                }
                if name.eq_ignore_ascii_case("listobject") && args.is_empty() {
                    return Ok(Some(self.list_object_of(range)));
                }
                if name.eq_ignore_ascii_case("hyperlinks") {
                    let scope = HyperlinkScope::Range(range);
                    return match args {
                        [] => Ok(Some(self.object(HostObject::Hyperlinks(scope)))),
                        [wanted] => self.hyperlink_item(scope, wanted).map(Some),
                        _ => Err("Hyperlinks expects zero or one argument".to_string()),
                    };
                }
                // Answers True, as `Clear` does.
                if name.eq_ignore_ascii_case("clearcomments") {
                    if !args.is_empty() {
                        return Err("Range.ClearComments does not accept arguments".to_string());
                    }
                    // Passed over in silence on a protected sheet, like a
                    // write to the note's text.
                    if !self.objects_protected(range.sheet) {
                        self.clear_comments(range);
                    }
                    return Ok(Some(Value::Boolean(true)));
                }
                // The older way to a note: `NoteText` alone reads it (an empty
                // string where there is none) and `NoteText "x"` writes it,
                // adding the note when the cell has none.
                if name.eq_ignore_ascii_case("notetext") {
                    return self.note_text_member(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("autofit") {
                    if !args.is_empty() {
                        return Err("Range.AutoFit does not accept arguments".to_string());
                    }
                    let sense = self.range_sense(receiver);
                    return self.auto_fit(range, sense).map(Some);
                }
                if name.eq_ignore_ascii_case("group") {
                    return self.group_range(range, true).map(Some);
                }
                if name.eq_ignore_ascii_case("ungroup") {
                    return self.group_range(range, false).map(Some);
                }
                if name.eq_ignore_ascii_case("clearoutline") {
                    self.clear_outline(range);
                    return Ok(Some(Value::Boolean(true)));
                }
                if name.eq_ignore_ascii_case("autofill") {
                    return self.auto_fill(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("borderaround") {
                    return self.border_around(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("subtotal") {
                    return self.subtotal(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("removesubtotal") {
                    return self.remove_subtotal(range).map(Some);
                }
                if name.eq_ignore_ascii_case("filldown") {
                    return self.fill_edge(range, FillEdge::Top).map(Some);
                }
                if name.eq_ignore_ascii_case("fillup") {
                    return self.fill_edge(range, FillEdge::Bottom).map(Some);
                }
                if name.eq_ignore_ascii_case("fillright") {
                    return self.fill_edge(range, FillEdge::Left).map(Some);
                }
                if name.eq_ignore_ascii_case("fillleft") {
                    return self.fill_edge(range, FillEdge::Right).map(Some);
                }
                if name.eq_ignore_ascii_case("removeduplicates") {
                    return self.remove_duplicates(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("specialcells") {
                    return self.special_cells(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("select") {
                    if !args.is_empty() {
                        return Err("Range.Select does not accept arguments".to_string());
                    }
                    if range.sheet != self.active_sheet {
                        return Err("Range.Select requires its worksheet to be active".to_string());
                    }
                    self.selection = range;
                    self.active_cell = range.first();
                    // True, like the other members that DO something: asked of
                    // Excel, `r = Range("A2").Select` is a Boolean.
                    return Ok(Some(Value::Boolean(true)));
                }
                // Excel moves the cell in front WITHOUT disturbing the
                // selection when the range is already inside it, and selects
                // the range outright when it is not: from a selection of
                // B2:C3, `Range("C3").Activate` leaves B2:C3 selected with C3
                // in front, while `Range("E5").Activate` selects E5 alone.
                if name.eq_ignore_ascii_case("activate") {
                    if !args.is_empty() {
                        return Err("Range.Activate does not accept arguments".to_string());
                    }
                    if range.sheet != self.active_sheet {
                        return Err(
                            "Range.Activate requires its worksheet to be active".to_string()
                        );
                    }
                    if !range_within(range, self.selection) {
                        self.selection = range;
                    }
                    self.active_cell = range.first();
                    // It answers True, like the other doing-members: asked of
                    // Excel, `r = Range("A2").Activate` is a Boolean and the
                    // active cell is A2 afterwards.
                    return Ok(Some(Value::Boolean(true)));
                }
                if name.eq_ignore_ascii_case("areas") {
                    return match args {
                        [] | [Value::Missing] => Ok(Some(self.areas_of(range))),
                        [wanted] => {
                            let at = positive_index(wanted, "index")? as usize;
                            if at != 1 {
                                return Err(format!("this range has no area number {at}"));
                            }
                            Ok(Some(self.object(HostObject::Range(range))))
                        }
                        _ => Err("Areas takes one number".to_string()),
                    };
                }
                // `Item` is what a range answers to when it is indexed with
                // nothing named — `Cells(1, 1)(2)` — and it counts the same
                // way `Cells` does: asked of Excel, `Range("B2:C3").Item(5)`
                // is B4 and `Range("A1").Item(2)` is the cell below.
                if name.eq_ignore_ascii_case("cells") || name.eq_ignore_ascii_case("item") {
                    return self.range_cells_object(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("offset") {
                    let moved = self.offset_range(range, args)?;
                    return Ok(Some(self.carry_sense(receiver, moved)));
                }
                if name.eq_ignore_ascii_case("resize") {
                    let sized = self.resize_range(range, args)?;
                    return Ok(Some(self.carry_sense(receiver, sized)));
                }
                if name.eq_ignore_ascii_case("end") {
                    return self.range_end(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("find") {
                    return self.find_in_range(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("findnext") {
                    return self.find_again(args, 1).map(Some);
                }
                if name.eq_ignore_ascii_case("findprevious") {
                    return self.find_again(args, 2).map(Some);
                }
                if name.eq_ignore_ascii_case("replace") {
                    return self.replace_in_range(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("currentregion") {
                    if !args.is_empty() {
                        return Err("Range.CurrentRegion does not accept arguments".to_string());
                    }
                    return self.current_region_object(range).map(Some);
                }
                if name.eq_ignore_ascii_case("address") {
                    return self
                        .range_address_from_args(range, args)
                        .map(Value::String)
                        .map(Some);
                }
                if name.eq_ignore_ascii_case("rows") {
                    return self
                        .range_collection_object_or_item(range, RangeAxis::Rows, args)
                        .map(Some);
                }
                if name.eq_ignore_ascii_case("columns") {
                    return self
                        .range_collection_object_or_item(range, RangeAxis::Columns, args)
                        .map(Some);
                }
                if name.eq_ignore_ascii_case("clearcontents") {
                    if !args.is_empty() {
                        return Err("Range.ClearContents does not accept arguments".to_string());
                    }
                    // Measured: clearing one cell of an array is 1004, where
                    // writing to it is quietly nothing.
                    self.arrays_allow(range, false)?;
                    self.set_range_input(range, Value::Empty, "range assignment", FormulaStyle::A1)?;
                    // Measured: the hyperlink goes with the contents and the
                    // blue underline stays.
                    let ids = self.links_in(HyperlinkScope::Range(range));
                    self.delete_links(&ids, true)?;
                    return Ok(Some(Value::Empty));
                }
                // These answer True, not nothing: asked of Excel,
                // `r = Range("A1").Clear` is a Boolean and so is
                // `.ClearFormats`. `ClearContents` is the odd one and answers
                // Empty, which is what it already did.
                if name.eq_ignore_ascii_case("clearformats") {
                    if !args.is_empty() {
                        return Err("Range.ClearFormats does not accept arguments".to_string());
                    }
                    self.clear_range(range, false, true)?;
                    return Ok(Some(Value::Boolean(true)));
                }
                if name.eq_ignore_ascii_case("clear") {
                    if !args.is_empty() {
                        return Err("Range.Clear does not accept arguments".to_string());
                    }
                    self.clear_range(range, true, true)?;
                    self.clear_comments(range);
                    let ids = self.links_in(HyperlinkScope::Range(range));
                    self.delete_links(&ids, true)?;
                    self.validations.retain(|held, _| {
                        held.sheet != range.sheet
                            || !(range.start_row..=range.end_row).contains(&held.row)
                            || !(range.start_column..=range.end_column).contains(&held.column)
                    });
                    return Ok(Some(Value::Boolean(true)));
                }
                if name.eq_ignore_ascii_case("autofilter") {
                    return self.auto_filter(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("pastespecial") {
                    return self.paste_special(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("sort") {
                    return self.sort_range(range, args).map(|()| Some(Value::Empty));
                }
                if name.eq_ignore_ascii_case("insert") {
                    return self.insert_range(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("delete") {
                    return self.delete_range(range, args).map(Some);
                }
                if name.eq_ignore_ascii_case("merge") {
                    let across = match args {
                        [] => false,
                        [across] => application_switch(across, "Range.Merge Across")?,
                        _ => {
                            return Err("Range.Merge expects zero or one argument".to_string())
                        }
                    };
                    // Across makes one merge of each ROW rather than one of
                    // the block: asked of Excel, `D1:E2` merged across leaves
                    // `D1:E1` and `D2:E2`, each keeping its own leftmost
                    // value where the block would have kept only D1's.
                    if across {
                        for row in range.start_row..=range.end_row {
                            self.merge_range(CellRange {
                                sheet: range.sheet,
                                start_row: row,
                                end_row: row,
                                start_column: range.start_column,
                                end_column: range.end_column,
                            })?;
                        }
                    } else {
                        self.merge_range(range)?;
                    }
                    return Ok(Some(Value::Empty));
                }
                if name.eq_ignore_ascii_case("unmerge") {
                    if !args.is_empty() {
                        return Err("Range.UnMerge does not accept arguments".to_string());
                    }
                    self.unmerge_range(range)?;
                    return Ok(Some(Value::Empty));
                }
            }
            return Ok(None);
        }
        if args.is_empty() {
            if let Some(value) = host_constant(name) {
                return Ok(Some(value));
            }
        }
        if name.eq_ignore_ascii_case("msgbox") {
            return self.show_message_box(args).map(Some);
        }
        if name.eq_ignore_ascii_case("rgb") {
            return rgb_value(args).map(Some);
        }
        // The Application's own, reachable bare: `Union(a, b)`,
        // `Intersect(a, b)`.
        if name.eq_ignore_ascii_case("union") {
            return self.union_ranges(args).map(Some);
        }
        if name.eq_ignore_ascii_case("intersect") {
            return self.intersect_ranges(args).map(Some);
        }
        // A bare `Range` is `Application.Range`, and reaches every name in
        // the workbook: measured, `Range("nm")` from a second sheet, with
        // `nm` standing for Sheet1!$A$1, answers that cell on Sheet1.
        if name.eq_ignore_ascii_case("range") {
            return self
                .range_object(self.active_sheet, args, NameReach::Workbook)
                .map(Some);
        }
        if name.eq_ignore_ascii_case("evaluate") {
            return self.evaluate_object(self.active_sheet, args).map(Some);
        }
        if name.eq_ignore_ascii_case("cells") {
            return self.cells_object(self.active_sheet, args).map(Some);
        }
        if name.eq_ignore_ascii_case("names") {
            return self.names_object_or_item(args).map(Some);
        }
        if name.eq_ignore_ascii_case("worksheets") || name.eq_ignore_ascii_case("sheets") {
            return self.worksheets_object_or_item(args).map(Some);
        }
        if name.eq_ignore_ascii_case("activesheet") {
            return Ok(Some(self.object(HostObject::Worksheet(self.active_sheet))));
        }
        if name.eq_ignore_ascii_case("activewindow") {
            return Ok(Some(self.object(HostObject::Window)));
        }
        if name.eq_ignore_ascii_case("thisworkbook") || name.eq_ignore_ascii_case("activeworkbook")
        {
            return Ok(Some(self.object(HostObject::Workbook)));
        }
        if name.eq_ignore_ascii_case("workbooks") {
            return self.workbooks_member(args).map(Some);
        }
        if name.eq_ignore_ascii_case("application") {
            return Ok(Some(self.object(HostObject::Application)));
        }
        if name.eq_ignore_ascii_case("worksheetfunction") {
            if !args.is_empty() {
                return Err("WorksheetFunction does not accept arguments".to_string());
            }
            return Ok(Some(self.object(HostObject::WorksheetFunction)));
        }
        if name.eq_ignore_ascii_case("selection") || name.eq_ignore_ascii_case("activecell") {
            if !args.is_empty() {
                return Err(format!("{name} does not accept arguments"));
            }
            let range = if name.eq_ignore_ascii_case("activecell") {
                CellRange::single(self.active_cell)
            } else {
                self.selection
            };
            return Ok(Some(self.object(HostObject::Range(range))));
        }
        if name.eq_ignore_ascii_case("debug") {
            if !args.is_empty() {
                return Err("Debug does not accept arguments".to_string());
            }
            return Ok(Some(self.object(HostObject::DebugConsole)));
        }
        if name.eq_ignore_ascii_case("usedrange") {
            if !args.is_empty() {
                return Err("UsedRange does not accept arguments".to_string());
            }
            return self.used_range_object(self.active_sheet).map(Some);
        }
        if name.eq_ignore_ascii_case("rows") {
            return self
                .worksheet_axis_object_or_item(self.active_sheet, RangeAxis::Rows, args)
                .map(Some);
        }
        if name.eq_ignore_ascii_case("columns") {
            return self
                .worksheet_axis_object_or_item(self.active_sheet, RangeAxis::Columns, args)
                .map(Some);
        }
        Ok(None)
    }

    fn call_named(
        &mut self,
        receiver: Option<&ObjectRef>,
        name: &str,
        args: &[Value],
        argument_names: &[Option<String>],
    ) -> Result<Option<Value>, String> {
        let parameters = if name.eq_ignore_ascii_case("find") {
            Some(
                &[
                    "What",
                    "After",
                    "LookIn",
                    "LookAt",
                    "SearchOrder",
                    "SearchDirection",
                    "MatchCase",
                    "MatchByte",
                    "SearchFormat",
                ][..],
            )
        } else if name.eq_ignore_ascii_case("findnext") || name.eq_ignore_ascii_case("findprevious")
        {
            Some(&["After"][..])
        } else if name.eq_ignore_ascii_case("replace") {
            Some(
                &[
                    "What",
                    "Replacement",
                    "LookAt",
                    "SearchOrder",
                    "MatchCase",
                    "MatchByte",
                    "SearchFormat",
                    "ReplaceFormat",
                ][..],
            )
        } else if name.eq_ignore_ascii_case("offset") {
            Some(&["RowOffset", "ColumnOffset"][..])
        } else if name.eq_ignore_ascii_case("resize") {
            Some(&["RowSize", "ColumnSize"][..])
        } else if name.eq_ignore_ascii_case("address") {
            Some(
                &[
                    "RowAbsolute",
                    "ColumnAbsolute",
                    "ReferenceStyle",
                    "External",
                    "RelativeTo",
                ][..],
            )
        } else if name.eq_ignore_ascii_case("add") {
            // Three collections answer to Add, and they name their arguments
            // differently.
            if receiver.is_some_and(|receiver| {
                matches!(self.objects.get(receiver.handle as usize), Some(HostObject::SortFields(_)))
            }) {
                Some(&["Key", "SortOn", "Order", "CustomOrder", "DataOption"][..])
            } else if receiver.is_some_and(|receiver| self.is_names(receiver)) {
                Some(&["Name", "RefersTo"][..])
            } else if receiver.is_some_and(|receiver| self.hyperlink_scope(receiver).is_some()) {
                Some(&["Anchor", "Address", "SubAddress", "ScreenTip", "TextToDisplay"][..])
            } else if receiver.is_some_and(|receiver| self.validation_range(receiver).is_some()) {
                Some(&["Type", "AlertStyle", "Operator", "Formula1", "Formula2"][..])
            } else if receiver.is_some_and(|receiver| self.list_objects_sheet(receiver).is_some()) {
                Some(&["SourceType", "Source", "LinkSource", "XlListObjectHasHeaders", "Destination"][..])
            } else if receiver
                .is_some_and(|receiver| matches!(self.table_part(receiver), Some((_, TablePart::Rows | TablePart::Columns))))
            {
                Some(&["Position", "AlwaysInsert"][..])
            } else if receiver.is_some_and(|receiver| self.conditions_range(receiver).is_some()) {
                Some(
                    &[
                        "Type",
                        "Operator",
                        "Formula1",
                        "Formula2",
                        "String",
                        "TextOperator",
                        "DateOperator",
                        "ScopeType",
                    ][..],
                )
            } else {
                Some(&["Before", "After", "Count"][..])
            }
        } else if name.eq_ignore_ascii_case("autofilter") {
            Some(&["Field", "Criteria1", "Operator", "Criteria2", "VisibleDropDown"][..])
        } else if name.eq_ignore_ascii_case("sort") {
            Some(
                &[
                    "Key1",
                    "Order1",
                    "Key2",
                    "Type",
                    "Order2",
                    "Key3",
                    "Order3",
                    "Header",
                    "OrderCustom",
                    "MatchCase",
                    "Orientation",
                    "SortMethod",
                    "DataOption1",
                    "DataOption2",
                    "DataOption3",
                ][..],
            )
        } else if name.eq_ignore_ascii_case("copy") {
            // A worksheet is copied somewhere among the sheets; a range is
            // copied onto other cells.
            match receiver.is_some_and(|receiver| self.worksheet(receiver).is_some()) {
                true => Some(&["Before", "After"][..]),
                false => Some(&["Destination"][..]),
            }
        } else if name.eq_ignore_ascii_case("move") {
            Some(&["Before", "After"][..])
        } else if name.eq_ignore_ascii_case("pastespecial") {
            Some(&["Paste", "Operation", "SkipBlanks", "Transpose"][..])
        } else if name.eq_ignore_ascii_case("insert") {
            Some(&["Shift", "CopyOrigin"][..])
        } else if name.eq_ignore_ascii_case("smallscroll") || name.eq_ignore_ascii_case("largescroll") {
            Some(&["Down", "Up", "ToRight", "ToLeft"][..])
        } else if name.eq_ignore_ascii_case("merge") {
            Some(&["Across"][..])
        } else if name.eq_ignore_ascii_case("borders") {
            Some(&["Index"][..])
        } else if name.eq_ignore_ascii_case("range") {
            Some(&["Cell1", "Cell2"][..])
        } else if name.eq_ignore_ascii_case("cells") {
            Some(&["RowIndex", "ColumnIndex"][..])
        } else if name.eq_ignore_ascii_case("msgbox") {
            Some(&["Prompt", "Buttons", "Title", "HelpFile", "Context"][..])
        } else if name.eq_ignore_ascii_case("texttocolumns") {
            Some(
                &[
                    "Destination",
                    "DataType",
                    "TextQualifier",
                    "ConsecutiveDelimiter",
                    "Tab",
                    "Semicolon",
                    "Comma",
                    "Space",
                    "Other",
                    "OtherChar",
                    "FieldInfo",
                    "DecimalSeparator",
                    "ThousandsSeparator",
                    "TrailingMinusNumbers",
                ][..],
            )
        } else if name.eq_ignore_ascii_case("modify")
            && receiver.is_some_and(|receiver| self.validation_range(receiver).is_some())
        {
            Some(&["Type", "AlertStyle", "Operator", "Formula1", "Formula2"][..])
        } else if name.eq_ignore_ascii_case("modify")
            && receiver.is_some_and(|receiver| self.condition_id(receiver).is_some())
        {
            Some(&["Type", "Operator", "Formula1", "Formula2", "String", "TextOperator"][..])
        } else if name.eq_ignore_ascii_case("showlevels") {
            Some(&["RowLevels", "ColumnLevels"][..])
        } else if name.eq_ignore_ascii_case("autofill") {
            Some(&["Destination", "Type"][..])
        } else if name.eq_ignore_ascii_case("add2")
            && receiver.is_some_and(|receiver| {
                matches!(self.objects.get(receiver.handle as usize), Some(HostObject::SortFields(_)))
            })
        {
            Some(&["Key", "SortOn", "Order", "CustomOrder", "DataOption"][..])
        } else if name.eq_ignore_ascii_case("setrange") {
            Some(&["Range"][..])
        } else if name.eq_ignore_ascii_case("borderaround") {
            Some(&["LineStyle", "Weight", "ColorIndex", "Color", "ThemeColor"][..])
        } else if name.eq_ignore_ascii_case("subtotal") {
            Some(&["GroupBy", "Function", "TotalList", "Replace", "PageBreaks", "SummaryBelowData"][..])
        } else if name.eq_ignore_ascii_case("addcomment") {
            Some(&["Text"][..])
        } else if name.eq_ignore_ascii_case("text")
            && receiver.is_some_and(|receiver| self.comment_cell(receiver).is_some())
        {
            Some(&["Text", "Start", "Overwrite"][..])
        } else if name.eq_ignore_ascii_case("notetext") {
            Some(&["Text", "Start", "Length"][..])
        } else if name.eq_ignore_ascii_case("protect") {
            Some(
                &[
                    "Password",
                    "DrawingObjects",
                    "Contents",
                    "Scenarios",
                    "UserInterfaceOnly",
                    "AllowFormattingCells",
                    "AllowFormattingColumns",
                    "AllowFormattingRows",
                    "AllowInsertingColumns",
                    "AllowInsertingRows",
                    "AllowInsertingHyperlinks",
                    "AllowDeletingColumns",
                    "AllowDeletingRows",
                    "AllowSorting",
                    "AllowFiltering",
                    "AllowUsingPivotTables",
                ][..],
            )
        } else if name.eq_ignore_ascii_case("unprotect") {
            Some(&["Password"][..])
        } else {
            None
        };
        if let Some(parameters) = parameters {
            let args = normalize_named_arguments(args, argument_names, parameters, name)?;
            return self.call(receiver, name, &args);
        }
        self.call(receiver, name, args)
    }

    fn get(&mut self, receiver: &ObjectRef, name: &str) -> Result<Option<Value>, String> {
        if self.gone(receiver) {
            return Err(host_error(424, "the object's worksheet has been deleted"));
        }
        if let Some(sheet) = self.tab_sheet(receiver) {
            return Ok(self.tab_member(sheet, name));
        }
        if let Some(HostObject::Sort(sheet)) = self.objects.get(receiver.handle as usize).copied() {
            let state = self.sorts.get(&sheet).cloned().unwrap_or_default();
            return Ok(match name.to_ascii_lowercase().as_str() {
                "sortfields" => Some(self.object(HostObject::SortFields(sheet))),
                "header" => Some(Value::Integer(if state.header == 0 { 0 } else { state.header })),
                "matchcase" => Some(Value::Boolean(state.match_case)),
                "orientation" => Some(Value::Integer(if state.sideways { 2 } else { 1 })),
                "rng" | "range" => state
                    .range
                    .map(|range| self.object(HostObject::Range(range))),
                "parent" => Some(self.object(HostObject::Worksheet(sheet))),
                _ => None,
            });
        }
        if let Some(HostObject::SortFields(sheet)) = self.objects.get(receiver.handle as usize).copied() {
            return Ok(match name.to_ascii_lowercase().as_str() {
                "count" => Some(Value::Integer(
                    self.sorts.get(&sheet).map_or(0, |state| state.fields.len() as i64),
                )),
                _ => None,
            });
        }
        if self.is_workbooks(receiver) {
            return Ok(match name.to_ascii_lowercase().as_str() {
                "count" => Some(Value::Integer(1)),
                "parent" | "application" => Some(self.object(HostObject::Application)),
                _ => None,
            });
        }
        if let Some(part) = self.drawing_part(receiver) {
            return self.drawing_get(part, name);
        }
        if let Some(sheet) = self.outline_sheet(receiver) {
            // Measured on a fresh sheet: SummaryRow xlSummaryBelow (1),
            // SummaryColumn xlSummaryOnRight (-4152), AutomaticStyles False.
            let outline = self.outlines.get(&sheet).cloned().unwrap_or_default();
            return Ok(match name.to_ascii_lowercase().as_str() {
                "summaryrow" => Some(Value::Integer(outline.summary_row)),
                "summarycolumn" => Some(Value::Integer(outline.summary_column)),
                "automaticstyles" => Some(Value::Boolean(outline.automatic_styles)),
                _ => None,
            });
        }
        // The Application's default member is its NAME, not a Value: asked of
        // Excel, `CStr(Range("A1").Application)` is `Microsoft Excel`. Without
        // this the object came through and then would not become a value, so
        // reaching it changed one 438 into another.
        if self.is_application(receiver)
            && (name.eq_ignore_ascii_case("value") || name.eq_ignore_ascii_case("name"))
        {
            return Ok(Some(Value::String("Microsoft Excel".to_string())));
        }
        if let Some(HostObject::Blocks(handle)) = self.objects.get(receiver.handle as usize) {
            return self.blocks_member(*handle, name, &[]);
        }
        if let Some(HostObject::BlocksStyle(handle, face)) =
            self.objects.get(receiver.handle as usize)
        {
            let (handle, face) = (*handle, *face);
            return self.get_from_every_block(handle, Some(face), name);
        }
        if let Some(HostObject::Areas(handle)) = self.objects.get(receiver.handle as usize) {
            if name.eq_ignore_ascii_case("count") {
                return Ok(Some(Value::Integer(self.blocks[*handle].len() as i64)));
            }
            return Ok(None);
        }
        if self.is_names(receiver) {
            if name.eq_ignore_ascii_case("count") {
                return Ok(Some(Value::Integer(
                    self.workbook.defined_names.len() as i64
                )));
            }
            return Ok(None);
        }
        if let Some(at) = self.comment_cell(receiver) {
            return self.comment_member(at, name, &[]);
        }
        if let Some((at, start, length)) = self.characters_of(receiver) {
            return self.characters_member(at, start, length, name, &[]);
        }
        if let Some(range) = self.validation_range(receiver) {
            return self.validation_member(range, name, &[]);
        }
        if let Some(range) = self.conditions_range(receiver) {
            return self.conditions_member(range, name, &[]);
        }
        if let Some(sheet) = self.list_objects_sheet(receiver) {
            return self.list_objects_member(sheet, name, &[]);
        }
        if let Some(sheet) = self.page_setup_sheet(receiver) {
            return self.page_setup_member(sheet, name);
        }
        if let Some((id, part)) = self.table_part(receiver) {
            return self.table_member(id, part, name, &[]);
        }
        if let Some((id, face)) = self.condition_id(receiver) {
            return self.condition_member(id, face, name, &[]);
        }
        if let Some((range, face)) = self.display_format_of(receiver) {
            return self.display_format_member(range, face, name);
        }
        if let Some((at, start, length)) = self.characters_font_of(receiver) {
            return self.characters_font_member(at, start, length, name);
        }
        if let Some(id) = self.link_id(receiver) {
            return self.hyperlink_member(id, name, &[]);
        }
        if let Some(scope) = self.hyperlink_scope(receiver) {
            return self.hyperlinks_member(scope, name, &[]);
        }
        if let Some(index) = self.style_index(receiver) {
            return self.style_member(index, name);
        }
        if self.is_styles(receiver) {
            if name.eq_ignore_ascii_case("count") {
                return Ok(Some(Value::Integer(self.listed_styles().len() as i64)));
            }
            return Ok(None);
        }
        if (self.is_workbook(receiver) || self.is_application(receiver))
            && name.eq_ignore_ascii_case("styles")
        {
            return Ok(Some(self.object(HostObject::Styles)));
        }
        if let Some(sheet) = self.comments_sheet(receiver) {
            if name.eq_ignore_ascii_case("count") {
                return Ok(Some(Value::Integer(self.notes_on(sheet).len() as i64)));
            }
            return Ok(None);
        }
        if let Some(held) = self.held_name(receiver).map(str::to_string) {
            return self.name_member(&held, name, &[]).map(Some);
        }
        if let Some((range, selection)) = self.range_borders(receiver) {
            if name.eq_ignore_ascii_case("linestyle") || name.eq_ignore_ascii_case("weight") {
                let line = name.eq_ignore_ascii_case("linestyle");
                return self.uniform_border(range, selection).map(|value| {
                    Some(match value {
                        Some((kind, weight)) => {
                            Value::Integer(if line { kind } else { weight })
                        }
                        None => Value::Null,
                    })
                });
            }
            // Measured: an edge not painted from the theme answers Null.
            if name.eq_ignore_ascii_case("themecolor") {
                return match self.uniform_theme_paint(range, Paint::Edge(selection))? {
                    Some(Some((theme, _))) => Ok(Some(Value::Integer(theme as i64))),
                    _ => Ok(Some(Value::Null)),
                };
            }
            if name.eq_ignore_ascii_case("tintandshade") {
                return match self.uniform_theme_paint(range, Paint::Edge(selection))? {
                    None => Ok(Some(Value::Null)),
                    Some(Some((_, tint))) => Ok(Some(Value::Double(tint))),
                    Some(None) => Ok(Some(Value::Double(0.0))),
                };
            }
            // Measured: an edge with no line answers Color 0 and ColorIndex
            // xlColorIndexNone; edges that disagree answer 0 too, not Null --
            // and that 0 is a Double, where the others are Longs.
            if name.eq_ignore_ascii_case("color") {
                return self.uniform_border_colour(range, selection).map(|colour| {
                    Some(match colour {
                        Some(EdgeColour::Named(colour)) => {
                            Value::Integer(colour_to_packed(Some(&colour)).unwrap_or(0))
                        }
                        Some(_) => Value::Integer(0),
                        None => Value::Double(0.0),
                    })
                });
            }
            if name.eq_ignore_ascii_case("colorindex") {
                return self.uniform_border_colour(range, selection).map(|colour| {
                    Some(match colour {
                        Some(EdgeColour::Named(colour)) => Value::Integer(
                            colour_to_packed(Some(&colour))
                                .map(nearest_palette_index)
                                .unwrap_or(COLOUR_AUTOMATIC),
                        ),
                        Some(EdgeColour::Automatic) => Value::Integer(COLOUR_AUTOMATIC),
                        Some(EdgeColour::NoLine) => Value::Integer(LINE_NONE),
                        None => Value::Null,
                    })
                });
            }
            return Ok(None);
        }
        if let Some(range) = self.range_font(receiver) {
            // Measured: a cell in the workbook's own face reads ThemeFont
            // xlThemeFontMinor (2); this build keeps no other, so it always
            // answers the minor. OutlineFont and Shadow are always False.
            if name.eq_ignore_ascii_case("themefont") {
                return Ok(Some(Value::Integer(2)));
            }
            if name.eq_ignore_ascii_case("outlinefont") || name.eq_ignore_ascii_case("shadow") {
                return Ok(Some(Value::Boolean(false)));
            }
            if name.eq_ignore_ascii_case("superscript") || name.eq_ignore_ascii_case("subscript") {
                let want = if name.eq_ignore_ascii_case("superscript") { "superscript" } else { "subscript" };
                return self
                    .uniform_font(range, |dress| dress.vert_align.as_deref() == Some(want))
                    .map(|value| Some(value.map(Value::Boolean).unwrap_or(Value::Null)));
            }
            if name.eq_ignore_ascii_case("bold") {
                return self
                    .uniform_font(range, |dress| dress.bold)
                    .map(|value| Some(value.map(Value::Boolean).unwrap_or(Value::Null)));
            }
            if name.eq_ignore_ascii_case("italic") {
                return self
                    .uniform_font(range, |dress| dress.italic)
                    .map(|value| Some(value.map(Value::Boolean).unwrap_or(Value::Null)));
            }
            if name.eq_ignore_ascii_case("strikethrough") {
                // This one IS a Boolean, where Underline beside it is not.
                return self
                    .uniform_style(range, |style| style.strikethrough)
                    .map(|value| Some(value.map(Value::Boolean).unwrap_or(Value::Null)));
            }
            if name.eq_ignore_ascii_case("underline") {
                // Not a Boolean: Excel answers with the STYLE of rule under
                // the writing. A cell nobody has underlined answers
                // `xlUnderlineStyleNone`, and one that has answers
                // `xlUnderlineStyleSingle` — which is also what it answers
                // after `Font.Underline = True`.
                // A double rule or an accounting one is kept beside the
                // cell, since the IR says only whether there is a rule.
                return self
                    .uniform_marked(range, |style, marks| {
                        if !style.underline {
                            return UNDERLINE_NONE;
                        }
                        marks.underline.unwrap_or(UNDERLINE_SINGLE)
                    })
                    .map(|value| Some(value.map(Value::Integer).unwrap_or(Value::Null)));
            }
            if name.eq_ignore_ascii_case("name") {
                // As with the alignment, what comes back is what the cells
                // EFFECTIVELY wear: a cell that names no face of its own
                // answers for the workbook's default style, which is what
                // Excel's own `Styles("Normal").Font.Name` says.
                let fallback = self.workbook.default_style.font_name.clone();
                return self
                    .uniform_font(range, |dress| dress.font.clone())
                    .map(|value| {
                        Some(match value {
                            None => Value::Null,
                            Some(Some(named)) => Value::String(named),
                            Some(None) => Value::String(
                                fallback.clone().unwrap_or_else(|| "Calibri".to_string()),
                            ),
                        })
                    });
            }
            if name.eq_ignore_ascii_case("size") {
                // A cell that states no size wears the workbook's, which is
                // 11 in Excel's own default workbook — it answered 11 for a
                // fresh cell and 11 for `Styles("Normal").Font.Size`. It does
                // not answer Empty.
                let fallback = self.workbook.default_style.font_size;
                return self
                    .uniform_font(range, |dress| dress.size)
                    .map(|value| {
                        Some(match value {
                            Some(Some(value)) => Value::Double(f64::from(value)),
                            Some(None) => Value::Double(f64::from(fallback.unwrap_or(11.0))),
                            None => Value::Null,
                        })
                    });
            }
            if name.eq_ignore_ascii_case("color") {
                return self
                    .uniform_font(range, |dress| dress.color.clone())
                    .map(|value| Some(style_color_value(value, BLACK)));
            }
            // Measured: a font never coloured answers ThemeColor 2, the dark
            // text colour; one coloured by number is error 5; one coloured
            // from the theme answers its number. TintAndShade is 0 wherever
            // there is no theme colour.
            if name.eq_ignore_ascii_case("themecolor") {
                return match self.uniform_theme_paint(range, Paint::Font)? {
                    None => Ok(Some(Value::Null)),
                    Some(Some((theme, _))) => Ok(Some(Value::Integer(theme as i64))),
                    Some(None) => match self.uniform_style(range, |style| style.font_color.clone())? {
                        Some(None) => Ok(Some(Value::Integer(2))),
                        Some(Some(_)) => Err(host_error(5, "the font's colour is not a theme colour")),
                        None => Ok(Some(Value::Null)),
                    },
                };
            }
            if name.eq_ignore_ascii_case("tintandshade") {
                return match self.uniform_theme_paint(range, Paint::Font)? {
                    None => Ok(Some(Value::Null)),
                    Some(Some((_, tint))) => Ok(Some(Value::Double(tint))),
                    Some(None) => Ok(Some(Value::Double(0.0))),
                };
            }
            if name.eq_ignore_ascii_case("colorindex") {
                // Excel names a colour by the nearest of its 56. A cell that
                // names none answers 1 — the palette's black — rather than
                // xlAutomatic, which is a state a cell only reaches by being
                // put there.
                return self
                    .uniform_style(range, |style| style.font_color.clone())
                    .map(|value| {
                        Some(match value.map(|held| colour_to_packed(held.as_deref())) {
                            None => Value::Null,
                            Some(None) => Value::Integer(1),
                            Some(Some(packed)) => Value::Integer(nearest_palette_index(packed)),
                        })
                    });
            }
            return Ok(None);
        }
        if let Some(range) = self.range_interior(receiver) {
            // The shade on the pattern is kept nowhere here; Excel answers 0.
            if name.eq_ignore_ascii_case("patterntintandshade") {
                return Ok(Some(Value::Double(0.0)));
            }
            // Measured: a cell with no fill answers ThemeColor xlNone; one
            // filled by number answers 0; one filled from the theme answers
            // its number.
            if name.eq_ignore_ascii_case("themecolor") {
                return match self.uniform_theme_paint(range, Paint::Interior)? {
                    None => Ok(Some(Value::Null)),
                    Some(Some((theme, _))) => Ok(Some(Value::Integer(theme as i64))),
                    Some(None) => match self.uniform_style(range, |style| style.bg_color.clone())? {
                        Some(None) => Ok(Some(Value::Integer(COLOUR_NONE))),
                        Some(Some(_)) => Ok(Some(Value::Integer(0))),
                        None => Ok(Some(Value::Null)),
                    },
                };
            }
            if name.eq_ignore_ascii_case("tintandshade") {
                return match self.uniform_theme_paint(range, Paint::Interior)? {
                    None => Ok(Some(Value::Null)),
                    Some(Some((_, tint))) => Ok(Some(Value::Double(tint))),
                    Some(None) => Ok(Some(Value::Double(0.0))),
                };
            }
            if name.eq_ignore_ascii_case("color") {
                return self
                    .uniform_style(range, |style| style.bg_color.clone())
                    .map(|value| {
                        // The one place Excel does not answer Null for cells
                        // that disagree: a block of mixed fills answers 0,
                        // where `Font.Color` in the same shape answers Null.
                        Some(match value {
                            None => Value::Integer(BLACK),
                            held => style_color_value(held, WHITE),
                        })
                    });
            }
            if name.eq_ignore_ascii_case("pattern") {
                // A bare cell answers `xlPatternNone` and a coloured one
                // `xlSolid` -- of 744 fills in the 285 conformance workbooks,
                // 741 are one of those two -- and a hatched one answers its
                // hatching by Excel's name for it.
                return self
                    .uniform_marked(range, |style, marks| match marks.hatching {
                        Some(hatching) => pattern_name(hatching.kind),
                        None if style.bg_color.is_some() => 1,
                        None => COLOUR_NONE,
                    })
                    .map(|value| Some(value.map(Value::Integer).unwrap_or(Value::Null)));
            }
            if name.eq_ignore_ascii_case("patterncolor") {
                // Automatic is black: measured, a bare cell and a fresh gray50
                // both answer 0.
                return self
                    .uniform_marked(range, |_, marks| {
                        marks.hatching.and_then(|hatching| hatching.colour).unwrap_or(BLACK)
                    })
                    .map(|value| Some(value.map(Value::Integer).unwrap_or(Value::Null)));
            }
            if name.eq_ignore_ascii_case("patterncolorindex") {
                // Measured: xlNone on a bare cell, xlAutomatic on a fresh
                // gray50, and 3 once the pattern is painted red.
                return self
                    .uniform_marked(range, |_, marks| match marks.hatching {
                        None => COLOUR_NONE,
                        Some(Hatching { colour: None, .. }) => COLOUR_AUTOMATIC,
                        Some(Hatching { colour: Some(colour), .. }) => nearest_palette_index(colour),
                    })
                    .map(|value| Some(value.map(Value::Integer).unwrap_or(Value::Null)));
            }
            if name.eq_ignore_ascii_case("colorindex") {
                // A fill with no colour of its own is xlNone -- unless a
                // pattern (a solid one included) sits on the cell, when the
                // colour is xlAutomatic: measured on `Pattern = xlSolid` and
                // `Pattern = xlGray50` over bare cells.
                return self
                    .uniform_marked(range, |style, marks| {
                        match colour_to_packed(style.bg_color.as_deref()) {
                            Some(packed) => nearest_palette_index(packed),
                            None if marks.hatching.is_some() => COLOUR_AUTOMATIC,
                            None => COLOUR_NONE,
                        }
                    })
                    .map(|value| Some(value.map(Value::Integer).unwrap_or(Value::Null)));
            }
            return Ok(None);
        }
        if self.is_window(receiver) {
            let sheet = &self.workbook.sheets[self.active_sheet];
            // Measured: a fresh window answers False / 0 / 0; after selecting
            // B3 and freezing, SplitRow is 2 and SplitColumn 1 -- the rows
            // above and the columns left of the active cell; after selecting
            // row 2, 1 and 0.
            if name.eq_ignore_ascii_case("freezepanes") {
                return Ok(Some(Value::Boolean(
                    sheet.frozen_rows > 0 || sheet.frozen_cols > 0,
                )));
            }
            if name.eq_ignore_ascii_case("splitrow") {
                return Ok(Some(Value::Integer(i64::from(sheet.frozen_rows))));
            }
            if name.eq_ignore_ascii_case("splitcolumn") {
                return Ok(Some(Value::Integer(i64::from(sheet.frozen_cols))));
            }
            if name.eq_ignore_ascii_case("activesheet") {
                return Ok(Some(self.object(HostObject::Worksheet(self.active_sheet))));
            }
            // What the window shows of the sheet in front. Measured on a
            // fresh window: Zoom 100 (a Double), gridlines and headings on,
            // formulas off, zeros on, and both scrolls at 1.
            let view = self.views.get(&self.active_sheet).copied().unwrap_or_default();
            if name.eq_ignore_ascii_case("zoom") {
                return Ok(Some(Value::Double(view.zoom)));
            }
            if name.eq_ignore_ascii_case("displaygridlines") {
                return Ok(Some(Value::Boolean(view.gridlines)));
            }
            if name.eq_ignore_ascii_case("displayheadings") {
                return Ok(Some(Value::Boolean(view.headings)));
            }
            if name.eq_ignore_ascii_case("displayformulas") {
                return Ok(Some(Value::Boolean(view.formulas)));
            }
            if name.eq_ignore_ascii_case("displayzeros") {
                return Ok(Some(Value::Boolean(view.zeros)));
            }
            if name.eq_ignore_ascii_case("scrollrow") {
                return Ok(Some(Value::Integer(i64::from(view.scroll_row))));
            }
            if name.eq_ignore_ascii_case("scrollcolumn") {
                return Ok(Some(Value::Integer(i64::from(view.scroll_column))));
            }
            // A window is open at its full size, in the normal view, with the
            // headings shown: measured on a fresh one.
            if name.eq_ignore_ascii_case("windowstate") {
                return Ok(Some(Value::Integer(-4137)));
            }
            if name.eq_ignore_ascii_case("view") {
                return Ok(Some(Value::Integer(1)));
            }
            if name.eq_ignore_ascii_case("displayheadings") {
                return Ok(Some(Value::Boolean(true)));
            }
            if name.eq_ignore_ascii_case("freezepanes") {
                return Ok(Some(Value::Boolean(sheet.frozen_rows > 0 || sheet.frozen_cols > 0)));
            }
            return Ok(None);
        }
        if let Some(sheet) = self.worksheet(receiver) {
            if name.eq_ignore_ascii_case("comments") {
                return Ok(Some(self.object(HostObject::Comments(sheet))));
            }
            if name.eq_ignore_ascii_case("hyperlinks") {
                return Ok(Some(self.object(HostObject::Hyperlinks(HyperlinkScope::Sheet(sheet)))));
            }
            if name.eq_ignore_ascii_case("listobjects") {
                return Ok(Some(self.object(HostObject::ListObjects(sheet))));
            }
            if name.eq_ignore_ascii_case("pagesetup") {
                return Ok(Some(self.object(HostObject::PageSetup(sheet))));
            }
            if name.eq_ignore_ascii_case("outline") {
                return Ok(Some(self.object(HostObject::Outline(sheet))));
            }
            if name.eq_ignore_ascii_case("tab") {
                return Ok(Some(self.object(HostObject::Tab(sheet))));
            }
            if name.eq_ignore_ascii_case("sort") {
                return Ok(Some(self.object(HostObject::Sort(sheet))));
            }
            if name.eq_ignore_ascii_case("shapes") || name.eq_ignore_ascii_case("drawingobjects") {
                return Ok(Some(self.object(HostObject::Drawing(shapes::DrawingPart::Shapes(sheet)))));
            }
            if name.eq_ignore_ascii_case("chartobjects") {
                return Ok(Some(self.object(HostObject::Drawing(shapes::DrawingPart::ChartObjects(sheet)))));
            }
            // What the sheet was protected with. `ProtectContents` is False
            // for a sheet protected with `Contents:=False`, and
            // `ProtectionMode` is the `UserInterfaceOnly` flag.
            if name.eq_ignore_ascii_case("protectcontents") {
                return Ok(Some(Value::Boolean(
                    self.protected
                        .get(sheet)
                        .and_then(Option::as_ref)
                        .is_some_and(|held| held.contents),
                )));
            }
            if name.eq_ignore_ascii_case("protectdrawingobjects") {
                return Ok(Some(Value::Boolean(self.objects_protected(sheet))));
            }
            if name.eq_ignore_ascii_case("protectionmode") {
                return Ok(Some(Value::Boolean(
                    self.protected
                        .get(sheet)
                        .and_then(Option::as_ref)
                        .is_some_and(|held| held.user_interface_only),
                )));
            }
        }
        if self.is_application(receiver) {
            if name.eq_ignore_ascii_case("worksheetfunction") {
                return Ok(Some(self.object(HostObject::WorksheetFunction)));
            }
            if name.eq_ignore_ascii_case("screenupdating") {
                return Ok(Some(Value::Boolean(self.screen_updating)));
            }
            if name.eq_ignore_ascii_case("enableevents") {
                return Ok(Some(Value::Boolean(self.enable_events)));
            }
            if name.eq_ignore_ascii_case("displayalerts") {
                return Ok(Some(Value::Boolean(self.display_alerts)));
            }
            if name.eq_ignore_ascii_case("calculation") {
                return Ok(Some(Value::Integer(self.calculation)));
            }
            if name.eq_ignore_ascii_case("statusbar") {
                // While the bar is Excel's own it answers False, which is how
                // a macro asks whether anything has taken it over.
                return Ok(Some(match &self.status_bar {
                    Some(shown) => Value::String(shown.clone()),
                    None => Value::Boolean(false),
                }));
            }
            if name.eq_ignore_ascii_case("cursor") {
                return Ok(Some(Value::Integer(self.cursor)));
            }
            if name.eq_ignore_ascii_case("interactive") {
                return Ok(Some(Value::Boolean(self.interactive)));
            }
            if matches!(
                name.to_ascii_lowercase().as_str(),
                "displayformulabar" | "displaystatusbar"
            ) {
                return Ok(Some(Value::Boolean(true)));
            }
            if name.eq_ignore_ascii_case("windowstate") {
                return Ok(Some(Value::Integer(-4137)));
            }
            if name.eq_ignore_ascii_case("cutcopymode") {
                // xlCut is 2 and xlCopy 1 -- measured, a Cut answers 2 and a
                // Copy 1 -- and nothing held answers 0, which is False, and
                // is how a macro asks whether anything is.
                return Ok(Some(Value::Integer(if self.pending_cut.is_some() {
                    2
                } else if self.clipboard.is_some() {
                    1
                } else {
                    0
                })));
            }
            if name.eq_ignore_ascii_case("activesheet") {
                return Ok(Some(self.object(HostObject::Worksheet(self.active_sheet))));
            }
            if name.eq_ignore_ascii_case("activeworkbook")
                || name.eq_ignore_ascii_case("thisworkbook")
            {
                return Ok(Some(self.object(HostObject::Workbook)));
            }
            if name.eq_ignore_ascii_case("workbooks") {
                return Ok(Some(self.object(HostObject::Workbooks)));
            }
            if name.eq_ignore_ascii_case("worksheets") || name.eq_ignore_ascii_case("sheets") {
                return Ok(Some(self.object(HostObject::Worksheets)));
            }
            if name.eq_ignore_ascii_case("names") {
                return Ok(Some(self.object(HostObject::Names)));
            }
            if name.eq_ignore_ascii_case("selection") || name.eq_ignore_ascii_case("activecell") {
                let range = if name.eq_ignore_ascii_case("activecell") {
                    CellRange::single(self.active_cell)
                } else {
                    self.selection
                };
                return Ok(Some(self.object(HostObject::Range(range))));
            }
            if name.eq_ignore_ascii_case("rows") {
                return self
                    .worksheet_axis_object_or_item(self.active_sheet, RangeAxis::Rows, &[])
                    .map(Some);
            }
            if name.eq_ignore_ascii_case("columns") {
                return self
                    .worksheet_axis_object_or_item(self.active_sheet, RangeAxis::Columns, &[])
                    .map(Some);
            }
            return Ok(None);
        }
        if self.is_workbook(receiver) {
            if name.eq_ignore_ascii_case("worksheets") || name.eq_ignore_ascii_case("sheets") {
                return Ok(Some(self.object(HostObject::Worksheets)));
            }
            // Every name the workbook holds. Excel counts a sheet's own names
            // among these as well, spelling each `Sheet1!total`, and answers
            // `Worksheet.Names` with just that sheet's — but the parser keeps
            // no sheet-scoped names, so that member is left to refuse rather
            // than hand back an empty collection, which would read as a sheet
            // having none.
            if name.eq_ignore_ascii_case("names") {
                return Ok(Some(self.object(HostObject::Names)));
            }
            if name.eq_ignore_ascii_case("activesheet") {
                return Ok(Some(self.object(HostObject::Worksheet(self.active_sheet))));
            }
            // Measured in Excel 16.0: a workbook that has never been saved is
            // called `Book1`, its `Path` is empty, and its `FullName` is the
            // name alone. Saved, the three become `a report.xlsx`, the folder
            // without a separator after it, and the two joined. A workbook
            // open in a browser is the first of those with a name of its own:
            // there is a file behind it, but no folder anyone can name.
            if name.eq_ignore_ascii_case("name") || name.eq_ignore_ascii_case("fullname") {
                return Ok(Some(Value::String(
                    self.file_name.clone().unwrap_or_else(|| "Book1".to_string()),
                )));
            }
            if name.eq_ignore_ascii_case("path") {
                return Ok(Some(Value::String(String::new())));
            }
            // Measured: a fresh workbook is not Saved; saying it is makes it
            // so until the next cell is written.
            if name.eq_ignore_ascii_case("saved") {
                return Ok(Some(Value::Boolean(self.saved)));
            }
        }
        if self.is_worksheets(receiver) {
            if name.eq_ignore_ascii_case("add") {
                return self.add_worksheet(&[]).map(Some);
            }
            if name.eq_ignore_ascii_case("count") {
                return Ok(Some(Value::Integer(self.workbook.sheets.len() as i64)));
            }
            return Ok(None);
        }
        if let Some((range, axis)) = self.range_collection(receiver) {
            if name.eq_ignore_ascii_case("count") {
                let count = match axis {
                    RangeAxis::Rows => range.end_row - range.start_row + 1,
                    RangeAxis::Columns => range.end_column - range.start_column + 1,
                };
                return Ok(Some(Value::Integer(i64::from(count))));
            }
            // Everything else a range answers, a row or a column answers the
            // same way, so this falls through to the ordinary range arms
            // rather than stopping here.
        }
        if let Some(sheet) = self.worksheet(receiver) {
            if name.eq_ignore_ascii_case("visible") {
                return Ok(Some(Value::Integer(
                    match self.workbook.sheets[sheet].visibility {
                        oxicells_core::ir::Visibility::Visible => -1,
                        oxicells_core::ir::Visibility::Hidden => 0,
                        oxicells_core::ir::Visibility::VeryHidden => 2,
                    },
                )));
            }
            if name.eq_ignore_ascii_case("name") {
                return Ok(Some(Value::String(
                    self.workbook.sheets[sheet].name.clone(),
                )));
            }
            // A worksheet is the only kind this build holds, and Excel names
            // that kind -4167.
            if name.eq_ignore_ascii_case("type") {
                return Ok(Some(Value::Integer(-4167)));
            }
            // What holds the sheet is the workbook, as `Range("A1").Parent`
            // is the sheet.
            if name.eq_ignore_ascii_case("parent") {
                return Ok(Some(self.object(HostObject::Workbook)));
            }
            // The default row height, in points. Excel answers 18.75 on a new
            // sheet and will not let it be written — `StandardHeight = 20`
            // raises. (`StandardWidth` is left out: Excel answers it in
            // characters of the standard font, which is a measurement this
            // build cannot make.)
            if name.eq_ignore_ascii_case("standardheight") {
                return Ok(Some(Value::Double(f64::from(
                    self.workbook.sheets[sheet].default_row_height,
                ))));
            }
            // The sheet beside this one, or Nothing at either end — the same
            // shape as a range's own Next and Previous.
            if name.eq_ignore_ascii_case("next") || name.eq_ignore_ascii_case("previous") {
                let beside = if name.eq_ignore_ascii_case("next") {
                    if sheet + 1 >= self.workbook.sheets.len() {
                        return Ok(Some(Value::Nothing));
                    }
                    sheet + 1
                } else {
                    if sheet == 0 {
                        return Ok(Some(Value::Nothing));
                    }
                    sheet - 1
                };
                return Ok(Some(self.object(HostObject::Worksheet(beside))));
            }
            // `Cells` with nothing after it is the whole grid. Excel cannot
            // count it — `Cells.Count` overflows a Long and raises — and
            // neither can this: the count runs into the execution limit and
            // says so.
            if name.eq_ignore_ascii_case("cells") {
                return Ok(Some(self.object(HostObject::Range(CellRange {
                    sheet,
                    start_row: 1,
                    start_column: 0,
                    end_row: MAX_WORKSHEET_ROW,
                    end_column: MAX_WORKSHEET_COLUMN,
                }))));
            }
            if name.eq_ignore_ascii_case("autofiltermode") {
                let filtering = self
                    .auto_filter
                    .as_ref()
                    .is_some_and(|filter| filter.range.sheet == sheet);
                return Ok(Some(Value::Boolean(filtering)));
            }
            // Measured: FilterMode is True while a filter hides anything, and
            // False again after ShowAllData, with AutoFilterMode still True.
            if name.eq_ignore_ascii_case("filtermode") {
                let filtering = self
                    .auto_filter
                    .as_ref()
                    .is_some_and(|filter| filter.range.sheet == sheet && !filter.fields.is_empty());
                return Ok(Some(Value::Boolean(filtering)));
            }
            if name.eq_ignore_ascii_case("index") {
                return Ok(Some(Value::Integer(sheet as i64 + 1)));
            }
            if name.eq_ignore_ascii_case("usedrange") {
                return self.used_range_object(sheet).map(Some);
            }
            if name.eq_ignore_ascii_case("rows") {
                return self
                    .worksheet_axis_object_or_item(sheet, RangeAxis::Rows, &[])
                    .map(Some);
            }
            if name.eq_ignore_ascii_case("columns") {
                return self
                    .worksheet_axis_object_or_item(sheet, RangeAxis::Columns, &[])
                    .map(Some);
            }
            return Ok(None);
        }
        let Some(range) = self.range(receiver) else {
            return Ok(None);
        };
        if name.eq_ignore_ascii_case("value") {
            self.settle(range);
            return self.range_value(range).map(Some);
        }
        // `Value2` is the number under the dress: measured, a cell typed
        // `1/5/2024` answers a Date to `Value` and 45296 to `Value2`, and a
        // cell typed `$3` answers a Currency and then 3.
        if name.eq_ignore_ascii_case("value2") {
            self.settle(range);
            return self.range_value(range).map(|value| Some(undressed(value)));
        }
        // The `Local` forms read and write the same text on this Office,
        // whose function names and separators are English: measured,
        // `FormulaLocal` of `=A1*2` is `=A1*2` and `NumberFormatLocal` of
        // General is `General`.
        if name.eq_ignore_ascii_case("formula")
            || name.eq_ignore_ascii_case("formula2")
            || name.eq_ignore_ascii_case("formulalocal")
        {
            return self.range_formula(range, FormulaStyle::A1).map(Some);
        }
        if name.eq_ignore_ascii_case("formular1c1")
            || name.eq_ignore_ascii_case("formula2r1c1")
            || name.eq_ignore_ascii_case("formular1c1local")
        {
            return self.range_formula(range, FormulaStyle::R1C1).map(Some);
        }
        if name.eq_ignore_ascii_case("hasformula") {
            return self.range_has_formula(range).map(Some);
        }
        if name.eq_ignore_ascii_case("hasarray") {
            // Measured: C1:D2, with only C1:C2 an array, answers True -- a
            // Boolean for its first cell, not Null for the disagreement.
            return Ok(Some(Value::Boolean(self.array_of(range.first()).is_some())));
        }
        if name.eq_ignore_ascii_case("formulaarray") {
            return self.range_formula_array(range).map(Some);
        }
        if name.eq_ignore_ascii_case("currentarray") {
            // The block the cell's array formula covers. Measured: asked of a
            // cell in no array, it is 1004.
            let Some((top, left, bottom, right)) = self.array_of(range.first()) else {
                return Err(host_error(1004, "the cell is not part of an array"));
            };
            let held = CellRange {
                sheet: range.sheet,
                start_row: top,
                start_column: left,
                end_row: bottom,
                end_column: right,
            };
            return Ok(Some(self.object(HostObject::Range(held))));
        }
        if name.eq_ignore_ascii_case("comment") {
            return Ok(Some(self.comment_of(range)));
        }
        if name.eq_ignore_ascii_case("style") {
            return Ok(Some(self.style_of(range)));
        }
        if name.eq_ignore_ascii_case("characters") {
            return self.characters_object(range, &[]).map(Some);
        }
        if name.eq_ignore_ascii_case("validation") {
            return Ok(Some(self.object(HostObject::Validation(range))));
        }
        if name.eq_ignore_ascii_case("formatconditions") {
            return Ok(Some(self.object(HostObject::FormatConditions(range))));
        }
        if name.eq_ignore_ascii_case("displayformat") {
            return Ok(Some(self.object(HostObject::DisplayFormat(range))));
        }
        if name.eq_ignore_ascii_case("listobject") {
            return Ok(Some(self.list_object_of(range)));
        }
        if name.eq_ignore_ascii_case("hyperlinks") {
            return Ok(Some(self.object(HostObject::Hyperlinks(HyperlinkScope::Range(range)))));
        }
        if name.eq_ignore_ascii_case("notetext") {
            return self.note_text_member(range, &[]).map(Some);
        }
        if name.eq_ignore_ascii_case("parent") || name.eq_ignore_ascii_case("worksheet") {
            return Ok(Some(self.object(HostObject::Worksheet(range.sheet))));
        }
        if name.eq_ignore_ascii_case("name") {
            // Excel answers with the Name itself, and with Nothing where the
            // block has not been given one.
            let stands_for = self.address_of(range);
            let held = self
                .workbook
                .defined_names
                .iter()
                .find(|(_, refers_to)| refers_to.eq_ignore_ascii_case(&stands_for))
                .map(|(held, _)| held.clone());
            return Ok(Some(match held {
                Some(held) => self.name_object(&held),
                None => Value::Nothing,
            }));
        }
        // Both of these SET the row-or-column sense rather than passing one
        // along: asked of Excel, `Range("A1:C3").EntireRow.Count` is 3 — its
        // rows — and `.EntireColumn.Count` is 3 as well, its columns, where a
        // plain range of the same cells counts 9.
        if name.eq_ignore_ascii_case("entirerow") {
            return Ok(Some(self.object(HostObject::RangeCollection(
                CellRange {
                    start_column: 0,
                    end_column: MAX_WORKSHEET_COLUMN,
                    ..range
                },
                RangeAxis::Rows,
            ))));
        }
        if name.eq_ignore_ascii_case("entirecolumn") {
            return Ok(Some(self.object(HostObject::RangeCollection(
                CellRange {
                    start_row: 1,
                    end_row: MAX_WORKSHEET_ROW,
                    ..range
                },
                RangeAxis::Columns,
            ))));
        }
        if name.eq_ignore_ascii_case("font") {
            return Ok(Some(self.object(HostObject::RangeFont(range))));
        }
        if name.eq_ignore_ascii_case("interior") {
            return Ok(Some(self.object(HostObject::RangeInterior(range))));
        }
        if name.eq_ignore_ascii_case("borders") {
            return Ok(Some(
                self.object(HostObject::RangeBorders(range, BorderSelection::All)),
            ));
        }
        if name.eq_ignore_ascii_case("verticalalignment") {
            // A cell that says nothing of its own wears the workbook's default
            // style, and only when that says nothing either does the file
            // format's own answer — the bottom — apply.
            //
            // Worth saying because the measurement nearly became a law: on the
            // machine this was asked, a brand new cell answered xlCenter, and
            // the reason is that Excel had written `<alignment
            // vertical="center"/>` into the Normal style of its own default
            // workbook. The object model reports what a cell EFFECTIVELY
            // wears, not what it states.
            let fallback = self.workbook.default_style.vertical_align.clone();
            return self
                .uniform_style(range, |style| style.vertical_align.clone())
                .map(|value| {
                    let seen = match value {
                        None => return Some(Value::Null),
                        Some(Some(named)) => Some(named),
                        Some(None) => fallback.clone(),
                    };
                    Some(Value::Integer(match seen.as_deref() {
                        Some("top") => -4160,
                        Some("center") | Some("centre") => -4108,
                        Some("justify") => -4130,
                        Some("distributed") => -4117,
                        _ => -4107,
                    }))
                });
        }
        // Every cell starts locked, and a range whose cells disagree answers
        // Null, the way Bold does.
        if name.eq_ignore_ascii_case("locked") {
            let mut seen: Option<bool> = None;
            for address in range.addresses() {
                let locked = !self.unlocked.contains(&address);
                match seen {
                    None => seen = Some(locked),
                    Some(held) if held == locked => {}
                    Some(_) => return Ok(Some(Value::Null)),
                }
            }
            return Ok(Some(seen.map(Value::Boolean).unwrap_or(Value::Boolean(true))));
        }
        if name.eq_ignore_ascii_case("wraptext") {
            // A range whose cells disagree answers Null, as Bold and
            // NumberFormat already do — measured on a pair where only one of
            // the two wraps.
            return self
                .uniform_style(range, |style| style.wrap_text)
                .map(|value| Some(value.map(Value::Boolean).unwrap_or(Value::Null)));
        }
        if name.eq_ignore_ascii_case("shrinktofit") {
            // Measured in Excel: False on a cell nobody has touched, True once
            // set, and Null across a pair where only one of them shrinks —
            // the same answer WrapText and Bold give.
            return self
                .uniform_style(range, |style| style.shrink_to_fit)
                .map(|value| Some(value.map(Value::Boolean).unwrap_or(Value::Null)));
        }
        if name.eq_ignore_ascii_case("orientation") {
            // Stacked writing answers xlVertical, and a turn answers its
            // angle -- except the two Excel has names for: measured, 90
            // reads back as xlUpward and -90 as xlDownward, where 45 is 45.
            return self
                .uniform_marked(range, |style, marks| {
                    if style.stacked_text {
                        return -4166;
                    }
                    match marks.rotation {
                        Some(90) => -4171,
                        Some(-90) => -4170,
                        Some(turn) => i64::from(turn),
                        None => -4128,
                    }
                })
                .map(|value| Some(value.map(Value::Integer).unwrap_or(Value::Null)));
        }
        if name.eq_ignore_ascii_case("addindent") {
            return self
                .uniform_marked(range, |_, marks| marks.indented)
                .map(|value| Some(value.map(Value::Boolean).unwrap_or(Value::Null)));
        }
        if name.eq_ignore_ascii_case("outlinelevel") {
            let Some((axis, first, last)) = Self::outline_band(range) else {
                return Err(host_error(1004, "OutlineLevel is a property of whole rows or columns"));
            };
            let mut level = None;
            for index in first..=last {
                let held = self.outline_level(range.sheet, axis, index);
                if level.is_some_and(|seen| seen != held) {
                    return Ok(Some(Value::Null));
                }
                level = Some(held);
            }
            return Ok(Some(Value::Integer(i64::from(level.unwrap_or(1)))));
        }
        if name.eq_ignore_ascii_case("readingorder") {
            // Excel leaves a cell reading by context, which is -5002.
            return Ok(Some(Value::Integer(-5002)));
        }
        if name.eq_ignore_ascii_case("indentlevel") {
            return self
                .uniform_style(range, |style| style.indent)
                .map(|value| {
                    Some(value.map(|indent| Value::Integer(i64::from(indent))).unwrap_or(Value::Null))
                });
        }
        if name.eq_ignore_ascii_case("numberformat") || name.eq_ignore_ascii_case("numberformatlocal")
        {
            return self
                .uniform_style(range, |style| style.number_format.clone())
                .map(|value| {
                    Some(match value {
                        Some(Some(value)) => Value::String(value),
                        Some(None) => Value::String("General".to_string()),
                        None => Value::Null,
                    })
                });
        }
        if name.eq_ignore_ascii_case("horizontalalignment") {
            return self
                .uniform_style(range, |style| style.horizontal_align.clone())
                .map(|value| Some(horizontal_alignment_value(value)));
        }
        if name.eq_ignore_ascii_case("columnwidth") {
            return self.range_column_width(range).map(Some);
        }
        if name.eq_ignore_ascii_case("rowheight") {
            return self.range_row_height(range).map(Some);
        }
        if name.eq_ignore_ascii_case("width")
            || name.eq_ignore_ascii_case("height")
            || name.eq_ignore_ascii_case("left")
            || name.eq_ignore_ascii_case("top")
        {
            return Ok(Some(self.range_extent(range, &name.to_ascii_lowercase())));
        }
        if name.eq_ignore_ascii_case("text") {
            self.settle(range);
            return Ok(Some(self.range_text(range)));
        }
        if name.eq_ignore_ascii_case("hidden") {
            return self.range_hidden(range).map(Some);
        }
        if name.eq_ignore_ascii_case("mergearea") {
            // The block a cell belongs to, or the range itself where it
            // belongs to none: asked of Excel, `Range("B2").MergeArea` inside
            // the merge `A1:B2` answers `$A$1:$B$2`, and a cell in no merge
            // answers with itself.
            let held = self
                .workbook
                .sheets
                .get(range.sheet)
                .ok_or_else(|| "worksheet no longer exists".to_string())?
                .merge_cells
                .iter()
                .map(|merge| merge_range(range.sheet, merge))
                .find(|merge| ranges_overlap(range, *merge));
            return Ok(Some(self.object(HostObject::Range(held.unwrap_or(range)))));
        }
        if name.eq_ignore_ascii_case("mergecells") {
            return self.range_merge_state(range).map(Some);
        }
        if name.eq_ignore_ascii_case("row") {
            return Ok(Some(Value::Integer(i64::from(range.start_row))));
        }
        if name.eq_ignore_ascii_case("column") {
            return Ok(Some(Value::Integer(i64::from(range.start_column) + 1)));
        }
        if name.eq_ignore_ascii_case("count") || name.eq_ignore_ascii_case("countlarge") {
            let count = Self::range_cell_count_large(range)?;
            // `Count` is a Long, and Excel stops answering it at exactly the
            // point one overflows: `A1:XFD131071` counts 2,147,467,264 and
            // comes back, `A1:XFD131072` is 2,147,483,648 and comes back with
            // nothing at all. `CountLarge` answers either way, and is what
            // the whole grid's 17,179,869,184 has to be asked for.
            if name.eq_ignore_ascii_case("count") && count > i64::from(i32::MAX) as u64 {
                return Err(host_error(6, format!("Range.Count cannot hold {count} cells; ask CountLarge")));
            }
            // And `CountLarge` says so in its TYPE: asked of Excel,
            // `TypeName(Range("A1").CountLarge)` is LongLong where `Count` is
            // a Long. It could not say that here until the runtime had a
            // LongLong of its own.
            return Ok(Some(if name.eq_ignore_ascii_case("countlarge") {
                Value::LongLong(count as i64)
            } else {
                Value::Integer(count as i64)
            }));
        }
        // Every range has these, not only one made of several blocks: asked
        // of Excel, `Range("A1").Areas.Count` is 1 and its one area is A1.
        // A macro that walks `Selection.Areas` has to keep working when the
        // selection happens to be in one piece.
        if name.eq_ignore_ascii_case("areas") {
            return Ok(Some(self.areas_of(range)));
        }
        // `Cells` with nothing in brackets after it is the range itself:
        // `Range("B2:C3").Cells` counts 4 and spells itself B2:C3.
        if name.eq_ignore_ascii_case("cells") {
            return Ok(Some(self.object(HostObject::Range(range))));
        }
        // A step sideways from the top-left cell, and only ever one cell
        // however big the range is: asked of Excel, `Range("A1:B2").Next` is
        // B1 and `Range("B2:C3").Previous` is A2. Neither wraps to another
        // row — `A2.Previous` and `XFD1.Next` are both Nothing.
        if name.eq_ignore_ascii_case("next") || name.eq_ignore_ascii_case("previous") {
            let forward = name.eq_ignore_ascii_case("next");
            let column = if forward {
                if range.start_column >= MAX_WORKSHEET_COLUMN {
                    return Ok(Some(Value::Nothing));
                }
                range.start_column + 1
            } else {
                if range.start_column == 0 {
                    return Ok(Some(Value::Nothing));
                }
                range.start_column - 1
            };
            return Ok(Some(self.object(HostObject::Range(CellRange::single(
                CellAddress {
                    sheet: range.sheet,
                    row: range.start_row,
                    column,
                },
            )))));
        }
        if name.eq_ignore_ascii_case("address") {
            return Ok(Some(Value::String(format_range_address(range, true, true))));
        }
        if name.eq_ignore_ascii_case("currentregion") {
            return self.current_region_object(range).map(Some);
        }
        if name.eq_ignore_ascii_case("rows") {
            return Ok(Some(
                self.object(HostObject::RangeCollection(range, RangeAxis::Rows)),
            ));
        }
        if name.eq_ignore_ascii_case("columns") {
            return Ok(Some(
                self.object(HostObject::RangeCollection(range, RangeAxis::Columns)),
            ));
        }
        Ok(None)
    }

    fn set(&mut self, receiver: &ObjectRef, name: &str, value: Value) -> Result<bool, String> {
        if self.gone(receiver) {
            return Err(host_error(424, "the object's worksheet has been deleted"));
        }
        if let Some(sheet) = self.tab_sheet(receiver) {
            return self.set_tab_member(sheet, name, &value);
        }
        if let Some(HostObject::Sort(sheet)) = self.objects.get(receiver.handle as usize).copied() {
            let state = self.sorts.entry(sheet).or_default();
            match name.to_ascii_lowercase().as_str() {
                "header" => state.header = any_whole_number(&value).unwrap_or(0),
                "matchcase" => state.match_case = style_face_boolean(&value, "Sort.MatchCase")?.unwrap_or(false),
                "orientation" => state.sideways = any_whole_number(&value) == Some(2),
                // SortMethod (xlPinYin / xlStroke) is kept nowhere here.
                "sortmethod" => {}
                _ => return Ok(false),
            }
            return Ok(true);
        }
        if let Some(part) = self.drawing_part(receiver) {
            return self.drawing_set(part, name, value);
        }
        if self.is_workbook(receiver) && name.eq_ignore_ascii_case("saved") {
            self.saved = style_face_boolean(&value, "Workbook.Saved")?.unwrap_or(false);
            return Ok(true);
        }
        if let Some(sheet) = self.outline_sheet(receiver) {
            let outline = self.outlines.entry(sheet).or_default();
            if name.eq_ignore_ascii_case("summaryrow") {
                match any_whole_number(&value) {
                    Some(side @ (0 | 1)) => outline.summary_row = side,
                    _ => return Err(host_error(1004, "Outline.SummaryRow takes xlSummaryAbove or xlSummaryBelow")),
                }
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("summarycolumn") {
                match any_whole_number(&value) {
                    Some(side @ (-4152 | -4131)) => outline.summary_column = side,
                    _ => return Err(host_error(1004, "Outline.SummaryColumn takes xlSummaryOnLeft or xlSummaryOnRight")),
                }
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("automaticstyles") {
                outline.automatic_styles =
                    style_face_boolean(&value, "Outline.AutomaticStyles")?.unwrap_or(false);
                return Ok(true);
            }
            return Ok(false);
        }
        if let Some(range) = self.validation_range(receiver) {
            return self.set_validation(range, name, value);
        }
        if let Some((id, face)) = self.condition_id(receiver) {
            return self.set_condition(id, face, name, value);
        }
        if let Some((id, part)) = self.table_part(receiver) {
            return self.set_table(id, part, name, value);
        }
        if let Some(sheet) = self.page_setup_sheet(receiver) {
            return self.set_page_setup(sheet, name, value);
        }
        if let Some((at, start, length)) = self.characters_of(receiver) {
            if name.eq_ignore_ascii_case("text") || name.eq_ignore_ascii_case("caption") {
                let with = match &value {
                    Value::String(text) => text.clone(),
                    value if any_number(value).is_some() => shown_text(value, None),
                    _ => return Err("Characters.Text takes text".to_string()),
                };
                self.replace_characters(at, start, length, &with)?;
                return Ok(true);
            }
            return Ok(false);
        }
        if let Some((at, start, length)) = self.characters_font_of(receiver) {
            return self.set_characters_font(at, start, length, name, value);
        }
        if let Some(id) = self.link_id(receiver) {
            let Some(index) = self.link_index(id) else {
                return Err("the hyperlink has been deleted".to_string());
            };
            let text = match &value {
                Value::String(text) => text.clone(),
                value if any_number(value).is_some() => shown_text(value, None),
                _ => return Err("a hyperlink's parts are text".to_string()),
            };
            if name.eq_ignore_ascii_case("address") {
                self.links[index].address = kept_address(&text);
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("subaddress") {
                self.links[index].sub_address = text;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("screentip") {
                self.links[index].screen_tip = text;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("texttodisplay") {
                let anchor = self.links[index].anchor;
                let corner = CellAddress {
                    sheet: anchor.sheet,
                    row: anchor.start_row,
                    column: anchor.start_column,
                };
                self.set_cell_value(corner, CellValue::String(text))?;
                return Ok(true);
            }
            return Ok(false);
        }
        if let Some(at) = self.comment_cell(receiver) {
            if name.eq_ignore_ascii_case("visible") {
                let Some(index) = self.note_at(at) else {
                    return Err("the comment has been deleted".to_string());
                };
                if let Some(visible) = style_face_boolean(&value, "Comment.Visible")? {
                    self.notes[index].visible = visible;
                }
                return Ok(true);
            }
            return Ok(false);
        }
        if self.is_window(receiver) && name.eq_ignore_ascii_case("freezepanes") {
            let Some(freeze) = style_face_boolean(&value, "Window.FreezePanes")? else {
                return Ok(true);
            };
            let sheet = self.active_sheet;
            let at = self.active_cell;
            let held = &mut self.workbook.sheets[sheet];
            if !freeze {
                held.frozen_rows = 0;
                held.frozen_cols = 0;
                return Ok(true);
            }
            // Freezing panes already frozen leaves them where they are:
            // measured, frozen at A4 and asked again from B2, the split stays
            // at row 3.
            if held.frozen_rows > 0 || held.frozen_cols > 0 {
                return Ok(true);
            }
            // The panes freeze above and to the left of the active cell: B3
            // gives two rows and one column, and a whole selected row gives
            // its rows and no columns. From A1 Excel instead splits the
            // visible window down the middle, which is the window's size and
            // not the sheet's: 21 rows and 13 columns on the machine measured,
            // in a window Excel opened at its default size. A browser host
            // has no window to halve, so that default window stands in --
            // the panes DO freeze, as they do in Excel, which a macro that
            // reads `FreezePanes` back can see.
            let (rows, cols) = match (at.row.saturating_sub(1), at.column) {
                (0, 0) => (21, 13),
                split => split,
            };
            held.frozen_rows = rows;
            held.frozen_cols = cols;
            // The scrolling pane starts under the frozen one: measured,
            // frozen from B2 with the window at the top, ScrollRow is 2.
            let view = self.views.entry(sheet).or_default();
            view.scroll_row = rows + 1;
            view.scroll_column = cols + 1;
            return Ok(true);
        }
        if self.is_window(receiver) {
            if let Some(set) = self.set_view(name, &value)? {
                return Ok(set);
            }
            // What a recorder does to the window that the browser has no way
            // to honour but must not refuse: its size, its view, the
            // headings, and the two scroll members that move by a screen.
            if matches!(
                name.to_ascii_lowercase().as_str(),
                "windowstate" | "view" | "displayheadings" | "displayoutline"
                    | "displayworkbooktabs" | "displayhorizontalscrollbar"
                    | "displayverticalscrollbar" | "zoom" | "tabratio"
            ) {
                // Zoom is already taken by set_view; the rest are accepted.
                if !name.eq_ignore_ascii_case("zoom") {
                    return Ok(true);
                }
            }
        }
        match self.objects.get(receiver.handle as usize) {
            Some(HostObject::Blocks(handle)) => {
                let handle = *handle;
                return self.set_on_every_block(handle, None, name, value);
            }
            Some(HostObject::BlocksStyle(handle, face)) => {
                let (handle, face) = (*handle, *face);
                return self.set_on_every_block(handle, Some(face), name, value);
            }
            _ => {}
        }
        if let Some(held) = self.held_name(receiver).map(str::to_string) {
            let Some(at) = self.name_at(&held) else {
                return Err(format!("the name {held:?} is no longer in the workbook"));
            };
            let Value::String(written) = &value else {
                return Err(format!("Name.{name} must be given a String"));
            };
            if name.eq_ignore_ascii_case("name") {
                check_name(written)?;
                self.workbook.defined_names[at].0 = written.clone();
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("refersto") || name.eq_ignore_ascii_case("value") {
                let written = written.trim();
                self.workbook.defined_names[at].1 = match written.strip_prefix('=') {
                    Some(rest) => rest.trim().to_string(),
                    None => format!("\"{}\"", written.replace('"', "\"\"")),
                };
                return Ok(true);
            }
            return Ok(false);
        }
        if let Some(sheet) = self.worksheet(receiver) {
            // Measured: `AutoFilterMode = False` takes the filter off and
            // shows every row; `= True` is 1004 and changes nothing.
            if name.eq_ignore_ascii_case("autofiltermode") {
                let asked = style_face_boolean(&value, "Worksheet.AutoFilterMode")?.unwrap_or(false);
                if asked {
                    return Err(host_error(1004, "AutoFilterMode can only be turned off"));
                }
                if self.auto_filter.as_ref().is_some_and(|filter| filter.range.sheet == sheet) {
                    self.auto_filter = None;
                    self.workbook.sheets[sheet].auto_filter = None;
                    self.show_all_rows(sheet)?;
                }
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("name") {
                let Value::String(renamed) = &value else {
                    return Err("a worksheet name must be a String".to_string());
                };
                self.rename_worksheet(sheet, renamed)?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("visible") {
                // Excel takes True and False as well as the three numbers, and
                // reads 1 as True: asked with it, it answered -1.
                let asked = match &value {
                    Value::Boolean(true) => -1,
                    Value::Boolean(false) => 0,
                    value if any_whole_number(value).is_some() => any_whole_number(value).unwrap_or_default(),
                    _ => {
                        return Err("Worksheet.Visible takes True, False or a number".to_string())
                    }
                };
                let visibility = match asked {
                    0 => oxicells_core::ir::Visibility::Hidden,
                    2 => oxicells_core::ir::Visibility::VeryHidden,
                    -1 | 1 => oxicells_core::ir::Visibility::Visible,
                    other => return Err(format!("Worksheet.Visible has no setting {other}")),
                };
                // A workbook has to show something. Asked to hide its last
                // showing sheet, Excel refuses.
                if !visibility.is_shown()
                    && !self
                        .workbook
                        .sheets
                        .iter()
                        .enumerate()
                        .any(|(index, held)| index != sheet && held.visibility.is_shown())
                {
                    return Err(
                        "Worksheet.Visible cannot hide the only sheet still showing".to_string(),
                    );
                }
                self.workbook.sheets[sheet].visibility = visibility;
                return Ok(true);
            }
        }
        if self.is_application(receiver) {
            if name.eq_ignore_ascii_case("cutcopymode") {
                // Excel takes False and lets go of what it held. It takes the
                // two constants as well, but they mean the same thing here:
                // there is no way to start holding something by saying so.
                self.clipboard = None;
                self.pending_cut = None;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("screenupdating") {
                self.screen_updating = application_switch(&value, "Application.ScreenUpdating")?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("enableevents") {
                self.enable_events = application_switch(&value, "Application.EnableEvents")?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("displayalerts") {
                self.display_alerts = application_switch(&value, "Application.DisplayAlerts")?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("calculation") {
                self.calculation = application_calculation(&value)?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("statusbar") {
                self.status_bar = status_bar_text(&value)?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("cursor") {
                self.cursor = application_cursor(&value)?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("interactive") {
                self.interactive = application_switch(&value, "Application.Interactive")?;
                return Ok(true);
            }
            // The rest of what a recorder turns off while it works, none of
            // which a browser has to honour but none of which may refuse.
            if matches!(
                name.to_ascii_lowercase().as_str(),
                "displayformulabar" | "displaystatusbar" | "displayscrollbars"
                    | "windowstate" | "calculatebeforesave" | "enableanimations"
                    | "printcommunication" | "displaycommentindicator"
                    | "askToUpdateLinks" | "asktoupdatelinks" | "enablecancelkey"
                    | "automationsecurity" | "referencestyle" | "sheetsinnewworkbook"
            ) {
                return Ok(true);
            }
            return Ok(false);
        }
        if let Some((range, selection)) = self.range_borders(receiver) {
            if name.eq_ignore_ascii_case("linestyle") {
                let asked = border_line_style(&value)?;
                self.set_range_style(range, |address, style| {
                    set_selected_borders(style, address, range, selection, &|held| {
                        border_after_line(asked, border_kind(held).1)
                    });
                })?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("weight") {
                let asked = border_weight(&value)?;
                self.set_range_style(range, |address, style| {
                    set_selected_borders(style, address, range, selection, &|held| {
                        let line = match border_kind(held).0 {
                            LINE_NONE => LINE_CONTINUOUS,
                            line => line,
                        };
                        border_after_weight(line, asked)
                    });
                })?;
                return Ok(true);
            }
            // A colour given to an edge with no line draws a thin one in that
            // colour: measured, `Borders(xlEdgeBottom).Color = 255` on a bare
            // cell reads back LineStyle 1, Weight 2, Color 255. A colour
            // outside the range -- -1, 16777216 -- reads back 0.
            if name.eq_ignore_ascii_case("themecolor") {
                let theme = theme_colour(&value)?;
                self.paint_from_theme(range, Paint::Edge(selection), Some(theme), None)?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("tintandshade") {
                let tint = tint_asked(&value)?;
                self.paint_from_theme(range, Paint::Edge(selection), None, Some(tint))?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("color") || name.eq_ignore_ascii_case("colorindex") {
                self.forget_theme_paint(range, Paint::Edge(selection));
                let colour = if name.eq_ignore_ascii_case("color") {
                    let Some(asked) = any_number(&value) else {
                        return Err("Borders.Color must be an RGB color number".to_string());
                    };
                    if asked.is_finite() && (0.0..=16_777_215.0).contains(&asked) {
                        Some(colour_from_packed(asked as i64))
                    } else {
                        None
                    }
                } else {
                    palette_choice(&value, COLOUR_AUTOMATIC, "Borders.ColorIndex")?
                };
                self.set_range_style(range, |address, style| {
                    recolour_selected_borders(style, address, range, selection, colour.as_deref());
                })?;
                return Ok(true);
            }
            return Ok(false);
        }
        if let Some(range) = self.range_font(receiver) {
            if name.eq_ignore_ascii_case("themecolor") {
                let theme = theme_colour(&value)?;
                self.paint_from_theme(range, Paint::Font, Some(theme), None)?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("tintandshade") {
                let tint = tint_asked(&value)?;
                self.paint_from_theme(range, Paint::Font, None, Some(tint))?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("colorindex") {
                let colour = palette_choice(&value, COLOUR_AUTOMATIC, "Font.ColorIndex")?;
                self.forget_theme_paint(range, Paint::Font);
                self.set_range_style(range, |_, style| style.font_color = colour.clone())?;
                self.redress_runs(range, |dress| dress.color = colour.clone());
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("strikethrough") {
                let Some(struck) = style_face_boolean(&value, "Font.Strikethrough")? else {
                    return Ok(true);
                };
                self.set_range_style(range, |_, style| style.strikethrough = struck)?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("underline") {
                let asked = match &value {
                    Value::Boolean(true) => UNDERLINE_SINGLE,
                    Value::Boolean(false) => UNDERLINE_NONE,
                    value if any_whole_number(value).is_some() => any_whole_number(value).unwrap_or_default(),
                    _ => {
                        return Err(
                            "Font.Underline takes True, False, or an underline style".to_string()
                        )
                    }
                };
                // Measured: 2 and True are the single rule, -4142, False and
                // 1 none, -4119 and 3 the double rule, 4 and 5 the two
                // accounting rules, and 0 is refused with 1004.
                let (underline, styled) = match asked {
                    UNDERLINE_SINGLE => (true, None),
                    UNDERLINE_NONE | 1 => (false, None),
                    -4119 | 3 => (true, Some(-4119)),
                    4 | 5 => (true, Some(asked)),
                    _ => return Err(host_error(1004, "that is not an underline style")),
                };
                self.set_range_style(range, |_, style| style.underline = underline)?;
                self.redress_runs(range, |dress| dress.underline = underline);
                for at in self.touched(range) {
                    match styled {
                        Some(rule) => {
                            self.underlines.insert(at, rule);
                        }
                        None => {
                            self.underlines.remove(&at);
                        }
                    }
                }
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("name") {
                // Excel keeps whatever it is given — a face this machine has
                // never heard of is stored verbatim — and a number is taken as
                // its own text. An empty name is not an empty face: it puts
                // the cell back on the workbook's default.
                let named = match &value {
                    Value::String(named) if named.is_empty() => None,
                    Value::String(named) => Some(named.clone()),
                    Value::Integer(number) => Some(number.to_string()),
                    value if any_number(value).is_some() => {
                        let number = any_number(value).unwrap_or_default();
                        Some(if number.fract() == 0.0 {
                            format!("{}", number as i64)
                        } else {
                            number.to_string()
                        })
                    }
                    Value::Empty | Value::Missing => None,
                    _ => return Err("Font.Name must be a name".to_string()),
                };
                self.set_range_style(range, |_, style| style.font_name = named.clone())?;
                self.redress_runs(range, |dress| dress.font = named.clone());
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("bold") {
                let Some(value) = style_face_boolean(&value, "Font.Bold")? else {
                    return Ok(true);
                };
                self.set_range_style(range, |_, style| style.bold = value)?;
                self.redress_runs(range, |dress| dress.bold = value);
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("italic") {
                let Some(value) = style_face_boolean(&value, "Font.Italic")? else {
                    return Ok(true);
                };
                self.set_range_style(range, |_, style| style.italic = value)?;
                self.redress_runs(range, |dress| dress.italic = value);
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("size") {
                let value = font_size(&value)?;
                self.set_range_style(range, |_, style| style.font_size = value)?;
                self.redress_runs(range, |dress| dress.size = value);
                self.refit_rows(range)?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("color") {
                let value = style_color(&value, "Font.Color")?;
                self.forget_theme_paint(range, Paint::Font);
                self.set_range_style(range, |_, style| style.font_color = value.clone())?;
                self.redress_runs(range, |dress| dress.color = value.clone());
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("themecolor") {
                let theme = theme_colour(&value)?;
                self.paint_from_theme(range, Paint::Font, Some(theme), None)?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("tintandshade") {
                let tint = tint_asked(&value)?;
                self.paint_from_theme(range, Paint::Font, None, Some(tint))?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("superscript") || name.eq_ignore_ascii_case("subscript") {
                let held = style_face_boolean(&value, "Font.Superscript")?.unwrap_or(false);
                let which = if name.eq_ignore_ascii_case("superscript") { "superscript" } else { "subscript" };
                self.redress_runs(range, |dress| {
                    dress.vert_align = held.then(|| which.to_string());
                });
                return Ok(true);
            }
            // A recorder writes the whole of a cell's font: these are the
            // members this build does not keep, taken without a word so the
            // block goes through.
            if matches!(
                name.to_ascii_lowercase().as_str(),
                "outlinefont" | "shadow" | "themefont" | "fontstyle"
            ) {
                return Ok(true);
            }
            return Ok(false);
        }
        if let Some(range) = self.range_interior(receiver) {
            if name.eq_ignore_ascii_case("themecolor") {
                let theme = theme_colour(&value)?;
                self.paint_from_theme(range, Paint::Interior, Some(theme), None)?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("tintandshade") {
                let tint = tint_asked(&value)?;
                self.paint_from_theme(range, Paint::Interior, None, Some(tint))?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("color") {
                let value = style_color(&value, "Interior.Color")?;
                self.forget_theme_paint(range, Paint::Interior);
                self.set_range_style(range, |_, style| style.bg_color = value.clone())?;
                self.fill_coloured(range, value.is_some());
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("colorindex") {
                let colour = palette_choice(&value, COLOUR_NONE, "Interior.ColorIndex")?;
                self.forget_theme_paint(range, Paint::Interior);
                self.set_range_style(range, |_, style| style.bg_color = colour.clone())?;
                self.fill_coloured(range, colour.is_some());
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("pattern") {
                let asked = match &value {
                    value if any_whole_number(value).is_some() => any_whole_number(value).unwrap_or_default(),
                    _ => return Err("Interior.Pattern takes a pattern by number".to_string()),
                };
                let kind = pattern_kind(asked)?;
                Self::sized(range)?;
                match kind {
                    // xlNone takes the fill away with the pattern: measured,
                    // the cell's Color is white and its ColorIndex xlNone after.
                    0 => {
                        self.set_range_style(range, |_, style| style.bg_color = None)?;
                        for at in self.touched(range) {
                            self.hatchings.remove(&at);
                        }
                    }
                    // xlSolid over a fill is what the fill already is; over a
                    // bare cell it is a solid of automatic colour -- Color
                    // white, ColorIndex xlAutomatic -- which cannot be told
                    // from the paper.
                    1 => {
                        for at in self.touched(range) {
                            let filled = self
                                .cell_here(at.sheet, at.row, at.column)
                                .is_some_and(|cell| cell.style.bg_color.is_some());
                            if filled {
                                self.hatchings.remove(&at);
                            } else {
                                let colour = self.hatchings.get(&at).and_then(|held| held.colour);
                                self.hatchings.insert(at, Hatching { kind: 1, colour });
                            }
                        }
                    }
                    // A hatching keeps whatever fill and pattern colour the
                    // cell had: measured, red then gray50 reads Color 255.
                    kind => {
                        for at in self.touched(range) {
                            let colour = self.hatchings.get(&at).and_then(|held| held.colour);
                            self.hatchings.insert(at, Hatching { kind, colour });
                        }
                    }
                }
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("patterncolor") {
                let Some(colour) = color_number(&value, "Interior.PatternColor")? else {
                    return Ok(true);
                };
                self.paint_pattern(range, Some(colour as i64))?;
                return Ok(true);
            }
            if name.eq_ignore_ascii_case("patterncolorindex") {
                let colour = palette_choice(&value, COLOUR_AUTOMATIC, "Interior.PatternColorIndex")?;
                self.paint_pattern(range, colour_to_packed(colour.as_deref()))?;
                return Ok(true);
            }
            // The shade on the fill and on its pattern are kept nowhere here,
            // but a recorder always writes them; taken without a word.
            if matches!(name.to_ascii_lowercase().as_str(), "patterntintandshade" | "gradient") {
                return Ok(true);
            }
            return Ok(false);
        }
        let Some(range) = self.range(receiver) else {
            return Ok(false);
        };
        if name.eq_ignore_ascii_case("value") || name.eq_ignore_ascii_case("value2") {
            self.set_range_input(range, value, "range assignment", FormulaStyle::A1)?;
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("name") {
            let Value::String(called) = &value else {
                return Err("a range is given a name as a String".to_string());
            };
            check_name(called)?;
            let stands_for = self.address_of(range);
            match self.name_at(called) {
                Some(at) => self.workbook.defined_names[at] = (called.clone(), stands_for),
                None => self
                    .workbook
                    .defined_names
                    .push((called.clone(), stands_for)),
            }
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("formula")
            || name.eq_ignore_ascii_case("formula2")
            || name.eq_ignore_ascii_case("formulalocal")
        {
            self.set_range_input(range, value, "range formula assignment", FormulaStyle::A1)?;
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("formulaarray") {
            self.set_formula_array(range, value)?;
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("formular1c1")
            || name.eq_ignore_ascii_case("formula2r1c1")
            || name.eq_ignore_ascii_case("formular1c1local")
        {
            self.set_range_input(
                range,
                value,
                "range formula assignment",
                FormulaStyle::R1C1,
            )?;
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("verticalalignment") {
            // The five Excel accepts. Asked with xlLeft, and with a bare 7, it
            // refuses outright rather than passing them through.
            let asked = match &value {
                value if any_number(value).is_some() => any_number(value).unwrap_or_default().trunc() as i64,
                _ => return Err("Range.VerticalAlignment must be a number".to_string()),
            };
            let named = match asked {
                -4160 => "top",
                -4108 => "center",
                -4107 => "bottom",
                -4130 => "justify",
                -4117 => "distributed",
                _ => {
                    return Err(format!("Range.VerticalAlignment cannot be set to {asked}"))
                }
            };
            self.set_range_style(range, |_, style| {
                style.vertical_align = Some(named.to_string());
            })?;
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("style") {
            let index = match &value {
                Value::String(named) => built_in_style(named)
                    .ok_or_else(|| host_error(450, format!("there is no style {named:?}")))?,
                Value::Object(object) => self
                    .style_index(object)
                    .ok_or_else(|| "Range.Style is given a style or its name".to_string())?,
                _ => return Err(host_error(450, "Range.Style is given a style or its name")),
            };
            self.apply_style(range, index)?;
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("locked") {
            let Some(locked) = style_face_boolean(&value, "Range.Locked")? else {
                return Ok(true);
            };
            self.guard_formats(range.sheet, "changing Locked")?;
            for address in self.touched(range) {
                if locked {
                    self.unlocked.remove(&address);
                } else {
                    self.unlocked.insert(address);
                }
            }
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("wraptext") {
            let Some(wraps) = style_face_boolean(&value, "Range.WrapText")? else {
                return Ok(true);
            };
            self.set_range_style(range, |_, style| style.wrap_text = wraps)?;
            self.refit_rows(range)?;
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("shrinktofit") {
            let Some(shrinks) = style_face_boolean(&value, "Range.ShrinkToFit")? else {
                return Ok(true);
            };
            self.set_range_style(range, |_, style| style.shrink_to_fit = shrinks)?;
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("orientation") {
            // A number, or text holding one -- measured, `"30"` is taken --
            // and a fraction is cut short: 45.6 reads back as 45.
            let Some(asked) = numeric_text(&value).map(f64::trunc) else {
                return Err("Range.Orientation takes a direction by number".to_string());
            };
            let asked = asked as i64;
            // 255 is how the FILE spells stacked, and Excel takes it as well
            // as its own name for it: setting 255 and reading the property
            // back answers -4166. A turn is -90 to 90; 91, 180 and -91 are
            // refused with 1004.
            let turn: Option<i32> = match asked {
                255 | -4166 => None,
                -4128 => Some(0),
                -4171 => Some(90),
                -4170 => Some(-90),
                degrees if (-90..=90).contains(&degrees) => Some(degrees as i32),
                _ => return Err(host_error(1004, "Range.Orientation takes -90 to 90")),
            };
            self.set_range_style(range, |_, style| style.stacked_text = turn.is_none())?;
            for at in self.touched(range) {
                match turn {
                    Some(0) | None => {
                        self.rotations.remove(&at);
                    }
                    Some(degrees) => {
                        self.rotations.insert(at, degrees);
                    }
                }
            }
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("readingorder") {
            // Left-to-right, right-to-left or by context: none kept here.
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("addindent") {
            let Some(indented) = style_face_boolean(&value, "Range.AddIndent")? else {
                return Ok(true);
            };
            Self::sized(range)?;
            for at in self.touched(range) {
                if indented {
                    self.indented.insert(at);
                } else {
                    self.indented.remove(&at);
                }
            }
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("outlinelevel") {
            let Some((axis, first, last)) = Self::outline_band(range) else {
                return Err(host_error(1004, "OutlineLevel is a property of whole rows or columns"));
            };
            // Measured: 3 is taken, and 0 and 9 are refused with 1004.
            let level = match any_whole_number(&value) {
                Some(level) if (1..=8).contains(&level) => level as u8,
                _ => return Err(host_error(1004, "OutlineLevel takes 1 to 8")),
            };
            for index in first..=last {
                self.set_outline_level(range.sheet, axis, index, level);
            }
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("indentlevel") {
            // Excel takes anything up to 250 and refuses 251; a negative
            // number is not refused but quietly becomes nought. Measured with
            // -1, 15, 250 and 251.
            let asked = match &value {
                value if any_number(value).is_some() => any_number(value).unwrap_or_default().trunc() as i64,
                _ => return Err("Range.IndentLevel must be a number".to_string()),
            };
            if asked > 250 {
                return Err("Range.IndentLevel cannot be set past 250".to_string());
            }
            let indent = asked.max(0) as u32;
            self.set_range_style(range, |_, style| {
                style.indent = indent;
                // Indenting a cell that was left to its own devices makes it
                // left-aligned: asked of Excel, a General cell given an indent
                // reads back xlLeft.
                if indent > 0 && style.horizontal_align.is_none() {
                    style.horizontal_align = Some("left".to_string());
                }
            })?;
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("numberformat") || name.eq_ignore_ascii_case("numberformatlocal")
        {
            let value = match value {
                Value::Empty => None,
                Value::String(value) if value.eq_ignore_ascii_case("general") => None,
                Value::String(value) => Some(value),
                _ => return Err("Range.NumberFormat must be a string".to_string()),
            };
            self.set_range_style(range, |_, style| style.number_format = value.clone())?;
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("horizontalalignment") {
            let value = horizontal_alignment(&value)?;
            self.set_range_style(range, |_, style| style.horizontal_align = value.clone())?;
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("columnwidth") {
            self.set_range_column_width(range, value)?;
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("rowheight") {
            self.set_range_row_height(range, value)?;
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("hidden") {
            // The odd one out: a hidden row given `Null` comes back, so
            // nothing-back means False here rather than "leave it".
            let hidden = style_face_boolean(&value, "Range.Hidden")?.unwrap_or(false);
            self.set_range_hidden(range, hidden)?;
            return Ok(true);
        }
        if name.eq_ignore_ascii_case("mergecells") {
            let Some(merges) = style_face_boolean(&value, "Range.MergeCells")? else {
                return Ok(true);
            };
            if merges {
                self.merge_range(range)?;
            } else {
                self.unmerge_range(range)?;
            }
            return Ok(true);
        }
        Ok(false)
    }

    fn set_from_object(
        &mut self,
        receiver: &ObjectRef,
        name: &str,
        object: &ObjectRef,
    ) -> Result<Option<bool>, String> {
        if self.gone(receiver) {
            return Err(host_error(424, "the object's worksheet has been deleted"));
        }
        let Some(part) = self.drawing_part(receiver) else {
            return Ok(None);
        };
        let Some(range) = self.range(object) else {
            return Ok(None);
        };
        self.drawing_set_range(part, name, range)
    }

    fn enumerate(&mut self, receiver: &ObjectRef) -> Result<Option<Vec<Value>>, String> {
        if self.gone(receiver) {
            return Err(host_error(424, "the object's worksheet has been deleted"));
        }
        if self.is_worksheets(receiver) {
            let mut worksheets = Vec::with_capacity(self.workbook.sheets.len());
            for sheet in 0..self.workbook.sheets.len() {
                worksheets.push(self.object(HostObject::Worksheet(sheet)));
            }
            return Ok(Some(worksheets));
        }
        // A range of several blocks is walked block by block in the order they
        // were written, and each block's cells row by row. Excel repeats a
        // cell that two blocks both name: `For Each` over `A1:A2,A2:A3` gives
        // A1 A2 A2 A3. `Areas` hands over the blocks themselves instead, in
        // the same order.
        if let Some(areas) = self.blocks(receiver).map(<[CellRange]>::to_vec) {
            let holding_areas =
                matches!(self.objects.get(receiver.handle as usize), Some(HostObject::Areas(_)));
            if holding_areas {
                let mut items = Vec::with_capacity(areas.len());
                for block in areas {
                    items.push(self.object(HostObject::Range(block)));
                }
                return Ok(Some(items));
            }
            let mut total = 0u64;
            for block in &areas {
                total += Self::range_cell_count_large(*block)?;
            }
            if total > 1_000_000 {
                return Err("cell range exceeds the 1,000,000-cell execution limit".to_string());
            }
            let mut cells = Vec::with_capacity(total as usize);
            for block in areas {
                for address in block.addresses() {
                    cells.push(self.object(HostObject::Range(CellRange::single(address))));
                }
            }
            return Ok(Some(cells));
        }
        if self.is_styles(receiver) {
            let mut items = Vec::with_capacity(BUILT_IN_STYLES.len());
            for index in self.listed_styles() {
                items.push(self.object(HostObject::Style(index)));
            }
            return Ok(Some(items));
        }
        if let Some(scope) = self.hyperlink_scope(receiver) {
            let mut items = Vec::new();
            for id in self.links_in(scope) {
                items.push(self.object(HostObject::Hyperlink(id)));
            }
            return Ok(Some(items));
        }
        if let Some(range) = self.conditions_range(receiver) {
            let mut items = Vec::new();
            for id in self.conditions_reaching(range) {
                items.push(self.object(HostObject::FormatCondition(id)));
            }
            return Ok(Some(items));
        }
        if let Some(sheet) = self.list_objects_sheet(receiver) {
            let names: Vec<String> = self.workbook.sheets[sheet]
                .tables
                .iter()
                .map(|table| table.name.clone())
                .collect();
            let mut items = Vec::new();
            for name in names {
                let id = self.table_handle(sheet, &name);
                items.push(self.object(HostObject::ListObject(id)));
            }
            return Ok(Some(items));
        }
        if let Some((id, TablePart::Rows)) = self.table_part(receiver) {
            let (sheet, index) = self.table_at(id)?;
            let (first, last) = self.table_data_rows(id, sheet, index);
            let mut items = Vec::new();
            for row_index in 1..=last.saturating_sub(first) + u32::from(first <= last) {
                items.push(self.object(HostObject::ListRow(id, row_index)));
            }
            return Ok(Some(items));
        }
        if let Some((id, TablePart::Columns)) = self.table_part(receiver) {
            let (sheet, index) = self.table_at(id)?;
            let count = self.workbook.sheets[sheet].tables[index].columns.len() as u32;
            let mut items = Vec::new();
            for column_index in 1..=count {
                items.push(self.object(HostObject::ListColumn(id, column_index)));
            }
            return Ok(Some(items));
        }
        if let Some(sheet) = self.comments_sheet(receiver) {
            let mut items = Vec::new();
            for index in self.notes_on(sheet) {
                let at = self.notes[index].at;
                items.push(self.object(HostObject::Comment(at)));
            }
            return Ok(Some(items));
        }
        // The names come out in the order `Names.Item(1)` counts them, which
        // Excel sorts by the name itself rather than by when it was given:
        // adding zebra, alpha, middle and Beta walks alpha Beta middle zebra.
        if self.is_names(receiver) {
            let mut held = self
                .workbook
                .defined_names
                .iter()
                .map(|(name, _)| name.clone())
                .collect::<Vec<_>>();
            held.sort_by(|one, other| compare_text_by_case(one, other));
            let mut items = Vec::with_capacity(held.len());
            for name in held {
                items.push(self.name_object(&name));
            }
            return Ok(Some(items));
        }
        if let Some((range, axis)) = self.range_collection(receiver) {
            Self::range_cell_count(range)?;
            let count = match axis {
                RangeAxis::Rows => range.end_row - range.start_row + 1,
                RangeAxis::Columns => range.end_column - range.start_column + 1,
            };
            let mut items = Vec::with_capacity(count as usize);
            for index in 1..=count {
                items.push(self.range_collection_item(
                    range,
                    axis,
                    &Value::Integer(i64::from(index)),
                )?);
            }
            return Ok(Some(items));
        }
        let Some(range) = self.range(receiver) else {
            return Ok(None);
        };
        Self::range_cell_count(range)?;
        let mut cells = Vec::new();
        for address in range.addresses() {
            cells.push(self.object(HostObject::Range(CellRange::single(address))));
        }
        Ok(Some(cells))
    }
}

fn format_debug_value(value: &Value) -> String {
    match value {
        Value::Empty => String::new(),
        Value::Missing => "Missing".to_string(),
        Value::Nothing => "Nothing".to_string(),
        Value::Null => "Null".to_string(),
        Value::Boolean(value) => if *value { "True" } else { "False" }.to_string(),
        Value::Int16(value) => value.to_string(),
        Value::Byte(value) => value.to_string(),
        Value::Integer(value) => value.to_string(),
        Value::LongLong(value) => value.to_string(),
        Value::Single(value) => vba_number_text(*value as f64),
        Value::Currency(value) => vba_number_text(*value as f64 / 10_000.0),
        Value::Date(value) => vba_date_text(*value),
        // The same digits `CStr` and `&` give, and the same the `Print`
        // statement writes -- measured at all three. What is NOT copied is
        // Print's spacing, which puts a space in front of every positive
        // number and one after every number: that is the Immediate window's
        // layout, and this log has its own.
        Value::Double(value) => vba_number_text(*value),
        Value::Error(value) => format!("Error {value}"),
        Value::String(value) => value.clone(),
        Value::Array(_) => "<Array>".to_string(),
        Value::Record(record) => format!("<{}>", record.type_name),
        Value::Object(value) => format!("<{}>", value.kind),
    }
}

/// The one-argument form of `Cells` counts from one but is not held there:
/// Excel answers `Cells(0)` with the cell before the first.
/// The one index of `Cells(n)`, made whole VBA's way — half to the even side.
///
/// Measured at both entrances, which is why one function may carry it: over a
/// range, `Range("B2:D4").Cells(1.5)` is C2 and `Cells(2.5)` is C2 as well
/// (2 and 2), and `Cells(3.5)` is B3 (4); over the sheet, `Cells(1.5)` is B1
/// and `Cells(2.5)` is B1. A number written as text is read as a number here —
/// `Cells("3")` is C1 — though the two-index form refuses one.
fn cells_index(value: &Value) -> Result<i64, String> {
    match value {
        value if any_number(value).is_some() => Ok(any_number(value).unwrap_or_default().round_ties_even() as i64),
        Value::String(text) => text
            .trim()
            .parse::<f64>()
            .map(|number| number.round_ties_even() as i64)
            .map_err(|_| "Range.Cells index must be a number".to_string()),
        _ => Err("Range.Cells index must be a number".to_string()),
    }
}

/// What one of the faces a cell wears — `Font.Bold`, `Font.Italic`,
/// `Font.Strikethrough`, `WrapText`, `ShrinkToFit`, `MergeCells` — makes of
/// `value`. Nothing back means LEAVE IT AS IT IS.
///
/// Measured by assigning to each of those six from VBA, which all answered
/// alike: a number is False only at zero, `Empty` is False, and a string has
/// to be the word True or False in any case with nothing around it — `"TRUE"`
/// is True, `" true "` is refused, and so are `"0"` and `"1"`, which the
/// application's switches DO take. `#FALSE#` is refused here and taken there.
///
/// ★ `Null` leaves the face alone rather than changing it: a bold cell given
/// `Null` stays bold, and a range where the cells disagree — the one place
/// `.Bold` answers `Null` when READ — keeps its disagreement. That is why this
/// hands back an Option rather than a bool.
///
/// `Range.Hidden` is NOT one of these, though it looks like one: asked the
/// same way, a hidden row given `Null` comes BACK. It is the one entrance of
/// the seven where `Null` does something, so it reads the Option itself.
/// Cut a line into fields at its delimiters.
///
/// A field fenced by the qualifier keeps the delimiters inside it, and the
/// fence itself goes. With `ConsecutiveDelimiter` a run of delimiters is one;
/// without it each one ends a field, except that a run of spaces is one
/// either way -- measured, `"  s  t "` split on Space gives four fields, an
/// empty one, `s`, `t` and an empty one, whichever way the flag is set. A
/// delimiter at the very end adds no field.
fn split_delimited(text: &str, split: &SplitSettings) -> Vec<String> {
    let is_delimiter = |one: char| {
        (split.tab && one == '\t')
            || (split.semicolon && one == ';')
            || (split.comma && one == ',')
            || (split.space && one == ' ')
            || split.other == Some(one)
    };
    let mut fields = Vec::new();
    let mut field = String::new();
    let mut fenced = false;
    let mut last: Option<char> = None;
    for one in text.chars() {
        if Some(one) == split.qualifier && !fenced && field.is_empty() {
            fenced = true;
            last = None;
            continue;
        }
        if Some(one) == split.qualifier && fenced {
            fenced = false;
            last = None;
            continue;
        }
        if !fenced && is_delimiter(one) {
            let collapses = split.consecutive || one == ' ';
            if collapses && last.is_some_and(is_delimiter) {
                last = Some(one);
                continue;
            }
            fields.push(std::mem::take(&mut field));
            last = Some(one);
            continue;
        }
        field.push(one);
        last = Some(one);
    }
    if !field.is_empty() || !last.is_some_and(is_delimiter) {
        fields.push(field);
    }
    fields
}

/// Cut a line at the character positions `FieldInfo` names, counted from 0.
fn split_fixed(text: &str, rules: &[FieldRule]) -> Vec<String> {
    let chars: Vec<char> = text.chars().collect();
    let mut starts: Vec<usize> = rules.iter().map(|rule| rule.at).collect();
    starts.sort_unstable();
    starts.dedup();
    starts
        .iter()
        .enumerate()
        .map(|(index, &start)| {
            let end = starts.get(index + 1).copied().unwrap_or(chars.len());
            chars
                .get(start.min(chars.len())..end.min(chars.len()))
                .unwrap_or(&[])
                .iter()
                .collect()
        })
        .collect()
}

/// `FieldInfo:=Array(Array(1, 1), Array(2, 9))`: one pair per field.
fn field_rules(value: &Value) -> Result<Vec<FieldRule>, String> {
    let Value::Array(outer) = value else {
        return Err("Range.TextToColumns FieldInfo must be an array of pairs".to_string());
    };
    let pair = |value: &Value| -> Result<FieldRule, String> {
        let Value::Array(inner) = value else {
            return Err("Range.TextToColumns FieldInfo must be an array of pairs".to_string());
        };
        let [at, kind] = inner.values.as_slice() else {
            return Err("Range.TextToColumns FieldInfo pairs need two numbers".to_string());
        };
        let at = sort_number(at, "FieldInfo")?;
        if at < 0 {
            return Err("Range.TextToColumns FieldInfo cannot start before 0".to_string());
        }
        Ok(FieldRule {
            at: at as usize,
            kind: sort_number(kind, "FieldInfo")?,
        })
    };
    // One bare pair is allowed for a single field.
    if outer.values.iter().all(|value| !matches!(value, Value::Array(_))) {
        return Ok(vec![pair(value)?]);
    }
    outer.values.iter().map(pair).collect()
}

/// Whether a formula's text is broken in a way no reading could mend: a string
/// or a quoted sheet name left open, brackets that do not pair, nothing at all,
/// or an operator with nothing after it. Anything else is left to the engine,
/// which is the one that knows the functions.
fn formula_is_malformed(body: &str) -> bool {
    let mut depth: i32 = 0;
    let mut in_string = false;
    let mut in_name = false;
    let mut last = ' ';
    for one in body.chars() {
        if in_string {
            if one == '"' {
                in_string = false;
            }
            continue;
        }
        if in_name {
            if one == '\'' {
                in_name = false;
            }
            continue;
        }
        match one {
            '"' => in_string = true,
            '\'' => in_name = true,
            '(' | '{' => depth += 1,
            ')' | '}' => {
                depth -= 1;
                if depth < 0 {
                    return true;
                }
            }
            _ => {}
        }
        if !one.is_whitespace() {
            last = one;
        }
    }
    in_string
        || in_name
        || depth != 0
        || body.trim().is_empty()
        || matches!(last, '+' | '-' | '*' | '/' | '^' | '&' | '=' | '<' | '>' | ',' | '(' | ':')
}

/// A value with its Date or Currency dress taken off, as `Value2` answers.
fn undressed(value: Value) -> Value {
    match value {
        Value::Date(serial) => Value::Double(serial),
        Value::Currency(held) => Value::Double(held as f64 / 10_000.0),
        Value::Array(mut array) => {
            array.values = array.values.into_iter().map(undressed).collect();
            Value::Array(array)
        }
        other => other,
    }
}

/// The notes the file keeps pinned open, which are the only ones the IR
/// reads: a macro asking `Range("A1").Comment` on a workbook that has one there
/// should find it.
fn notes_pinned_open(workbook: &Workbook) -> Vec<Note> {
    let mut notes = Vec::new();
    for (sheet, held) in workbook.sheets.iter().enumerate() {
        for comment in &held.comments {
            let text = comment
                .text
                .paragraphs
                .iter()
                .map(|paragraph| paragraph.text.as_str())
                .collect::<Vec<_>>()
                .join("\n");
            notes.push(Note {
                at: CellAddress {
                    sheet,
                    row: comment.cell.0 + 1,
                    column: comment.cell.1,
                },
                text,
                visible: true,
            });
        }
    }
    notes
}

fn style_face_boolean(value: &Value, property: &str) -> Result<Option<bool>, String> {
    match value {
        Value::Boolean(asked) => Ok(Some(*asked)),
        value if any_number(value).is_some() => Ok(Some(any_number(value).unwrap_or_default() != 0.0)),
        Value::Double(asked) if asked.is_finite() => Ok(Some(*asked != 0.0)),
        Value::Empty | Value::Missing => Ok(Some(false)),
        Value::Null => Ok(None),
        Value::String(written) => match written.to_ascii_lowercase().as_str() {
            "true" => Ok(Some(true)),
            "false" => Ok(Some(false)),
            _ => Err(format!("{property} cannot be given {written:?}")),
        },
        _ => Err(format!("{property} must be True or False")),
    }
}

/// What one of the switches a macro flips around its work — `ScreenUpdating`,
/// `EnableEvents`, `DisplayAlerts`, `Interactive` — makes of `value`, and also
/// what `Range.Merge`'s `Across` and `Range.Find`'s flags make of one.
///
/// Those last two were measured on their own rather than assumed into this,
/// and they agree on every case that tells the two rules apart: `Across:="0"`
/// merges the whole block (so a numeric string IS read, where a cell's own
/// faces refuse one), `Across:=Empty` does too, `Across:=5` and `:=0.4` merge
/// across, and `Across:=Null` and `:="no"` are both refused. `Find`'s
/// `MatchCase` answers the same way. The `#TRUE#` spelling was only ever
/// measured at the switches; nothing else here rests on it.
///
/// This is NOT the rule a cell's own Boolean properties follow, and the two
/// must not share a helper. Asked of Excel at both entrances: assigning `"0"`
/// to `Application.ScreenUpdating` gives False, and assigning it to
/// `Font.Bold` is refused; assigning `Null` to `Font.Bold` is taken, and to
/// `ScreenUpdating` it raises. So each entrance keeps its own answer.
///
/// Measured by assignment from VBA, which is also not what `CallByName`
/// reports — that one refuses the numeric strings this takes, and takes the
/// `Null` this refuses. What the switches do:
///
/// - a number is False only when it is zero, so `0.4` and `-0.4` are both True
/// - `Empty` is False
/// - a string that looks like a number is read as one, spaces around it and
///   all: `"0"` is False, `"2.5"` and `" -1 "` are True
/// - otherwise a string has to be the word True or False, in any case and in
///   either the plain or the `#...#` form, with nothing around it: `"false"`
///   and `"#FALSE#"` are False, and `" False "` is a type mismatch
/// - `Null` and an `Error` are refused
fn application_switch(value: &Value, property: &str) -> Result<bool, String> {
    match value {
        Value::Boolean(asked) => Ok(*asked),
        value if any_number(value).is_some() => Ok(any_number(value).unwrap_or_default() != 0.0),
        Value::Double(asked) if asked.is_finite() => Ok(*asked != 0.0),
        Value::Empty | Value::Missing => Ok(false),
        Value::Null => Err(format!("{property} cannot be given Null")),
        Value::String(written) => {
            if let Ok(number) = written.trim().parse::<f64>() {
                if number.is_finite() {
                    return Ok(number != 0.0);
                }
            }
            match written.to_ascii_lowercase().as_str() {
                "true" | "#true#" => Ok(true),
                "false" | "#false#" => Ok(false),
                _ => Err(format!("{property} cannot be given {written:?}")),
            }
        }
        _ => Err(format!("{property} must be True or False")),
    }
}

/// How many characters the status bar holds. A 256th is refused.
const STATUS_BAR_LIMIT: usize = 255;

/// Excel keeps fifteen significant digits of a number and no more.
const EXCEL_SIGNIFICANT_DIGITS: usize = 15;

/// How wide a number written as text may be before Excel gives up on the plain
/// form. Measured at two entrances, which answer the same way except here:
/// `Range.Formula` allows 21 characters and the status bar allows 20, so
/// `1E+20` is `100000000000000000000` through the first and `1E+20` through
/// the second. The sign is not counted — `-1.5E+20` still writes out plain
/// through `Formula`, at 21 digits and a minus.
const FORMULA_TEXT_WIDTH: usize = 21;
const STATUS_BAR_TEXT_WIDTH: usize = 20;

/// A number written as text the way Excel writes one.
///
/// Not the way a CELL shows one — that is a different rendering again, capped
/// at eleven characters and narrowed further by the column, and it belongs to
/// the cell renderer. This is the value-as-text form that `Range.Formula` and
/// the status bar answer with, and it goes: keep fifteen significant digits,
/// write it out plainly if that fits `width`, and otherwise write it in
/// exponent form with as many significant digits as will fit.
///
/// Asked of Excel: `1/3` is `0.333333333333333`, `0.1 + 0.2` is `0.3`,
/// `1234567890123456` is `1234567890123460`, `1E+19` is
/// `10000000000000000000`, `1E+21` is `1E+21`, `1E-18` writes out in full and
/// `1E-20` does not, and the largest Double there is comes back as
/// `1.79769313486232E+308` through `Formula` and `1.7976931348623E+308`
/// through the bar — the exponent form giving up a digit to fit the narrower
/// budget.
fn excel_number_text(value: f64, width: usize) -> String {
    if value == 0.0 {
        return "0".to_string();
    }
    if !value.is_finite() {
        // Excel holds neither, and a cell cannot be given one, so nothing was
        // measured here. Rust's own spelling keeps it readable.
        return value.to_string();
    }
    let sign = if value < 0.0 { "-" } else { "" };
    let magnitude = value.abs();

    // Fifteen significant digits, and the exponent they sit at.
    let (digits, exponent) = significant_digits(magnitude, EXCEL_SIGNIFICANT_DIGITS);
    let plain = plain_decimal(&digits, exponent);
    if plain.len() <= width {
        return format!("{sign}{plain}");
    }

    // The exponent form, giving up significant digits until it fits.
    let mut kept = EXCEL_SIGNIFICANT_DIGITS;
    loop {
        let (digits, exponent) = significant_digits(magnitude, kept);
        let mantissa = match digits.len() {
            1 => digits.clone(),
            _ => format!("{}.{}", &digits[..1], &digits[1..]),
        };
        let written = format!("{mantissa}E{}{}", if exponent < 0 { "-" } else { "+" }, {
            exponent.abs()
        });
        if written.len() <= width || kept == 1 {
            return format!("{sign}{written}");
        }
        kept -= 1;
    }
}

/// The significant digits of a positive number, rounded to `count` of them and
/// with trailing zeros dropped, together with the power of ten the first digit
/// sits at.
fn significant_digits(magnitude: f64, count: usize) -> (String, i32) {
    let written = format!("{:.*e}", count.saturating_sub(1), magnitude);
    let (mantissa, exponent) = written.split_once('e').expect("Rust writes an exponent");
    let exponent: i32 = exponent.parse().expect("Rust writes a whole exponent");
    let digits: String = mantissa.chars().filter(char::is_ascii_digit).collect();
    let trimmed = digits.trim_end_matches('0');
    if trimmed.is_empty() {
        return ("0".to_string(), exponent);
    }
    (trimmed.to_string(), exponent)
}

/// Those digits written out without an exponent.
fn plain_decimal(digits: &str, exponent: i32) -> String {
    if exponent < 0 {
        let zeros = (-exponent - 1) as usize;
        return format!("0.{}{}", "0".repeat(zeros), digits);
    }
    let whole = exponent as usize + 1;
    if digits.len() <= whole {
        return format!("{}{}", digits, "0".repeat(whole - digits.len()));
    }
    format!("{}.{}", &digits[..whole], &digits[whole..])
}

/// The pointer Excel puts up when nobody has asked for another one.
const CURSOR_DEFAULT: i64 = -4143;

/// Which pointer `Application.Cursor` is left showing after a macro asks for
/// `value`.
///
/// Excel takes four of them — `xlDefault` (-4143), `xlNorthwestArrow` (1),
/// `xlWait` (2) and `xlIBeam` (3) — and one more number that is not a pointer
/// at all: 0, which it answers -4143 to. So `False` and `Empty` both put the
/// arrow back, being zero, while `True` is -1 and is refused along with 4, 7
/// and -4142.
///
/// What it is given is made a whole number first, VBA's way: half goes to the
/// even side. Asked of Excel, 1.5 gives 2 and 2.5 also gives 2, 2.7 gives 3,
/// and 3.5 is refused — because it rounds to 4, which is not a pointer. A
/// string is read as a number if it looks like one, spaces and a leading plus
/// and all: `" 3 "`, `"+3"` and `"0003"` all give 3, while `"3.7"` rounds to 4
/// and is refused, and `"xlIBeam"` is a type mismatch.
fn application_cursor(value: &Value) -> Result<i64, String> {
    let asked = match value {
        Value::Boolean(true) => -1.0,
        Value::Boolean(false) => 0.0,
        value if any_number(value).is_some() => any_number(value).unwrap_or_default(),
        Value::Empty | Value::Missing => 0.0,
        Value::Null => return Err("Application.Cursor cannot be given Null".to_string()),
        Value::String(written) => match written.trim().parse::<f64>() {
            Ok(number) if number.is_finite() => number,
            _ => return Err(format!("Application.Cursor cannot be given {written:?}")),
        },
        _ => return Err("Application.Cursor must be a mouse pointer".to_string()),
    };
    match asked.round_ties_even() as i64 {
        0 | CURSOR_DEFAULT => Ok(CURSOR_DEFAULT),
        pointer @ (1 | 2 | 3) => Ok(pointer),
        other => Err(format!("Application.Cursor has no pointer {other}")),
    }
}

/// What the status bar is left holding once a macro has written `value` to it,
/// where nothing means Excel has it back.
///
/// Asked of Excel from VBA itself: the bar starts out Excel's own and answers
/// `False` while it is. A string takes it over. An empty string, `Empty` and
/// `Null` all hand it back.
///
/// Anything else is shown the way Excel writes a value as text — `42`, `3.5`,
/// `1E+20`, and for a Boolean the word `TRUE` or `FALSE`. Which makes `False`
/// the trap: every guide ends a macro with `Application.StatusBar = False` to
/// restore the default bar, and in Excel 16 that does not restore it, it
/// leaves the word FALSE sitting across the bottom of the window. The Boolean
/// is reaching Excel intact — the same assignment into a cell stores a
/// Boolean, so this is Excel's own answer and not a bridge losing the type.
/// The way to give the bar back is an empty string.
///
/// Only text can go on it: an `Error` variant is refused, and so is anything
/// past 255 characters — counted in characters, not bytes, so 255 kana fit.
/// A refusal leaves what was already there.
fn status_bar_text(value: &Value) -> Result<Option<String>, String> {
    let shown = match value {
        Value::Empty | Value::Missing | Value::Null => return Ok(None),
        Value::String(written) if written.is_empty() => return Ok(None),
        Value::String(written) => written.clone(),
        value if any_number(value).is_some() => {
            excel_number_text(any_number(value).unwrap_or_default(), STATUS_BAR_TEXT_WIDTH)
        }
        Value::Boolean(_) => shown_text(value, None),
        _ => return Err("Application.StatusBar can only be shown text".to_string()),
    };
    let width = shown.chars().count();
    if width > STATUS_BAR_LIMIT {
        return Err(format!(
            "Application.StatusBar holds {STATUS_BAR_LIMIT} characters, and was given {width}"
        ));
    }
    Ok(Some(shown))
}

fn application_calculation(value: &Value) -> Result<i64, String> {
    let value = match value {
        value if any_whole_number(value).is_some() => any_whole_number(value).unwrap_or_default(),
        _ => {
            return Err("Application.Calculation must be an Excel calculation constant".to_string())
        }
    };
    match value {
        -4105 | -4135 | 2 => Ok(value),
        _ => Err(format!(
            "unsupported Application.Calculation constant: {value}"
        )),
    }
}

fn find_integer_argument(value: Option<&Value>, default: i64, label: &str) -> Result<i64, String> {
    match value {
        None | Some(Value::Missing) => Ok(default),
        Some(value) if any_whole_number(value).is_some() => {
            Ok(any_whole_number(value).unwrap_or_default())
        }
        _ => Err(format!("Range.Find {label} must be an Excel constant")),
    }
}

fn normalize_named_arguments(
    args: &[Value],
    argument_names: &[Option<String>],
    parameters: &[&str],
    method: &str,
) -> Result<Vec<Value>, String> {
    if args.len() != argument_names.len() {
        return Err(format!("Range.{method} received invalid argument metadata"));
    }
    if argument_names.iter().all(Option::is_none) {
        return Ok(args.to_vec());
    }
    let mut normalized = vec![Value::Missing; parameters.len()];
    let mut assigned = vec![false; parameters.len()];
    let mut positional_index = 0;
    let mut highest_index = None;
    for (value, argument_name) in args.iter().zip(argument_names) {
        let index = if let Some(argument_name) = argument_name {
            parameters
                .iter()
                .position(|parameter| parameter.eq_ignore_ascii_case(argument_name))
                .ok_or_else(|| format!("Range.{method} has no argument named {argument_name}"))?
        } else {
            while positional_index < assigned.len() && assigned[positional_index] {
                positional_index += 1;
            }
            if positional_index >= parameters.len() {
                return Err(format!("Range.{method} received too many arguments"));
            }
            let index = positional_index;
            positional_index += 1;
            index
        };
        if assigned[index] {
            return Err(format!(
                "Range.{method} argument {} was supplied more than once",
                parameters[index]
            ));
        }
        normalized[index] = value.clone();
        assigned[index] = true;
        highest_index = Some(highest_index.map_or(index, |highest: usize| highest.max(index)));
    }
    normalized.truncate(highest_index.map_or(0, |index| index + 1));
    Ok(normalized)
}

fn find_boolean_argument(
    value: Option<&Value>,
    default: bool,
    label: &str,
) -> Result<bool, String> {
    match value {
        None | Some(Value::Missing) => Ok(default),
        Some(value) => application_switch(value, &format!("Range.Find {label}")),
    }
}

/// The three value classes Excel's lookups compare within. Values of different
/// classes never compare equal, so `Match` on a numeric column never matches a
/// text needle.
enum LookupKey<'a> {
    Number(f64),
    Text(&'a str),
    Boolean(bool),
}

fn lookup_key(value: &Value) -> Option<LookupKey<'_>> {
    match value {
        Value::Boolean(value) => Some(LookupKey::Boolean(*value)),
        value if any_number(value).is_some() => Some(LookupKey::Number(any_number(value).unwrap_or_default())),
        Value::String(value) => Some(LookupKey::Text(value)),
        _ => None,
    }
}

fn lookup_compare(cell: &Value, needle: &Value) -> Option<Ordering> {
    match (lookup_key(cell)?, lookup_key(needle)?) {
        (LookupKey::Number(cell), LookupKey::Number(needle)) => cell.partial_cmp(&needle),
        (LookupKey::Text(cell), LookupKey::Text(needle)) => {
            Some(cell.to_lowercase().cmp(&needle.to_lowercase()))
        }
        (LookupKey::Boolean(cell), LookupKey::Boolean(needle)) => Some(cell.cmp(&needle)),
        _ => None,
    }
}

/// Exact lookup matching. A text needle is a wildcard pattern; every other
/// comparison is a plain equality within the needle's value class.
fn lookup_exact_matches(cell: &Value, needle: &Value) -> bool {
    match (lookup_key(cell), lookup_key(needle)) {
        (Some(LookupKey::Text(cell)), Some(LookupKey::Text(needle))) => {
            wildcard_matches(cell, needle)
        }
        _ => lookup_compare(cell, needle) == Some(Ordering::Equal),
    }
}

enum WildcardToken {
    AnyRun,
    AnyCharacter,
    Literal(char),
}

/// Excel's lookup wildcards: `*` runs, `?` single characters, and `~` escaping
/// the character after it. A trailing `~` contributes nothing at all.
fn wildcard_tokens(pattern: &str) -> Vec<WildcardToken> {
    let mut tokens = Vec::new();
    let mut characters = pattern.to_lowercase().chars().collect::<Vec<_>>().into_iter();
    while let Some(character) = characters.next() {
        match character {
            '~' => {
                if let Some(escaped) = characters.next() {
                    tokens.push(WildcardToken::Literal(escaped));
                }
            }
            '*' => tokens.push(WildcardToken::AnyRun),
            '?' => tokens.push(WildcardToken::AnyCharacter),
            character => tokens.push(WildcardToken::Literal(character)),
        }
    }
    tokens
}

fn wildcard_matches(candidate: &str, pattern: &str) -> bool {
    let candidate = candidate.to_lowercase().chars().collect::<Vec<_>>();
    let tokens = wildcard_tokens(pattern);
    let mut candidate_index = 0;
    let mut token_index = 0;
    let mut resume: Option<(usize, usize)> = None;
    while candidate_index < candidate.len() {
        let matched = match tokens.get(token_index) {
            Some(WildcardToken::AnyRun) => {
                token_index += 1;
                resume = Some((token_index, candidate_index));
                continue;
            }
            Some(WildcardToken::AnyCharacter) => true,
            Some(WildcardToken::Literal(expected)) => *expected == candidate[candidate_index],
            None => false,
        };
        if matched {
            token_index += 1;
            candidate_index += 1;
        } else if let Some((resume_token, resume_candidate)) = resume {
            token_index = resume_token;
            candidate_index = resume_candidate + 1;
            resume = Some((resume_token, candidate_index));
        } else {
            return false;
        }
    }
    tokens[token_index..]
        .iter()
        .all(|token| matches!(token, WildcardToken::AnyRun))
}

/// Excel's search over a table it assumes is sorted, derived from Excel 16 COM
/// measurements. It is a plain binary search that stops on the first equal
/// probe, then walks to the far end of that run of equal values: forward for an
/// ascending table, backward for a descending one. A descending search also
/// rejects a needle above the leading value, the ordering's assumed maximum.
///
/// Measured against Excel over 5,040 differential cases: the ascending search
/// agrees on every ordering, and the descending one agrees on every sorted
/// table. Only a descending search of a shuffled table can differ, which is
/// input the sorted contract does not define an answer for.
fn sorted_lookup_position(
    count: usize,
    descending: bool,
    value_at: impl Fn(usize) -> Value,
    needle: &Value,
) -> Option<usize> {
    if count == 0 {
        return None;
    }
    if descending {
        match lookup_compare(&value_at(0), needle) {
            Some(Ordering::Less) => return None,
            Some(Ordering::Equal) => return Some(1),
            _ => {}
        }
    }
    let mut low = 1;
    let mut high = count;
    let mut found = None;
    while low <= high {
        let middle = (low + high) / 2;
        match lookup_compare(&value_at(middle - 1), needle) {
            Some(Ordering::Equal) => {
                found = Some(middle);
                break;
            }
            Some(order) if (order == Ordering::Less) != descending => {
                found = Some(middle);
                low = middle + 1;
            }
            _ => high = middle - 1,
        }
    }
    let mut position = found?;
    if descending {
        while position > 1 && lookup_compare(&value_at(position - 2), needle) == Some(Ordering::Equal)
        {
            position -= 1;
        }
    } else {
        while position < count && lookup_compare(&value_at(position), needle) == Some(Ordering::Equal)
        {
            position += 1;
        }
    }
    Some(position)
}

fn lookup_index_argument(value: &Value, name: &str) -> Result<usize, String> {
    let number = match value {
        value if any_number(value).is_some() => any_number(value).unwrap_or_default(),
        _ => return Err(format!("WorksheetFunction.{name} index must be numeric")),
    };
    let number = number.trunc();
    if !(1.0..=u32::MAX as f64).contains(&number) {
        return Err(format!(
            "WorksheetFunction.{name} index must be 1 or greater"
        ));
    }
    Ok(number as usize)
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum ConditionalKind {
    Count,
    Sum,
    Average,
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum CriteriaOperator {
    Equal,
    NotEqual,
    Less,
    LessOrEqual,
    Greater,
    GreaterOrEqual,
}

struct Criteria {
    operator: CriteriaOperator,
    /// `Value::Empty` for the bare `"="` and `"<>"` forms, which ask whether
    /// the cell is blank rather than comparing it to anything.
    operand: Value,
}

impl Criteria {
    fn matches(&self, cell: &Value) -> bool {
        let blank = matches!(cell, Value::Empty | Value::Missing);
        if matches!(self.operand, Value::Empty) {
            return match self.operator {
                CriteriaOperator::Equal => blank,
                CriteriaOperator::NotEqual => !blank,
                _ => false,
            };
        }
        match self.operator {
            CriteriaOperator::Equal => criteria_equal(cell, &self.operand, true),
            CriteriaOperator::NotEqual => !criteria_equal(cell, &self.operand, false),
            operator => match lookup_compare(cell, &self.operand) {
                Some(Ordering::Less) => matches!(
                    operator,
                    CriteriaOperator::Less | CriteriaOperator::LessOrEqual
                ),
                Some(Ordering::Equal) => matches!(
                    operator,
                    CriteriaOperator::LessOrEqual | CriteriaOperator::GreaterOrEqual
                ),
                Some(Ordering::Greater) => matches!(
                    operator,
                    CriteriaOperator::Greater | CriteriaOperator::GreaterOrEqual
                ),
                None => false,
            },
        }
    }
}

/// Splits a criteria argument into an operator and the value it compares
/// against. Only text carries an operator; any other value is compared for
/// equality as it stands.
fn parse_criteria(value: &Value) -> Criteria {
    let Value::String(text) = value else {
        return Criteria {
            operator: CriteriaOperator::Equal,
            operand: value.clone(),
        };
    };
    let text = text.trim();
    let (operator, rest) = if let Some(rest) = text.strip_prefix("<>") {
        (CriteriaOperator::NotEqual, rest)
    } else if let Some(rest) = text.strip_prefix(">=") {
        (CriteriaOperator::GreaterOrEqual, rest)
    } else if let Some(rest) = text.strip_prefix("<=") {
        (CriteriaOperator::LessOrEqual, rest)
    } else if let Some(rest) = text.strip_prefix('>') {
        (CriteriaOperator::Greater, rest)
    } else if let Some(rest) = text.strip_prefix('<') {
        (CriteriaOperator::Less, rest)
    } else if let Some(rest) = text.strip_prefix('=') {
        (CriteriaOperator::Equal, rest)
    } else {
        (CriteriaOperator::Equal, text)
    };
    Criteria {
        operator,
        operand: criteria_operand(rest.trim()),
    }
}

fn criteria_operand(text: &str) -> Value {
    if text.is_empty() {
        return Value::Empty;
    }
    if let Ok(number) = text.parse::<f64>() {
        if number.is_finite() {
            return Value::Double(number);
        }
    }
    if text.eq_ignore_ascii_case("true") {
        return Value::Boolean(true);
    }
    if text.eq_ignore_ascii_case("false") {
        return Value::Boolean(false);
    }
    Value::String(text.to_string())
}

/// Equality reads a cell holding text that spells a number as that number, so
/// `CountIf` over a column mixing `20` and `"20"` counts both. No other
/// operator coerces: `"<>20"` and `">=20"` see the text cell as text.
fn criteria_equal(cell: &Value, operand: &Value, coercing: bool) -> bool {
    if lookup_exact_matches(cell, operand) {
        return true;
    }
    if !coercing {
        return false;
    }
    match (cell, operand) {
        (Value::String(cell), Value::Double(operand)) => cell
            .trim()
            .parse::<f64>()
            .is_ok_and(|cell| cell == *operand),
        _ => false,
    }
}

/// Writes a criterion back out the way VBA stated it, so a saved filter reads
/// as the macro wrote it.
fn criteria_text(criteria: &Criteria) -> String {
    let operand = match &criteria.operand {
        Value::Empty => String::new(),
        value => find_value_text(value),
    };
    let prefix = match criteria.operator {
        CriteriaOperator::Equal => "",
        CriteriaOperator::NotEqual => "<>",
        CriteriaOperator::Less => "<",
        CriteriaOperator::LessOrEqual => "<=",
        CriteriaOperator::Greater => ">",
        CriteriaOperator::GreaterOrEqual => ">=",
    };
    format!("{prefix}{operand}")
}

fn criteria_number(value: &Value) -> Option<f64> {
    match value {
        value if any_number(value).is_some() => Some(any_number(value).unwrap_or_default()),
        _ => None,
    }
}

fn conditional_result(
    name: &str,
    kind: ConditionalKind,
    matches: usize,
    numbers: usize,
    total: f64,
) -> Result<Value, String> {
    match kind {
        ConditionalKind::Count => Ok(Value::Integer(matches as i64)),
        ConditionalKind::Sum => Ok(numeric_result(total)),
        ConditionalKind::Average if numbers == 0 => Err(format!(
            "WorksheetFunction.{name} has no matching numeric values"
        )),
        ConditionalKind::Average => Ok(numeric_result(total / numbers as f64)),
    }
}

fn numeric_result(value: f64) -> Value {
    if value.fract() == 0.0 && value >= i64::MIN as f64 && value <= i64::MAX as f64 {
        Value::Integer(value as i64)
    } else {
        Value::Double(value)
    }
}

/// The text a value shows under a number format. Only numbers are formatted;
/// text comes back as it is, and a Boolean reads TRUE or FALSE whatever the
/// format says.
/// What a cell's own display format says its value IS, over and above the
/// number underneath.
///
/// Asked of Excel, `VarType(Range("A1").Value)` is not 5 for every number in a
/// cell: a cell showing a date hands back a Date and a cell showing dollars
/// hands back a Currency, rounded to the four places a Currency keeps. So the
/// format is not decoration -- it decides the TYPE the macro receives, which
/// is in turn what `IsDate` answers about.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum ShownAs {
    Plain,
    Moment,
    Money,
}

/// Read a display format for the two things that change a number's type.
///
/// Swept against Excel over 50 format codes. What was learnt:
///
/// - A DATE needs a day, month or year field. A time-only format is NOT a
///   date: `h:mm:ss`, `h:mm AM/PM`, `[h]:mm:ss` and `mm:ss.0` all hand back a
///   plain Double, where `d`, `yy`, `mmm`, `ddd` and `m` alone hand back Dates.
/// - An `m` is a MINUTE, not a month, when the nearest field letter before it
///   is `h` or the nearest one after it is `s` -- so `h:m`, `m:ss` and `mm:ss`
///   are times while `m`, `m/d` and `d-m` are dates.
/// - MONEY is the ASCII `$` and nothing else. `¥`, `€`, `£`, `₩` and a
///   trailing `"円"` all leave it a plain Double, and so does the `$` inside a
///   `[$¥-411]` locale bracket or behind a `\` escape. A `$` inside quotes
///   DOES count: `"$"#,##0.00` hands back a Currency.
/// - Quoted runs and bracketed runs carry no fields at all, so `"d"0` is
///   plain, while `\dm` is a date -- the escape kills the `d` and the `m`
///   after it is still a month.
/// How much of what follows an `a` spells out the rest of `AM/PM` or `A/P`,
/// so the whole token can be stepped over as the one thing it is.
fn meridiem_length(rest: &std::iter::Peekable<std::str::Chars<'_>>) -> usize {
    let tail = rest.clone().take(4).collect::<String>().to_ascii_lowercase();
    if tail.starts_with("m/pm") {
        4
    } else if tail.starts_with("/p") {
        2
    } else {
        0
    }
}

fn shown_as(format: Option<&str>) -> ShownAs {
    let Some(format) = format else {
        return ShownAs::Plain;
    };
    // Field letters in the order they appear, with everything that cannot
    // carry a field already dropped. `m` is left undecided until its
    // neighbours are known.
    let mut fields: Vec<char> = Vec::new();
    let mut money = false;
    let mut characters = format.chars().peekable();
    while let Some(character) = characters.next() {
        match character {
            '\\' => {
                characters.next();
            }
            '"' => {
                for quoted in characters.by_ref() {
                    if quoted == '"' {
                        break;
                    }
                    money |= quoted == '$';
                }
            }
            '[' => {
                for bracketed in characters.by_ref() {
                    if bracketed == ']' {
                        break;
                    }
                }
            }
            '$' => money = true,
            // `AM/PM` and `A/P` are one token apiece, not letters. Their `m`s
            // are not months, and counting them as such made
            // `h:mm:ss AM/PM` look like a date format -- which it is not: a
            // cell under it hands its value back as a Double.
            'a' | 'A' if meridiem_length(&characters) > 0 => {
                for _ in 0..meridiem_length(&characters) {
                    characters.next();
                }
            }
            _ => {
                let letter = character.to_ascii_lowercase();
                if matches!(letter, 'y' | 'd' | 'm' | 'h' | 's') {
                    fields.push(letter);
                }
            }
        }
    }
    for (place, letter) in fields.iter().enumerate() {
        let dated = match letter {
            'y' | 'd' => true,
            // A month unless a clock is standing next to it.
            'm' => {
                let before = fields[..place].iter().rev().find(|near| **near != 'm');
                let after = fields[place + 1..].iter().find(|near| **near != 'm');
                before != Some(&'h') && after != Some(&'s')
            }
            _ => false,
        };
        if dated {
            return ShownAs::Moment;
        }
    }
    if money {
        ShownAs::Money
    } else {
        ShownAs::Plain
    }
}

fn shown_text(value: &Value, format: Option<&str>) -> String {
    match value {
        // Every numeric kind takes the format -- a Date among them:
        // measured, `WorksheetFunction.Text(DateSerial(2024, 1, 5),
        // "yyyy/mm/dd")` is 2024/01/05.
        value if any_number(value).is_some() => {
            oxicells_core::format_number(any_number(value).unwrap_or_default(), format.unwrap_or("General"))
        }
        Value::Empty | Value::Missing => String::new(),
        value => find_value_text(value),
    }
}

fn worksheet_number(value: &Value, name: &str) -> Result<f64, String> {
    match value {
        value if any_number(value).is_some() => Ok(any_number(value).unwrap_or_default()),
        Value::Boolean(value) => Ok(f64::from(*value)),
        Value::String(value) => value
            .trim()
            .parse::<f64>()
            .map_err(|_| format!("WorksheetFunction.{name} expects a number")),
        _ => Err(format!("WorksheetFunction.{name} expects a number")),
    }
}

fn sort_number(value: &Value, label: &str) -> Result<i64, String> {
    match value {
        value if any_number(value).is_some() => Ok(any_number(value).unwrap_or_default().trunc() as i64),
        _ => Err(format!("Range.Sort {label} must be numeric")),
    }
}

/// Excel's sort order: numbers first, then text, then Booleans, with blanks
/// last however the sort runs. Text ignores case.
fn sort_rank(value: &Value) -> u8 {
    match value {
        value if any_number(value).is_some() => 0,
        Value::String(_) => 1,
        Value::Boolean(_) => 2,
        _ => 3,
    }
}

/// How two strings compare when the sort has been told to tell case apart.
///
/// Case is a TIEBREAK, not a part of the comparison. Asked of Excel,
/// `a10 A2 a2 A10` sorts to `a10 A10 a2 A2`: if case were weighed at the first
/// letter, `a2` would come before `A10`, and it does not. The strings are
/// compared without regard to case first, and only where they are the same
/// does the case decide — lower before upper, at the first letter where they
/// differ. That gives `b A a B` → `a A b B` and `aB Ab ab AB` → `ab aB Ab AB`.
fn compare_text_by_case(left: &str, right: &str) -> Ordering {
    let folded = left.to_lowercase().cmp(&right.to_lowercase());
    if folded != Ordering::Equal {
        return folded;
    }
    for (ours, other) in left.chars().zip(right.chars()) {
        let cased = ours.is_uppercase().cmp(&other.is_uppercase());
        if cased != Ordering::Equal {
            return cased;
        }
    }
    Ordering::Equal
}

/// The plain comparison, with the case ignored — which is what every caller
/// but a `MatchCase` sort wants, and what the tests below are written against.
#[cfg(test)]
fn sort_compare(left: &Value, right: &Value, descending: bool) -> Ordering {
    sort_compare_cased(left, right, descending, false)
}

fn sort_compare_cased(
    left: &Value,
    right: &Value,
    descending: bool,
    match_case: bool,
) -> Ordering {
    let (left_rank, right_rank) = (sort_rank(left), sort_rank(right));
    if left_rank == 3 || right_rank == 3 {
        // A blank sinks to the bottom whichever way the rest is going.
        return left_rank.cmp(&right_rank);
    }
    let ordering = if left_rank != right_rank {
        left_rank.cmp(&right_rank)
    } else {
        match (left, right) {
            (Value::String(left), Value::String(right)) => {
                if match_case {
                    compare_text_by_case(left, right)
                } else {
                    left.to_lowercase().cmp(&right.to_lowercase())
                }
            }
            (Value::Boolean(left), Value::Boolean(right)) => left.cmp(right),
            _ => match (number_of(left), number_of(right)) {
                (Some(left), Some(right)) => {
                    left.partial_cmp(&right).unwrap_or(Ordering::Equal)
                }
                _ => Ordering::Equal,
            },
        }
    };
    if descending {
        ordering.reverse()
    } else {
        ordering
    }
}

/// Every shape a number can arrive in from the interpreter.
///
/// The interpreter tells VBA's numeric types apart — Integer, Long, Byte,
/// Single, Currency and Date are separate things there — so a host that
/// recognised only two of them refused perfectly ordinary arguments:
/// `Range.Borders(xlEdgeTop)` stopped working the day a small whole number
/// stopped being a Long. One place to ask, so the next type added reaches
/// every caller at once.
fn any_number(value: &Value) -> Option<f64> {
    match value {
        Value::Int16(value) => Some(*value as f64),
        Value::Byte(value) => Some(*value as f64),
        Value::Integer(value) => Some(*value as f64),
        Value::LongLong(value) => Some(*value as f64),
        Value::Single(value) if value.is_finite() => Some(*value as f64),
        Value::Double(value) if value.is_finite() => Some(*value),
        Value::Currency(value) => Some(*value as f64 / 10_000.0),
        Value::Date(value) if value.is_finite() => Some(*value),
        _ => None,
    }
}

/// The same, where the caller needs a whole number and a fraction is not one.
/// A number, or text holding one: `Range.Orientation = "30"` is taken.
fn numeric_text(value: &Value) -> Option<f64> {
    match value {
        Value::String(text) => text.trim().parse::<f64>().ok().filter(|number| number.is_finite()),
        value => any_number(value),
    }
}

/// A pattern as the file numbers it, from either of the numbers Excel takes
/// for it. Measured: 7 is taken and reads back as xlDown, 19 is refused with
/// error 9.
fn pattern_kind(asked: i64) -> Result<i64, String> {
    Ok(match asked {
        COLOUR_NONE => 0,
        // Automatic is a solid of automatic colour.
        COLOUR_AUTOMATIC => 1,
        -4125 => 2,
        -4126 => 3,
        -4124 => 4,
        -4128 => 5,
        -4166 => 6,
        -4121 => 7,
        -4162 => 8,
        1..=18 | 4000 | 4001 => asked,
        _ => return Err(host_error(9, format!("there is no pattern {asked}"))),
    })
}

/// A pattern by Excel's name for it, where it has one.
fn pattern_name(kind: i64) -> i64 {
    match kind {
        0 => COLOUR_NONE,
        2 => -4125,
        3 => -4126,
        4 => -4124,
        5 => -4128,
        6 => -4166,
        7 => -4121,
        8 => -4162,
        kind => kind,
    }
}

fn any_whole_number(value: &Value) -> Option<i64> {
    let number = any_number(value)?;
    (number.fract() == 0.0 && number.abs() < 9.2e18).then_some(number as i64)
}

fn number_of(value: &Value) -> Option<f64> {
    any_number(value)
}

fn index_argument(value: &Value, label: &str) -> Result<usize, String> {
    let number = match value {
        value if any_number(value).is_some() => any_number(value).unwrap_or_default(),
        _ => return Err(format!("WorksheetFunction.Index {label} must be numeric")),
    };
    let number = number.trunc();
    if !(0.0..=u32::MAX as f64).contains(&number) {
        return Err(format!(
            "WorksheetFunction.Index {label} must be zero or greater"
        ));
    }
    Ok(number as usize)
}

/// Resolves `Index` arguments to a one-based row and column, where zero selects
/// a whole row or column. Omitting the column walks the length of a table that
/// has only one row or column; for anything wider Excel accepts the shorthand
/// from an array, taking a whole row, but rejects it from a cell reference.
fn index_selection(
    rows: usize,
    columns: usize,
    row: usize,
    column: Option<usize>,
    reference: bool,
) -> Result<(usize, usize), String> {
    let (row, column) = match column {
        Some(column) => (row, column),
        None if rows == 1 => (1, row),
        None if columns == 1 => (row, 1),
        None if reference => {
            return Err(
                "WorksheetFunction.Index needs a column for a two-dimensional reference".to_string(),
            )
        }
        None => (row, 0),
    };
    if row > rows || column > columns {
        return Err(format!(
            "WorksheetFunction.Index {row},{column} is outside a {rows}-by-{columns} array"
        ));
    }
    Ok((row, column))
}

fn lookup_boolean_argument(value: Option<&Value>, name: &str) -> Result<bool, String> {
    match value {
        None | Some(Value::Missing) => Ok(true),
        Some(Value::Boolean(value)) => Ok(*value),
        Some(Value::Integer(value)) => Ok(*value != 0),
        Some(Value::Double(value)) if value.is_finite() => Ok(*value != 0.0),
        Some(_) => Err(format!(
            "WorksheetFunction.{name} range lookup flag must be Boolean"
        )),
    }
}

fn match_type_argument(value: Option<&Value>) -> Result<i64, String> {
    let number = match value {
        None | Some(Value::Missing) => return Ok(1),
        Some(value) if any_number(value).is_some() => any_number(value).unwrap_or_default(),
        Some(_) => return Err("WorksheetFunction.Match type must be numeric".to_string()),
    };
    let number = number.trunc();
    Ok(if number > 0.0 {
        1
    } else if number < 0.0 {
        -1
    } else {
        0
    })
}

fn find_value_text(value: &Value) -> String {
    match value {
        Value::Empty => String::new(),
        Value::Boolean(value) => if *value { "TRUE" } else { "FALSE" }.to_string(),
        Value::Int16(value) => value.to_string(),
        Value::Byte(value) => value.to_string(),
        Value::Integer(value) => value.to_string(),
        Value::LongLong(value) => value.to_string(),
        Value::Single(value) => (*value as f64).to_string(),
        Value::Currency(value) => (*value as f64 / 10_000.0).to_string(),
        Value::Date(value) => value.to_string(),
        Value::Double(value) => value.to_string(),
        // The word itself is what a cell holding an error shows and what a
        // search reads: asked of Excel, `.Text` of a cell holding #DIV/0! is
        // `#DIV/0!`, and `Find("N/A")` lands on the cell holding #N/A.
        // `Debug.Print` is NOT this -- VBA writes `Error 2042` there.
        Value::Error(value) => spreadsheet_error_text(*value).to_string(),
        Value::String(value) => value.clone(),
        Value::Null => "Null".to_string(),
        Value::Missing => String::new(),
        Value::Nothing => "Nothing".to_string(),
        Value::Array(_) => "<Array>".to_string(),
        Value::Record(record) => format!("<{}>", record.type_name),
        Value::Object(value) => format!("<{}>", value.kind),
    }
}

/// A character as the search compares it: one case unless the case matters,
/// one width unless the width does.
///
/// Excel calls the second of those `MatchByte`, and with it off — which is how
/// it starts — the wide and narrow forms of a letter are the same letter.
/// Asked of it, `Find("ABC")` lands on a cell holding the wide `ＡＢＣ`, and
/// half-width `ｱｲ` lands on `アイ`. What does NOT fold is a narrow kana with
/// its voice mark beside it: `ｶ` + `ﾞ` stays two characters and never meets
/// the single `ガ`.
fn compared(one: char, match_case: bool, match_byte: bool) -> char {
    let one = if match_byte { one } else { one_width(one) };
    if match_case {
        one
    } else {
        one.to_lowercase().next().unwrap_or(one)
    }
}

/// The full-width kana, in the order the narrow ones run from `FF61`.
const NARROW_KANA: [char; 63] = [
    '\u{3002}', '\u{300c}', '\u{300d}', '\u{3001}', '\u{30fb}', '\u{30f2}', '\u{30a1}',
    '\u{30a3}', '\u{30a5}', '\u{30a7}', '\u{30a9}', '\u{30e3}', '\u{30e5}', '\u{30e7}',
    '\u{30c3}', '\u{30fc}', '\u{30a2}', '\u{30a4}', '\u{30a6}', '\u{30a8}', '\u{30aa}',
    '\u{30ab}', '\u{30ad}', '\u{30af}', '\u{30b1}', '\u{30b3}', '\u{30b5}', '\u{30b7}',
    '\u{30b9}', '\u{30bb}', '\u{30bd}', '\u{30bf}', '\u{30c1}', '\u{30c4}', '\u{30c6}',
    '\u{30c8}', '\u{30ca}', '\u{30cb}', '\u{30cc}', '\u{30cd}', '\u{30ce}', '\u{30cf}',
    '\u{30d2}', '\u{30d5}', '\u{30d8}', '\u{30db}', '\u{30de}', '\u{30df}', '\u{30e0}',
    '\u{30e1}', '\u{30e2}', '\u{30e4}', '\u{30e6}', '\u{30e8}', '\u{30e9}', '\u{30ea}',
    '\u{30eb}', '\u{30ec}', '\u{30ed}', '\u{30ef}', '\u{30f3}', '\u{309b}', '\u{309c}',
];

/// One width for a character that has two.
fn one_width(one: char) -> char {
    let code = one as u32;
    // The wide forms of what a keyboard types run from FF01 to FF5E, exactly
    // 0xFEE0 above the narrow ones.
    if (0xFF01..=0xFF5E).contains(&code) {
        return char::from_u32(code - 0xFEE0).unwrap_or(one);
    }
    if (0xFF61..=0xFF9F).contains(&code) {
        return NARROW_KANA[(code - 0xFF61) as usize];
    }
    one
}

/// The characters of a string as they are compared.
fn compared_chars(text: &str, match_case: bool, match_byte: bool) -> Vec<char> {
    text.chars()
        .map(|one| compared(one, match_case, match_byte))
        .collect()
}

fn find_text_matches(
    candidate: &str,
    needle: &str,
    whole: bool,
    match_case: bool,
    match_byte: bool,
) -> bool {
    let candidate = compared_chars(candidate, match_case, match_byte);
    let needle = compared_chars(needle, match_case, match_byte);
    if needle.iter().any(|c| matches!(c, '*' | '?' | '~')) {
        return wildcard_span(&candidate, &needle, whole).is_some();
    }
    if whole {
        return candidate == needle;
    }
    if needle.is_empty() {
        return true;
    }
    candidate.windows(needle.len()).any(|held| held == needle)
}

/// Where a wildcard needle -- `*` a run, `?` one character, `~` escaping
/// the next -- first matches in the candidate, as (start, length); the run
/// is greedy. `whole` asks the match to cover the candidate entirely.
/// Measured: `Replace "ab*", "z"` turns `abc` and `abd` into `z`.
fn wildcard_span(candidate: &[char], needle: &[char], whole: bool) -> Option<(usize, usize)> {
    let mut tokens: Vec<WildcardToken> = Vec::new();
    let mut at = 0;
    while at < needle.len() {
        match needle[at] {
            '~' => {
                if let Some(escaped) = needle.get(at + 1) {
                    tokens.push(WildcardToken::Literal(*escaped));
                }
                at += 2;
                continue;
            }
            '*' => tokens.push(WildcardToken::AnyRun),
            '?' => tokens.push(WildcardToken::AnyCharacter),
            c => tokens.push(WildcardToken::Literal(c)),
        }
        at += 1;
    }
    fn reach(candidate: &[char], from: usize, tokens: &[WildcardToken], whole: bool) -> Option<usize> {
        match tokens.first() {
            None => {
                if whole && from != candidate.len() {
                    None
                } else {
                    Some(from)
                }
            }
            Some(WildcardToken::AnyRun) => {
                // Greedy: the longest run that lets the rest match.
                (from..=candidate.len()).rev().find_map(|stop| reach(candidate, stop, &tokens[1..], whole))
            }
            Some(WildcardToken::AnyCharacter) => {
                (from < candidate.len()).then(|| reach(candidate, from + 1, &tokens[1..], whole)).flatten()
            }
            Some(WildcardToken::Literal(c)) => {
                (candidate.get(from) == Some(c)).then(|| reach(candidate, from + 1, &tokens[1..], whole)).flatten()
            }
        }
    }
    if whole {
        return reach(candidate, 0, &tokens, true).map(|end| (0, end));
    }
    (0..=candidate.len()).find_map(|start| reach(candidate, start, &tokens, false).map(|end| (start, end - start)))
}

fn replace_matching_text(
    candidate: &str,
    needle: &str,
    replacement: &str,
    whole: bool,
    match_case: bool,
    match_byte: bool,
) -> Option<String> {
    if !find_text_matches(candidate, needle, whole, match_case, match_byte) {
        return None;
    }
    if whole {
        return Some(replacement.to_string());
    }
    if needle.is_empty() {
        return None;
    }
    // Counted in CHARACTERS, not bytes: a letter and its wide twin are one
    // character each but three bytes apart, so only the character count lines
    // the two strings up.
    let held: Vec<char> = candidate.chars().collect();
    let looking = compared_chars(candidate, match_case, match_byte);
    let needle = compared_chars(needle, match_case, match_byte);
    if needle.iter().any(|c| matches!(c, '*' | '?' | '~')) {
        // Each match, left to right, gives way to the replacement.
        let mut result = String::with_capacity(candidate.len());
        let mut at = 0;
        let mut replaced_any = false;
        while at <= looking.len() {
            match wildcard_span(&looking[at..], &needle, false) {
                Some((start, length)) if length > 0 || start < looking.len() - at => {
                    result.extend(held[at..at + start].iter());
                    result.push_str(replacement);
                    replaced_any = true;
                    at += start + length.max(1);
                }
                _ => {
                    result.extend(held[at..].iter());
                    break;
                }
            }
        }
        return replaced_any.then_some(result);
    }
    let mut result = String::with_capacity(candidate.len());
    let mut at = 0;
    let mut replaced_any = false;
    while at < looking.len() {
        if at + needle.len() <= looking.len() && looking[at..at + needle.len()] == needle[..] {
            result.push_str(replacement);
            at += needle.len();
            replaced_any = true;
        } else {
            result.push(held[at]);
            at += 1;
        }
    }
    replaced_any.then_some(result)
}

fn optional_dimension(value: Value, property: &str, maximum: f64) -> Result<Option<f32>, String> {
    let number = match value {
        Value::Empty => return Ok(None),
        value if any_number(&value).is_some() => any_number(&value).unwrap_or_default(),
        _ => return Err(format!("{property} must be numeric")),
    };
    if !number.is_finite() || !(0.0..=maximum).contains(&number) {
        return Err(format!("{property} must be between 0 and {maximum}"));
    }
    Ok(Some(number as f32))
}

fn font_size(value: &Value) -> Result<Option<f32>, String> {
    let number = match value {
        Value::Empty => return Ok(None),
        value if any_number(value).is_some() => any_number(value).unwrap_or_default(),
        _ => return Err("Font.Size must be numeric".to_string()),
    };
    if !number.is_finite() || number <= 0.0 || number > f32::MAX as f64 {
        return Err("Font.Size must be a positive finite number".to_string());
    }
    Ok(Some(number as f32))
}

fn color_number(value: &Value, property: &str) -> Result<Option<u32>, String> {
    let number = match value {
        Value::Empty => return Ok(None),
        value if any_number(value).is_some() => any_number(value).unwrap_or_default(),
        _ => return Err(format!("{property} must be an RGB color number")),
    };
    if !number.is_finite() || number.fract() != 0.0 || !(0.0..=16_777_215.0).contains(&number) {
        return Err(format!(
            "{property} must be an RGB color number from 0 to 16777215"
        ));
    }
    Ok(Some(number as u32))
}

fn style_color(value: &Value, property: &str) -> Result<Option<String>, String> {
    Ok(color_number(value, property)?.map(|colour| colour_from_packed(colour as i64)))
}

/// A colour as VBA counts it, or the one the cell is wearing without saying.
///
/// A cell that names no colour is not colourless: asked of Excel, an untouched
/// cell answers `0` for `Font.Color` — black — and `16777215` for
/// `Interior.Color`, which is white. `bare` is that answer.
fn style_color_value(value: Option<Option<String>>, bare: i64) -> Value {
    let Some(value) = value else {
        return Value::Null;
    };
    let Some(value) = value else {
        return Value::Integer(bare);
    };
    // The file writes a colour as six hex digits with nothing in front, and
    // that is the form the IR keeps; a `#` in front is taken as well so that
    // nothing written the other way is read as colourless.
    let hex = value.strip_prefix('#').unwrap_or(&value);
    if hex.len() != 6 {
        return Value::Integer(bare);
    }
    let Ok(rgb) = u32::from_str_radix(hex, 16) else {
        return Value::Integer(bare);
    };
    let red = (rgb >> 16) & 0xff;
    let green = (rgb >> 8) & 0xff;
    let blue = rgb & 0xff;
    Value::Integer(i64::from(red | (green << 8) | (blue << 16)))
}

fn horizontal_alignment(value: &Value) -> Result<Option<String>, String> {
    let value = match value {
        Value::Empty => return Ok(None),
        value if any_whole_number(value).is_some() => any_whole_number(value).unwrap_or_default(),
        _ => {
            return Err("Range.HorizontalAlignment must be an Excel alignment constant".to_string())
        }
    };
    match value {
        1 => Ok(None),
        -4131 => Ok(Some("left".to_string())),
        -4108 => Ok(Some("center".to_string())),
        -4152 => Ok(Some("right".to_string())),
        5 => Ok(Some("fill".to_string())),
        -4130 => Ok(Some("justify".to_string())),
        7 => Ok(Some("centerContinuous".to_string())),
        -4117 => Ok(Some("distributed".to_string())),
        _ => Err(format!(
            "unsupported Range.HorizontalAlignment constant: {value}"
        )),
    }
}

fn horizontal_alignment_value(value: Option<Option<String>>) -> Value {
    let Some(value) = value else {
        return Value::Null;
    };
    let Some(value) = value else {
        return Value::Integer(1);
    };
    let constant = match value.to_ascii_lowercase().as_str() {
        "left" => -4131,
        "center" => -4108,
        "right" => -4152,
        "fill" => 5,
        "justify" => -4130,
        "centercontinuous" => 7,
        "distributed" => -4117,
        _ => return Value::Empty,
    };
    Value::Integer(constant)
}

fn border_selection(value: &Value) -> Result<BorderSelection, String> {
    let value = match value {
        value if any_whole_number(value).is_some() => any_whole_number(value).unwrap_or_default(),
        _ => return Err("Range.Borders index must be an Excel border constant".to_string()),
    };
    match value {
        5 => Ok(BorderSelection::DiagonalDown),
        6 => Ok(BorderSelection::DiagonalUp),
        7 => Ok(BorderSelection::EdgeLeft),
        8 => Ok(BorderSelection::EdgeTop),
        9 => Ok(BorderSelection::EdgeBottom),
        10 => Ok(BorderSelection::EdgeRight),
        11 => Ok(BorderSelection::InsideVertical),
        12 => Ok(BorderSelection::InsideHorizontal),
        _ => Err(format!("unsupported Range.Borders index: {value}")),
    }
}

const LINE_NONE: i64 = -4142;
const LINE_CONTINUOUS: i64 = 1;
const WEIGHT_THIN: i64 = 2;

/// The thirteen rules Excel can draw along an edge: the name the file gives
/// each, and the pair the object model splits it into.
///
/// Swept in Excel 16.0 — every line style crossed with every weight, written
/// into a workbook and read back out of its `styles.xml`. The pairs missing
/// from this table cannot be had: asking for one snaps to a neighbour, and
/// which neighbour depends on which of the two was asked for last (see
/// `border_after_line` and `border_after_weight`).
const BORDER_KINDS: &[(&str, i64, i64)] = &[
    ("hair", LINE_CONTINUOUS, 1),
    ("thin", LINE_CONTINUOUS, WEIGHT_THIN),
    ("medium", LINE_CONTINUOUS, -4138),
    ("thick", LINE_CONTINUOUS, 4),
    ("dashed", -4115, WEIGHT_THIN),
    ("mediumDashed", -4115, -4138),
    ("dotted", -4118, WEIGHT_THIN),
    ("dashDot", 4, WEIGHT_THIN),
    ("mediumDashDot", 4, -4138),
    ("dashDotDot", 5, WEIGHT_THIN),
    ("mediumDashDotDot", 5, -4138),
    ("slantDashDot", 13, -4138),
    ("double", -4119, 4),
];

/// What the file calls this edge, read as a line style and a weight. An edge
/// with nothing drawn along it answers `LineStyle` None and `Weight` Thin,
/// which is what Excel answers for a cell nobody has touched.
fn border_kind(drawn: Option<&BorderLine>) -> (i64, i64) {
    let Some(drawn) = drawn else {
        return (LINE_NONE, WEIGHT_THIN);
    };
    BORDER_KINDS
        .iter()
        .find(|(name, _, _)| name.eq_ignore_ascii_case(&drawn.style))
        .map(|(_, line, weight)| (*line, *weight))
        .unwrap_or((LINE_CONTINUOUS, WEIGHT_THIN))
}

/// The edge after `LineStyle` is written: the style is kept and the weight
/// gives way. Measured — from Thick, asking for Dash gives `dashed`, which is
/// thin, because there is no thick dash; Medium keeps its weight because
/// `mediumDashed` exists; Double is always thick and SlantDashDot always
/// medium, whatever the edge was before.
fn border_after_line(line: i64, weight: i64) -> Option<&'static str> {
    if line == LINE_NONE {
        return None;
    }
    if let Some((name, _, _)) = BORDER_KINDS
        .iter()
        .find(|(_, kind, held)| *kind == line && *held == weight)
    {
        return Some(name);
    }
    BORDER_KINDS
        .iter()
        .find(|(_, kind, held)| *kind == line && *held == WEIGHT_THIN)
        .or_else(|| BORDER_KINDS.iter().find(|(_, kind, _)| *kind == line))
        .map(|(name, _, _)| *name)
}

/// The edge after `Weight` is written: the weight is kept and the LINE gives
/// way, all the way back to a plain rule. Measured — a dashed edge asked for
/// Hairline becomes `hair`, a double edge asked for Thin becomes `thin`.
fn border_after_weight(line: i64, weight: i64) -> Option<&'static str> {
    BORDER_KINDS
        .iter()
        .find(|(_, kind, held)| *kind == line && *held == weight)
        .or_else(|| {
            BORDER_KINDS
                .iter()
                .find(|(_, kind, held)| *kind == LINE_CONTINUOUS && *held == weight)
        })
        .map(|(name, _, _)| *name)
}

fn border_line_style(value: &Value) -> Result<i64, String> {
    let value = match value {
        Value::Empty => return Ok(LINE_NONE),
        value if any_whole_number(value).is_some() => any_whole_number(value).unwrap_or_default(),
        _ => return Err("Borders.LineStyle must be an Excel line-style constant".to_string()),
    };
    if value == LINE_NONE || BORDER_KINDS.iter().any(|(_, line, _)| *line == value) {
        Ok(value)
    } else {
        Err(format!("unsupported Borders.LineStyle constant: {value}"))
    }
}

fn border_weight(value: &Value) -> Result<i64, String> {
    let value = match value {
        value if any_whole_number(value).is_some() => any_whole_number(value).unwrap_or_default(),
        _ => return Err("Borders.Weight must be an Excel weight constant".to_string()),
    };
    // Measured: `Weight = 3` is taken, and reads back xlMedium.
    let value = if value == 3 { -4138 } else { value };
    if BORDER_KINDS.iter().any(|(_, _, weight)| *weight == value) {
        Ok(value)
    } else {
        Err(host_error(1004, format!("unsupported Borders.Weight constant: {value}")))
    }
}

fn selected_borders(
    style: &CellStyle,
    address: CellAddress,
    range: CellRange,
    selection: BorderSelection,
) -> Vec<(i64, i64)> {
    let kind = border_kind;
    match selection {
        BorderSelection::All => vec![
            kind(style.border_top.as_ref()),
            kind(style.border_bottom.as_ref()),
            kind(style.border_left.as_ref()),
            kind(style.border_right.as_ref()),
        ],
        BorderSelection::EdgeLeft if address.column == range.start_column => {
            vec![kind(style.border_left.as_ref())]
        }
        BorderSelection::EdgeTop if address.row == range.start_row => {
            vec![kind(style.border_top.as_ref())]
        }
        BorderSelection::EdgeBottom if address.row == range.end_row => {
            vec![kind(style.border_bottom.as_ref())]
        }
        BorderSelection::EdgeRight if address.column == range.end_column => {
            vec![kind(style.border_right.as_ref())]
        }
        BorderSelection::InsideVertical => {
            let mut values = Vec::with_capacity(2);
            if address.column > range.start_column {
                values.push(kind(style.border_left.as_ref()));
            }
            if address.column < range.end_column {
                values.push(kind(style.border_right.as_ref()));
            }
            values
        }
        BorderSelection::InsideHorizontal => {
            let mut values = Vec::with_capacity(2);
            if address.row > range.start_row {
                values.push(kind(style.border_top.as_ref()));
            }
            if address.row < range.end_row {
                values.push(kind(style.border_bottom.as_ref()));
            }
            values
        }
        BorderSelection::DiagonalDown => {
            vec![kind(style.border_diagonal.as_ref().filter(|_| style.diagonal_down))]
        }
        BorderSelection::DiagonalUp => {
            vec![kind(style.border_diagonal.as_ref().filter(|_| style.diagonal_up))]
        }
        _ => Vec::new(),
    }
}

/// What an edge answers for its colour: nothing drawn, drawn in the
/// automatic colour, or drawn in a named one.
#[derive(Debug, Clone, PartialEq, Eq)]
enum EdgeColour {
    NoLine,
    Automatic,
    Named(String),
}

/// The edges of a cell a selection names, as drawn.
fn selected_border_lines(
    style: &CellStyle,
    address: CellAddress,
    range: CellRange,
    selection: BorderSelection,
) -> Vec<Option<BorderLine>> {
    match selection {
        BorderSelection::All => vec![
            style.border_top.clone(),
            style.border_bottom.clone(),
            style.border_left.clone(),
            style.border_right.clone(),
        ],
        BorderSelection::EdgeLeft if address.column == range.start_column => {
            vec![style.border_left.clone()]
        }
        BorderSelection::EdgeTop if address.row == range.start_row => {
            vec![style.border_top.clone()]
        }
        BorderSelection::EdgeBottom if address.row == range.end_row => {
            vec![style.border_bottom.clone()]
        }
        BorderSelection::EdgeRight if address.column == range.end_column => {
            vec![style.border_right.clone()]
        }
        BorderSelection::InsideVertical => {
            let mut edges = Vec::with_capacity(2);
            if address.column > range.start_column {
                edges.push(style.border_left.clone());
            }
            if address.column < range.end_column {
                edges.push(style.border_right.clone());
            }
            edges
        }
        BorderSelection::InsideHorizontal => {
            let mut edges = Vec::with_capacity(2);
            if address.row > range.start_row {
                edges.push(style.border_top.clone());
            }
            if address.row < range.end_row {
                edges.push(style.border_bottom.clone());
            }
            edges
        }
        _ => Vec::new(),
    }
}

/// Give the selected edges a colour, drawing a thin line where there was
/// none.
fn recolour_selected_borders(
    style: &mut CellStyle,
    address: CellAddress,
    range: CellRange,
    selection: BorderSelection,
    colour: Option<&str>,
) {
    let recoloured = |edge: &mut Option<BorderLine>| {
        let kind = edge
            .as_ref()
            .map(|line| line.style.clone())
            .unwrap_or_else(|| "thin".to_string());
        *edge = Some(BorderLine {
            style: kind,
            color: colour.map(str::to_string),
        });
    };
    match selection {
        BorderSelection::All => {
            recoloured(&mut style.border_top);
            recoloured(&mut style.border_bottom);
            recoloured(&mut style.border_left);
            recoloured(&mut style.border_right);
        }
        BorderSelection::EdgeLeft if address.column == range.start_column => {
            recoloured(&mut style.border_left);
        }
        BorderSelection::EdgeTop if address.row == range.start_row => {
            recoloured(&mut style.border_top);
        }
        BorderSelection::EdgeBottom if address.row == range.end_row => {
            recoloured(&mut style.border_bottom);
        }
        BorderSelection::EdgeRight if address.column == range.end_column => {
            recoloured(&mut style.border_right);
        }
        BorderSelection::InsideVertical => {
            if address.column > range.start_column {
                recoloured(&mut style.border_left);
            }
            if address.column < range.end_column {
                recoloured(&mut style.border_right);
            }
        }
        BorderSelection::InsideHorizontal => {
            if address.row > range.start_row {
                recoloured(&mut style.border_top);
            }
            if address.row < range.end_row {
                recoloured(&mut style.border_bottom);
            }
        }
        _ => {}
    }
}

fn set_selected_borders(
    style: &mut CellStyle,
    address: CellAddress,
    range: CellRange,
    selection: BorderSelection,
    // What each edge becomes, worked out from what it already was: the two
    // halves of a border snap differently, so the edge has to be seen first.
    becomes: &dyn Fn(Option<&BorderLine>) -> Option<&'static str>,
) {
    let existing = match selection {
        BorderSelection::EdgeLeft | BorderSelection::InsideVertical => style.border_left.clone(),
        BorderSelection::EdgeTop | BorderSelection::InsideHorizontal => style.border_top.clone(),
        BorderSelection::EdgeBottom => style.border_bottom.clone(),
        BorderSelection::EdgeRight => style.border_right.clone(),
        BorderSelection::DiagonalDown | BorderSelection::DiagonalUp => style.border_diagonal.clone(),
        BorderSelection::All => style
            .border_top
            .clone()
            .or_else(|| style.border_bottom.clone()),
    };
    let drawn = becomes(existing.as_ref()).map(|name| BorderLine {
        style: name.to_string(),
        color: existing.as_ref().and_then(|held| held.color.clone()),
    });
    match selection {
        BorderSelection::All => {
            style.border_top = drawn.clone();
            style.border_bottom = drawn.clone();
            style.border_left = drawn.clone();
            style.border_right = drawn.clone();
        }
        BorderSelection::EdgeLeft if address.column == range.start_column => {
            style.border_left = drawn.clone();
        }
        BorderSelection::EdgeTop if address.row == range.start_row => {
            style.border_top = drawn.clone();
        }
        BorderSelection::EdgeBottom if address.row == range.end_row => {
            style.border_bottom = drawn.clone();
        }
        BorderSelection::EdgeRight if address.column == range.end_column => {
            style.border_right = drawn.clone();
        }
        BorderSelection::InsideVertical => {
            if address.column > range.start_column {
                style.border_left = drawn.clone();
            }
            if address.column < range.end_column {
                style.border_right = drawn.clone();
            }
        }
        BorderSelection::InsideHorizontal => {
            if address.row > range.start_row {
                style.border_top = drawn.clone();
            }
            if address.row < range.end_row {
                style.border_bottom = drawn.clone();
            }
        }
        BorderSelection::DiagonalDown => {
            style.diagonal_down = drawn.is_some();
            if drawn.is_some() || !style.diagonal_up {
                style.border_diagonal = drawn.clone();
            }
        }
        BorderSelection::DiagonalUp => {
            style.diagonal_up = drawn.is_some();
            if drawn.is_some() || !style.diagonal_down {
                style.border_diagonal = drawn.clone();
            }
        }
        _ => {}
    }
}

fn rgb_value(args: &[Value]) -> Result<Value, String> {
    let [red, green, blue] = args else {
        return Err("RGB expects red, green, and blue arguments".to_string());
    };
    let component = |value: &Value, name: &str| -> Result<u32, String> {
        let value = match value {
            value if any_number(value).is_some() => any_number(value).unwrap_or_default(),
            _ => return Err(format!("RGB {name} must be numeric")),
        };
        if !value.is_finite() || value.fract() != 0.0 || !(0.0..=255.0).contains(&value) {
            return Err(format!("RGB {name} must be an integer from 0 to 255"));
        }
        Ok(value as u32)
    };
    let red = component(red, "red")?;
    let green = component(green, "green")?;
    let blue = component(blue, "blue")?;
    Ok(Value::Integer(i64::from(red | (green << 8) | (blue << 16))))
}

fn cell_has_content(cell: &Cell) -> bool {
    cell.formula.is_some() || !matches!(&cell.value, CellValue::Empty)
}

fn merge_range(sheet: usize, merge: &MergeCell) -> CellRange {
    CellRange {
        sheet,
        start_row: merge.start_row,
        start_column: merge.start_col,
        end_row: merge.end_row,
        end_column: merge.end_col,
    }
}

fn ranges_overlap(left: CellRange, right: CellRange) -> bool {
    left.sheet == right.sheet
        && left.start_row <= right.end_row
        && right.start_row <= left.end_row
        && left.start_column <= right.end_column
        && right.start_column <= left.end_column
}

fn ranges_equal(left: CellRange, right: CellRange) -> bool {
    left.sheet == right.sheet
        && left.start_row == right.start_row
        && left.start_column == right.start_column
        && left.end_row == right.end_row
        && left.end_column == right.end_column
}

fn range_contains(outer: CellRange, inner: CellRange) -> bool {
    outer.sheet == inner.sheet
        && outer.start_row <= inner.start_row
        && outer.start_column <= inner.start_column
        && outer.end_row >= inner.end_row
        && outer.end_column >= inner.end_column
}

fn ctrl_arrow_destination(
    occupied: &[u32],
    start: u32,
    minimum: u32,
    maximum: u32,
    forward: bool,
) -> u32 {
    if start == if forward { maximum } else { minimum } {
        return start;
    }
    let start_index = occupied.binary_search(&start).ok();
    let neighbour = if forward { start + 1 } else { start - 1 };
    let neighbour_index = occupied.binary_search(&neighbour).ok();
    if let (Some(_), Some(mut index)) = (start_index, neighbour_index) {
        let mut destination = neighbour;
        if forward {
            while occupied.get(index + 1) == Some(&(destination + 1)) {
                index += 1;
                destination += 1;
            }
        } else {
            while index > 0 && occupied.get(index - 1) == Some(&(destination - 1)) {
                index -= 1;
                destination -= 1;
            }
        }
        return destination;
    }
    if forward {
        occupied
            .iter()
            .copied()
            .find(|position| *position > start)
            .unwrap_or(maximum)
    } else {
        occupied
            .iter()
            .rev()
            .copied()
            .find(|position| *position < start)
            .unwrap_or(minimum)
    }
}

fn end_direction(value: &Value) -> Result<EndDirection, String> {
    let value = match value {
        value if any_whole_number(value).is_some() => any_whole_number(value).unwrap_or_default(),
        _ => return Err("Range.End direction must be an Excel direction constant".to_string()),
    };
    match value {
        -4162 => Ok(EndDirection::Up),
        -4121 => Ok(EndDirection::Down),
        -4159 => Ok(EndDirection::Left),
        -4161 => Ok(EndDirection::Right),
        _ => Err(format!("unsupported Range.End direction: {value}")),
    }
}

