    /// Excel keeps every number in a cell as a Double, whole or not, and that is
    /// the type VBA reports for it. Text, Booleans and blanks keep their own.
    #[test]
    fn a_cells_number_carries_the_double_type() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub CellTypes()\n\
               Range(\"A1\").Value = 42\n\
               Range(\"A2\").Value = 42.5\n\
               Range(\"A3\").Value = \"text\"\n\
               Range(\"A4\").Value = True\n\
               Debug.Print TypeName(Range(\"A1\").Value), TypeName(Range(\"A2\").Value)\n\
               Debug.Print TypeName(Range(\"A3\").Value), TypeName(Range(\"A4\").Value), TypeName(Range(\"A5\").Value)\n\
               Debug.Print VarType(Range(\"A1\")), VarType(Range(\"A3\")), VarType(Range(\"A5\"))\n\
               Debug.Print Range(\"A1\"), \"x\" & Range(\"A1\"), Range(\"A1\") + 1\n\
             End Sub\n",
        )
        .unwrap();
        let debug_output = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "CellTypes", vec![], &mut host).unwrap();
            host.take_debug_output()
        };

        assert_eq!(
            debug_output,
            vec![
                "Double\tDouble".to_string(),
                "String\tBoolean\tEmpty".to_string(),
                "5\t8\t0".to_string(),
                // A whole Double still reads back without a trailing zero.
                "42\tx42\t43".to_string(),
            ]
        );
    }

    /// Reads the top-left corner of a sheet the way the Excel probes printed it,
    /// so the expectations below are the grids Excel actually left behind.
    fn grid(workbook: &Workbook, rows: u32, columns: u32) -> String {
        (1..=rows)
            .map(|row| {
                (0..columns)
                    .map(|column| {
                        workbook.sheets[0]
                            .rows
                            .iter()
                            .find(|candidate| candidate.index == row)
                            .and_then(|found| found.cells.iter().find(|cell| cell.col == column))
                            .map(|cell| match &cell.value {
                                CellValue::String(value) => value.clone(),
                                value => value.display(),
                            })
                            .filter(|value| !value.is_empty())
                            .unwrap_or_else(|| ".".to_string())
                    })
                    .collect::<Vec<_>>()
                    .join(",")
            })
            .collect::<Vec<_>>()
            .join(" / ")
    }

    fn filled_grid() -> Workbook {
        let mut workbook = workbook();
        workbook.sheets[0].rows = (1..=4)
            .map(|row| Row {
                index: row,
                height: None,
                custom_height: false,
                style_font: None,
                thick_top: false,
                thick_bottom: false,
                hidden: false,
                cells: (0..4)
                    .map(|column| Cell {
                        array_block: None,
                        col: column,
                        value: CellValue::String(format!(
                            "{}{row}",
                            (b'A' + column as u8) as char
                        )),
                        style: CellStyle::default(),
                        formula: None,
                        runs: Vec::new(),
                    })
                    .collect(),
            })
            .collect();
        workbook
    }

    fn run_on_grid(source: &str) -> Workbook {
        let mut workbook = filled_grid();
        let module = parse_module(source).unwrap();
        {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
        }
        workbook
    }

    #[test]
    fn vba_inserts_and_deletes_whole_rows_and_columns() {
        let workbook = run_on_grid(
            "Public Sub Act()\n  Range(\"A2\").EntireRow.Insert\nEnd Sub\n",
        );
        assert_eq!(
            grid(&workbook, 4, 4),
            "A1,B1,C1,D1 / .,.,.,. / A2,B2,C2,D2 / A3,B3,C3,D3"
        );

        let workbook = run_on_grid(
            "Public Sub Act()\n  Range(\"B1\").EntireColumn.Insert\nEnd Sub\n",
        );
        assert_eq!(
            grid(&workbook, 4, 4),
            "A1,.,B1,C1 / A2,.,B2,C2 / A3,.,B3,C3 / A4,.,B4,C4"
        );

        let workbook = run_on_grid(
            "Public Sub Act()\n  Range(\"A2\").EntireRow.Delete\nEnd Sub\n",
        );
        assert_eq!(
            grid(&workbook, 4, 4),
            "A1,B1,C1,D1 / A3,B3,C3,D3 / A4,B4,C4,D4 / .,.,.,."
        );

        let workbook = run_on_grid(
            "Public Sub Act()\n  Range(\"B1\").EntireColumn.Delete\nEnd Sub\n",
        );
        assert_eq!(
            grid(&workbook, 4, 4),
            "A1,C1,D1,. / A2,C2,D2,. / A3,C3,D3,. / A4,C4,D4,."
        );

        // A band wider than one row moves everything below it that much further.
        let workbook = run_on_grid(
            "Public Sub Act()\n  Range(\"A2:A3\").EntireRow.Insert\nEnd Sub\n",
        );
        assert_eq!(
            grid(&workbook, 5, 2),
            "A1,B1 / .,. / .,. / A2,B2 / A3,B3"
        );
    }

    #[test]
    fn vba_moves_formulas_across_an_inserted_or_deleted_row() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Act()\n\
               Range(\"A1\").Value = 10\n\
               Range(\"A2\").Value = 20\n\
               Range(\"B1\").Formula = \"=A1*2\"\n\
               Range(\"C1\").Formula = \"=SUM(A1:A2)\"\n\
               Range(\"D3\").Formula = \"=A2*2\"\n\
               Range(\"A1\").EntireRow.Insert\n\
             End Sub\n",
        )
        .unwrap();
        {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
        }
        let formula = |row: u32, column: u32| {
            workbook.sheets[0]
                .rows
                .iter()
                .find(|candidate| candidate.index == row)
                .and_then(|found| found.cells.iter().find(|cell| cell.col == column))
                .and_then(|cell| cell.formula.clone())
                .unwrap_or_default()
        };
        // A sheet keeps a formula without its leading '=', so that is what the
        // shifted formula reads as too.
        assert_eq!(formula(2, 1), "A2*2");
        assert_eq!(formula(2, 2), "SUM(A2:A3)");
        assert_eq!(formula(4, 3), "A3*2");
    }

    #[test]
    fn a_formula_pointing_at_a_deleted_row_reads_ref() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Act()\n\
               Range(\"A2\").Value = 20\n\
               Range(\"B1\").Formula = \"=A2*2\"\n\
               Range(\"A2\").EntireRow.Delete\n\
             End Sub\n",
        )
        .unwrap();
        {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
        }
        let cell = workbook.sheets[0].rows[0]
            .cells
            .iter()
            .find(|cell| cell.col == 1)
            .expect("B1 still holds its formula");
        assert_eq!(cell.formula.as_deref(), Some("#REF!*2"));
    }

    /// A merge follows the rows under it, and one whose rows all go, goes too.
    #[test]
    fn merges_follow_an_inserted_or_deleted_row() {
        let mut workbook = filled_grid();
        workbook.sheets[0].merge_cells.push(MergeCell {
            start_row: 2,
            start_col: 1,
            end_row: 2,
            end_col: 2,
        });
        let module =
            parse_module("Public Sub Act()\n  Range(\"A1\").EntireRow.Insert\nEnd Sub\n").unwrap();
        {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
        }
        let merge = &workbook.sheets[0].merge_cells[0];
        assert_eq!(
            (merge.start_row, merge.end_row, merge.start_col, merge.end_col),
            (3, 3, 1, 2)
        );

        let mut workbook = filled_grid();
        workbook.sheets[0].merge_cells.push(MergeCell {
            start_row: 2,
            start_col: 1,
            end_row: 2,
            end_col: 2,
        });
        let module =
            parse_module("Public Sub Act()\n  Range(\"A2\").EntireRow.Delete\nEnd Sub\n").unwrap();
        {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
        }
        assert!(workbook.sheets[0].merge_cells.is_empty());
    }

    /// Every grid here is what Excel 16 left behind for the same call.
    #[test]
    fn vba_shifts_part_of_a_row_or_column() {
        // A single cell is as wide as it is tall, so it moves down.
        let workbook = run_on_grid("Public Sub Act()\n  Range(\"B2\").Insert\nEnd Sub\n");
        assert_eq!(
            grid(&workbook, 4, 4),
            "A1,B1,C1,D1 / A2,.,C2,D2 / A3,B2,C3,D3 / A4,B3,C4,D4"
        );

        // Taller than wide, so this one moves sideways instead.
        let workbook = run_on_grid("Public Sub Act()\n  Range(\"B2:B3\").Insert\nEnd Sub\n");
        assert_eq!(
            grid(&workbook, 4, 4),
            "A1,B1,C1,D1 / A2,.,B2,C2 / A3,.,B3,C3 / A4,B4,C4,D4"
        );

        // Wider than tall, so it moves down, carrying both columns.
        let workbook = run_on_grid("Public Sub Act()\n  Range(\"B2:C2\").Insert\nEnd Sub\n");
        assert_eq!(
            grid(&workbook, 4, 4),
            "A1,B1,C1,D1 / A2,.,.,D2 / A3,B2,C2,D3 / A4,B3,C3,D4"
        );

        let workbook = run_on_grid("Public Sub Act()\n  Range(\"B2\").Delete\nEnd Sub\n");
        assert_eq!(
            grid(&workbook, 4, 4),
            "A1,B1,C1,D1 / A2,B3,C2,D2 / A3,B4,C3,D3 / A4,.,C4,D4"
        );

        let workbook = run_on_grid("Public Sub Act()\n  Range(\"B2:B3\").Delete\nEnd Sub\n");
        assert_eq!(
            grid(&workbook, 4, 4),
            "A1,B1,C1,D1 / A2,C2,D2,. / A3,C3,D3,. / A4,B4,C4,D4"
        );

        let workbook = run_on_grid("Public Sub Act()\n  Range(\"B2:C3\").Delete\nEnd Sub\n");
        assert_eq!(
            grid(&workbook, 4, 4),
            "A1,B1,C1,D1 / A2,B4,C4,D2 / A3,.,.,D3 / A4,.,.,D4"
        );
    }

    /// An explicit shift overrides the shape's own leaning.
    #[test]
    fn an_explicit_shift_decides_the_direction() {
        let workbook =
            run_on_grid("Public Sub Act()\n  Range(\"B2\").Insert xlShiftToRight\nEnd Sub\n");
        assert_eq!(
            grid(&workbook, 4, 4),
            "A1,B1,C1,D1 / A2,.,B2,C2 / A3,B3,C3,D3 / A4,B4,C4,D4"
        );

        let workbook =
            run_on_grid("Public Sub Act()\n  Range(\"B2\").Delete xlShiftToLeft\nEnd Sub\n");
        assert_eq!(
            grid(&workbook, 4, 4),
            "A1,B1,C1,D1 / A2,C2,D2,. / A3,B3,C3,D3 / A4,B4,C4,D4"
        );
    }

    /// A partial shift moves only the formulas sharing its column, and leaves a
    /// range reaching past the band alone.
    #[test]
    fn a_partial_shift_moves_only_what_shares_its_column() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Act()\n\
               Range(\"F1\").Formula = \"=B3*2\"\n\
               Range(\"F2\").Formula = \"=C3*2\"\n\
               Range(\"F3\").Formula = \"=SUM(B1:B4)\"\n\
               Range(\"F4\").Formula = \"=SUM(A1:C3)\"\n\
               Range(\"B2\").Insert xlShiftDown\n\
             End Sub\n",
        )
        .unwrap();
        {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
        }
        let formula = |row: u32| {
            workbook.sheets[0]
                .rows
                .iter()
                .find(|candidate| candidate.index == row)
                .and_then(|found| found.cells.iter().find(|cell| cell.col == 5))
                .and_then(|cell| cell.formula.clone())
                .unwrap_or_default()
        };
        assert_eq!(formula(1), "B4*2");
        assert_eq!(formula(2), "C3*2");
        assert_eq!(formula(3), "SUM(B1:B5)");
        assert_eq!(formula(4), "SUM(A1:C3)");
    }

    #[test]
    fn vba_refuses_a_shift_that_does_not_belong(
    ) {
        let mut workbook = filled_grid();
        for source in [
            // xlShiftToLeft is a deletion's shift, not an insertion's.
            "Public Sub Act()\n  Range(\"B2\").Insert xlShiftToLeft\nEnd Sub\n",
            "Public Sub Act()\n  Range(\"B2\").Delete xlShiftDown\nEnd Sub\n",
        ] {
            let module = parse_module(source).unwrap();
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host)
                .expect_err("that shift belongs to the other operation");
        }
    }

    /// A formula on one sheet follows rows inserted on the sheet it names.
    /// Measured against Excel with sheets called Data and Report.
    #[test]
    fn formulas_on_other_sheets_follow_the_rows_that_moved() {
        let mut workbook = workbook();
        workbook.sheets[0].name = "Data".to_string();
        let mut report = workbook.sheets[0].clone();
        report.name = "Report".to_string();
        report.rows = Vec::new();
        workbook.sheets.push(report);

        let module = parse_module(
            "Public Sub Act()\n\
               Worksheets(\"Report\").Range(\"A1\").Formula = \"=Data!A5*2\"\n\
               Worksheets(\"Report\").Range(\"A2\").Formula = \"=SUM(Data!A1:A6)\"\n\
               Worksheets(\"Report\").Range(\"A3\").Formula = \"=Report!A5*2\"\n\
               Worksheets(\"Data\").Range(\"A1\").EntireRow.Insert\n\
             End Sub\n",
        )
        .unwrap();
        {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
        }

        let formula = |row: u32| {
            workbook.sheets[1]
                .rows
                .iter()
                .find(|candidate| candidate.index == row)
                .and_then(|found| found.cells.iter().find(|cell| cell.col == 0))
                .and_then(|cell| cell.formula.clone())
                .unwrap_or_default()
        };
        assert_eq!(formula(1), "Data!A6*2");
        assert_eq!(formula(2), "SUM(Data!A2:A7)");
        // Report's own rows never moved, so a reference to them stays.
        assert_eq!(formula(3), "Report!A5*2");
    }

    /// Renders the merges a sheet holds, in the address form the Excel probe
    /// printed, so the expectations below are what Excel actually left.
    fn merges(workbook: &Workbook) -> String {
        if workbook.sheets[0].merge_cells.is_empty() {
            return "none".to_string();
        }
        workbook.sheets[0]
            .merge_cells
            .iter()
            .map(|merge| {
                format!(
                    "{}{}:{}{}",
                    (b'A' + merge.start_col as u8) as char,
                    merge.start_row,
                    (b'A' + merge.end_col as u8) as char,
                    merge.end_row
                )
            })
            .collect::<Vec<_>>()
            .join(" ")
    }

    fn merged_grid(start_row: u32, start_col: u32, end_row: u32, end_col: u32) -> Workbook {
        let mut workbook = filled_grid();
        workbook.sheets[0].merge_cells.push(MergeCell {
            start_row,
            start_col,
            end_row,
            end_col,
        });
        workbook
    }

    fn act_on(mut workbook: Workbook, body: &str) -> Workbook {
        let module = parse_module(&format!("Public Sub Act()\n  {body}\nEnd Sub\n")).unwrap();
        {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
        }
        workbook
    }

    /// A band carries a merge it covers and takes apart one it only half
    /// reaches. Every expectation is what Excel 16 left behind.
    #[test]
    fn a_merge_survives_only_a_band_that_covers_it() {
        // The band is column B alone, so the B2:C2 merge cannot come along.
        let workbook = act_on(
            merged_grid(2, 1, 2, 2),
            "Range(\"B2\").Insert xlShiftDown",
        );
        assert_eq!(merges(&workbook), "none");

        let workbook = act_on(merged_grid(2, 1, 2, 2), "Range(\"B2\").Delete xlShiftUp");
        assert_eq!(merges(&workbook), "none");

        // A band as wide as the merge carries it down whole.
        let workbook = act_on(
            merged_grid(2, 1, 2, 2),
            "Range(\"B2:C2\").Insert xlShiftDown",
        );
        assert_eq!(merges(&workbook), "B3:C3");

        // Taking one of its two rows leaves the merge a row shorter.
        let workbook = act_on(
            merged_grid(2, 1, 3, 2),
            "Range(\"B2:C2\").Delete xlShiftUp",
        );
        assert_eq!(merges(&workbook), "B2:C2");

        // A column band cannot carry a merge that spans two rows.
        let workbook = act_on(
            merged_grid(2, 1, 3, 1),
            "Range(\"B2\").Insert xlShiftToRight",
        );
        assert_eq!(merges(&workbook), "none");

        // Whole rows reach across everything, so these always carry.
        let workbook = act_on(merged_grid(2, 1, 2, 2), "Range(\"A2\").EntireRow.Delete");
        assert_eq!(merges(&workbook), "none");

        let workbook = act_on(merged_grid(2, 1, 3, 2), "Range(\"A2\").EntireRow.Delete");
        assert_eq!(merges(&workbook), "B2:C2");

        let workbook = act_on(merged_grid(2, 1, 3, 2), "Range(\"A1\").EntireRow.Insert");
        assert_eq!(merges(&workbook), "B3:C4");
    }

    /// A new sheet lands in front of the active one, becomes active, and is
    /// handed back. Measured against Excel with the first sheet named Base.
    #[test]
    fn vba_adds_a_worksheet_in_front_of_the_active_one() {
        let mut workbook = workbook();
        workbook.sheets[0].name = "Base".to_string();
        let module = parse_module(
            "Public Sub Act()\n\
               Dim added As Object\n\
               Set added = Worksheets.Add\n\
               Debug.Print added.Name, TypeName(added), ActiveSheet.Name\n\
             End Sub\n",
        )
        .unwrap();
        let debug_output = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            host.take_debug_output()
        };

        assert_eq!(debug_output, vec!["Sheet1\tWorksheet\tSheet1".to_string()]);
        assert_eq!(
            workbook
                .sheets
                .iter()
                .map(|sheet| sheet.name.clone())
                .collect::<Vec<_>>(),
            vec!["Sheet1".to_string(), "Base".to_string()]
        );
    }

    /// Everything held beside the workbook is held by the sheet's position,
    /// and a new sheet in front moves every position along. Measured: a
    /// `Worksheet` and a `Range` kept across `Worksheets.Add` still name
    /// Sheet1; its note, unlocked cell, page setup and validation stay
    /// with it; the new sheet has none; each sheet keeps its own selection;
    /// and the objects of a deleted sheet answer 424.
    #[test]
    fn vba_side_tables_follow_a_renumbered_sheet() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Act()
               Dim ws As Object, r As Object
               Application.DisplayAlerts = False
               Set ws = Worksheets(1)
               Set r = Range(\"B2\")
               Range(\"A1\").AddComment \"n1\"
               Range(\"A2\").Locked = False
               ActiveSheet.PageSetup.Orientation = 2
               Range(\"A6\").Validation.Add 1, 1, 1, \"1\", \"9\"
               Range(\"A8:B9\").Select
               Worksheets.Add
               r.Value = 5
               Debug.Print ws.Name; ws.Index; r.Worksheet.Name; ActiveSheet.Name
               Debug.Print Worksheets(\"Sheet1\").Range(\"B2\").Value; IsEmpty(Range(\"B2\").Value)
               Debug.Print Worksheets(\"Sheet1\").Comments.Count; ActiveSheet.Comments.Count
               Debug.Print Worksheets(\"Sheet1\").Range(\"A2\").Locked; Range(\"A2\").Locked
               Debug.Print Worksheets(\"Sheet1\").PageSetup.Orientation; ActiveSheet.PageSetup.Orientation
               Debug.Print Worksheets(\"Sheet1\").Range(\"A6\").Validation.Formula1
               Debug.Print Selection.Address(0, 0)
               Worksheets(\"Sheet1\").Activate
               Debug.Print Selection.Address(0, 0)
               Worksheets(1).Delete
               Debug.Print Worksheets.Count; ws.Index; Range(\"A1\").Comment.Text
               Worksheets.Add Count:=2
               Debug.Print Worksheets(1).Name; Worksheets(2).Name; ActiveSheet.Name
               Set ws = Worksheets(1)
               Worksheets(1).Delete
               On Error Resume Next
               Debug.Print ws.Name
               Debug.Print Err.Number
               Err.Clear
               r.Value = 1
               Debug.Print Err.Number
             End Sub
",
        )
        .unwrap();
        let debug_output = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            host.take_debug_output()
        };
        assert_eq!(
            debug_output,
            vec![
                "Sheet1	2	Sheet1	Sheet2".to_string(),
                "5	True".to_string(),
                "1	0".to_string(),
                "False	True".to_string(),
                "2	1".to_string(),
                "1".to_string(),
                "A1".to_string(),
                "A8:B9".to_string(),
                "1	1	n1".to_string(),
                // Two at once go in front of each other, numbered on from
                // the sheets made so far -- Sheet2 is gone, but its number
                // is spent.
                "Sheet4	Sheet3	Sheet4".to_string(),
                "424".to_string(),
                // The range on Sheet1 is still there to write to.
                "0".to_string(),
            ]
        );
    }

    /// What the window shows, and how a sheet is outlined, turned, ruled
    /// and hatched -- each measured against Excel (misc1.vba, 2026-09-05).
    #[test]
    fn vba_keeps_the_view_the_outline_and_the_marks_on_a_cell() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Act()\n\
               Application.DisplayAlerts = False\n\
               Debug.Print ActiveWindow.Zoom; ActiveWindow.DisplayGridlines; ActiveWindow.ScrollRow\n\
               On Error Resume Next\n\
               ActiveWindow.Zoom = 5\n\
               Debug.Print Err.Number; ActiveWindow.Zoom\n\
               Err.Clear\n\
               ActiveWindow.ScrollRow = 0\n\
               Debug.Print Err.Number\n\
               Err.Clear\n\
               On Error GoTo 0\n\
               ActiveWindow.Zoom = 80.6: ActiveWindow.DisplayGridlines = False: ActiveWindow.ScrollRow = 5\n\
               Worksheets.Add After:=Worksheets(1)\n\
               Debug.Print ActiveWindow.Zoom; ActiveWindow.DisplayGridlines; ActiveWindow.ScrollRow\n\
               Worksheets(1).Activate\n\
               Debug.Print ActiveWindow.Zoom; ActiveWindow.DisplayGridlines; ActiveWindow.ScrollRow\n\
               Rows(\"7:8\").Group: Rows(\"7:8\").Group\n\
               Debug.Print Rows(7).OutlineLevel; Rows(6).OutlineLevel\n\
               Rows(\"7:8\").Ungroup: Rows(\"7:8\").Ungroup\n\
               Range(\"A11:B12\").Group\n\
               Debug.Print Rows(7).OutlineLevel; Rows(11).OutlineLevel; Columns(1).OutlineLevel\n\
               Rows(\"30:31\").Group: Rows(20).OutlineLevel = 3\n\
               ActiveSheet.Outline.ShowLevels RowLevels:=1\n\
               Debug.Print Rows(30).Hidden; Rows(7).Hidden; Rows(20).Hidden\n\
               ActiveSheet.Outline.ShowLevels RowLevels:=2\n\
               Debug.Print Rows(30).Hidden; Rows(20).Hidden; ActiveSheet.Outline.SummaryRow; ActiveSheet.Outline.SummaryColumn\n\
               Range(\"M1\").Orientation = 45: Range(\"M3\").Orientation = -90: Range(\"M4\").Orientation = -4171: Range(\"M6\").Orientation = \"30\": Range(\"M7\").Orientation = 45.6\n\
               Debug.Print Range(\"M1\").Orientation; Range(\"M3\").Orientation; Range(\"M4\").Orientation; Range(\"M6\").Orientation; Range(\"M7\").Orientation; IsNull(Range(\"M1:M3\").Orientation)\n\
               On Error Resume Next\n\
               Range(\"M2\").Orientation = 91\n\
               Debug.Print Err.Number; Range(\"M2\").Orientation\n\
               Err.Clear\n\
               On Error GoTo 0\n\
               Debug.Print Range(\"P1\").Interior.Pattern; Range(\"P1\").Interior.PatternColor; Range(\"P1\").Interior.PatternColorIndex\n\
               Range(\"P1\").Interior.Pattern = -4125\n\
               Debug.Print Range(\"P1\").Interior.Pattern; Range(\"P1\").Interior.PatternColorIndex; Range(\"P1\").Interior.Color; Range(\"P1\").Interior.ColorIndex\n\
               Range(\"P1\").Interior.PatternColor = 255: Range(\"P1\").Interior.Color = 65280\n\
               Debug.Print Range(\"P1\").Interior.Pattern; Range(\"P1\").Interior.PatternColor; Range(\"P1\").Interior.PatternColorIndex; Range(\"P1\").Interior.Color\n\
               Range(\"P3\").Interior.Pattern = 1: Range(\"P4\").Interior.Pattern = 7\n\
               Debug.Print Range(\"P3\").Interior.Pattern; Range(\"P3\").Interior.Color; Range(\"P3\").Interior.ColorIndex; Range(\"P4\").Interior.Pattern\n\
               Range(\"P1\").Copy Range(\"P9\"): Range(\"P1\").ClearFormats\n\
               Debug.Print Range(\"P9\").Interior.Pattern; Range(\"P9\").Interior.PatternColor; Range(\"P1\").Interior.Pattern\n\
               Range(\"R1\").AddIndent = True\n\
               Debug.Print Range(\"R1\").AddIndent; Range(\"R2\").AddIndent; IsNull(Range(\"R1:R2\").AddIndent)\n\
             End Sub\n",
        )
        .unwrap();
        let debug_output = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            host.take_debug_output()
        };
        assert_eq!(
            debug_output,
            vec![
                "100\tTrue\t1".to_string(),
                "1004\t100".to_string(),
                "1004".to_string(),
                // A new sheet has a view of its own; the old one keeps its.
                "100\tTrue\t1".to_string(),
                "80\tFalse\t5".to_string(),
                "3\t1".to_string(),
                // A block that is neither whole rows nor whole columns groups
                // its columns.
                "1\t1\t2".to_string(),
                "True\tFalse\tTrue".to_string(),
                "False\tTrue\t1\t-4152".to_string(),
                "45\t-4170\t-4171\t30\t45\tTrue".to_string(),
                "1004\t-4128".to_string(),
                "-4142\t0\t-4142".to_string(),
                "-4125\t-4105\t16777215\t-4105".to_string(),
                "-4125\t255\t3\t65280".to_string(),
                "1\t16777215\t-4105\t-4121".to_string(),
                "-4125\t255\t-4142".to_string(),
                "True\tFalse\tTrue".to_string(),
            ]
        );
    }

    /// `Range.FormulaArray`: one formula dealt across a block, and what can
    /// and cannot be done to part of it. Every line measured (arr.vba,
    /// 2026-09-05; the case agrees in the differential harness).
    #[test]
    fn vba_deals_an_array_formula_across_its_block() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Act()\n\
               Range(\"A1\").Value = 1: Range(\"A2\").Value = 2\n\
               Range(\"C1:C2\").FormulaArray = \"=A1:A2*2\"\n\
               Debug.Print Range(\"C1\").Value; Range(\"C2\").Value; Range(\"C1\").HasArray; Range(\"C2\").Formula; Range(\"C1:C2\").FormulaArray\n\
               Debug.Print Range(\"C1:D2\").HasArray; Range(\"D1\").HasArray; Range(\"C1\").CurrentArray.Address; Range(\"C1:D2\").FormulaArray; IsNull(Range(\"A1:A2\").FormulaArray)\n\
               On Error Resume Next\n\
               Range(\"C1\").Value = 9\n\
               Debug.Print Err.Number; Range(\"C1\").Value\n\
               Range(\"C1\").ClearContents\n\
               Debug.Print Err.Number; Range(\"C1\").Value\n\
               Err.Clear\n\
               Range(\"C1\").EntireRow.Insert\n\
               Debug.Print Err.Number; Range(\"C2\").CurrentArray.Address(0, 0)\n\
               Err.Clear\n\
               Range(\"C3\").EntireRow.Insert\n\
               Debug.Print Err.Number\n\
               Err.Clear\n\
               Range(\"A9\").CurrentArray.Select\n\
               Debug.Print Err.Number\n\
               Err.Clear\n\
               On Error GoTo 0\n\
               Range(\"C2:C3\").Copy Range(\"E2\")\n\
               Debug.Print Range(\"E2\").HasArray; Range(\"E3\").Value; Range(\"E2\").CurrentArray.Address(0, 0)\n\
               Range(\"E2:E3\").Value = 4\n\
               Debug.Print Range(\"E2\").HasArray; Range(\"E3\").Value\n\
               Range(\"G1:G3\").FormulaArray = \"=A1:A2*2\"\n\
               Range(\"H1:H2\").FormulaArray = \"=7\"\n\
               Range(\"I1:J1\").FormulaArray = \"=TRANSPOSE(A1:A2)\"\n\
               Debug.Print Range(\"G3\").Text; Range(\"H2\").Value; Range(\"J1\").Value\n\
               Range(\"A2\").Value = 5\n\
               Debug.Print Range(\"C2\").Value; Range(\"C3\").Value\n\
             End Sub\n",
        )
        .unwrap();
        let debug_output = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            host.take_debug_output()
        };
        assert_eq!(
            debug_output,
            vec![
                "2\t4\tTrue\t=A1:A2*2\t=A1:A2*2".to_string(),
                "True\tFalse\t$C$1:$C$2\t=A1:A2*2\tTrue".to_string(),
                // Writing one cell of the block is quietly nothing; clearing
                // it is refused.
                "0\t2".to_string(),
                "1004\t2".to_string(),
                // A row put in at the block's first row moves it; one put in
                // inside it is refused; CurrentArray off an array is refused.
                "0\tC2:C3".to_string(),
                "1004".to_string(),
                "1004".to_string(),
                "True\t4\tE2:E3".to_string(),
                "False\t4".to_string(),
                // The row put in above moved A1:A2 down to A2:A3, so the
                // transposed block starts with the empty A1 -- and it is A2
                // that C2 now reads.
                "#N/A\t7\t1".to_string(),
                "10\t4".to_string(),
            ]
        );
    }

    /// `Range.AutoFill` and the four `Fill*` members, as measured (fill.vba,
    /// 2026-09-05; the case agrees in the differential harness). The law of
    /// the series itself is pinned in `oxicells_core::fill`; this pins the
    /// wiring: where the cells land, what a destination may be, what the
    /// formats do.
    #[test]
    fn vba_fills_a_range_from_its_pattern() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Act()\n\
               Range(\"A1\").Value = 5: Range(\"A1\").AutoFill Range(\"A1:A3\")\n\
               Range(\"B1\").Value = 5: Range(\"B1\").AutoFill Range(\"B1:B3\"), 2\n\
               Range(\"F1\").Value = 1: Range(\"F1\").Font.Bold = True: Range(\"F2\").Value = 2: Range(\"F1:F2\").AutoFill Range(\"F1:F5\")\n\
               Debug.Print Range(\"A3\").Value; Range(\"B3\").Value; Range(\"F5\").Value; Range(\"F3\").Font.Bold; Range(\"F4\").Font.Bold; Range(\"F5\").Font.Bold\n\
               Range(\"H1\").Value = 1: Range(\"H1\").Font.Bold = True: Range(\"H2\").Value = 2: Range(\"H1:H2\").AutoFill Range(\"H1:H4\"), 3\n\
               Range(\"G1\").Value = 1: Range(\"G1\").Font.Bold = True: Range(\"G2\").Value = 2: Range(\"G1:G2\").AutoFill Range(\"G1:G4\"), 4\n\
               Debug.Print IsEmpty(Range(\"H3\").Value); Range(\"H3\").Font.Bold; Range(\"G3\").Value; Range(\"G3\").Font.Bold\n\
               Range(\"O4\").Value = 10: Range(\"O5\").Value = 8: Range(\"O4:O5\").AutoFill Range(\"O1:O5\")\n\
               Range(\"T1\").Value = 1: Range(\"U1\").Value = 3: Range(\"T1:U1\").AutoFill Range(\"T1:W1\")\n\
               Range(\"N1\").Formula = \"=A1*2\": Range(\"N1\").AutoFill Range(\"N1:N3\")\n\
               Debug.Print Range(\"O1\").Value; Range(\"O3\").Value; Range(\"W1\").Value; Range(\"N3\").Formula\n\
               On Error Resume Next\n\
               Range(\"P1\").Value = 1: Range(\"P1\").AutoFill Range(\"P2:P4\")\n\
               Debug.Print Err.Number; IsEmpty(Range(\"P2\").Value)\n\
               Err.Clear\n\
               Range(\"S1\").AutoFill Range(\"S1\")\n\
               Debug.Print Err.Number\n\
               Err.Clear\n\
               Range(\"AN1\").AutoFill Range(\"AN1:AN3\"), 99\n\
               Debug.Print Err.Number\n\
               Err.Clear\n\
               Range(\"H9\").Value = 1: Range(\"H9\").FillDown\n\
               Debug.Print Err.Number\n\
               Err.Clear\n\
               On Error GoTo 0\n\
               Range(\"Q1\").Value = 1: Range(\"Q1\").AutoFill Range(\"Q1:R3\")\n\
               Debug.Print IsEmpty(Range(\"Q2\").Value); IsEmpty(Range(\"R1\").Value); Range(\"R2\").Value; Range(\"R3\").Value\n\
               Range(\"AC1\").Formula = \"=A1*2\": Range(\"AC1\").Font.Bold = True: Range(\"AC1:AC3\").FillDown\n\
               Range(\"AD3\").Value = \"z\": Range(\"AD1:AD3\").FillUp\n\
               Range(\"AE1\").Value = \"q\": Range(\"AE1:AG1\").FillRight\n\
               Range(\"AJ1\").Formula = \"=$A$1+B1\": Range(\"AH1:AJ1\").FillLeft\n\
               Range(\"J1\").Value = 1: Range(\"J2\").Value = 2: Range(\"J1:J2\").FillDown\n\
               Debug.Print Range(\"AC3\").Formula; Range(\"AC3\").Font.Bold; Range(\"AD1\").Value; Range(\"AG1\").Value; Range(\"AH1\").Formula; Range(\"J2\").Value\n\
               Debug.Print TypeName(Range(\"J1:J2\").AutoFill(Range(\"J1:J3\")))\n\
             End Sub\n",
        )
        .unwrap();
        let debug_output = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            host.take_debug_output()
        };
        assert_eq!(
            debug_output,
            vec![
                // A lone number is copied, a series counts, and the formats
                // follow the pattern cell by cell.
                "5\t7\t5\tTrue\tFalse\tTrue".to_string(),
                // xlFillFormats carries no values; xlFillValues no formats.
                "True\tTrue\t3\tFalse".to_string(),
                "16\t12\t7\t=A3*2".to_string(),
                // The destination must hold the source, and be more than it.
                "1004\tTrue".to_string(),
                "1004".to_string(),
                "1004".to_string(),
                "1004".to_string(),
                // A destination reaching both ways fills only the corner,
                // with the first cell.
                "True\tTrue\t1\t1".to_string(),
                "=A3*2\tTrue\tz\tq\t=$A$1+#REF!\t1".to_string(),
                "Boolean".to_string(),
            ]
        );
    }

    /// `Range.Subtotal` and `RemoveSubtotal`, as a Japanese Excel lays them
    /// (misc2/misc3/sub.vba, 2026-09-05; the case agrees in the harness).
    #[test]
    fn vba_lays_subtotals_the_way_excel_does() {
        let mut workbook = workbook();
        let module = parse_module(
            "Public Sub Act()\n\
               Dim r As Long\n\
               Range(\"A1\").Value = \"k\": Range(\"B1\").Value = \"v\": Range(\"C1\").Value = \"w\"\n\
               Range(\"A2\").Value = \"a\": Range(\"B2\").Value = 1: Range(\"C2\").Value = 10\n\
               Range(\"A3\").Value = \"A\": Range(\"B3\").Value = 2: Range(\"C3\").Value = 20\n\
               Range(\"A4\").Value = \"b\": Range(\"B4\").Value = 5: Range(\"C4\").Value = 50\n\
               Range(\"B2\").Font.Bold = True: Range(\"B2\").NumberFormat = \"0.00\"\n\
               Range(\"A1:C4\").Subtotal GroupBy:=1, Function:=xlSum, TotalList:=Array(2, 3)\n\
               For r = 1 To 7\n\
                 Debug.Print Range(\"A\" & r).Value; Range(\"B\" & r).Formula; Range(\"C\" & r).Formula; Rows(r).OutlineLevel; Range(\"A\" & r).Font.Bold; Range(\"B\" & r).Font.Bold\n\
               Next\n\
               Debug.Print Range(\"B7\").Value; Range(\"B4\").NumberFormat; ActiveSheet.Outline.SummaryRow\n\
               Range(\"A1:C7\").Subtotal GroupBy:=1, Function:=xlCount, TotalList:=Array(2), Replace:=False\n\
               For r = 4 To 10\n\
                 Debug.Print Range(\"A\" & r).Value; Range(\"B\" & r).Formula; Rows(r).OutlineLevel\n\
               Next\n\
               Range(\"A1:C10\").RemoveSubtotal\n\
               Debug.Print Range(\"A4\").Value; IsEmpty(Range(\"A5\").Value); Rows(2).OutlineLevel\n\
               Range(\"A1:C4\").Subtotal GroupBy:=1, Function:=xlAverage, TotalList:=Array(3), SummaryBelowData:=False\n\
               For r = 1 To 7\n\
                 Debug.Print Range(\"A\" & r).Value; Range(\"C\" & r).Formula; Rows(r).OutlineLevel\n\
               Next\n\
               Debug.Print ActiveSheet.Outline.SummaryRow\n\
               Range(\"A1:C7\").RemoveSubtotal\n\
               Range(\"A1:C4\").Subtotal GroupBy:=3, Function:=xlSum, TotalList:=2\n\
               Debug.Print Range(\"C3\").Value; Range(\"B3\").Formula; Range(\"C8\").Value; Range(\"B8\").Formula\n\
               On Error Resume Next\n\
               Range(\"A1:C4\").Subtotal GroupBy:=1, Function:=xlSum, TotalList:=Array(4)\n\
               Debug.Print Err.Number\n\
               Err.Clear\n\
               Range(\"A1:C4\").Subtotal GroupBy:=0, Function:=xlSum, TotalList:=Array(2)\n\
               Debug.Print Err.Number\n\
               Err.Clear\n\
             End Sub\n",
        )
        .unwrap();
        let debug_output = {
            let mut host = WorkbookHost::new(&mut workbook, 0).unwrap();
            execute_with_host(&module, "Act", vec![], &mut host).unwrap();
            host.take_debug_output()
        };
        assert_eq!(
            debug_output,
            vec![
                // a and A are one group; the label is bold, the totals are
                // not; data rows level 3, group rows 2, the grand row 1.
                "k\tv\tw\t1\tFalse\tFalse".to_string(),
                "a\t1\t10\t3\tFalse\tTrue".to_string(),
                "A\t2\t20\t3\tFalse\tFalse".to_string(),
                "a 集計\t=SUBTOTAL(9,B2:B3)\t=SUBTOTAL(9,C2:C3)\t2\tTrue\tFalse".to_string(),
                "b\t5\t50\t3\tFalse\tFalse".to_string(),
                "b 集計\t=SUBTOTAL(9,B5:B5)\t=SUBTOTAL(9,C5:C5)\t2\tTrue\tFalse".to_string(),
                "総計\t=SUBTOTAL(9,B2:B5)\t=SUBTOTAL(9,C2:C5)\t1\tTrue\tFalse".to_string(),
                // The grand total runs over the data rows; the put-in row
                // wears the format of the row above it.
                "8\tGeneral\t1".to_string(),
                // A second function joins the first in Excel's function
                // order, the first innermost.
                "a 集計\t=SUBTOTAL(9,B2:B3)\t3".to_string(),
                "a 個数\t=SUBTOTAL(3,B2:B3)\t2".to_string(),
                "b\t5\t4".to_string(),
                "b 集計\t=SUBTOTAL(9,B6:B6)\t3".to_string(),
                "b 個数\t=SUBTOTAL(3,B6:B6)\t2".to_string(),
                "総計\t=SUBTOTAL(9,B2:B6)\t1".to_string(),
                "総合計\t=SUBTOTAL(3,B2:B6)\t1".to_string(),
                "b\tTrue\t1".to_string(),
                // Summary above: the grand row first, then each group's
                // row before its rows.
                "k\tw\t1".to_string(),
                "全体の平均\t=SUBTOTAL(1,C4:C7)\t1".to_string(),
                "a 平均\t=SUBTOTAL(1,C4:C5)\t2".to_string(),
                "a\t10\t3".to_string(),
                "A\t20\t3".to_string(),
                "b 平均\t=SUBTOTAL(1,C7:C7)\t2".to_string(),
                "b\t50\t3".to_string(),
                "0".to_string(),
                // Grouping by the third column labels in that column, and a
                // scalar TotalList is taken.
                "10 集計\t=SUBTOTAL(9,B2:B2)\t総計\t=SUBTOTAL(9,B2:B6)".to_string(),
                "1004".to_string(),
                "1004".to_string(),
            ]
        );
    }

    /// The seventh discovery batch (misc4.vba, 2026-09-05; the case agrees
